CREATE OR REPLACE FUNCTION public.accept_document_extraction_atomic(p_document_id uuid, p_actor_id uuid, p_apply_to_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_doc public.crm_product_documents%ROWTYPE;
  v_extraction JSONB;
  v_status TEXT;
  v_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Lock the document row
  SELECT * INTO v_doc
  FROM public.crm_product_documents
  WHERE id = p_document_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;
  END IF;

  v_extraction := v_doc.ai_extraction;
  IF v_extraction IS NULL THEN
    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;
  END IF;

  v_status := v_extraction->>'status';
  IF v_status IN ('accepted', 'dismissed') THEN
    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;
  END IF;

  -- If request linking is requested, associate document with the request if not already linked
  IF p_apply_to_request_id IS NOT NULL THEN
    UPDATE public.crm_product_documents
    SET enquiry_request_id = p_apply_to_request_id
    WHERE id = p_document_id AND enquiry_request_id IS NULL;
  END IF;

  -- Update extraction status to accepted, recording human reviewer and timestamp
  UPDATE public.crm_product_documents
  SET ai_extraction = jsonb_set(
    jsonb_set(
      jsonb_set(
        v_extraction,
        '{status}',
        '"accepted"'::jsonb
      ),
      '{reviewed_by}',
      to_jsonb(p_actor_id::text)
    ),
    '{reviewed_at}',
    to_jsonb(v_now::text)
  )
  WHERE id = p_document_id;

  RETURN jsonb_build_object(
    'success', true,
    'document_id', p_document_id,
    'status', 'accepted',
    'reviewed_at', v_now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_enquiry_brain_proposal_atomic(p_message_id uuid, p_inquiry_id uuid, p_expected_values jsonb DEFAULT NULL::jsonb, p_actor_type text DEFAULT 'user'::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_role TEXT;
  v_caller_auth_uid UUID;
  v_effective_actor_type TEXT;
  v_effective_actor_id UUID;
  v_user_role TEXT;

  v_msg public.enquiry_conversation_messages%ROWTYPE;
  v_proposal JSONB;
  v_proposal_status TEXT;
  v_update JSONB;
  v_req_id UUID;
  v_req public.enquiry_requests%ROWTYPE;
  v_field TEXT;
  v_event_type TEXT;
  v_new_req_val TEXT;
  v_new_status_val TEXT;
  v_new_waiting_val TEXT;
  v_new_next_action TEXT;
  v_new_team TEXT;

  v_new_req_item JSONB;
  v_created_req_id UUID;
  v_req_code TEXT;
  v_new_category TEXT;
  v_new_title TEXT;
  v_new_requirement_text TEXT;
  v_new_params JSONB;
  v_new_waiting TEXT;

  v_updated_req_ids UUID[] := '{}';
  v_created_req_ids UUID[] := '{}';
BEGIN
  v_caller_role := auth.role();
  v_caller_auth_uid := auth.uid();

  IF v_caller_role = 'authenticated' THEN
    SELECT role INTO v_user_role
    FROM public.user_profiles
    WHERE id = v_caller_auth_uid AND is_active = true;

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN
      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can approve AI proposals';
    END IF;

    -- Anti-spoofing guards
    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN
      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';
    END IF;

    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN
      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';
    END IF;

    v_effective_actor_type := 'user';
    v_effective_actor_id := v_caller_auth_uid;

  ELSIF v_caller_role = 'service_role' THEN
    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN
      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';
    END IF;
    v_effective_actor_type := p_actor_type;
    v_effective_actor_id := p_actor_id;

  ELSE
    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';
  END IF;

  -- 1. Row lock the message record to serialize concurrent approvals
  SELECT * INTO v_msg
  FROM public.enquiry_conversation_messages
  WHERE id = p_message_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Canonical message not found: %', p_message_id;
  END IF;

  v_proposal := v_msg.ai_proposal;
  IF v_proposal IS NULL THEN
    RAISE EXCEPTION 'Message % does not contain an AI proposal', p_message_id;
  END IF;

  -- 2. Concurrency / Idempotency check: strictly only 'suggested' can be accepted
  v_proposal_status := v_proposal->>'status';
  IF v_proposal_status IS NULL OR v_proposal_status <> 'suggested' THEN
    RAISE EXCEPTION 'PROPOSAL_ALREADY_PROCESSED: AI proposal has already been processed (current status: %)', COALESCE(v_proposal_status, 'none')
      USING ERRCODE = 'P0002';
  END IF;

  -- 3. Process proposed updates with inside-transaction stale checking
  IF v_proposal ? 'proposed_updates' AND jsonb_typeof(v_proposal->'proposed_updates') = 'array' THEN
    FOR v_update IN SELECT * FROM jsonb_array_elements(v_proposal->'proposed_updates')
    LOOP
      v_req_id := (v_update->>'request_id')::UUID;
      IF v_req_id IS NULL THEN
        RAISE EXCEPTION 'Missing request_id in proposed update';
      END IF;

      -- Lock target enquiry_requests record
      SELECT * INTO v_req
      FROM public.enquiry_requests
      WHERE id = v_req_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Target request % no longer exists', v_req_id;
      END IF;

      v_field := v_update->>'field';

      -- Check stale condition against live row
      IF v_update ? 'old_value' AND v_update->'old_value' IS NOT NULL AND v_update->>'old_value' <> 'null' THEN
        IF v_field = 'customer_requirement' THEN
          IF trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(v_update->>'old_value', '')) THEN
            RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI proposal was created (expected: "%", current: "%")',
              v_update->>'old_value', v_req.customer_requirement
              USING ERRCODE = 'P0001';
          END IF;
        ELSIF v_field = 'status' THEN
          IF v_req.status <> (v_update->>'old_value') THEN
            RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI proposal was created (expected: "%", current: "%")',
              v_update->>'old_value', v_req.status
              USING ERRCODE = 'P0001';
          END IF;
        ELSIF v_field = 'waiting_for' THEN
          IF v_req.waiting_for <> (v_update->>'old_value') THEN
            RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI proposal was created (expected: "%", current: "%")',
              v_update->>'old_value', v_req.waiting_for
              USING ERRCODE = 'P0001';
          END IF;
        ELSIF v_field = 'assigned_team' THEN
          IF COALESCE(v_req.assigned_team, '') <> COALESCE(v_update->>'old_value', '') THEN
            RAISE EXCEPTION 'STALE_PROPOSAL: assigned_team has changed since AI proposal was created (expected: "%", current: "%")',
              v_update->>'old_value', v_req.assigned_team
              USING ERRCODE = 'P0001';
          END IF;
        END IF;
      END IF;

      -- Check caller expected values if provided for this request
      IF p_expected_values IS NOT NULL THEN
        IF p_expected_values ? 'customer_requirement' AND trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(p_expected_values->>'customer_requirement', '')) THEN
          RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI proposal was created (expected: "%", current: "%")',
            p_expected_values->>'customer_requirement', v_req.customer_requirement
            USING ERRCODE = 'P0001';
        END IF;
        IF p_expected_values ? 'status' AND v_req.status <> (p_expected_values->>'status') THEN
          RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI proposal was created (expected: "%", current: "%")',
            p_expected_values->>'status', v_req.status
            USING ERRCODE = 'P0001';
        END IF;
        IF p_expected_values ? 'waiting_for' AND v_req.waiting_for <> (p_expected_values->>'waiting_for') THEN
          RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI proposal was created (expected: "%", current: "%")',
            p_expected_values->>'waiting_for', v_req.waiting_for
            USING ERRCODE = 'P0001';
        END IF;
      END IF;

      -- Determine event type
      v_event_type := CASE
        WHEN v_proposal->>'intent' = 'customer_decision' THEN 'customer_decision'
        WHEN v_proposal->>'intent' = 'requirement_change' OR v_field = 'customer_requirement' THEN 'requirement_changed'
        WHEN v_proposal->>'intent' = 'supplier_response' THEN 'supplier_response'
        ELSE 'status_changed'
      END;

      -- Compute effective new values
      v_new_req_val := CASE WHEN v_field = 'customer_requirement' THEN v_update->>'new_value' ELSE v_req.customer_requirement END;
      v_new_status_val := CASE WHEN v_field = 'status' THEN v_update->>'new_value' ELSE v_req.status END;
      v_new_waiting_val := CASE
        WHEN v_field = 'waiting_for' THEN v_update->>'new_value'
        WHEN v_proposal->>'suggested_waiting_for' IS NOT NULL THEN v_proposal->>'suggested_waiting_for'
        ELSE v_req.waiting_for
      END;
      v_new_next_action := CASE
        WHEN v_field = 'next_action' THEN v_update->>'new_value'
        WHEN v_proposal->>'suggested_next_action' IS NOT NULL THEN v_proposal->>'suggested_next_action'
        ELSE v_req.next_action
      END;
      v_new_team := CASE
        WHEN v_field = 'assigned_team' THEN v_update->>'new_value'
        WHEN v_proposal->>'suggested_team' IS NOT NULL THEN v_proposal->>'suggested_team'
        ELSE v_req.assigned_team
      END;

      -- Update enquiry_requests
      UPDATE public.enquiry_requests
      SET
        customer_requirement = v_new_req_val,
        status = v_new_status_val,
        waiting_for = v_new_waiting_val,
        next_action = v_new_next_action,
        assigned_team = v_new_team,
        ai_status = 'confirmed',
        confirmed_by = v_effective_actor_id,
        confirmed_at = now(),
        updated_at = now()
      WHERE id = v_req_id;

      -- Insert immutable event
      INSERT INTO public.enquiry_request_events (
        request_id,
        inquiry_id,
        event_type,
        summary,
        old_status,
        new_status,
        old_waiting_for,
        new_waiting_for,
        details,
        source_message_id,
        actor_type,
        actor_id
      ) VALUES (
        v_req_id,
        v_req.inquiry_id,
        v_event_type,
        'AI Suggestion Accepted: ' || COALESCE(v_proposal->>'summary', ''),
        v_req.status,
        v_new_status_val,
        v_req.waiting_for,
        v_new_waiting_val,
        jsonb_build_object(
          'ai_proposal', v_proposal,
          'decision', 'accepted',
          'approved_field', v_field,
          'old_value', v_update->'old_value',
          'new_value', v_update->'new_value'
        ),
        p_message_id,
        v_effective_actor_type,
        v_effective_actor_id
      );

      -- Link provenance
      INSERT INTO public.enquiry_request_messages (
        request_id,
        message_id,
        relationship
      ) VALUES (
        v_req_id,
        p_message_id,
        'clarified'
      )
      ON CONFLICT (request_id, message_id, relationship) DO NOTHING;

      v_updated_req_ids := array_append(v_updated_req_ids, v_req_id);
    END LOOP;
  END IF;

  -- 4. Process proposed new requests (exactly once, atomic idempotency)
  IF v_proposal ? 'proposed_new_requests' AND jsonb_typeof(v_proposal->'proposed_new_requests') = 'array' THEN
    FOR v_new_req_item IN SELECT * FROM jsonb_array_elements(v_proposal->'proposed_new_requests')
    LOOP
      v_req_code := 'REQ-' || lpad(floor(random() * 10000)::text, 4, '0');
      v_new_category := COALESCE(v_new_req_item->>'category', 'commercial');
      v_new_title := COALESCE(v_new_req_item->>'title', 'New Request');
      v_new_requirement_text := COALESCE(v_new_req_item->>'customer_requirement', '');
      v_new_params := COALESCE(v_new_req_item->'parameters', '{}'::jsonb);
      v_new_waiting := COALESCE(v_new_req_item->>'waiting_for', 'INTERNAL');
      v_new_team := v_new_req_item->>'assigned_team';

      INSERT INTO public.enquiry_requests (
        inquiry_id,
        category,
        request_code,
        title,
        customer_requirement,
        parameters,
        assigned_to,
        assigned_team,
        due_at,
        status,
        waiting_for,
        source_message_id,
        ai_status,
        ai_confidence,
        ai_extracted_text
      ) VALUES (
        p_inquiry_id,
        v_new_category,
        v_req_code,
        v_new_title,
        v_new_requirement_text,
        v_new_params,
        NULL,
        v_new_team,
        NULL,
        'OPEN',
        v_new_waiting,
        p_message_id,
        'confirmed',
        CASE WHEN v_proposal->>'confidence_tier' = 'HIGH' THEN 0.9 ELSE 0.7 END,
        v_proposal->>'summary'
      )
      RETURNING id INTO v_created_req_id;

      -- Append initial created event
      INSERT INTO public.enquiry_request_events (
        request_id,
        inquiry_id,
        event_type,
        summary,
        old_status,
        new_status,
        old_waiting_for,
        new_waiting_for,
        details,
        source_message_id,
        actor_type,
        actor_id
      ) VALUES (
        v_created_req_id,
        p_inquiry_id,
        'created',
        'Request created from AI suggestion: ' || v_new_title,
        NULL,
        'OPEN',
        NULL,
        v_new_waiting,
        jsonb_build_object(
          'ai_proposal', v_proposal,
          'decision', 'accepted',
          'initial_requirement', v_new_requirement_text,
          'parameters', v_new_params
        ),
        p_message_id,
        v_effective_actor_type,
        v_effective_actor_id
      );

      -- Link provenance
      INSERT INTO public.enquiry_request_messages (
        request_id,
        message_id,
        relationship
      ) VALUES (
        v_created_req_id,
        p_message_id,
        'originated'
      )
      ON CONFLICT (request_id, message_id, relationship) DO NOTHING;

      v_created_req_ids := array_append(v_created_req_ids, v_created_req_id);
    END LOOP;
  END IF;

  -- 5. Mark proposal as accepted, preserving original proposal snapshot
  UPDATE public.enquiry_conversation_messages
  SET ai_proposal = v_proposal || jsonb_build_object(
    'status', 'accepted',
    'original_proposal', v_proposal,
    'reviewed_by', v_effective_actor_id,
    'reviewed_at', now()
  )
  WHERE id = p_message_id;

  RETURN jsonb_build_object(
    'success', true,
    'status', 'accepted',
    'updated_request_ids', v_updated_req_ids,
    'created_request_ids', v_created_req_ids
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.adjust_batch_stock_atomic(p_batch_id uuid, p_quantity_change numeric, p_transaction_type text, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(new_stock numeric, transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch public.batches%ROWTYPE;
  v_transaction_id uuid;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for stock adjustment';
  END IF;
  IF p_transaction_type IS DISTINCT FROM 'adjustment' THEN
    RAISE EXCEPTION 'Manual inventory entry supports Stock Adjustment only';
  END IF;
  IF COALESCE(p_quantity_change, 0) = 0 THEN
    RAISE EXCEPTION 'Stock adjustment cannot be zero';
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch not found';
  END IF;

  v_transaction_id := public.post_inventory_movement(
    p_operation_id,
    v_batch.product_id,
    v_batch.id,
    'adjustment',
    p_quantity_change,
    CURRENT_DATE,
    NULL,
    'stock_adjustment',
    p_reference_id,
    p_notes,
    COALESCE(p_created_by, auth.uid()),
    NULL,
    NULL
  );

  SELECT current_stock
  INTO new_stock
  FROM public.batches
  WHERE id = p_batch_id;

  transaction_id := v_transaction_id;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_id uuid;
  v_caller_role text;
  v_caller_active boolean;
  v_can_del boolean;
  v_reason text;
  v_refs integer;
  v_username text;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, is_active INTO v_caller_role, v_caller_active
  FROM public.user_profiles
  WHERE id = v_caller_id;

  IF v_caller_role <> 'admin' OR v_caller_active IS NOT TRUE THEN
    RAISE EXCEPTION 'Only active administrators can delete users';
  END IF;

  IF v_caller_id = p_user_id THEN
    RAISE EXCEPTION 'You cannot delete your own account';
  END IF;

  SELECT username INTO v_username
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_username IS NULL THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  SELECT can_delete, reason, reference_count INTO v_can_del, v_reason, v_refs
  FROM public.check_user_can_delete(p_user_id);

  IF v_can_del IS NOT TRUE THEN
    RAISE EXCEPTION '%', v_reason;
  END IF;

  -- Safe to delete: remove permissions, profile, and auth record
  DELETE FROM public.user_permissions WHERE user_id = p_user_id;
  DELETE FROM public.user_profiles WHERE id = p_user_id;
  DELETE FROM auth.users WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'username', v_username,
    'message', 'User deleted successfully'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_edit_approved_delivery_challan(p_challan_id uuid, p_new_items jsonb, p_operation_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_challan public.delivery_challans%ROWTYPE;
  v_old_item record;
  v_item jsonb;
  v_item_id uuid;
  v_product_id uuid;
  v_batch_id uuid;
  v_quantity numeric;
  v_blocking_invoices text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin']) THEN
    RAISE EXCEPTION 'Only admin can edit an approved Delivery Challan';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;

  SELECT *
  INTO v_challan
  FROM public.delivery_challans
  WHERE id = p_challan_id
  FOR UPDATE;

  IF NOT FOUND OR v_challan.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'Approved Delivery Challan not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.inventory_transactions
    WHERE reference_type = 'delivery_challan'
      AND reference_id = p_challan_id
      AND COALESCE(metadata->>'canonical_engine_version', '') <> '1.0'
  ) THEN
    RAISE EXCEPTION 'Historical DC movement is ambiguous; manual review is required';
  END IF;

  SELECT string_agg(DISTINCT si.invoice_number, ', ')
  INTO v_blocking_invoices
  FROM public.sales_invoice_items sii
  JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id
  JOIN public.sales_invoices si ON si.id = sii.invoice_id
  WHERE dci.challan_id = p_challan_id
    AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');

  IF v_blocking_invoices IS NOT NULL AND v_blocking_invoices <> '' THEN
    RAISE EXCEPTION 'Approved Delivery Challan % already invoiced by active invoice(s) %; reverse or cancel the invoice(s) before editing',
      v_challan.challan_number, v_blocking_invoices;
  END IF;

  FOR v_old_item IN
    SELECT *
    FROM public.delivery_challan_items
    WHERE challan_id = p_challan_id
    ORDER BY id
  LOOP
    PERFORM public.post_inventory_movement(
      public.uuid_from_text(
        'inventory-v1:dc-edit-reverse:' || p_operation_id || ':' ||
        v_old_item.id
      ),
      v_old_item.product_id,
      v_old_item.batch_id,
      'adjustment',
      v_old_item.quantity,
      CURRENT_DATE,
      v_challan.challan_number,
      'delivery_challan_edit_reversal',
      p_challan_id,
      'Canonical reversal before approved DC edit',
      auth.uid(),
      NULL,
      NULL
    );
  END LOOP;

  DELETE FROM public.delivery_challan_items
  WHERE challan_id = p_challan_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)
  LOOP
    v_item_id := COALESCE(
      NULLIF(v_item->>'id', '')::uuid,
      gen_random_uuid()
    );
    v_product_id := (v_item->>'product_id')::uuid;
    v_batch_id := (v_item->>'batch_id')::uuid;
    v_quantity := (v_item->>'quantity')::numeric;

    IF v_quantity <= 0 THEN
      RAISE EXCEPTION 'Delivery Challan item quantity must be greater than zero';
    END IF;

    INSERT INTO public.delivery_challan_items (
      id,
      challan_id,
      product_id,
      batch_id,
      sales_order_item_id,
      quantity,
      pack_size,
      pack_type,
      number_of_packs
    ) VALUES (
      v_item_id,
      p_challan_id,
      v_product_id,
      v_batch_id,
      NULLIF(v_item->>'sales_order_item_id', '')::uuid,
      v_quantity,
      NULLIF(v_item->>'pack_size', ''),
      NULLIF(v_item->>'pack_type', ''),
      NULLIF(v_item->>'number_of_packs', '')::integer
    );

    PERFORM public.post_inventory_movement(
      public.uuid_from_text(
        'inventory-v1:dc-edit-apply:' || p_operation_id || ':' || v_item_id
      ),
      v_product_id,
      v_batch_id,
      'sale',
      v_quantity,
      CURRENT_DATE,
      v_challan.challan_number,
      'delivery_challan',
      p_challan_id,
      'Canonical delivery challan edit application',
      auth.uid(),
      NULL,
      NULL
    );
  END LOOP;

  IF v_challan.sales_order_id IS NOT NULL THEN
    PERFORM public.fn_recompute_so_delivered(v_challan.sales_order_id);
    PERFORM public.fn_reserve_stock_for_so_v2(v_challan.sales_order_id);
    PERFORM public.fn_recompute_so_status(v_challan.sales_order_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'challan_id', p_challan_id,
    'operation_id', p_operation_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_toggle_user_status(p_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_id uuid;
  v_caller_role text;
  v_caller_active boolean;
  v_target_user record;
  v_other_admin_count integer;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, is_active INTO v_caller_role, v_caller_active
  FROM public.user_profiles
  WHERE id = v_caller_id;

  IF v_caller_role <> 'admin' OR v_caller_active IS NOT TRUE THEN
    RAISE EXCEPTION 'Only active administrators can modify user status';
  END IF;

  SELECT * INTO v_target_user
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  -- Prevent self-deactivation
  IF v_caller_id = p_user_id AND p_is_active IS FALSE THEN
    RAISE EXCEPTION 'You cannot deactivate your own account';
  END IF;

  -- Ensure at least one active admin remains
  IF v_target_user.role = 'admin' AND v_target_user.is_active IS TRUE AND p_is_active IS FALSE THEN
    SELECT COUNT(*) INTO v_other_admin_count
    FROM public.user_profiles
    WHERE role = 'admin' AND is_active IS TRUE AND id <> p_user_id;

    IF v_other_admin_count = 0 THEN
      RAISE EXCEPTION 'Cannot deactivate the last active administrator';
    END IF;
  END IF;

  UPDATE public.user_profiles
  SET is_active = p_is_active,
      updated_at = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'username', v_target_user.username,
    'is_active', p_is_active
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.allocate_import_costs_to_batches(p_container_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_container RECORD;
v_batch RECORD;
v_total_invoice_value DECIMAL(18,2);
v_total_import_cost DECIMAL(18,2);
v_linked_expenses_total DECIMAL(18,2);
v_linked_petty_cash_total DECIMAL(18,2);
v_broker_canonical_total DECIMAL(18,2);
v_allocation_percentage DECIMAL(10,6);
v_allocated_cost DECIMAL(18,2);
v_batches_allocated INTEGER := 0;
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot allocate import costs', v_role;
END IF;

SELECT * INTO v_container
FROM import_containers
WHERE id = p_container_id;

IF NOT FOUND THEN
RETURN json_build_object('success', false, 'error', 'Container not found');
END IF;

IF v_container.status != 'draft' THEN
RETURN json_build_object('success', false, 'error', 'Container already allocated or locked');
END IF;

-- Linked finance expenses (NULL = included, TRUE = included, FALSE = excluded)
-- For broker expenses, compute canonical accountingExpenseTotal in SQL
WITH canonical_expenses AS (
SELECT
fe.id,
fe.expense_category,
fe.amount,
fe.ppn_amount,
fe.stamp_duty_amount,
fe.broker_items,
CASE
WHEN fe.expense_category = 'import_broker' THEN
-- accountingExpenseTotal = brokerInvoiceAmount - headerPpn + sum(brokerLineExpenseBase) + stampDuty
-- brokerLineExpenseBase = brokerLineTotal - item.ppn_amount
-- brokerLineTotal = item.amount (when invoice_amount_authoritative) else amount != 0 ? amount : dpp + ppn
fe.amount - COALESCE(fe.ppn_amount, 0)
+ COALESCE((
SELECT SUM(
CASE
WHEN (item->>'invoice_amount_authoritative')::boolean = true
THEN (item->>'amount')::numeric
ELSE COALESCE(NULLIF((item->>'amount')::numeric, 0), (item->>'dpp_amount')::numeric + (item->>'ppn_amount')::numeric)
END
- COALESCE((item->>'ppn_amount')::numeric, 0)
)
FROM jsonb_array_elements(fe.broker_items) AS item
), 0)
+ COALESCE(fe.stamp_duty_amount, 0)
ELSE
COALESCE(fe.amount, 0)
END AS canonical_total
FROM finance_expenses fe
WHERE fe.import_container_id = p_container_id
AND fe.expense_category != 'pib_import'
AND COALESCE(fe.include_in_landed_cost, true) = true
)
SELECT COALESCE(SUM(canonical_total), 0) INTO v_linked_expenses_total
FROM canonical_expenses;

-- Linked petty cash (NULL = included, TRUE = included, FALSE = excluded)
SELECT COALESCE(SUM(amount), 0) INTO v_linked_petty_cash_total
FROM petty_cash_transactions
WHERE import_container_id = p_container_id
AND COALESCE(include_in_landed_cost, true) = true;

v_total_import_cost := v_linked_expenses_total + v_linked_petty_cash_total + COALESCE(v_container.other_import_costs, 0);

IF v_total_import_cost = 0 THEN
RETURN json_build_object('success', false, 'error', 'No import costs to allocate');
END IF;

SELECT COALESCE(SUM(import_price * import_quantity), 0) INTO v_total_invoice_value
FROM batches
WHERE import_container_id = p_container_id;

IF v_total_invoice_value = 0 THEN
RETURN json_build_object('success', false, 'error', 'No batches linked to this container');
END IF;

FOR v_batch IN
SELECT id, import_price, import_quantity, (import_price * import_quantity) as batch_invoice_value
FROM batches
WHERE import_container_id = p_container_id
AND COALESCE(cost_locked, false) = false
LOOP
v_allocation_percentage := (v_batch.batch_invoice_value / v_total_invoice_value) * 100;
v_allocated_cost := (v_total_import_cost * v_batch.batch_invoice_value) / v_total_invoice_value;

INSERT INTO import_container_allocations (
container_id, batch_id, batch_invoice_value,
allocation_percentage, allocated_cost, allocated_by
) VALUES (
p_container_id, v_batch.id, v_batch.batch_invoice_value,
v_allocation_percentage, v_allocated_cost, auth.uid()
)
ON CONFLICT (container_id, batch_id)
DO UPDATE SET
allocation_percentage = EXCLUDED.allocation_percentage,
allocated_cost = EXCLUDED.allocated_cost;

UPDATE batches
SET import_cost_allocated = v_allocated_cost,
final_landed_cost = import_price + v_allocated_cost,
cost_locked = true
WHERE id = v_batch.id;

v_batches_allocated := v_batches_allocated + 1;
END LOOP;

UPDATE import_containers
SET status = 'allocated',
locked_at = now(),
locked_by = auth.uid(),
allocated_expenses = v_total_import_cost
WHERE id = p_container_id;

RETURN json_build_object(
'success', true,
'batches_allocated', v_batches_allocated,
'total_cost', v_total_import_cost,
'linked_expenses_total', v_linked_expenses_total,
'linked_petty_cash_total', v_linked_petty_cash_total,
'other_import_costs', COALESCE(v_container.other_import_costs, 0),
'note', 'Canonical broker calculation; PIB excluded; NULL=included'
);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_batch_receipt_weighted_average(p_batch_id uuid, p_received_quantity numeric, p_receipt_unit_cost numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  b public.batches%ROWTYPE;
  prior_qty numeric;
  prior_cost numeric;
  new_cost numeric;
BEGIN
  SELECT * INTO b FROM public.batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR p_received_quantity <= 0 THEN RETURN; END IF;
  prior_qty := GREATEST(COALESCE(b.current_stock,0) - p_received_quantity, 0);
  prior_cost := COALESCE(NULLIF(b.landed_cost_per_unit,0), NULLIF(b.cost_per_unit,0), NULLIF(b.import_price,0), 0);
  new_cost := CASE WHEN prior_qty <= 0 THEN p_receipt_unit_cost
    ELSE ((prior_qty * prior_cost) + (p_received_quantity * p_receipt_unit_cost))
      / NULLIF(prior_qty + p_received_quantity,0) END;
  UPDATE public.batches
     SET cost_per_unit=round(new_cost,2), landed_cost_per_unit=round(new_cost,2), updated_at=now()
   WHERE id=p_batch_id AND COALESCE(cost_locked,false)=false;
END; $function$

CREATE OR REPLACE FUNCTION public.apply_credit_note_to_invoice(p_credit_note_id uuid, p_target_invoice_id uuid, p_amount numeric, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_target public.sales_invoices%ROWTYPE;
  v_role text;
  v_caller uuid := auth.uid();
  v_alloc_amount numeric(18,2);
  v_remaining_balance numeric(18,2);
  v_alloc_number text;
  v_target_outstanding numeric(18,2);
BEGIN
  -- Strict Authentication & Authorization check (prevent caller spoofing)
  IF v_caller IS NULL THEN
    IF current_user = 'service_role' OR session_user = 'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) OR (COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''), '')) = 'service_role' THEN
      v_caller := p_actor;
    ELSE
      RAISE EXCEPTION 'Authentication required: no active session';
    END IF;
  END IF;

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required: valid actor identity missing';
  END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'manager') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot apply credit notes', COALESCE(v_role, 'none');
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Application amount must be strictly positive (got %)', p_amount;
  END IF;

  -- Deterministic row locking on both credit note and target invoice
  SELECT * INTO v_cn FROM public.credit_notes WHERE id = p_credit_note_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit Note % not found', p_credit_note_id;
  END IF;

  IF v_cn.status <> 'approved' THEN
    RAISE EXCEPTION 'Cannot apply unapproved Credit Note %', v_cn.credit_note_number;
  END IF;

  IF COALESCE(v_cn.customer_credit_balance, 0) < p_amount THEN
    RAISE EXCEPTION 'Insufficient credit balance % on Credit Note % (Requested %)',
      v_cn.customer_credit_balance, v_cn.credit_note_number, p_amount;
  END IF;

  SELECT * INTO v_target FROM public.sales_invoices WHERE id = p_target_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target Sales Invoice % not found', p_target_invoice_id;
  END IF;

  IF NOT public.is_reportable_sales_invoice(v_target.document_status, v_target.is_draft, v_target.notes) THEN
    RAISE EXCEPTION 'Cannot apply credit to cancelled or draft invoice %', v_target.invoice_number;
  END IF;

  -- Enforce same customer matching
  IF v_target.customer_id <> v_cn.customer_id THEN
    RAISE EXCEPTION 'Customer mismatch: Credit Note customer does not match target invoice customer';
  END IF;

  v_target_outstanding := GREATEST(0, v_target.total_amount - COALESCE(v_target.paid_amount, 0));
  IF v_target_outstanding <= 0.01 THEN
    RAISE EXCEPTION 'Target invoice % has no outstanding balance', v_target.invoice_number;
  END IF;

  v_alloc_amount := LEAST(p_amount, v_target_outstanding);

  -- 1. Create uniquely referenced allocation record
  v_alloc_number := public.next_credit_note_allocation_number();
  INSERT INTO public.credit_note_allocations (
    allocation_number, credit_note_id, target_invoice_id, allocated_amount, notes, created_by
  ) VALUES (
    v_alloc_number, v_cn.id, v_target.id, v_alloc_amount,
    'Settlement of ' || v_target.invoice_number || ' via ' || v_cn.credit_note_number,
    v_caller
  );

  -- 2. Insert into voucher_allocations linking this settlement
  INSERT INTO public.voucher_allocations (
    voucher_type, sales_invoice_id, allocated_amount, status
  ) VALUES (
    'receipt', v_target.id, v_alloc_amount, 'approved'
  );

  v_remaining_balance := v_cn.customer_credit_balance - v_alloc_amount;

  -- 3. Update Credit Note
  UPDATE public.credit_notes
     SET customer_credit_balance = v_remaining_balance,
         applied_to_invoice_id = v_target.id,
         applied_amount = COALESCE(applied_amount, 0) + v_alloc_amount,
         settlement_status = CASE 
           WHEN v_remaining_balance <= 0.01 THEN 'applied_to_invoice'
           ELSE 'partially_allocated'
         END,
         updated_at = now()
   WHERE id = v_cn.id;

  -- 4. Recalculate target invoice payment state
  PERFORM public.recalculate_sales_invoice_payment_state(v_target.id);

  RETURN jsonb_build_object(
    'success', true,
    'allocation_number', v_alloc_number,
    'credit_note_id', v_cn.id,
    'credit_note_number', v_cn.credit_note_number,
    'target_invoice_number', v_target.invoice_number,
    'allocated_amount', v_alloc_amount,
    'remaining_credit_balance', v_remaining_balance
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_payment_allocation_rounding_adjustment(p_invoice_id uuid, p_payment_voucher_id uuid DEFAULT NULL::uuid, p_adjustment_type text DEFAULT 'rounding'::text, p_reason text DEFAULT 'invoice_rounding_tolerance'::text, p_amount numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invoice record;
  v_allocated numeric(18,2);
  v_residual numeric(18,2);
  v_tolerance numeric(18,2);
  v_existing record;
  v_entry_id uuid;
  v_entry_number text;
  v_ap_account_id uuid;
  v_adjustment_account_id uuid;
  v_user_id uuid;
  v_target_pv_id uuid;
  v_has_posted_allocations boolean := false;
  v_adj_amount numeric(18,2);
  v_adj_type text;
  v_adj_reason text;
  v_adjustment_date date;
BEGIN
  SELECT *
  INTO v_invoice
  FROM public.purchase_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Verify tolerance from settings
  SELECT COALESCE(rounding_tolerance_amount, 100)
  INTO v_tolerance
  FROM public.app_settings
  LIMIT 1;
  v_tolerance := COALESCE(v_tolerance, 100);

  -- Fetch existing adjustment for this purchase invoice
  SELECT *
  INTO v_existing
  FROM public.invoice_rounding_adjustments
  WHERE purchase_invoice_id = p_invoice_id
  LIMIT 1;

  -- Only POSTED payment voucher allocations count
  SELECT COALESCE(SUM(va.allocated_amount), 0)
  INTO v_allocated
  FROM public.voucher_allocations va
  JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
  WHERE va.purchase_invoice_id = p_invoice_id
    AND va.voucher_type = 'payment'
    AND pv.is_posted = true;

  SELECT EXISTS (
    SELECT 1
    FROM public.voucher_allocations va
    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
    WHERE va.purchase_invoice_id = p_invoice_id
      AND va.voucher_type = 'payment'
      AND pv.is_posted = true
  ) INTO v_has_posted_allocations;

  -- Target PV selection
  IF p_payment_voucher_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.payment_vouchers WHERE id = p_payment_voucher_id AND is_posted = true
  ) THEN
    v_target_pv_id := p_payment_voucher_id;
  ELSIF v_has_posted_allocations THEN
    SELECT pv.id INTO v_target_pv_id
    FROM public.voucher_allocations va
    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
    WHERE va.purchase_invoice_id = p_invoice_id
      AND va.voucher_type = 'payment'
      AND pv.is_posted = true
    ORDER BY pv.created_at DESC
    LIMIT 1;
  ELSE
    v_target_pv_id := NULL;
  END IF;

  -- Settlement adjustments belong to the payment voucher date, not the original invoice date.
  SELECT pv.voucher_date INTO v_adjustment_date
  FROM public.payment_vouchers pv
  WHERE pv.id = v_target_pv_id;
  v_adjustment_date := COALESCE(v_adjustment_date, CURRENT_DATE);

  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);

  -- Determine adjustment amount and type
  IF p_amount IS NOT NULL AND p_amount <> 0 THEN
    v_adj_amount := ROUND(p_amount, 2);
    v_adj_type := COALESCE(p_adjustment_type, 'rounding');
    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');
  ELSE
    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN
      v_adj_amount := v_residual;
      v_adj_type := COALESCE(p_adjustment_type, 'rounding');
      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');
    ELSE
      v_adj_amount := 0;
      v_adj_type := 'rounding';
      v_adj_reason := 'none';
    END IF;
  END IF;

  -- Tolerance validation for rounding
  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN
    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;
  END IF;

  -- Reason validation for discount or write-off
  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN
    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';
  END IF;

  -- Settle with posted payment activity
  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN
    -- If already correctly adjusted with identical amount and type, just ensure state sync and return
    IF v_existing.id IS NOT NULL
       AND v_existing.adjustment_amount = v_adj_amount
       AND v_existing.adjustment_type = v_adj_type THEN
      PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);
      RETURN;
    END IF;

    -- Clean up previous adjustment journal and record before replacing
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;

    -- AP Account 2110
    SELECT id INTO v_ap_account_id
    FROM public.chart_of_accounts
    WHERE code = '2110'
    LIMIT 1;

    -- Adjustment account selection
    IF v_adj_type = 'rounding' THEN
      IF v_adj_amount > 0 THEN
        SELECT COALESCE(
          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      ELSE
        SELECT COALESCE(
          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      END IF;
    ELSIF v_adj_type IN ('discount', 'write_off') THEN
      IF v_adj_amount > 0 THEN
        -- Supplier discount reduces AP, credited to Other Income / Purchase Discount (4900 / 4910)
        SELECT COALESCE(
          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '4910' LIMIT 1)
        ) INTO v_adjustment_account_id;
      ELSE
        SELECT id INTO v_adjustment_account_id
        FROM public.chart_of_accounts
        WHERE code = '6900'
        LIMIT 1;
      END IF;
    END IF;

    IF v_ap_account_id IS NULL OR v_adjustment_account_id IS NULL THEN
      RAISE EXCEPTION 'Missing COA setup for purchase invoice settlement adjustment';
    END IF;

    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);
    v_entry_number := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, total_debit, total_credit, is_posted, posted_by, created_by
    ) VALUES (
      v_entry_number,
      COALESCE(v_adjustment_date, CURRENT_DATE),
      'purchase_invoice_rounding',
      v_invoice.id,
      v_invoice.invoice_number,
      'Payment settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,
      ABS(v_adj_amount),
      ABS(v_adj_amount),
      true,
      v_user_id,
      v_user_id
    )
    RETURNING id INTO v_entry_id;

    IF v_adj_amount > 0 THEN
      -- Debit AP (clearing payable), Credit Rounding Gain / Purchase Discount (4900)
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
      VALUES
        (v_entry_id, 1, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),
        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);
    ELSE
      -- Debit Expense / Write-off (6900), Credit AP
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
      VALUES
        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),
        (v_entry_id, 2, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);
    END IF;

    INSERT INTO public.invoice_rounding_adjustments (
      payment_voucher_id, purchase_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by
    ) VALUES (
      v_target_pv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id
    );
  ELSE
    -- Residual is zero or exceeds tolerance or unposted: clear existing
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;
  END IF;

  PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_receipt_allocation_rounding_adjustment(p_invoice_id uuid, p_receipt_voucher_id uuid DEFAULT NULL::uuid, p_adjustment_type text DEFAULT 'rounding'::text, p_reason text DEFAULT 'invoice_rounding_tolerance'::text, p_amount numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invoice record;
  v_allocated numeric(18,2);
  v_residual numeric(18,2);
  v_tolerance numeric(18,2);
  v_existing record;
  v_entry_id uuid;
  v_entry_number text;
  v_ar_account_id uuid;
  v_adjustment_account_id uuid;
  v_user_id uuid;
  v_target_rv_id uuid;
  v_adjustment_date date;
  v_has_posted_allocations boolean := false;
  v_adj_amount numeric(18,2);
  v_adj_type text;
  v_adj_reason text;
BEGIN
  SELECT *
  INTO v_invoice
  FROM public.sales_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(rounding_tolerance_amount, 100)
  INTO v_tolerance
  FROM public.app_settings
  LIMIT 1;
  v_tolerance := COALESCE(v_tolerance, 100);

  SELECT *
  INTO v_existing
  FROM public.invoice_rounding_adjustments
  WHERE sales_invoice_id = p_invoice_id
  LIMIT 1;

  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);

  SELECT EXISTS (
    SELECT 1 
    FROM public.voucher_allocations va
    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id
    WHERE va.sales_invoice_id = p_invoice_id
      AND va.voucher_type = 'receipt'
      AND rv.is_posted = true
  ) INTO v_has_posted_allocations;

  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true
  ) THEN
    v_target_rv_id := p_receipt_voucher_id;
  ELSIF v_has_posted_allocations THEN
    SELECT rv.id INTO v_target_rv_id
    FROM public.voucher_allocations va
    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id
    WHERE va.sales_invoice_id = p_invoice_id
      AND va.voucher_type = 'receipt'
      AND rv.is_posted = true
    ORDER BY rv.created_at DESC
    LIMIT 1;
  ELSE
    v_target_rv_id := NULL;
  END IF;

  -- Settlement adjustments belong to the receipt voucher date, not the original invoice date.
  SELECT rv.voucher_date INTO v_adjustment_date
  FROM public.receipt_vouchers rv
  WHERE rv.id = v_target_rv_id;
  v_adjustment_date := COALESCE(v_adjustment_date, CURRENT_DATE);

  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);

  IF p_amount IS NOT NULL AND p_amount <> 0 THEN
    v_adj_amount := ROUND(p_amount, 2);
    v_adj_type := COALESCE(p_adjustment_type, 'rounding');
    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');
  ELSE
    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN
      v_adj_amount := v_residual;
      v_adj_type := COALESCE(p_adjustment_type, 'rounding');
      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');
    ELSE
      v_adj_amount := 0;
      v_adj_type := 'rounding';
      v_adj_reason := 'none';
    END IF;
  END IF;

  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN
    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;
  END IF;

  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN
    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';
  END IF;

  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN
    IF v_existing.id IS NOT NULL 
       AND v_existing.adjustment_amount = v_adj_amount 
       AND v_existing.adjustment_type = v_adj_type THEN
      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
      RETURN;
    END IF;

    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;

    -- AR Account 1120
    SELECT id INTO v_ar_account_id
    FROM public.chart_of_accounts
    WHERE code = '1120'
    LIMIT 1;

    IF v_adj_type = 'rounding' THEN
      IF v_adj_amount > 0 THEN
        -- Customer short payment under tolerance: write-off expense
        SELECT COALESCE(
          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      ELSE
        -- Customer overpayment under tolerance: rounding gain
        SELECT COALESCE(
          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      END IF;
    ELSIF v_adj_type IN ('discount', 'write_off') THEN
      IF v_adj_amount > 0 THEN
        -- Commercial sales discount granted: debit Sales Discounts (4200)
        SELECT COALESCE(
          (SELECT id FROM public.chart_of_accounts WHERE code = '4200' LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      ELSE
        SELECT id INTO v_adjustment_account_id
        FROM public.chart_of_accounts
        WHERE code = '4900'
        LIMIT 1;
      END IF;
    END IF;

    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN
      RAISE EXCEPTION 'Missing COA setup for sales invoice settlement adjustment';
    END IF;

    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);
    v_entry_number := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, total_debit, total_credit, is_posted, posted_by, created_by
    ) VALUES (
      v_entry_number,
      COALESCE(v_adjustment_date, CURRENT_DATE),
      'sales_invoice_rounding',
      v_invoice.id,
      v_invoice.invoice_number,
      'Receipt settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,
      ABS(v_adj_amount),
      ABS(v_adj_amount),
      true,
      v_user_id,
      v_user_id
    )
    RETURNING id INTO v_entry_id;

    IF v_adj_amount > 0 THEN
      -- Customer underpaid: Debit Sales Discount/Expense, Credit AR (1120)
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),
        (v_entry_id, 2, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);
    ELSE
      -- Customer overpaid: Debit AR (1120), Credit Gain
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),
        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);
    END IF;

    INSERT INTO public.invoice_rounding_adjustments (
      receipt_voucher_id, sales_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by
    ) VALUES (
      v_target_rv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id
    );
  ELSE
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;
  END IF;

  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_salary_advances_to_expense(p_salary_expense_id uuid, p_apply boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_salary public.finance_expenses%ROWTYPE;
  v_staff_name text;
  v_remaining numeric;
  v_total numeric := 0;
  v_settlement jsonb;
  v_settlement_id uuid;
  v_advance record;
  v_advance_applied numeric;
  v_available numeric;
  v_to_apply numeric;
  v_currency text;
  v_application_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_salary FROM public.finance_expenses WHERE id=p_salary_expense_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Salary expense not found'; END IF;
  IF v_salary.expense_category<>'salary' OR v_salary.staff_id IS NULL THEN
    RAISE EXCEPTION 'Salary advances require a Salary expense with a selected staff member';
  END IF;
  SELECT full_name INTO v_staff_name FROM public.finance_staff_master WHERE id=v_salary.staff_id;
  SELECT upper(COALESCE(v_salary.transaction_currency,v_salary.currency_code,'IDR')) INTO v_currency;

  SELECT greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-COALESCE(sum(applied_amount),0),0)
    INTO v_remaining FROM public.salary_advance_applications WHERE salary_expense_id=p_salary_expense_id;
  v_remaining:=COALESCE(v_remaining,greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0),0));
  IF NOT p_apply OR v_remaining<=0 THEN
    RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining);
  END IF;

  FOR v_advance IN
    SELECT pv.id,pv.voucher_number,pv.voucher_date,pv.amount
      FROM public.payment_vouchers pv
     WHERE pv.payment_purpose='salary_advance' AND pv.is_posted=true AND pv.staff_id=v_salary.staff_id
       AND NOT EXISTS(SELECT 1 FROM public.salary_advance_applications existing
         WHERE existing.advance_payment_voucher_id=pv.id AND existing.salary_expense_id=p_salary_expense_id)
     ORDER BY pv.voucher_date,pv.created_at,pv.id FOR UPDATE OF pv
  LOOP
    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied
      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;
    v_available:=greatest(v_advance.amount-v_advance_applied,0);
    v_to_apply:=least(v_available,v_remaining-v_total);
    IF v_to_apply>0 THEN
      v_total:=v_total+v_to_apply;
      v_application_ids:=array_append(v_application_ids,v_advance.id);
    END IF;
    EXIT WHEN v_total>=v_remaining;
  END LOOP;
  IF v_total<=0 THEN RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining); END IF;

  v_settlement:=public.save_payment_voucher_command(
    p_voucher_id=>NULL,
    p_payload=>jsonb_build_object(
      'voucher_date',v_salary.expense_date,'staff_id',v_salary.staff_id,
      'payment_method','advance_adjustment','amount',v_total,'payment_currency',v_currency,
      'exchange_rate',CASE WHEN v_currency='IDR' THEN 1 ELSE COALESCE(v_salary.exchange_rate,1) END,
      'description','Salary Advance Recovery - '||COALESCE(v_salary.voucher_number,v_salary.id::text),
      'created_by',auth.uid(),'document_urls','[]'::jsonb),
    p_allocations=>jsonb_build_array(jsonb_build_object(
      'finance_expense_id',v_salary.id,'amount',v_total,'currency',v_currency)),
    p_payment_purpose=>'salary_advance_settlement');
  v_settlement_id:=(v_settlement->>'id')::uuid;
  PERFORM public.post_payment_voucher(v_settlement_id,auth.uid());

  v_remaining:=v_total;
  FOR v_advance IN
    SELECT pv.id,pv.amount FROM public.payment_vouchers pv WHERE pv.id=ANY(v_application_ids)
     ORDER BY pv.voucher_date,pv.created_at,pv.id
  LOOP
    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied
      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;
    v_available:=greatest(v_advance.amount-v_advance_applied,0);
    v_to_apply:=least(v_available,v_remaining);
    IF v_to_apply>0 THEN
      INSERT INTO public.salary_advance_applications(
        advance_payment_voucher_id,salary_expense_id,settlement_payment_voucher_id,applied_amount)
      VALUES(v_advance.id,v_salary.id,v_settlement_id,v_to_apply);
      PERFORM public.refresh_salary_advance_status(v_advance.id);
      v_remaining:=v_remaining-v_to_apply;
    END IF;
    EXIT WHEN v_remaining<=0;
  END LOOP;
  RETURN jsonb_build_object(
    'applied',true,'total_applied',v_total,
    'remaining_salary',greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-v_total,0),
    'settlement_payment_voucher_id',v_settlement_id,
    'settlement_payment_voucher_number',v_settlement->>'voucher_number');
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_selected_salary_advances_to_expense(p_salary_expense_id uuid, p_advance_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_salary public.finance_expenses%ROWTYPE;
  v_remaining numeric;
  v_total numeric := 0;
  v_settlement jsonb;
  v_settlement_id uuid;
  v_advance record;
  v_advance_applied numeric;
  v_available numeric;
  v_take numeric;
  v_currency text;
  v_selected_ids uuid[] := ARRAY[]::uuid[];
  v_selected_amounts numeric[] := ARRAY[]::numeric[];
  v_selected_count integer := 0;
  v_idx integer;
  v_bpjs numeric := 0;
BEGIN
  PERFORM public._sec_check_finance_role();

  IF p_advance_ids IS NULL OR cardinality(p_advance_ids) = 0 THEN
    RETURN jsonb_build_object('applied', false, 'total_applied', 0, 'reason', 'No advances selected');
  END IF;

  IF cardinality(p_advance_ids) <> (
    SELECT count(DISTINCT selected_id)::integer FROM unnest(p_advance_ids) AS selected_id
  ) THEN
    RAISE EXCEPTION 'Duplicate advance IDs were supplied. Select each advance only once.';
  END IF;

  SELECT * INTO v_salary
    FROM public.finance_expenses
   WHERE id = p_salary_expense_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Salary expense not found';
  END IF;
  IF v_salary.expense_category <> 'salary' OR v_salary.staff_id IS NULL THEN
    RAISE EXCEPTION 'Salary advance settlements require a Salary expense with a selected staff member';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.salary_advance_applications
     WHERE salary_expense_id = p_salary_expense_id
  ) THEN
    RAISE EXCEPTION 'This salary already has advance applications. Reverse or review the existing settlement before applying more advances.';
  END IF;

  v_currency := upper(COALESCE(v_salary.transaction_currency, v_salary.currency_code, 'IDR'));

  -- Use the canonical salary calculation for the maximum deduction, but do NOT
  -- use its auto-derived advance total: only explicitly selected IDs are eligible.
  BEGIN
    v_bpjs := COALESCE(
      (public.calculate_staff_salary(v_salary.staff_id, v_salary.expense_date, v_salary.amount, v_salary.pph_amount)->>'bpjs_amount')::numeric,
      0
    );
  EXCEPTION WHEN OTHERS THEN
    v_bpjs := 0;
  END;

  v_remaining := GREATEST(v_salary.amount - COALESCE(v_salary.pph_amount, 0) - v_bpjs, 0);

  FOR v_advance IN
    SELECT pv.id, pv.voucher_number, pv.voucher_date, pv.amount
      FROM public.payment_vouchers pv
     WHERE pv.id = ANY(p_advance_ids)
       AND pv.payment_purpose = 'salary_advance'
       AND pv.is_posted = true
       AND pv.staff_id = v_salary.staff_id
       AND pv.voucher_date <= v_salary.expense_date
     ORDER BY pv.voucher_date, pv.created_at, pv.id
     FOR UPDATE OF pv
  LOOP
    v_selected_count := v_selected_count + 1;

    IF EXISTS (
      SELECT 1
        FROM public.salary_advance_applications sa
       WHERE sa.advance_payment_voucher_id = v_advance.id
         AND sa.salary_expense_id = p_salary_expense_id
    ) THEN
      RAISE EXCEPTION 'Advance % is already applied to this salary', v_advance.voucher_number;
    END IF;

    SELECT COALESCE(SUM(sa.applied_amount), 0)
      INTO v_advance_applied
      FROM public.salary_advance_applications sa
     WHERE sa.advance_payment_voucher_id = v_advance.id;

    v_available := GREATEST(v_advance.amount - v_advance_applied, 0);
    v_take := LEAST(v_available, GREATEST(v_remaining - v_total, 0));

    IF v_take > 0 THEN
      v_total := v_total + v_take;
      v_selected_ids := array_append(v_selected_ids, v_advance.id);
      v_selected_amounts := array_append(v_selected_amounts, v_take);
    END IF;
  END LOOP;

  IF v_selected_count <> cardinality(p_advance_ids) THEN
    RAISE EXCEPTION 'One or more selected advances are not posted, do not belong to this staff member, or are dated after the salary period. Refresh and select valid advances.';
  END IF;

  IF v_total <= 0 THEN
    RETURN jsonb_build_object('applied', false, 'total_applied', 0, 'reason', 'Selected advances have no available balance or salary has no payable balance');
  END IF;

  v_settlement := public.save_payment_voucher_command(
    p_voucher_id => NULL,
    p_payload => jsonb_build_object(
      'voucher_date', v_salary.expense_date,
      'staff_id', v_salary.staff_id,
      'payment_method', 'advance_adjustment',
      'amount', v_total,
      'payment_currency', v_currency,
      'exchange_rate', CASE WHEN v_currency = 'IDR' THEN 1 ELSE COALESCE(v_salary.exchange_rate, 1) END,
      'description', 'Salary Advance Recovery - ' || COALESCE(v_salary.voucher_number, v_salary.id::text),
      'created_by', auth.uid(),
      'document_urls', '[]'::jsonb
    ),
    p_allocations => jsonb_build_array(jsonb_build_object(
      'finance_expense_id', v_salary.id,
      'amount', v_total,
      'currency', v_currency
    )),
    p_payment_purpose => 'salary_advance_settlement'
  );

  v_settlement_id := (v_settlement->>'id')::uuid;
  PERFORM public.post_payment_voucher(v_settlement_id, auth.uid());

  FOR v_idx IN 1..COALESCE(array_length(v_selected_ids, 1), 0) LOOP
    INSERT INTO public.salary_advance_applications(
      advance_payment_voucher_id,
      salary_expense_id,
      settlement_payment_voucher_id,
      applied_amount
    )
    VALUES (
      v_selected_ids[v_idx],
      v_salary.id,
      v_settlement_id,
      v_selected_amounts[v_idx]
    );

    PERFORM public.refresh_salary_advance_status(v_selected_ids[v_idx]);
  END LOOP;

  RETURN jsonb_build_object(
    'applied', true,
    'total_applied', v_total,
    'remaining_salary', GREATEST(v_salary.amount - COALESCE(v_salary.pph_amount, 0) - v_bpjs - v_total, 0),
    'settlement_payment_voucher_id', v_settlement_id,
    'settlement_payment_voucher_number', v_settlement->>'voucher_number',
    'advance_ids_applied', to_jsonb(v_selected_ids)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_so_allocation_rounding_adjustment(p_so_id uuid, p_receipt_voucher_id uuid, p_adjustment_type text DEFAULT 'rounding'::text, p_reason text DEFAULT 'invoice_rounding_tolerance'::text, p_amount numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_so RECORD;
  v_tolerance numeric;
  v_existing RECORD;
  v_allocated numeric;
  v_residual numeric;
  v_target_rv_id uuid;
  v_has_posted_allocations boolean := false;
  v_adj_amount numeric(18,2);
  v_adj_type text;
  v_adj_reason text;
  v_voucher_date date;
  v_ar_account_id uuid;
  v_adjustment_account_id uuid;
  v_user_id uuid;
  v_entry_number text;
  v_entry_id uuid;
BEGIN
  SELECT *
  INTO v_so
  FROM public.sales_orders
  WHERE id = p_so_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(rounding_tolerance_amount, 100)
  INTO v_tolerance
  FROM public.app_settings
  LIMIT 1;
  v_tolerance := COALESCE(v_tolerance, 100);

  SELECT *
  INTO v_existing
  FROM public.invoice_rounding_adjustments
  WHERE sales_order_id = p_so_id
  LIMIT 1;

  SELECT COALESCE(SUM(allocated_amount), 0)
  INTO v_allocated
  FROM public.voucher_allocations
  WHERE sales_order_id = p_so_id
    AND voucher_type = 'receipt';

  SELECT EXISTS (
    SELECT 1 
    FROM public.voucher_allocations va
    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id
    WHERE va.sales_order_id = p_so_id
      AND va.voucher_type = 'receipt'
      AND rv.is_posted = true
  ) INTO v_has_posted_allocations;

  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true
  ) THEN
    v_target_rv_id := p_receipt_voucher_id;
  ELSIF v_has_posted_allocations THEN
    SELECT rv.id INTO v_target_rv_id
    FROM public.voucher_allocations va
    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id
    WHERE va.sales_order_id = p_so_id
      AND va.voucher_type = 'receipt'
      AND rv.is_posted = true
    ORDER BY rv.created_at DESC
    LIMIT 1;
  ELSE
    v_target_rv_id := NULL;
  END IF;

  IF v_target_rv_id IS NOT NULL THEN
    SELECT voucher_date INTO v_voucher_date
    FROM public.receipt_vouchers
    WHERE id = v_target_rv_id;
  END IF;

  v_residual := ROUND(COALESCE(v_so.total_amount, 0) - COALESCE(v_allocated, 0), 2);

  IF p_amount IS NOT NULL AND p_amount <> 0 THEN
    v_adj_amount := ROUND(p_amount, 2);
    v_adj_type := COALESCE(p_adjustment_type, 'rounding');
    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');
  ELSE
    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN
      v_adj_amount := v_residual;
      v_adj_type := COALESCE(p_adjustment_type, 'rounding');
      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');
    ELSE
      v_adj_amount := 0;
      v_adj_type := 'rounding';
      v_adj_reason := 'none';
    END IF;
  END IF;

  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN
    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;
  END IF;

  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN
    IF v_existing.id IS NOT NULL 
       AND v_existing.adjustment_amount = v_adj_amount 
       AND v_existing.adjustment_type = v_adj_type THEN
      IF v_existing.journal_entry_id IS NOT NULL AND v_voucher_date IS NOT NULL THEN
        UPDATE public.journal_entries
        SET entry_date = v_voucher_date
        WHERE id = v_existing.journal_entry_id AND entry_date <> v_voucher_date;
      END IF;
      RETURN;
    END IF;

    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;

    -- AR / Advance Account 1120
    SELECT id INTO v_ar_account_id
    FROM public.chart_of_accounts
    WHERE code = '1120'
    LIMIT 1;

    IF v_adj_type = 'rounding' THEN
      IF v_adj_amount > 0 THEN
        -- Short payment under tolerance: write-off expense
        SELECT COALESCE(
          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      ELSE
        -- Overpayment under tolerance: rounding gain
        SELECT COALESCE(
          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),
          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)
        ) INTO v_adjustment_account_id;
      END IF;
    ELSIF v_adj_type IN ('discount', 'write_off') THEN
      SELECT COALESCE(
        (SELECT id FROM public.chart_of_accounts WHERE code = '4200' LIMIT 1),
        (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)
      ) INTO v_adjustment_account_id;
    END IF;

    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN
      RAISE EXCEPTION 'Missing COA setup for sales order settlement adjustment';
    END IF;

    v_user_id := COALESCE(auth.uid(), v_so.created_by);
    v_entry_number := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, total_debit, total_credit, is_posted, posted_by, created_by
    ) VALUES (
      v_entry_number,
      COALESCE(v_voucher_date, CURRENT_DATE),
      'sales_order_rounding',
      v_so.id,
      v_so.so_number,
      'Receipt settlement ' || v_adj_type || ' adjustment: ' || v_so.so_number,
      ABS(v_adj_amount),
      ABS(v_adj_amount),
      true,
      v_user_id,
      v_user_id
    )
    RETURNING id INTO v_entry_id;

    IF v_adj_amount > 0 THEN
      -- Customer underpaid: Debit Rounding Expense (6900) or Discount (4200), Credit AR (1120)
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_so.so_number, ABS(v_adj_amount), 0, v_so.customer_id),
        (v_entry_id, 2, v_ar_account_id, 'SO advance clearance - ' || v_so.so_number, 0, ABS(v_adj_amount), v_so.customer_id);
    ELSE
      -- Customer overpaid: Debit AR (1120), Credit Rounding Gain (4900)
      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
      VALUES
        (v_entry_id, 1, v_ar_account_id, 'SO advance clearance - ' || v_so.so_number, ABS(v_adj_amount), 0, v_so.customer_id),
        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_so.so_number, 0, ABS(v_adj_amount), v_so.customer_id);
    END IF;

    INSERT INTO public.invoice_rounding_adjustments (
      receipt_voucher_id, sales_order_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by
    ) VALUES (
      v_target_rv_id, p_so_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id
    );
  ELSE
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;
    IF v_existing.id IS NOT NULL THEN
      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_finance_expense(p_expense_id uuid, p_approved_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_exp public.finance_expenses%rowtype;
  v_line public.bank_statement_lines%rowtype;
  v_exp_currency text;
  v_bank_currency text;
  v_payable numeric;
  v_allocate numeric;
  v_period_status text;
  v_je_exists boolean;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  SELECT * INTO v_exp FROM public.finance_expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found';
  END IF;

  -- Mandatory validation: Tax expenses cannot be approved without a valid party
  IF (COALESCE(v_exp.ppn_amount, 0) > 0 OR COALESCE(v_exp.pph_amount, 0) > 0)
     AND COALESCE(v_exp.expense_category, '') <> 'pib_import' THEN
    IF v_exp.supplier_id IS NULL AND v_exp.payee_id IS NULL AND v_exp.staff_id IS NULL THEN
      RAISE EXCEPTION 'Cannot approve tax expense % without selecting a valid Supplier, Payee, or Staff member.',
        COALESCE(v_exp.voucher_number, p_expense_id::text)
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF v_exp.approval_status IS DISTINCT FROM 'approved' THEN
    UPDATE public.finance_expenses
       SET approval_status = 'approved',
           approved_by = COALESCE(p_approved_by, auth.uid()),
           approved_at = now(),
           rejection_reason = NULL
     WHERE id = p_expense_id;

    -- Refresh row state after trigger_auto_post_expense_accounting_update fires
    SELECT * INTO v_exp FROM public.finance_expenses WHERE id = p_expense_id;
  END IF;

  -- Confirm accounting journal was successfully posted for this approved expense
  SELECT EXISTS (
    SELECT 1 FROM public.journal_entries
     WHERE source_module IN ('expense', 'expenses')
       AND (reference_id = p_expense_id OR reference_number = 'EXP-' || p_expense_id::text)
       AND is_posted = true AND NOT COALESCE(is_reversed, false)
  ) INTO v_je_exists;

  -- Auto-reconcile originating or matched bank statement line if linked
  IF v_je_exists THEN
    FOR v_line IN
      SELECT *
        FROM public.bank_statement_lines
       WHERE (matched_expense_id = p_expense_id OR id = v_exp.originating_bank_statement_line_id)
         AND matching_status IN ('suggested', 'none')
         AND reconciliation_status <> 'reconciled'
       ORDER BY transaction_date ASC, created_at ASC
       FOR UPDATE
    LOOP
      IF EXISTS (
        SELECT 1 FROM public.bank_statement_allocations
         WHERE bank_statement_line_id = v_line.id
           AND document_type = 'expense'
           AND document_id = p_expense_id
      ) THEN
        PERFORM public.refresh_bank_statement_allocation_status(v_line.id);
        CONTINUE;
      END IF;

      IF COALESCE(v_line.debit_amount, 0) <= 0 THEN
        UPDATE public.bank_statement_lines
           SET notes = COALESCE(notes, '') || ' [Auto-reconciliation skipped: bank transaction is not an outgoing debit]'
         WHERE id = v_line.id;
        CONTINUE;
      END IF;

      IF v_exp.bank_account_id IS NOT NULL AND v_exp.bank_account_id <> v_line.bank_account_id THEN
        UPDATE public.bank_statement_lines
           SET notes = COALESCE(notes, '') || ' [Auto-reconciliation skipped: bank account mismatch]'
         WHERE id = v_line.id;
        CONTINUE;
      END IF;

      v_exp_currency := upper(COALESCE(v_exp.transaction_currency, v_exp.currency_code, 'IDR'));
      SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id = v_line.bank_account_id;
      IF COALESCE(v_bank_currency, 'IDR') <> v_exp_currency THEN
        UPDATE public.bank_statement_lines
           SET notes = COALESCE(notes, '') || ' [Auto-reconciliation skipped: currency mismatch]'
         WHERE id = v_line.id;
        CONTINUE;
      END IF;

      v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id), 0);
      IF v_payable <= 0.01 THEN
        CONTINUE;
      END IF;

      v_allocate := LEAST(v_line.debit_amount, v_payable);

      SELECT ap.status INTO v_period_status
        FROM public.accounting_periods ap
       WHERE ap.start_date <= v_line.transaction_date AND ap.end_date >= v_line.transaction_date
       ORDER BY ap.start_date DESC LIMIT 1;

      IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
        UPDATE public.bank_statement_lines
           SET notes = COALESCE(notes, '') || ' [Auto-reconciliation pending: closed accounting period]'
         WHERE id = v_line.id;
        CONTINUE;
      END IF;

      BEGIN
        PERFORM public.link_bank_statement_line(
          v_line.id,
          'expense',
          p_expense_id,
          COALESCE(v_line.payment_kind, 'supplier'),
          v_allocate
        );
      EXCEPTION WHEN OTHERS THEN
        UPDATE public.bank_statement_lines
           SET notes = COALESCE(notes, '') || ' [Auto-reconciliation pending: ' || SQLERRM || ']'
         WHERE id = v_line.id;
      END;
    END LOOP;
  END IF;

  RETURN p_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_status text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_status <> 'pending_approval' THEN RAISE EXCEPTION 'Purchase Invoice must be pending approval'; END IF;
  UPDATE public.purchase_invoices SET receiving_approval_status='approved', receiving_approved_at=now(), receiving_approved_by=auth.uid(), updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','approved');
END; $function$

CREATE OR REPLACE FUNCTION public.approve_sales_order_inventory_v1(p_so_id uuid, p_approved_by uuid)
 RETURNS TABLE(success boolean, message text, shortage_items jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_previous_context text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for Sales Order approval';
  END IF;

  v_previous_context := current_setting('app.canonical_reservation_engine', true);
  PERFORM set_config('app.canonical_reservation_engine', 'on', true);

  UPDATE public.sales_orders
  SET status = 'approved',
      approved_by = COALESCE(p_approved_by, auth.uid()),
      approved_at = now(),
      updated_at = now()
  WHERE id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order not found';
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.fn_reserve_stock_for_so_v2(p_so_id);

  PERFORM set_config(
    'app.canonical_reservation_engine',
    COALESCE(v_previous_context, ''),
    true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_sales_order_product_reservation_v2(p_so_id uuid, p_approved_by uuid)
 RETURNS TABLE(success boolean, message text, shortage_items jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_so record;
  r record;
  v_delivered numeric;
  v_item_required numeric;
  v_reserved numeric;
  v_shortage_qty numeric;
  v_shortage_list jsonb := '[]'::jsonb;
  v_has_shortage boolean := false;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse'])
     AND current_setting('app.canonical_reservation_engine', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'Permission denied for SO product reservation approval';
  END IF;

  SELECT * INTO v_so FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order not found';
  END IF;

  -- Guard: If IDR Sales Order has any line with quoted_usd_unit_price > 0, commercial_usd_to_idr_rate must be provided before approval
  IF v_so.currency = 'IDR' AND (v_so.commercial_usd_to_idr_rate IS NULL OR v_so.commercial_usd_to_idr_rate <= 0) THEN
    IF EXISTS (
      SELECT 1 FROM public.sales_order_items
      WHERE sales_order_id = p_so_id
        AND quoted_usd_unit_price IS NOT NULL
        AND quoted_usd_unit_price > 0
    ) THEN
      RAISE EXCEPTION 'Set the commercial USD→IDR exchange rate before approving this Sales Order.';
    END IF;
  END IF;

  PERFORM set_config('app.canonical_reservation_engine', 'on', true);

  UPDATE public.sales_orders
  SET approved_by = COALESCE(p_approved_by, auth.uid()),
      approved_at = COALESCE(approved_at, now())
  WHERE id = p_so_id;

  FOR r IN
    SELECT id, product_id, quantity
    FROM public.sales_order_items
    WHERE sales_order_id = p_so_id
    ORDER BY product_id, id
  LOOP
    v_reserved := public.reconcile_so_product_reservation_v2(r.id, 'SO approval/re-approval');

    SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered
    FROM public.delivery_challan_items dci
    JOIN public.delivery_challans dc ON dc.id = dci.challan_id
    WHERE dci.sales_order_item_id = r.id
      AND dc.approval_status = 'approved';

    v_item_required := GREATEST(r.quantity - v_delivered, 0);

    IF v_item_required > v_reserved THEN
      v_has_shortage := true;
      v_shortage_qty := v_item_required - v_reserved;
      v_shortage_list := v_shortage_list || jsonb_build_object(
        'product_id', r.product_id,
        'required_qty', r.quantity,
        'shortage_qty', v_shortage_qty
      );
    END IF;
  END LOOP;

  IF v_has_shortage THEN
    UPDATE public.sales_orders
    SET status = 'shortage',
        updated_at = now()
    WHERE id = p_so_id;

    PERFORM public.fn_create_import_requirements(p_so_id, v_shortage_list);

    RETURN QUERY
    SELECT false, 'Partial stock reserved - shortage exists.'::text, v_shortage_list;
  ELSE
    UPDATE public.sales_orders
    SET status = 'stock_reserved',
        updated_at = now()
    WHERE id = p_so_id;

    -- Cancel any pending import requirements for this SO
    UPDATE public.import_requirements
    SET status = 'cancelled',
        notes = COALESCE(notes || ' | ', '') ||
          'Auto-cancelled: shortage resolved by stock reservation ' ||
          to_char(now(), 'YYYY-MM-DD'),
        updated_at = now()
    WHERE sales_order_id = p_so_id
      AND status = 'pending';

    RETURN QUERY
    SELECT true, 'Stock fully reserved'::text, '[]'::jsonb;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_batch_inventory_v1(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch public.batches%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.inventory_v1_actor_allowed(
    ARRAY['admin', 'accounts', 'warehouse']
  ) THEN
    RAISE EXCEPTION 'Permission denied for batch archive';
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', 'Batch not found'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stock_reservations
    WHERE batch_id = p_batch_id
      AND status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', format(
        'Batch %s has active reservations and cannot be archived',
        v_batch.batch_number
      )
    );
  END IF;

  IF v_batch.current_stock <> 0 THEN
    RETURN jsonb_build_object(
      'archived', false,
      'reason', format(
        'Batch %s still has stock %s. Post a canonical adjustment to zero before archiving',
        v_batch.batch_number,
        v_batch.current_stock
      )
    );
  END IF;

  UPDATE public.batches
  SET is_active = false,
      updated_at = now()
  WHERE id = p_batch_id;

  RETURN jsonb_build_object(
    'archived', true,
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_old_records()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
v_notifications_deleted integer := 0;
v_gmail_deleted integer := 0;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin') THEN
RAISE EXCEPTION 'Permission denied: only admin can archive old records';
END IF;

DELETE FROM notifications
WHERE is_read = true
AND created_at < now() - interval '90 days';
GET DIAGNOSTICS v_notifications_deleted = ROW_COUNT;

DELETE FROM notifications
WHERE is_read = false
AND created_at < now() - interval '180 days';

DELETE FROM gmail_processed_messages
WHERE created_at < now() - interval '60 days';
GET DIAGNOSTICS v_gmail_deleted = ROW_COUNT;

RETURN jsonb_build_object(
'notifications_deleted', v_notifications_deleted,
'gmail_processed_deleted', v_gmail_deleted,
'archived_at', now()
);
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_faktur_pajak_number(p_sales_invoice_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_settings   organization_tax_settings%ROWTYPE;
  v_number     text;
  v_next       int;
  v_invoice    sales_invoices%ROWTYPE;
  v_lock_id    bigint;
  v_period_id  uuid;
  v_dpp        numeric(18,2);
  v_ppn        numeric(18,2);
BEGIN
  -- Serialize faktur-number issuance across concurrent callers
  v_lock_id := hashtext('faktur_pajak_seq');
  PERFORM pg_advisory_xact_lock(v_lock_id);

  SELECT * INTO v_settings FROM organization_tax_settings ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_tax_settings not configured — cannot issue Faktur Pajak';
  END IF;
  IF v_settings.pkp_status = false THEN
    RAISE EXCEPTION 'Organization is not PKP — cannot issue Faktur Pajak';
  END IF;

  SELECT * INTO v_invoice FROM sales_invoices WHERE id = p_sales_invoice_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales invoice % not found', p_sales_invoice_id;
  END IF;
  IF v_invoice.faktur_pajak_number IS NOT NULL AND v_invoice.faktur_pajak_number <> '' THEN
    -- Idempotent: return the existing number
    RETURN v_invoice.faktur_pajak_number;
  END IF;

  v_next := COALESCE(v_settings.faktur_current_number, 0) + 1;

  v_number := COALESCE(v_settings.faktur_prefix, '000') || '.' ||
              lpad(v_next::text, 8, '0') || '-' ||
              to_char(COALESCE(v_invoice.invoice_date, CURRENT_DATE), 'YY');

  UPDATE organization_tax_settings
    SET faktur_current_number = v_next, updated_at = now()
    WHERE id = v_settings.id;

  UPDATE sales_invoices
    SET faktur_pajak_number = v_number,
        updated_at = now()
    WHERE id = p_sales_invoice_id;

  -- Attribute invoice to its PPN tax_period (idempotent upsert)
  v_period_id := upsert_tax_period(
    EXTRACT(YEAR  FROM v_invoice.invoice_date)::int,
    EXTRACT(MONTH FROM v_invoice.invoice_date)::int,
    'PPN'
  );
  UPDATE sales_invoices SET tax_period_id = v_period_id WHERE id = p_sales_invoice_id;

  -- Derive DPP + PPN split from tax_amount (Indonesian PPN 11%)
  v_ppn := COALESCE(v_invoice.tax_amount, 0);
  v_dpp := GREATEST(COALESCE(v_invoice.total_amount, 0) - v_ppn, 0);

  INSERT INTO faktur_pajak
    (sales_invoice_id, tax_period_id, faktur_number, issue_date,
     customer_id, dpp_amount, ppn_amount, status, created_by)
  VALUES
    (p_sales_invoice_id, v_period_id, v_number,
     COALESCE(v_invoice.invoice_date, CURRENT_DATE),
     v_invoice.customer_id, v_dpp, v_ppn, 'generated', auth.uid())
  ON CONFLICT (sales_invoice_id) DO UPDATE SET
    faktur_number = EXCLUDED.faktur_number,
    tax_period_id = EXCLUDED.tax_period_id,
    dpp_amount    = EXCLUDED.dpp_amount,
    ppn_amount    = EXCLUDED.ppn_amount,
    updated_at    = now();

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'faktur_pajak', 'insert', p_sales_invoice_id,
          jsonb_build_object('faktur_number', v_number, 'sales_invoice_id', p_sales_invoice_id));

  RETURN v_number;
END $function$

CREATE OR REPLACE FUNCTION public.audit_fund_transfer_repair_eligibility(p_fund_transfer_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  t public.fund_transfers%ROWTYPE;
  j public.journal_entries%ROWTYPE;
  from_coa uuid;
  to_coa uuid;
  from_currency text;
  to_currency text;
  expected_rate numeric;
  candidate_count integer;
  line_count integer;
BEGIN
  SELECT * INTO t FROM public.fund_transfers WHERE id = p_fund_transfer_id;
  IF NOT FOUND THEN RETURN 'Fund Transfer record is missing'; END IF;
  IF t.status <> 'posted' THEN RETURN 'Fund Transfer is not posted'; END IF;
  IF t.journal_entry_id IS NULL THEN RETURN 'Posted Fund Transfer has no linked journal'; END IF;

  SELECT * INTO j FROM public.journal_entries WHERE id = t.journal_entry_id;
  IF NOT FOUND OR NOT COALESCE(j.is_posted, false) OR COALESCE(j.is_reversed, false)
     THEN RETURN 'Linked journal is missing, unposted, or reversed'; END IF;
  IF j.source_module NOT IN ('fund_transfer', 'fund_transfers')
     OR j.reference_id IS DISTINCT FROM t.id
     THEN RETURN 'Journal source relationship does not prove this Fund Transfer'; END IF;

  IF t.from_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO from_coa, from_currency
      FROM public.bank_accounts WHERE id = t.from_bank_account_id AND is_active;
  ELSIF t.from_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts
      WHERE code = '1102' AND is_active LIMIT 1;
  ELSE
    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts
      WHERE code = '1101' AND is_active LIMIT 1;
  END IF;
  IF t.to_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO to_coa, to_currency
      FROM public.bank_accounts WHERE id = t.to_bank_account_id AND is_active;
  ELSIF t.to_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts
      WHERE code = '1102' AND is_active LIMIT 1;
  ELSE
    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts
      WHERE code = '1101' AND is_active LIMIT 1;
  END IF;
  IF from_coa IS NULL OR to_coa IS NULL OR from_currency IS NULL OR to_currency IS NULL
     THEN RETURN 'Fund Transfer account or currency cannot be derived'; END IF;
  IF t.from_amount IS NULL OR t.to_amount IS NULL OR t.exchange_rate IS NULL
     THEN RETURN 'Fund Transfer is missing an amount or exchange rate'; END IF;

  expected_rate := CASE
    WHEN from_currency = to_currency THEN 1
    WHEN from_currency = 'IDR' AND t.to_amount > 0 THEN t.from_amount / t.to_amount
    WHEN to_currency = 'IDR' AND t.from_amount > 0 THEN t.to_amount / t.from_amount
  END;
  IF expected_rate IS NULL OR abs(t.exchange_rate - expected_rate) > 0.000001
     THEN RETURN 'Fund Transfer exchange rate is inconsistent with its stored amounts'; END IF;
  -- This is the known unsafe legacy shape: the USD source amount was stored
  -- in functional journal columns. Do not silently reinterpret posted values.
  IF from_currency = 'USD' AND to_currency = 'IDR'
     THEN RETURN 'Legacy USD-source transfer has a functional accounting inconsistency'; END IF;

  SELECT count(*) INTO line_count FROM public.journal_entry_lines WHERE journal_entry_id = j.id;
  IF line_count <> 2
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=1 AND COALESCE(debit,0)>0 AND COALESCE(credit,0)=0)
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=2 AND COALESCE(credit,0)>0 AND COALESCE(debit,0)=0)
     THEN RETURN 'Posted journal is not a safe two-line transfer'; END IF;
  IF abs(COALESCE(j.total_debit,0) - t.from_amount) > 0.01
     OR abs(COALESCE(j.total_credit,0) - t.from_amount) > 0.01
     OR EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=j.id
       AND ((l.line_number=1 AND abs(COALESCE(l.debit,0)-t.from_amount)>0.01)
         OR (l.line_number=2 AND abs(COALESCE(l.credit,0)-t.from_amount)>0.01)))
     THEN RETURN 'Posted journal debit/credit values do not match the Fund Transfer'; END IF;

  -- The Fund Transfer may name a statement line, but this audit never changes
  -- that row. A missing link is only eligible when there is no ambiguity; a
  -- multiple-match case is always left for manual review.
  IF t.from_account_type = 'bank' AND t.from_bank_statement_line_id IS NULL THEN
    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b
      WHERE b.bank_account_id=t.from_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8
        AND (COALESCE(b.debit_amount,0)=t.from_amount OR COALESCE(b.credit_amount,0)=t.from_amount);
    IF candidate_count > 1 THEN RETURN 'Multiple possible From Bank transactions; no link was guessed'; END IF;
  END IF;
  IF t.to_account_type = 'bank' AND t.to_bank_statement_line_id IS NULL THEN
    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b
      WHERE b.bank_account_id=t.to_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8
        AND (COALESCE(b.debit_amount,0)=t.to_amount OR COALESCE(b.credit_amount,0)=t.to_amount);
    IF candidate_count > 1 THEN RETURN 'Multiple possible To Bank transactions; no link was guessed'; END IF;
  END IF;

  -- Explicit links are audited for consistency but never updated.
  IF t.from_bank_statement_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.bank_statement_lines b
    WHERE b.id=t.from_bank_statement_line_id AND b.bank_account_id=t.from_bank_account_id
      AND COALESCE(b.debit_amount,0)=t.from_amount
  ) THEN RETURN 'From Bank statement link does not match the Fund Transfer source'; END IF;
  IF t.to_bank_statement_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.bank_statement_lines b
    WHERE b.id=t.to_bank_statement_line_id AND b.bank_account_id=t.to_bank_account_id
      AND COALESCE(b.credit_amount,0)=t.to_amount
  ) THEN RETURN 'To Bank statement link does not match the Fund Transfer source'; END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.authorize_tax_period_amendment(p_tax_period_id uuid, p_reason text, p_duration_minutes integer DEFAULT 15)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_auth_id UUID;
    v_is_admin BOOLEAN := false;
BEGIN
    -- Verify administrator privilege
    IF (current_setting('request.jwt.claim.role', true) = 'service_role') THEN
        v_is_admin := true;
    ELSIF auth.uid() IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1 FROM public.user_profiles up
            WHERE up.id = auth.uid() AND up.role IN ('admin', 'super_admin')
        ) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
        RAISE EXCEPTION 'Unauthorized: Only system administrators can authorize amendments to filed tax periods.'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF TRIM(COALESCE(p_reason, '')) = '' THEN
        RAISE EXCEPTION 'An explicit justification reason is required to authorize a tax period amendment.'
            USING ERRCODE = 'check_violation';
    END IF;

    INSERT INTO public.tax_period_amendment_authorizations (
        tax_period_id, authorized_by, reason, expires_at
    ) VALUES (
        p_tax_period_id,
        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid),
        p_reason,
        now() + (GREATEST(1, LEAST(120, p_duration_minutes)) || ' minutes')::interval
    ) RETURNING id INTO v_auth_id;

    RETURN v_auth_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_bank_account_book_balance(p_bank_account_id uuid, p_as_of_date date DEFAULT CURRENT_DATE)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_opening numeric := 0;
  v_coa_id uuid;
  v_currency text;
  v_opening_date date;
  v_debits numeric := 0;
  v_credits numeric := 0;
BEGIN
  SELECT COALESCE(opening_balance, 0),
         coa_id,
         upper(COALESCE(currency, 'IDR')),
         COALESCE(opening_balance_date, DATE '1900-01-01')
    INTO v_opening, v_coa_id, v_currency, v_opening_date
    FROM public.bank_accounts
   WHERE id = p_bank_account_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF p_as_of_date < v_opening_date THEN
    RETURN 0;
  END IF;

  IF v_coa_id IS NULL THEN
    RETURN v_opening;
  END IF;

  IF v_currency = 'USD' THEN
    SELECT COALESCE(SUM(jel.transaction_debit), 0),
           COALESCE(SUM(jel.transaction_credit), 0)
      INTO v_debits, v_credits
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
     WHERE jel.account_id = v_coa_id
       AND je.is_posted = true
       AND NOT COALESCE(je.is_reversed, false)
       AND je.entry_date >= v_opening_date
       AND je.entry_date <= p_as_of_date
       AND jel.transaction_currency = 'USD'
       AND jel.functional_currency = 'IDR'
       AND COALESCE(jel.exchange_rate, 0) > 0;
  ELSE
    SELECT COALESCE(SUM(jel.debit), 0),
           COALESCE(SUM(jel.credit), 0)
      INTO v_debits, v_credits
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
     WHERE jel.account_id = v_coa_id
       AND je.is_posted = true
       AND NOT COALESCE(je.is_reversed, false)
       AND je.entry_date >= v_opening_date
       AND je.entry_date <= p_as_of_date;
  END IF;

  RETURN ROUND(v_opening + v_debits - v_credits, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_rejection_financial_loss(p_rejection_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
v_loss decimal;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'warehouse') THEN
RAISE EXCEPTION 'Permission denied: role % cannot calculate rejection financial loss', v_role;
END IF;

SELECT sr.quantity * b.purchase_price INTO v_loss
FROM stock_rejections sr
JOIN batches b ON b.id = sr.batch_id
WHERE sr.id = p_rejection_id;

RETURN COALESCE(v_loss, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_staff_bpjs(p_staff_id uuid, p_wage_override numeric DEFAULT NULL::numeric, p_period_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_staff public.finance_staff_master%ROWTYPE;
  v_wage numeric;
  v_is_discrepant boolean := false;
  v_emp_jht numeric := 0;
  v_emp_jp numeric := 0;
  v_emp_deduction numeric := 0;
  v_er_jht numeric := 0;
  v_er_jkk numeric := 0;
  v_er_jkm numeric := 0;
  v_er_jp numeric := 0;
  v_er_expense numeric := 0;
  v_total_payable numeric := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    PERFORM public._sec_check_finance_role();
  END IF;
  SELECT * INTO v_staff FROM public.finance_staff_master WHERE id = p_staff_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff member not found';
  END IF;

  -- Eligibility checks:
  IF NOT COALESCE(v_staff.bpjs_applicable, false) THEN
    RETURN jsonb_build_object(
      'applicable', false,
      'staff_id', v_staff.id,
      'wage_basis', 0,
      'total_employee_deduction', 0,
      'total_employer_expense', 0,
      'total_payable', 0
    );
  END IF;

  -- Enrollment date checks:
  IF v_staff.bpjs_enrollment_start_date IS NOT NULL AND p_period_date < v_staff.bpjs_enrollment_start_date THEN
    RETURN jsonb_build_object(
      'applicable', false,
      'staff_id', v_staff.id,
      'reason', 'Before enrollment start date',
      'total_employee_deduction', 0,
      'total_employer_expense', 0,
      'total_payable', 0
    );
  END IF;

  IF v_staff.bpjs_enrollment_end_date IS NOT NULL AND p_period_date > v_staff.bpjs_enrollment_end_date THEN
    RETURN jsonb_build_object(
      'applicable', false,
      'staff_id', v_staff.id,
      'reason', 'After enrollment end date',
      'total_employee_deduction', 0,
      'total_employer_expense', 0,
      'total_payable', 0
    );
  END IF;

  IF v_staff.status = 'inactive' AND v_staff.last_working_date IS NOT NULL AND p_period_date > v_staff.last_working_date THEN
    RETURN jsonb_build_object(
      'applicable', false,
      'staff_id', v_staff.id,
      'reason', 'After last working date',
      'total_employee_deduction', 0,
      'total_employer_expense', 0,
      'total_payable', 0
    );
  END IF;

  -- Determine wage basis:
  v_wage := COALESCE(p_wage_override, v_staff.bpjs_wage_basis, v_staff.monthly_salary, 0);
  IF v_wage < 0 THEN
    RAISE EXCEPTION 'BPJS wage basis cannot be negative';
  END IF;

  IF v_staff.monthly_salary IS NOT NULL AND v_wage <> v_staff.monthly_salary THEN
    v_is_discrepant := true;
  END IF;

  -- Program calculations:
  -- JHT (Employee 2%, Employer 3.7%)
  IF COALESCE(v_staff.bpjs_program_jht, true) THEN
    v_emp_jht := round(v_wage * COALESCE(v_staff.bpjs_jht_employee_rate, 2.0) / 100.0, 2);
    v_er_jht := round(v_wage * COALESCE(v_staff.bpjs_jht_employer_rate, 3.7) / 100.0, 2);
  END IF;

  -- JKK (Employer 0.24%)
  IF COALESCE(v_staff.bpjs_program_jkk, true) THEN
    v_er_jkk := round(v_wage * COALESCE(v_staff.bpjs_jkk_employer_rate, 0.24) / 100.0, 2);
  END IF;

  -- JKM (Employer 0.30%)
  IF COALESCE(v_staff.bpjs_program_jkm, true) THEN
    v_er_jkm := round(v_wage * COALESCE(v_staff.bpjs_jkm_employer_rate, 0.30) / 100.0, 2);
  END IF;

  -- JP (Pension)
  IF COALESCE(v_staff.bpjs_program_jp, false) THEN
    v_emp_jp := round(v_wage * COALESCE(v_staff.bpjs_jp_employee_rate, 0.0) / 100.0, 2);
    v_er_jp := round(v_wage * COALESCE(v_staff.bpjs_jp_employer_rate, 0.0) / 100.0, 2);
  END IF;

  v_emp_deduction := v_emp_jht + v_emp_jp;
  v_er_expense := v_er_jht + v_er_jkk + v_er_jkm + v_er_jp;
  v_total_payable := v_emp_deduction + v_er_expense;

  RETURN jsonb_build_object(
    'applicable', true,
    'staff_id', v_staff.id,
    'staff_name', v_staff.full_name,
    'employee_code', v_staff.employee_code,
    'kpj_number', v_staff.bpjs_kpj_number,
    'monthly_salary', v_staff.monthly_salary,
    'wage_basis', v_wage,
    'is_wage_discrepant', v_is_discrepant,
    'program_jht', v_staff.bpjs_program_jht,
    'program_jkk', v_staff.bpjs_program_jkk,
    'program_jkm', v_staff.bpjs_program_jkm,
    'program_jp', v_staff.bpjs_program_jp,
    'jht_employee_rate', v_staff.bpjs_jht_employee_rate,
    'jht_employer_rate', v_staff.bpjs_jht_employer_rate,
    'jkk_employer_rate', v_staff.bpjs_jkk_employer_rate,
    'jkm_employer_rate', v_staff.bpjs_jkm_employer_rate,
    'jp_employee_rate', v_staff.bpjs_jp_employee_rate,
    'jp_employer_rate', v_staff.bpjs_jp_employer_rate,
    'employee_jht_amount', v_emp_jht,
    'employee_jp_amount', v_emp_jp,
    'total_employee_deduction', v_emp_deduction,
    'employer_jht_amount', v_er_jht,
    'employer_jkk_amount', v_er_jkk,
    'employer_jkm_amount', v_er_jkm,
    'employer_jp_amount', v_er_jp,
    'total_employer_expense', v_er_expense,
    'total_payable', v_total_payable
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_staff_salary(p_staff_id uuid, p_salary_date date DEFAULT CURRENT_DATE, p_gross_override numeric DEFAULT NULL::numeric, p_pph21_override numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_staff public.finance_staff_master%ROWTYPE;
  v_gross numeric;
  v_advance numeric;
  v_pph21 numeric;
  v_bpjs numeric := 0;
  v_bpjs_calc jsonb;
BEGIN
  PERFORM public._sec_check_finance_role();

  SELECT * INTO v_staff FROM public.finance_staff_master WHERE id = p_staff_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff member not found';
  END IF;

  -- If employee is inactive:
  IF v_staff.status = 'inactive' THEN
    IF v_staff.last_working_date IS NOT NULL AND COALESCE(p_salary_date, CURRENT_DATE) > v_staff.last_working_date THEN
      RAISE EXCEPTION 'Cannot generate salary for inactive employee after last working date (%)', v_staff.last_working_date;
    END IF;
  END IF;

  v_gross := COALESCE(p_gross_override, v_staff.monthly_salary, 0);
  IF v_gross < 0 THEN
    RAISE EXCEPTION 'Gross salary cannot be negative';
  END IF;

  SELECT COALESCE(sum(available_amount), 0) INTO v_advance
    FROM public.get_outstanding_salary_advances(p_staff_id, COALESCE(p_salary_date, CURRENT_DATE));

  v_pph21 := CASE
    WHEN NOT v_staff.pph21_applicable THEN 0
    WHEN v_staff.pph21_method = 'percentage' THEN round(v_gross * v_staff.pph21_percentage / 100, 2)
    ELSE COALESCE(p_pph21_override, 0)
  END;

  IF v_pph21 < 0 OR v_pph21 > v_gross THEN
    RAISE EXCEPTION 'PPh21 must be between zero and gross salary';
  END IF;

  -- Calculate employee BPJS deduction (JHT 2% etc.) using single calculation service
  IF COALESCE(v_staff.bpjs_applicable, false) THEN
    v_bpjs_calc := public.calculate_staff_bpjs(v_staff.id, NULL, COALESCE(p_salary_date, CURRENT_DATE));
    IF (v_bpjs_calc->>'applicable')::boolean THEN
      v_bpjs := COALESCE((v_bpjs_calc->>'total_employee_deduction')::numeric, 0);
    END IF;
  END IF;

  v_advance := least(v_advance, greatest(v_gross - v_pph21 - v_bpjs, 0));

  RETURN jsonb_build_object(
    'staff_id', v_staff.id,
    'monthly_salary', v_staff.monthly_salary,
    'salary_type', v_staff.salary_type,
    'gross_salary', v_gross,
    'outstanding_salary_advances', v_advance,
    'pph21_applicable', v_staff.pph21_applicable,
    'pph21_method', v_staff.pph21_method,
    'pph21_percentage', v_staff.pph21_percentage,
    'pph21_amount', v_pph21,
    'bpjs_amount', v_bpjs,
    'net_salary_payable', greatest(v_gross - v_advance - v_pph21 - v_bpjs, 0),
    'default_payment_method', v_staff.default_payment_method,
    'status', v_staff.status,
    'last_working_date', v_staff.last_working_date,
    'bpjs_applicable', v_staff.bpjs_applicable,
    'bpjs_wage_basis', v_staff.bpjs_wage_basis
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_expense_posting(p_exp_id uuid, p_cancelled_by uuid, p_reason text DEFAULT 'Posting cancelled by administrator'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_exp public.finance_expenses%ROWTYPE;
  v_je public.journal_entries%ROWTYPE;
  v_reversal_id uuid;
  v_period_status text;
  v_reversal_number text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_cancelled_by IS NULL OR p_cancelled_by <> auth.uid() THEN
    RAISE EXCEPTION 'Cancelled-by identity must match the authenticated user';
  END IF;
  PERFORM public._sec_check_finance_role();
  IF btrim(COALESCE(p_reason, '')) = '' THEN
    RAISE EXCEPTION 'Cancellation reason is required';
  END IF;

  SELECT * INTO v_exp
  FROM public.finance_expenses
  WHERE id = p_exp_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense % not found', p_exp_id;
  END IF;
  IF v_exp.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'Cannot cancel posting: expense % is not approved (current: %)',
      p_exp_id, v_exp.approval_status;
  END IF;

  SELECT * INTO v_je
  FROM public.journal_entries
  WHERE source_module IN ('expense', 'expenses')
    AND (reference_id = p_exp_id OR reference_number = 'EXP-' || p_exp_id::text)
    AND is_posted = true
    AND NOT COALESCE(is_reversed, false)
  ORDER BY created_at DESC, id DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No active journal entry found for expense %', p_exp_id;
  END IF;

  SELECT ap.status INTO v_period_status
  FROM public.accounting_periods ap
  WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date
  ORDER BY ap.start_date DESC
  LIMIT 1;
  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN
    RAISE EXCEPTION
      'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',
      to_char(v_je.entry_date, 'FMMonth YYYY');
  END IF;

  IF COALESCE(v_exp.paid_amount, 0) > 0
     OR COALESCE(v_exp.pph_paid_amount, 0) > 0
     OR EXISTS (SELECT 1 FROM public.voucher_allocations va WHERE va.finance_expense_id = p_exp_id)
     OR EXISTS (SELECT 1 FROM public.bank_statement_allocations a
                WHERE (a.document_type = 'expense' AND a.document_id = p_exp_id)
                   OR a.journal_entry_id = v_je.id)
     OR EXISTS (SELECT 1 FROM public.bank_statement_lines b
                WHERE b.matched_expense_id = p_exp_id OR b.matched_entry_id = v_je.id)
     OR EXISTS (SELECT 1 FROM public.bank_reconciliation_items bri WHERE bri.journal_entry_id = v_je.id) THEN
    RAISE EXCEPTION
      'Cannot cancel posting for paid/settled expense %. Reverse or unlink its payment/bank allocation first.',
      COALESCE(v_exp.voucher_number, p_exp_id::text)
      USING ERRCODE = 'check_violation';
  END IF;

  v_reversal_number := public.generate_journal_entry_number();
  INSERT INTO public.journal_entries(
    entry_number, entry_date, period_id, source_module, reference_id,
    reference_number, description, total_debit, total_credit,
    is_posted, is_reversed, posted_by, posted_at, created_by,
    transaction_category, transaction_currency, functional_currency,
    exchange_rate, amounts_are_functional
  ) VALUES (
    v_reversal_number, v_je.entry_date, v_je.period_id, 'expense_cancellation', p_exp_id,
    'CANCEL-' || COALESCE(v_exp.voucher_number, p_exp_id::text),
    'Cancellation reversal of ' || v_je.entry_number || ': ' || p_reason,
    v_je.total_credit, v_je.total_debit,
    true, true, p_cancelled_by, now(), p_cancelled_by,
    v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency,
    v_je.exchange_rate, v_je.amounts_are_functional
  ) RETURNING id INTO v_reversal_id;

  INSERT INTO public.journal_entry_lines(
    journal_entry_id, line_number, account_id, description,
    debit, credit, tax_code_id, customer_id, supplier_id, batch_id,
    transaction_currency, transaction_debit, transaction_credit,
    functional_currency, exchange_rate
  )
  SELECT v_reversal_id, l.line_number, l.account_id,
         'CANCEL: ' || COALESCE(l.description, ''),
         l.credit, l.debit, l.tax_code_id, l.customer_id, l.supplier_id, l.batch_id,
         l.transaction_currency, l.transaction_credit, l.transaction_debit,
         l.functional_currency, l.exchange_rate
  FROM public.journal_entry_lines l
  WHERE l.journal_entry_id = v_je.id
  ORDER BY l.line_number;

  IF NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_reversal_id) THEN
    RAISE EXCEPTION 'Cannot cancel empty journal entry %', v_je.id;
  END IF;

  UPDATE public.journal_entries
  SET is_reversed = true, reversed_by_id = v_reversal_id
  WHERE id = v_je.id AND NOT COALESCE(is_reversed, false);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense journal % was already reversed', v_je.id;
  END IF;

  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)
  VALUES (
    'finance_expenses', p_exp_id, 'update',
    jsonb_build_object(
      '_action', 'CANCEL_POSTING',
      'journal_entry_id', v_je.id,
      'journal_entry_number', v_je.entry_number,
      'reversal_journal_id', v_reversal_id,
      'reversal_journal_number', v_reversal_number,
      'entry_date', v_je.entry_date,
      'amount', v_exp.amount,
      'expense_category', v_exp.expense_category,
      'approval_status', v_exp.approval_status,
      'reason', p_reason
    ),
    jsonb_build_object(
      'approval_status', 'cancelled',
      'cancelled_by', p_cancelled_by,
      'cancelled_at', now()
    ),
    p_cancelled_by
  );

  UPDATE public.finance_expenses
  SET approval_status = 'cancelled', approved_by = NULL, approved_at = NULL
  WHERE id = p_exp_id;

  IF EXISTS (
    SELECT 1 FROM public.journal_entries
    WHERE source_module IN ('expense', 'expenses')
      AND reference_id = p_exp_id AND is_posted AND NOT COALESCE(is_reversed, false)
  ) THEN
    RAISE EXCEPTION 'Expense % still has an active journal after cancellation', p_exp_id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_gl_posting(p_je_id uuid, p_doc_id uuid, p_table_name text, p_cancelled_by uuid, p_reason text, p_extra_audit jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_je            journal_entries%ROWTYPE;
  v_period_status TEXT;
  v_actor         UUID;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_actor := auth.uid();

  SELECT * INTO v_je FROM journal_entries WHERE id = p_je_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Journal entry % not found', p_je_id;
  END IF;

  SELECT ap.status INTO v_period_status
  FROM accounting_periods ap
  WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date
  ORDER BY ap.start_date DESC
  LIMIT 1;

  IF v_period_status IS NOT NULL AND v_period_status != 'open' THEN
    RAISE EXCEPTION
      'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',
      TO_CHAR(v_je.entry_date, 'FMMonth YYYY');
  END IF;

  DELETE FROM journal_entry_lines WHERE journal_entry_id = p_je_id;
  DELETE FROM journal_entries      WHERE id              = p_je_id;

  INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)
  VALUES (
    p_table_name, p_doc_id, 'update',
    p_extra_audit || jsonb_build_object(
      '_action',              'CANCEL_POSTING',
      'journal_entry_id',     p_je_id,
      'journal_entry_number', v_je.entry_number,
      'entry_date',           v_je.entry_date,
      'reason',               p_reason
    ),
    jsonb_build_object('cancelled_by', v_actor, 'cancelled_at', NOW()),
    v_actor
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_payment_voucher_posting(p_pv_id uuid, p_cancelled_by uuid, p_reason text DEFAULT 'Posting cancelled by administrator'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_pv RECORD;
  v_je RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  PERFORM public._sec_check_finance_role();
  IF p_cancelled_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Cancelled-by identity must match the authenticated user';
  END IF;

  SELECT * INTO v_pv FROM payment_vouchers WHERE id = p_pv_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;
  IF NOT v_pv.is_posted THEN
    RAISE EXCEPTION 'Payment voucher % is not posted', COALESCE(v_pv.voucher_number, p_pv_id::TEXT);
  END IF;

  SELECT * INTO v_je FROM journal_entries WHERE id = v_pv.journal_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No journal entry found for payment voucher %', v_pv.voucher_number;
  END IF;

  -- Clear any settlement adjustments linked to this payment voucher
  PERFORM public.clear_payment_allocation_rounding_adjustment(NULL, p_pv_id);

  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row
  UPDATE payment_vouchers
  SET is_posted = FALSE, journal_entry_id = NULL
  WHERE id = p_pv_id;

  PERFORM cancel_gl_posting(
    v_je.id, p_pv_id, 'payment_vouchers', p_cancelled_by, p_reason,
    jsonb_build_object(
      'voucher_number', v_pv.voucher_number,
      'amount',         v_pv.amount,
      'is_posted',      TRUE
    )
  );

  -- Synchronize bank account current_balance with authoritative GL
  IF v_pv.bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_pv.bank_account_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_receipt_voucher_posting(p_rv_id uuid, p_cancelled_by uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'Posting cancelled by administrator'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rv RECORD;
  v_je RECORD;
  v_actor uuid;
  v_alloc RECORD;
  v_line_ids uuid[] := ARRAY[]::uuid[];
  v_line_id uuid;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_actor := COALESCE(auth.uid(), p_cancelled_by);

  SELECT * INTO v_rv FROM public.receipt_vouchers WHERE id = p_rv_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id;
  END IF;

  IF NOT v_rv.is_posted THEN
    RAISE EXCEPTION 'Receipt voucher % is not posted', COALESCE(v_rv.voucher_number, p_rv_id::TEXT);
  END IF;

  SELECT * INTO v_je FROM public.journal_entries WHERE id = v_rv.journal_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No journal entry found for receipt voucher %', v_rv.voucher_number;
  END IF;

  -- Clean up any associated rounding adjustments
  DELETE FROM public.invoice_rounding_adjustments WHERE receipt_voucher_id = p_rv_id;

  -- Step 1: Identify all bank allocations associated with this receipt voucher or its journal entry
  FOR v_alloc IN
    SELECT bsa.id, bsa.bank_statement_line_id
    FROM public.bank_statement_allocations bsa
    WHERE (bsa.document_type = 'receipt' AND bsa.document_id = p_rv_id)
       OR (v_rv.journal_entry_id IS NOT NULL AND bsa.journal_entry_id = v_rv.journal_entry_id)
    FOR UPDATE
  LOOP
    IF NOT (v_alloc.bank_statement_line_id = ANY(v_line_ids)) THEN
      v_line_ids := array_append(v_line_ids, v_alloc.bank_statement_line_id);
    END IF;

    IF to_regclass('public.finance_historical_repair_commands') IS NOT NULL THEN
      EXECUTE 'UPDATE public.finance_historical_repair_commands SET created_allocation_id = NULL WHERE created_allocation_id = $1' USING v_alloc.id;
    END IF;

    PERFORM public.unmatch_bank_statement_allocation(v_alloc.id);
  END LOOP;

  -- Step 2: Identify any bank lines directly referencing this receipt or journal entry
  FOR v_line_id IN
    SELECT id FROM public.bank_statement_lines
    WHERE matched_receipt_id = p_rv_id
       OR (v_rv.journal_entry_id IS NOT NULL AND matched_entry_id = v_rv.journal_entry_id)
  LOOP
    IF NOT (v_line_id = ANY(v_line_ids)) THEN
      v_line_ids := array_append(v_line_ids, v_line_id);
    END IF;
  END LOOP;

  -- Step 3: Clear direct bank line references and refresh ownership and reconciliation status
  IF array_length(v_line_ids, 1) > 0 THEN
    UPDATE public.bank_statement_lines
    SET matched_receipt_id = NULL
    WHERE matched_receipt_id = p_rv_id;

    IF v_rv.journal_entry_id IS NOT NULL THEN
      UPDATE public.bank_statement_lines
      SET matched_entry_id = NULL
      WHERE matched_entry_id = v_rv.journal_entry_id;
    END IF;

    FOREACH v_line_id IN ARRAY v_line_ids LOOP
      PERFORM public.sync_bank_line_allocation_owner(v_line_id);
      PERFORM public.refresh_bank_statement_allocation_status(v_line_id);
    END LOOP;
  END IF;

  -- Step 4: Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.
  UPDATE public.receipt_vouchers
  SET is_posted = FALSE, journal_entry_id = NULL
  WHERE id = p_rv_id;

  -- Step 5: Delete original receipt journal entry and record audit log via cancel_gl_posting
  PERFORM public.cancel_gl_posting(
    v_je.id,
    p_rv_id,
    'receipt_vouchers',
    v_actor,
    p_reason,
    jsonb_build_object(
      'voucher_number', v_rv.voucher_number,
      'amount',         v_rv.amount,
      'is_posted',      TRUE
    )
  );

  -- Step 6: Synchronize bank account current_balance with authoritative GL
  IF v_rv.bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_rv.bank_account_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_sales_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller uuid := COALESCE(auth.uid(), p_actor);
  v_role text;
  v_inv record;
  v_alloc_paid numeric := 0;
  v_adj_paid numeric := 0;
  v_reason text;
  v_rev_count int := 0;
  v_cogs_count int := 0;
  v_updated_notes text;
  v_je record;
  v_period_id uuid;
  v_rev_entry text;
  v_reversal_id uuid;
BEGIN
  -- Permission check: only admin and accounts can cancel financially posted invoices
  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    v_caller := p_actor;
  END IF;
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot cancel sales invoices', COALESCE(v_role, 'none');
  END IF;

  -- Lock invoice row
  SELECT * INTO v_inv
  FROM public.sales_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales invoice % not found', p_invoice_id;
  END IF;

  -- Idempotency check: if already cancelled, return success without duplicate reversals
  IF v_inv.document_status = 'cancelled' OR v_inv.notes LIKE '[CANCELLED%' THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_cancelled', true,
      'invoice_id', p_invoice_id,
      'invoice_number', v_inv.invoice_number,
      'document_status', 'cancelled',
      'cancelled_at', v_inv.cancelled_at,
      'reason', v_inv.cancellation_reason
    );
  END IF;

  -- Payment guard: check allocated receipts and adjustments
  SELECT COALESCE(SUM(allocated_amount), 0) INTO v_alloc_paid
  FROM public.voucher_allocations
  WHERE sales_invoice_id = p_invoice_id AND voucher_type = 'receipt';

  SELECT COALESCE(SUM(adjustment_amount), 0) INTO v_adj_paid
  FROM public.invoice_rounding_adjustments
  WHERE sales_invoice_id = p_invoice_id;

  IF (COALESCE(v_inv.paid_amount, 0) > 0.01 OR v_alloc_paid > 0.01 OR v_adj_paid > 0.01) THEN
    RAISE EXCEPTION 'Cannot cancel invoice %: payments of Rp % are allocated. Unallocate payments first.',
      v_inv.invoice_number, (COALESCE(v_inv.paid_amount, 0) + v_alloc_paid + v_adj_paid);
  END IF;

  v_reason := COALESCE(p_reason, '[CANCELLED on ' || CURRENT_DATE::text || ' by ' || COALESCE(v_role, 'Admin') || ']');

  -- 1. Reverse Revenue Journal Entries (Commercial AR, Sales, VAT Output, Stamp Duty)
  FOR v_je IN
    SELECT *
    FROM public.journal_entries
    WHERE is_posted = true
      AND COALESCE(is_reversed, false) = false
      AND (
        id = v_inv.journal_entry_id
        OR (reference_id = p_invoice_id AND source_module IN ('sales_invoice', 'sales', 'sales_invoices'))
        OR (reference_number = v_inv.invoice_number AND source_module IN ('sales_invoice', 'sales', 'sales_invoices'))
      )
    FOR UPDATE
  LOOP
    SELECT id INTO v_period_id
    FROM public.accounting_periods
    WHERE CURRENT_DATE BETWEEN start_date AND end_date
      AND status = 'open'
    LIMIT 1;
    IF v_period_id IS NULL THEN v_period_id := v_je.period_id; END IF;

    v_rev_entry := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, period_id, source_module, reference_id,
      reference_number, description, total_debit, total_credit,
      is_posted, is_reversed, posted_by, posted_at, created_by, created_at,
      transaction_category, transaction_currency, functional_currency, exchange_rate, amounts_are_functional
    ) VALUES (
      v_rev_entry, CURRENT_DATE, v_period_id, v_je.source_module || '_cancellation', p_invoice_id,
      'CANCEL-' || v_inv.invoice_number,
      'Cancellation reversal of ' || v_je.entry_number || ': ' || v_reason,
      v_je.total_credit, v_je.total_debit,
      true, true, v_caller, now(), v_caller, now(),
      v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency, v_je.exchange_rate, v_je.amounts_are_functional
    ) RETURNING id INTO v_reversal_id;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, description, debit, credit,
      tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,
      transaction_debit, transaction_credit, functional_currency, exchange_rate, sales_invoice_item_id
    )
    SELECT
      v_reversal_id, line_number, account_id, 'CANCEL: ' || COALESCE(description, ''),
      credit, debit, tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,
      transaction_credit, transaction_debit, functional_currency, exchange_rate, sales_invoice_item_id
    FROM public.journal_entry_lines
    WHERE journal_entry_id = v_je.id
    ORDER BY line_number;

    UPDATE public.journal_entries
    SET is_reversed = true,
        reversed_by_id = v_reversal_id,
        description = v_reason || ' ' || COALESCE(description, '')
    WHERE id = v_je.id;

    v_rev_count := v_rev_count + 1;
  END LOOP;

  -- 2. Reverse COGS Journal Entries (COGS Dr 5100, Inventory Cr 1130)
  FOR v_je IN
    SELECT *
    FROM public.journal_entries
    WHERE is_posted = true
      AND COALESCE(is_reversed, false) = false
      AND source_module = 'sales_invoice_cogs'
      AND (reference_id = p_invoice_id OR reference_number = v_inv.invoice_number)
    FOR UPDATE
  LOOP
    SELECT id INTO v_period_id
    FROM public.accounting_periods
    WHERE CURRENT_DATE BETWEEN start_date AND end_date
      AND status = 'open'
    LIMIT 1;
    IF v_period_id IS NULL THEN v_period_id := v_je.period_id; END IF;

    v_rev_entry := public.next_journal_entry_number();

    INSERT INTO public.journal_entries (
      entry_number, entry_date, period_id, source_module, reference_id,
      reference_number, description, total_debit, total_credit,
      is_posted, is_reversed, posted_by, posted_at, created_by, created_at,
      transaction_category, transaction_currency, functional_currency, exchange_rate, amounts_are_functional
    ) VALUES (
      v_rev_entry, CURRENT_DATE, v_period_id, 'sales_invoice_cogs_cancellation', p_invoice_id,
      'CANCEL-' || v_inv.invoice_number || '-COGS',
      'Cancellation reversal of COGS ' || v_je.entry_number || ': ' || v_reason,
      v_je.total_credit, v_je.total_debit,
      true, true, v_caller, now(), v_caller, now(),
      v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency, v_je.exchange_rate, v_je.amounts_are_functional
    ) RETURNING id INTO v_reversal_id;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, description, debit, credit,
      tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,
      transaction_debit, transaction_credit, functional_currency, exchange_rate, sales_invoice_item_id
    )
    SELECT
      v_reversal_id, line_number, account_id, 'CANCEL: ' || COALESCE(description, ''),
      credit, debit, tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,
      transaction_credit, transaction_debit, functional_currency, exchange_rate, sales_invoice_item_id
    FROM public.journal_entry_lines
    WHERE journal_entry_id = v_je.id
    ORDER BY line_number;

    UPDATE public.journal_entries
    SET is_reversed = true,
        reversed_by_id = v_reversal_id,
        description = v_reason || ' ' || COALESCE(description, '') || ' COGS'
    WHERE id = v_je.id;

    v_cogs_count := v_cogs_count + 1;
  END LOOP;

  -- 3. Release Delivery Challan link while preserving invoice line items for viewing
  PERFORM set_config('app.sales_invoice_cancel', 'true', true);
  UPDATE public.sales_invoice_items
  SET delivery_challan_item_id = NULL
  WHERE invoice_id = p_invoice_id;
  PERFORM set_config('app.sales_invoice_cancel', 'false', true);

  -- 4. Update sales invoice header with canonical status & audit metadata
  v_updated_notes := CASE
    WHEN v_inv.notes IS NULL OR v_inv.notes = '' THEN v_reason
    WHEN v_inv.notes LIKE '[CANCELLED%' THEN v_inv.notes
    ELSE v_reason || E'\n' || v_inv.notes
  END;

  UPDATE public.sales_invoices
  SET document_status = 'cancelled',
      cancelled_at = now(),
      cancelled_by = v_caller,
      cancellation_reason = v_reason,
      notes = v_updated_notes,
      balance_amount = 0,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'invoice_number', v_inv.invoice_number,
    'document_status', 'cancelled',
    'cancelled_at', now(),
    'cancelled_by', v_caller,
    'reason', v_reason,
    'reversed_revenue_journals', v_rev_count,
    'reversed_cogs_journals', v_cogs_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_approval_required(p_transaction_type text, p_amount numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_threshold decimal;
BEGIN
IF auth.uid() IS NULL THEN
RAISE EXCEPTION 'Permission denied: must be authenticated';
END IF;

SELECT amount_threshold INTO v_threshold
FROM approval_thresholds
WHERE transaction_type = p_transaction_type
AND is_active = true
ORDER BY amount_threshold DESC
LIMIT 1;

IF v_threshold IS NULL THEN
RETURN false;
END IF;

RETURN p_amount >= v_threshold;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_inquiry_requirements_fulfilled(inquiry_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
inquiry_record RECORD;
all_fulfilled boolean;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts', 'sales') THEN
RAISE EXCEPTION 'Permission denied: role % cannot check inquiry requirements', v_role;
END IF;

SELECT * INTO inquiry_record FROM crm_inquiries WHERE id = inquiry_id;

IF NOT FOUND THEN
RETURN false;
END IF;

all_fulfilled := (
(NOT inquiry_record.price_required OR inquiry_record.price_sent_at IS NOT NULL) AND
(NOT inquiry_record.coa_required OR inquiry_record.coa_sent_at IS NOT NULL) AND
(NOT inquiry_record.sample_required OR inquiry_record.sample_sent_at IS NOT NULL) AND
(NOT inquiry_record.agency_letter_required OR inquiry_record.agency_letter_sent_at IS NOT NULL)
);

RETURN all_fulfilled;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_user_can_delete(p_user_id uuid)
 RETURNS TABLE(can_delete boolean, reason text, reference_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target_user record;
  v_total_refs integer := 0;
  v_count integer;
  v_details text := '';
  v_other_admin_count integer;
BEGIN
  SELECT * INTO v_target_user
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'User profile not found', 0;
    RETURN;
  END IF;

  -- Check if target is last active admin
  IF v_target_user.role = 'admin' AND v_target_user.is_active IS TRUE THEN
    SELECT COUNT(*) INTO v_other_admin_count
    FROM public.user_profiles
    WHERE role = 'admin' AND is_active IS TRUE AND id <> p_user_id;

    IF v_other_admin_count = 0 THEN
      RETURN QUERY SELECT false, 'Cannot delete the last active administrator', 0;
      RETURN;
    END IF;
  END IF;

  -- Check audit_logs
  SELECT COUNT(*) INTO v_count FROM public.audit_logs WHERE user_id = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('audit logs (%s), ', v_count);
  END IF;

  -- Check finance_expenses
  SELECT COUNT(*) INTO v_count FROM public.finance_expenses WHERE created_by = p_user_id OR approved_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('expenses (%s), ', v_count);
  END IF;

  -- Check sales_invoices
  SELECT COUNT(*) INTO v_count FROM public.sales_invoices WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('sales invoices (%s), ', v_count);
  END IF;

  -- Check purchase_invoices
  SELECT COUNT(*) INTO v_count FROM public.purchase_invoices WHERE receiving_submitted_by = p_user_id OR receiving_approved_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('purchase invoices (%s), ', v_count);
  END IF;

  -- Check batches
  SELECT COUNT(*) INTO v_count FROM public.batches WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('batches (%s), ', v_count);
  END IF;

  -- Check products
  SELECT COUNT(*) INTO v_count FROM public.products WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('products (%s), ', v_count);
  END IF;

  -- Check inventory_transactions
  SELECT COUNT(*) INTO v_count FROM public.inventory_transactions WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('inventory transactions (%s), ', v_count);
  END IF;

  -- Check customer_payments & vendor_payments
  SELECT COUNT(*) INTO v_count FROM public.customer_payments WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('customer payments (%s), ', v_count);
  END IF;

  SELECT COUNT(*) INTO v_count FROM public.vendor_payments WHERE created_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('vendor payments (%s), ', v_count);
  END IF;

  -- Check tasks
  SELECT COUNT(*) INTO v_count FROM public.tasks WHERE created_by = p_user_id OR completed_by = p_user_id;
  IF v_count > 0 THEN
    v_total_refs := v_total_refs + v_count;
    v_details := v_details || format('tasks (%s), ', v_count);
  END IF;

  IF v_total_refs > 0 THEN
    v_details := rtrim(v_details, ', ');
    RETURN QUERY SELECT false, 
      format('Cannot delete user "%s": user is associated with historical financial, business, or audit records (%s). Deactivate the user instead to preserve audit history.', v_target_user.username, v_details),
      v_total_refs;
  ELSE
    RETURN QUERY SELECT true, 'User has no historical business records and can be safely deleted.', 0;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_payment_allocation_rounding_adjustment(p_invoice_id uuid DEFAULT NULL::uuid, p_payment_voucher_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_existing record;
BEGIN
  FOR v_existing IN
    SELECT *
    FROM public.invoice_rounding_adjustments
    WHERE (p_invoice_id IS NOT NULL AND purchase_invoice_id = p_invoice_id)
       OR (p_payment_voucher_id IS NOT NULL AND payment_voucher_id = p_payment_voucher_id)
  LOOP
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;

    DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
    IF v_existing.purchase_invoice_id IS NOT NULL THEN
      PERFORM public.recalculate_purchase_invoice_payment_state(v_existing.purchase_invoice_id);
    END IF;
  END LOOP;

  IF p_invoice_id IS NOT NULL THEN
    PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_receipt_allocation_rounding_adjustment(p_invoice_id uuid, p_receipt_voucher_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_existing record;
BEGIN
  FOR v_existing IN
    SELECT *
    FROM public.invoice_rounding_adjustments
    WHERE sales_invoice_id = p_invoice_id
       OR (p_receipt_voucher_id IS NOT NULL AND receipt_voucher_id = p_receipt_voucher_id)
  LOOP
    IF v_existing.journal_entry_id IS NOT NULL THEN
      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;
      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;
    END IF;

    DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;
  END LOOP;

  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.close_tax_period(p_period_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_period public.tax_periods%ROWTYPE;
  v_draft_count integer;
BEGIN
  SELECT * INTO v_period FROM public.tax_periods WHERE id = p_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_period_id;
  END IF;

  IF v_period.status = 'closed' THEN
    RAISE EXCEPTION 'Tax period is already closed';
  END IF;

  -- Check for unfinalized/draft sales invoices in this tax period
  SELECT COUNT(*) INTO v_draft_count
  FROM public.sales_invoices
  WHERE tax_period_id = p_period_id
    AND COALESCE(is_draft, false) = true;

  IF v_draft_count > 0 THEN
    RAISE EXCEPTION 'Cannot close tax period: % draft sales invoices remain', v_draft_count;
  END IF;

  UPDATE public.tax_periods
  SET status = 'closed',
      closed_at = now(),
      closed_by = auth.uid()
  WHERE id = p_period_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_import_cost_posting(p_header_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
v_je_id UUID;
v_result JSONB;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot post import costs', v_role;
END IF;

PERFORM calculate_import_cost_allocation(p_header_id);
PERFORM apply_import_costs_to_batches(p_header_id);
v_je_id := post_import_cost_journal(p_header_id);

UPDATE import_cost_headers
SET
status = 'posted',
journal_entry_id = v_je_id,
posted_by = auth.uid(),
posted_at = NOW()
WHERE id = p_header_id;

v_result := jsonb_build_object(
'success', true,
'message', 'Import costs calculated, allocated, and posted successfully',
'journal_entry_id', v_je_id,
'header_id', p_header_id
);

RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_period_ppn(p_period_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_period public.tax_periods%rowtype;
  v_pph_total numeric(18,2);
BEGIN
  SELECT * INTO v_period
    FROM public.tax_periods
   WHERE id = p_period_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_period_id;
  END IF;

  -- PPN calculation remains unchanged.
  IF v_period.tax_type = 'PPN' THEN
    PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);
    RETURN;
  END IF;

  -- Filed periods are immutable snapshots. Never overwrite a submitted
  -- government return from live source rows during later expense edits.
  IF v_period.filing_status = 'filed' OR v_period.status = 'closed' THEN
    RETURN;
  END IF;

  PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);

  SELECT COALESCE(public.fn_pph_authoritative_source_total(p_period_id), 0)
       + COALESCE((
           SELECT SUM(tp.amount)
             FROM public.tax_payments tp
            WHERE tp.tax_period_id = p_period_id
              AND tp.tax_type = v_period.tax_type
              AND tp.historical_source_status = 'missing_source_verified'
         ), 0)
    INTO v_pph_total;

  UPDATE public.tax_periods
     SET pph_total = v_pph_total,
         updated_at = now()
   WHERE id = p_period_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_bank_match(p_bank_line_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_line RECORD;
  v_bank_acct RECORD;
  v_alloc RECORD;
  v_total_alloc numeric := 0;
  v_line_amount numeric := 0;
  v_journal RECORD;
  v_role text;
  v_alloc_count integer := 0;
BEGIN
  -- Permission check
  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
  IF v_role IS NOT NULL AND v_role NOT IN ('admin', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot confirm bank matches', v_role;
  END IF;

  SELECT * INTO v_line 
    FROM public.bank_statement_lines 
   WHERE id = p_bank_line_id 
     FOR UPDATE;

  IF NOT FOUND THEN 
    RETURN jsonb_build_object('success', false, 'error', 'Bank statement line not found'); 
  END IF;

  SELECT * INTO v_bank_acct 
    FROM public.bank_accounts 
   WHERE id = v_line.bank_account_id;

  IF NOT FOUND THEN 
    RETURN jsonb_build_object('success', false, 'error', 'Bank account not found'); 
  END IF;

  v_line_amount := COALESCE(NULLIF(v_line.debit_amount, 0), v_line.credit_amount, 0);

  -- Count allocations
  SELECT count(*), COALESCE(sum(allocation_amount), 0)
    INTO v_alloc_count, v_total_alloc
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_line_id;

  -- Case A: Line has allocations
  IF v_alloc_count > 0 THEN
    IF v_total_alloc > v_line_amount + 0.01 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Total allocations (' || v_total_alloc || ') exceed bank line amount (' || v_line_amount || ')');
    END IF;

    -- Validate each allocation
    FOR v_alloc IN 
      SELECT bsa.*, je.is_posted, je.transaction_currency
        FROM public.bank_statement_allocations bsa
        LEFT JOIN public.journal_entries je ON je.id = bsa.journal_entry_id
       WHERE bsa.bank_statement_line_id = p_bank_line_id
    LOOP
      -- 1. Must have journal entry
      IF v_alloc.journal_entry_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Allocation has no journal entry attached');
      END IF;

      -- 2. Active posted journal
      IF COALESCE(v_alloc.is_posted, false) = false THEN
        RETURN jsonb_build_object('success', false, 'error', 'Journal entry ' || v_alloc.journal_entry_id || ' is not posted');
      END IF;

      -- 3. Journal must contain the bank account COA
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines 
         WHERE journal_entry_id = v_alloc.journal_entry_id 
           AND account_id = v_bank_acct.coa_id
      ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Journal entry does not contain bank account COA');
      END IF;

      -- 4. Direction match:
      -- Bank statement debit (money out) -> GL bank line credit
      -- Bank statement credit (money in) -> GL bank line debit
      IF v_line.debit_amount > 0 THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.journal_entry_lines
           WHERE journal_entry_id = v_alloc.journal_entry_id 
             AND account_id = v_bank_acct.coa_id 
             AND credit > 0
        ) THEN
          RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement debit requires GL bank credit');
        END IF;
      ELSIF v_line.credit_amount > 0 THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.journal_entry_lines
           WHERE journal_entry_id = v_alloc.journal_entry_id 
             AND account_id = v_bank_acct.coa_id 
             AND debit > 0
        ) THEN
          RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement credit requires GL bank debit');
        END IF;
      END IF;

      -- 5. Currency check
      IF v_bank_acct.currency = 'USD' AND v_alloc.transaction_currency IS NOT NULL AND v_alloc.transaction_currency <> 'USD' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Currency mismatch between journal and bank account');
      END IF;

      -- 6. Document settlement validity if expense
      IF v_alloc.document_type = 'expense' THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.finance_expenses WHERE id = v_alloc.document_id
        ) THEN
          RETURN jsonb_build_object('success', false, 'error', 'Referenced finance expense does not exist');
        END IF;
      END IF;
    END LOOP;

  -- Case B: Direct matched journal without allocations
  ELSIF v_line.matched_entry_id IS NOT NULL THEN
    SELECT * INTO v_journal 
      FROM public.journal_entries 
     WHERE id = v_line.matched_entry_id;

    IF NOT FOUND OR COALESCE(v_journal.is_posted, false) = false THEN
      RETURN jsonb_build_object('success', false, 'error', 'Direct matched journal is missing or unposted');
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.journal_entry_lines 
       WHERE journal_entry_id = v_journal.id 
         AND account_id = v_bank_acct.coa_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Journal does not contain bank account COA');
    END IF;

    IF v_line.debit_amount > 0 THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines
         WHERE journal_entry_id = v_journal.id AND account_id = v_bank_acct.coa_id AND credit > 0
      ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement debit requires GL credit');
      END IF;
    ELSIF v_line.credit_amount > 0 THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines
         WHERE journal_entry_id = v_journal.id AND account_id = v_bank_acct.coa_id AND debit > 0
      ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement credit requires GL debit');
      END IF;
    END IF;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Cannot confirm match: line has no valid allocation or posted journal entry');
  END IF;

  -- Perform the confirmation
  UPDATE public.bank_statement_lines
     SET matching_status = 'confirmed',
         reconciliation_status = CASE
           WHEN v_alloc_count > 0 AND v_total_alloc < v_line_amount - 0.01 THEN 'partially_reconciled'
           ELSE 'matched'
         END,
         matched_at = now(),
         matched_by = COALESCE(p_user_id, auth.uid()),
         notes = COALESCE(notes, 'User confirmed match')
   WHERE id = p_bank_line_id;

  RETURN jsonb_build_object('success', true, 'message', 'Match confirmed successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_so_product_reservation_v2(p_dc_item_id uuid, p_operation_id uuid, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v record;
  v_res public.so_product_reservations%ROWTYPE;
  v_soi record;
  v_tx uuid;
  v_after numeric;
  v_consume_qty numeric;
  v_res_id uuid;
BEGIN
  SELECT dci.*, dc.id AS dc_id, dc.sales_order_id, dc.challan_number, dc.challan_date INTO v
  FROM public.delivery_challan_items dci
  JOIN public.delivery_challans dc ON dc.id = dci.challan_id
  WHERE dci.id = p_dc_item_id
  FOR UPDATE OF dci, dc;

  IF NOT FOUND OR v.sales_order_item_id IS NULL THEN
    RAISE EXCEPTION 'DC item has no canonical SO item';
  END IF;

  SELECT * INTO v_soi
  FROM public.sales_order_items
  WHERE id = v.sales_order_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order item not found';
  END IF;

  -- Validate remaining SO quantity
  IF v.quantity > (v_soi.quantity - COALESCE(v_soi.delivered_quantity, 0) + 0.0001) THEN
    RAISE EXCEPTION 'DC quantity exceeds remaining Sales Order quantity';
  END IF;

  -- Validate physical batch stock
  IF NOT EXISTS (
    SELECT 1 FROM public.batches b
    WHERE b.id = v.batch_id
      AND b.product_id = v.product_id
      AND b.is_active = true
      AND b.current_stock >= v.quantity
      AND (b.expiry_date IS NULL OR b.expiry_date > CURRENT_DATE)
  ) THEN
    RAISE EXCEPTION 'Selected batch is invalid, expired, or has insufficient physical stock';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.dc_batch_allocations
    WHERE delivery_challan_item_id = v.id
      AND status = 'consumed'
  ) THEN
    RAISE EXCEPTION 'Delivery Challan item reservation is already consumed';
  END IF;

  -- Post inventory movement
  v_tx := public.post_inventory_movement(
    public.uuid_from_text('inventory-v2:dc:' || p_operation_id || ':' || v.id),
    v.product_id,
    v.batch_id,
    'delivery_challan',
    -v.quantity,
    v.challan_date,
    v.challan_number,
    'delivery_challan',
    v.dc_id,
    'Product delivery against DC batch',
    COALESCE(p_actor, auth.uid()),
    NULL,
    NULL
  );

  -- Check if there is an active reservation to consume
  SELECT * INTO v_res
  FROM public.so_product_reservations
  WHERE sales_order_item_id = v.sales_order_item_id
    AND product_id = v.product_id
    AND status = 'active'
  FOR UPDATE;

  IF FOUND THEN
    v_res_id := v_res.id;
    v_consume_qty := LEAST(v_res.reserved_quantity, v.quantity);
    v_after := v_res.reserved_quantity - v_consume_qty;

    UPDATE public.so_product_reservations SET
      reserved_quantity = v_after,
      status = CASE WHEN v_after = 0 THEN 'consumed' ELSE 'active' END,
      closed_at = CASE WHEN v_after = 0 THEN now() END,
      close_reason = CASE WHEN v_after = 0 THEN 'Fully delivered' END,
      updated_at = now()
    WHERE id = v_res.id;

    INSERT INTO public.so_product_reservation_events(
      reservation_id, sales_order_id, sales_order_item_id, event_type,
      quantity_delta, quantity_after, delivery_challan_item_id, reason, actor_id
    ) VALUES (
      v_res.id, v.sales_order_id, v.sales_order_item_id, 'consumed',
      -v_consume_qty, v_after, v.id, 'DC approval', COALESCE(p_actor, auth.uid())
    );
  ELSE
    -- If no active reservation existed prior to delivery (e.g. shortage SO fulfilled on stock arrival),
    -- create a fulfilled/consumed reservation record for complete audit trail & FK integrity in dc_batch_allocations
    INSERT INTO public.so_product_reservations(
      sales_order_id, sales_order_item_id, product_id, reserved_quantity,
      status, created_at, closed_at, close_reason, created_by
    ) VALUES (
      v.sales_order_id, v.sales_order_item_id, v.product_id, 0,
      'consumed', now(), now(), 'Direct DC delivery without prior reservation', COALESCE(p_actor, auth.uid())
    ) RETURNING id INTO v_res_id;

    INSERT INTO public.so_product_reservation_events(
      reservation_id, sales_order_id, sales_order_item_id, event_type,
      quantity_delta, quantity_after, delivery_challan_item_id, reason, actor_id
    ) VALUES (
      v_res_id, v.sales_order_id, v.sales_order_item_id, 'consumed',
      -v.quantity, 0, v.id, 'Direct DC delivery without prior reservation', COALESCE(p_actor, auth.uid())
    );
  END IF;

  INSERT INTO public.dc_batch_allocations(
    delivery_challan_id, delivery_challan_item_id, sales_order_item_id,
    reservation_id, product_id, batch_id, allocated_quantity,
    operation_id, inventory_transaction_id, created_by
  ) VALUES (
    v.dc_id, v.id, v.sales_order_item_id,
    v_res_id, v.product_id, v.batch_id, v.quantity,
    p_operation_id, v_tx, COALESCE(p_actor, auth.uid())
  );

  RETURN v_tx;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_batch_inventory_transaction(p_product_id uuid, p_batch_id uuid, p_transaction_type text, p_quantity numeric, p_transaction_date date, p_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts','warehouse') THEN
RAISE EXCEPTION 'Permission denied: role % cannot create inventory transactions', v_role;
END IF;

INSERT INTO inventory_transactions (
