CREATE OR REPLACE FUNCTION public.generate_bpjs_monthly_register(p_year integer, p_month integer, p_official_bill numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_period_date date;
  v_register_id uuid;
  v_register public.bpjs_monthly_registers%ROWTYPE;
  v_staff record;
  v_calc jsonb;
  v_item_id uuid;
  v_primary_exp_id uuid;
  v_wages numeric := 0;
  v_emp_jht numeric := 0;
  v_emp_jp numeric := 0;
  v_emp_ded numeric := 0;
  v_er_jht numeric := 0;
  v_er_jkk numeric := 0;
  v_er_jkm numeric := 0;
  v_er_jp numeric := 0;
  v_er_exp numeric := 0;
  v_total_pay numeric := 0;
  v_has_official_bill boolean;
  v_official_billed_amount numeric;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  IF p_year < 2020 OR p_year > 2100 THEN
    RAISE EXCEPTION 'Invalid period year %', p_year;
  END IF;
  IF p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'Invalid period month %', p_month;
  END IF;

  v_period_date := make_date(p_year, p_month, 1);

  SELECT * INTO v_register
    FROM public.bpjs_monthly_registers
   WHERE period_year = p_year AND period_month = p_month
   FOR UPDATE;

  IF FOUND THEN
    -- Protect approved, posted, and reconciled registers
    IF v_register.status <> 'draft' THEN
      RAISE EXCEPTION 'Cannot recalculate %-%: register status is % (only draft registers can be recalculated). An approved register must be explicitly reopened before recalculation.',
        p_year, p_month, v_register.status;
    END IF;

    v_register_id := v_register.id;

    -- Resolve official bill flag and amount
    v_has_official_bill := CASE
      WHEN p_official_bill IS NOT NULL AND p_official_bill > 0 THEN true
      ELSE v_register.has_official_bill
    END;
    v_official_billed_amount := CASE
      WHEN p_official_bill IS NOT NULL AND p_official_bill > 0 THEN p_official_bill
      WHEN v_register.has_official_bill THEN v_register.official_billed_amount
      ELSE NULL
    END;

    -- Clear linked register items from expenses before deleting draft items
    UPDATE public.finance_expenses
       SET bpjs_register_item_id = NULL
     WHERE bpjs_register_item_id IN (
       SELECT id FROM public.bpjs_monthly_register_items WHERE register_id = v_register_id
     );
    DELETE FROM public.bpjs_monthly_register_items WHERE register_id = v_register_id;
  ELSE
    v_has_official_bill := (p_official_bill IS NOT NULL AND p_official_bill > 0);
    v_official_billed_amount := CASE WHEN v_has_official_bill THEN p_official_bill ELSE NULL END;

    INSERT INTO public.bpjs_monthly_registers (
      period_year, period_month, official_billed_amount, has_official_bill, created_by
    ) VALUES (
      p_year, p_month, v_official_billed_amount, v_has_official_bill, auth.uid()
    ) RETURNING id INTO v_register_id;
  END IF;

  -- Iterate eligible active staff
  FOR v_staff IN
    SELECT id, full_name, employee_code, department, monthly_salary, bpjs_wage_basis,
           bpjs_enrollment_start_date, bpjs_enrollment_end_date, last_working_date, status
      FROM public.finance_staff_master
     WHERE bpjs_applicable = true
       AND (bpjs_enrollment_start_date IS NULL OR bpjs_enrollment_start_date <= (v_period_date + interval '1 month - 1 day')::date)
       AND (bpjs_enrollment_end_date IS NULL OR bpjs_enrollment_end_date >= v_period_date)
       AND (status = 'active' OR (last_working_date IS NOT NULL AND last_working_date >= v_period_date))
     ORDER BY employee_code NULLS LAST, full_name
  LOOP
    v_calc := public.calculate_staff_bpjs(v_staff.id, NULL, v_period_date);
    IF (v_calc->>'applicable')::boolean THEN
      INSERT INTO public.bpjs_monthly_register_items (
        register_id, staff_id, staff_name, employee_code, kpj_number, department,
        monthly_salary, wage_basis, is_wage_discrepant,
        program_jht, program_jkk, program_jkm, program_jp,
        jht_employee_rate, jht_employer_rate, jkk_employer_rate, jkm_employer_rate, jp_employee_rate, jp_employer_rate,
        employee_jht_amount, employee_jp_amount, total_employee_deduction,
        employer_jht_amount, employer_jkk_amount, employer_jkm_amount, employer_jp_amount,
        total_employer_expense, total_payable
      ) VALUES (
        v_register_id, v_staff.id, v_staff.full_name, v_staff.employee_code, v_calc->>'kpj_number', v_staff.department,
        v_staff.monthly_salary, (v_calc->>'wage_basis')::numeric, (v_calc->>'is_wage_discrepant')::boolean,
        (v_calc->>'program_jht')::boolean, (v_calc->>'program_jkk')::boolean, (v_calc->>'program_jkm')::boolean, (v_calc->>'program_jp')::boolean,
        (v_calc->>'jht_employee_rate')::numeric, (v_calc->>'jht_employer_rate')::numeric, (v_calc->>'jkk_employer_rate')::numeric, (v_calc->>'jkm_employer_rate')::numeric,
        (v_calc->>'jp_employee_rate')::numeric, (v_calc->>'jp_employer_rate')::numeric,
        (v_calc->>'employee_jht_amount')::numeric, (v_calc->>'employee_jp_amount')::numeric, (v_calc->>'total_employee_deduction')::numeric,
        (v_calc->>'employer_jht_amount')::numeric, (v_calc->>'employer_jkk_amount')::numeric, (v_calc->>'employer_jkm_amount')::numeric, (v_calc->>'employer_jp_amount')::numeric,
        (v_calc->>'total_employer_expense')::numeric, (v_calc->>'total_payable')::numeric
      ) RETURNING id INTO v_item_id;

      -- Controlled payroll grouping: select the primary regular salary expense for this staff member and month
      SELECT id INTO v_primary_exp_id
        FROM public.finance_expenses
       WHERE staff_id = v_staff.id
         AND expense_category = 'salary'
         AND approval_status <> 'cancelled'
         AND (
           (payroll_period_year = p_year AND payroll_period_month = p_month)
           OR (
             payroll_period_year IS NULL AND (
               description ILIKE '%' || to_char(v_period_date, 'Mon YYYY') || '%'
               OR description ILIKE '%' || to_char(v_period_date, 'Mon-YY') || '%'
               OR description ILIKE '%' || to_char(v_period_date, 'YYYY-MM') || '%'
               OR (EXTRACT(YEAR FROM expense_date) = p_year AND EXTRACT(MONTH FROM expense_date) = p_month)
             )
           )
         )
       ORDER BY
         -- Prefer regular salary over bonus/THR/overtime
         CASE WHEN description ILIKE '%bonus%' OR description ILIKE '%thr%' OR description ILIKE '%overtime%' THEN 1 ELSE 0 END ASC,
         -- Prefer salary matching or exceeding monthly base salary
         CASE WHEN amount >= v_staff.monthly_salary - 0.01 THEN 0 ELSE 1 END ASC,
         expense_date DESC,
         created_at DESC
       LIMIT 1;

      IF v_primary_exp_id IS NOT NULL THEN
        -- Synchronize employee deduction and register item on primary salary expense
        UPDATE public.finance_expenses
           SET bpjs_register_item_id = v_item_id,
               bpjs_employee_deduction = CASE
                 WHEN bpjs_employee_deduction = 0 OR bpjs_employee_deduction IS NULL THEN (v_calc->>'total_employee_deduction')::numeric
                 ELSE bpjs_employee_deduction
               END,
               payroll_period_year = p_year,
               payroll_period_month = p_month
         WHERE id = v_primary_exp_id;

        -- Unlink any secondary/bonus salary expenses from this register item to prevent duplicate deductions
        UPDATE public.finance_expenses
           SET bpjs_register_item_id = NULL
         WHERE staff_id = v_staff.id
           AND expense_category = 'salary'
           AND id <> v_primary_exp_id
           AND bpjs_register_item_id = v_item_id;
      END IF;

      v_wages := v_wages + (v_calc->>'wage_basis')::numeric;
      v_emp_jht := v_emp_jht + (v_calc->>'employee_jht_amount')::numeric;
      v_emp_jp := v_emp_jp + (v_calc->>'employee_jp_amount')::numeric;
      v_emp_ded := v_emp_ded + (v_calc->>'total_employee_deduction')::numeric;
      v_er_jht := v_er_jht + (v_calc->>'employer_jht_amount')::numeric;
      v_er_jkk := v_er_jkk + (v_calc->>'employer_jkk_amount')::numeric;
      v_er_jkm := v_er_jkm + (v_calc->>'employer_jkm_amount')::numeric;
      v_er_jp := v_er_jp + (v_calc->>'employer_jp_amount')::numeric;
      v_er_exp := v_er_exp + (v_calc->>'total_employer_expense')::numeric;
      v_total_pay := v_total_pay + (v_calc->>'total_payable')::numeric;
    END IF;
  END LOOP;

  -- Update register totals
  UPDATE public.bpjs_monthly_registers
     SET total_reported_wages = v_wages,
         total_employee_jht = v_emp_jht,
         total_employee_jp = v_emp_jp,
         total_employee_deductions = v_emp_ded,
         total_employer_jht = v_er_jht,
         total_employer_jkk = v_er_jkk,
         total_employer_jkm = v_er_jkm,
         total_employer_jp = v_er_jp,
         total_employer_expenses = v_er_exp,
         total_contribution_payable = v_total_pay,
         official_billed_amount = v_official_billed_amount,
         has_official_bill = v_has_official_bill,
         updated_at = now()
   WHERE id = v_register_id;

  RETURN jsonb_build_object(
    'register_id', v_register_id,
    'period_year', p_year,
    'period_month', p_month,
    'total_reported_wages', v_wages,
    'total_employee_deductions', v_emp_ded,
    'total_employer_expenses', v_er_exp,
    'total_contribution_payable', v_total_pay,
    'has_official_bill', v_has_official_bill,
    'official_billed_amount', v_official_billed_amount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_fund_transfer_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_year   TEXT;
v_month  TEXT;
v_prefix TEXT;
v_max    INT;
v_number TEXT;
BEGIN
v_year   := TO_CHAR(CURRENT_DATE, 'YY');
v_month  := TO_CHAR(CURRENT_DATE, 'MM');
v_prefix := 'FT' || v_year || v_month;

PERFORM pg_advisory_xact_lock(
hashtext('ft_number_' || v_year || v_month)
);

SELECT COALESCE(
MAX(
CAST(
SUBSTRING(transfer_number FROM '^FT\d{4}-(\d+)$')
AS INTEGER
)
),
0
) + 1
INTO v_max
FROM fund_transfers
WHERE transfer_number LIKE v_prefix || '-%';

v_number := v_prefix || '-' || LPAD(v_max::TEXT, 4, '0');
RETURN v_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_nota_retur_number(p_date date DEFAULT CURRENT_DATE)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_year TEXT;
  v_month TEXT;
  v_seq INTEGER;
  v_number TEXT;
BEGIN
  v_year := to_char(p_date, 'YYYY');
  v_month := to_char(p_date, 'MM');
  v_seq := nextval('public.nota_retur_number_seq');
  v_number := 'NR/' || v_year || '/' || v_month || '/' || lpad(v_seq::text, 4, '0');
  RETURN v_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_credit_note_item_fifo_cogs(p_cni_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cni record;
  v_cn record;
  v_orig_inv_id uuid;
  v_unit_cogs numeric(18,4);
BEGIN
  SELECT * INTO v_cni FROM public.credit_note_items WHERE id = p_cni_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  SELECT * INTO v_cn FROM public.credit_notes WHERE id = v_cni.credit_note_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- Resolve original invoice ID: directly on CN, or indirectly via Material Return
  v_orig_inv_id := v_cn.original_invoice_id;
  IF v_orig_inv_id IS NULL AND v_cn.material_return_id IS NOT NULL THEN
    SELECT mr.original_invoice_id INTO v_orig_inv_id
      FROM public.material_returns mr
     WHERE mr.id = v_cn.material_return_id;

    IF v_orig_inv_id IS NULL THEN
      SELECT si.id INTO v_orig_inv_id
        FROM public.material_returns mr
        JOIN public.sales_invoices si ON mr.original_dc_id::text = ANY(si.linked_challan_ids)
       WHERE mr.id = v_cn.material_return_id
       LIMIT 1;
    END IF;
  END IF;

  -- 1. Exact historical FIFO cost from original sales invoice line
  IF v_orig_inv_id IS NOT NULL THEN
    SELECT COALESCE(sii.cogs_unit_cost, CASE WHEN sii.quantity > 0 THEN ROUND(sii.cogs_total_cost / sii.quantity, 4) ELSE NULL END)
      INTO v_unit_cogs
      FROM public.sales_invoice_items sii
     WHERE sii.invoice_id = v_orig_inv_id
       AND (
         (v_cni.batch_id IS NOT NULL AND sii.batch_id = v_cni.batch_id)
         OR (v_cni.batch_id IS NULL AND sii.product_id = v_cni.product_id)
       )
       AND ((sii.cogs_unit_cost IS NOT NULL AND sii.cogs_unit_cost > 0) OR (sii.cogs_total_cost IS NOT NULL AND sii.cogs_total_cost > 0))
     ORDER BY sii.created_at
     LIMIT 1;
  END IF;

  -- 1b. Fallback: Delivery challan / inventory transaction for original FIFO cost
  IF (v_unit_cogs IS NULL OR v_unit_cogs <= 0) AND v_cn.material_return_id IS NOT NULL THEN
    SELECT it.unit_cost INTO v_unit_cogs
      FROM public.material_returns mr
      JOIN public.inventory_transactions it ON it.source_id = mr.original_dc_id
     WHERE mr.id = v_cn.material_return_id
       AND (
         (v_cni.batch_id IS NOT NULL AND it.batch_id = v_cni.batch_id)
         OR (v_cni.batch_id IS NULL AND it.product_id = v_cni.product_id)
       )
       AND it.unit_cost IS NOT NULL AND it.unit_cost > 0
     ORDER BY it.created_at
     LIMIT 1;
  END IF;

  -- 2. Fallback to batch landed cost if original transaction cost not found
  IF v_unit_cogs IS NULL OR v_unit_cogs <= 0 THEN
    SELECT COALESCE(b.landed_cost_per_unit, b.cost_per_unit, 0) INTO v_unit_cogs
      FROM public.batches b
     WHERE b.id = v_cni.batch_id;
  END IF;

  RETURN ROUND(v_cni.quantity * COALESCE(v_unit_cogs, 0), 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_next_product_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role text;
  v_max_code text;
  v_next_num integer;
BEGIN
  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
  IF v_role NOT IN ('admin', 'accounts', 'warehouse') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot generate product codes', v_role;
  END IF;

  SELECT MAX(product_code) INTO v_max_code
  FROM products
  WHERE product_code ~ '^[A-Z]{2,4}-[0-9]+$';

  IF v_max_code IS NULL THEN RETURN 'PRD-001'; END IF;
  v_next_num := (regexp_match(v_max_code, '[0-9]+$'))[1]::integer + 1;
  RETURN regexp_replace(v_max_code, '[0-9]+$', LPAD(v_next_num::text, 3, '0'));
END;
$function$

CREATE OR REPLACE FUNCTION public.invoke_bulk_email_worker()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_due_count integer;
  v_settings record;
BEGIN
  -- 1. Check if there are any in_progress campaigns due for processing
  SELECT count(*) INTO v_due_count
  FROM public.bulk_email_campaigns
  WHERE status = 'in_progress'
    AND (next_run_at IS NULL OR next_run_at <= now())
    AND (worker_lock_until IS NULL OR worker_lock_until < now());

  IF v_due_count = 0 THEN
    RETURN;
  END IF;

  -- 2. Read worker URL and secret from app_settings
  SELECT bulk_email_worker_url, bulk_email_worker_secret
  INTO v_settings
  FROM public.app_settings
  LIMIT 1;

  IF v_settings.bulk_email_worker_url IS NULL OR v_settings.bulk_email_worker_secret IS NULL THEN
    RAISE LOG 'bulk email worker cron skipped: worker URL/secret not configured';
    RETURN;
  END IF;

  -- 3. Post to process-bulk-email-campaign via pg_net
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    PERFORM net.http_post(
      url := v_settings.bulk_email_worker_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'X-Bulk-Email-Worker-Secret', v_settings.bulk_email_worker_secret
      ),
      body := '{}'::jsonb,
      timeout_milliseconds := 25000
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.invoke_process_whatsapp_campaign()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_due_count integer;
  v_worker_url text;
  v_worker_secret text := 'sapj_wa_worker_internal_2026';
  v_vault_secret text;
BEGIN
  -- 1. Check if there are any in_progress campaigns due for next recipient dispatch
  SELECT count(*) INTO v_due_count
  FROM public.whatsapp_campaigns
  WHERE status = 'in_progress'
    AND (next_run_at IS NULL OR next_run_at <= now())
    AND (worker_lock_until IS NULL OR worker_lock_until < now());

  IF v_due_count = 0 THEN
    RETURN;
  END IF;

  -- 2. Worker URL
  v_worker_url := 'https://dkrtsqienlhpouohmfki.supabase.co/functions/v1/process-whatsapp-campaign';

  -- 3. Read optional secret override from Supabase Vault if present
  BEGIN
    SELECT decrypted_secret INTO v_vault_secret
    FROM vault.decrypted_secrets
    WHERE name = 'whatsapp_worker_secret'
    LIMIT 1;
    IF v_vault_secret IS NOT NULL AND v_vault_secret <> '' THEN
      v_worker_secret := v_vault_secret;
    END IF;
  EXCEPTION WHEN OTHERS THEN
  END;

  -- 4. Dispatch HTTP POST to process-whatsapp-campaign edge function via pg_net
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    PERFORM net.http_post(
      url := v_worker_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'X-WhatsApp-Worker-Secret', v_worker_secret
      ),
      body := jsonb_build_object(
        'source', 'pg_cron',
        'scheduled', true
      ),
      timeout_milliseconds := 25000
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.learn_from_match(p_description text, p_expense_category text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_pattern  text;
v_existing record;
v_role     text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot update match memory', v_role;
END IF;

v_pattern := LOWER(TRIM(SUBSTRING(p_description FROM 1 FOR 50)));

SELECT * INTO v_existing FROM bank_match_memory
WHERE description_pattern = v_pattern AND expense_category = p_expense_category;

IF v_existing.id IS NOT NULL THEN
UPDATE bank_match_memory
SET match_count = match_count + 1, confidence_score = LEAST(confidence_score + 5, 100),
last_matched_at = now()
WHERE id = v_existing.id;
ELSE
INSERT INTO bank_match_memory (
description_pattern, expense_category, match_count, confidence_score, created_by
) VALUES (v_pattern, p_expense_category, 1, 50, auth.uid());
END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.link_bank_statement_line(p_bank_line_id uuid, p_document_type text, p_document_id uuid, p_payment_kind text DEFAULT 'supplier'::text, p_allocation_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_line public.bank_statement_lines%rowtype;
  v_expense public.finance_expenses%rowtype;
  v_je uuid;
  v_bank_coa uuid;
  v_bank_currency text;
  v_expense_currency text;
  v_bank_total numeric;
  v_bank_allocated numeric;
  v_bank_remaining numeric;
  v_doc_total numeric;
  v_doc_allocated numeric;
  v_doc_remaining numeric;
  v_allocate numeric;
  v_allocation_id uuid := gen_random_uuid();
  v_settlement_coa uuid;
  v_rate numeric;
  v_functional_amount numeric;
  v_entry text;
  v_period_id uuid;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  ELSIF auth.role() = 'anon' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_bank_line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;

  IF p_document_type = 'expense' THEN
    SELECT * INTO v_expense FROM public.finance_expenses WHERE id = p_document_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
    SELECT (array_agg(id ORDER BY created_at DESC, id DESC))[1] INTO v_je
      FROM public.journal_entries
     WHERE source_module IN ('expense', 'expenses')
       AND (reference_id = p_document_id OR reference_number = 'EXP-' || p_document_id::text)
       AND is_posted = true AND NOT COALESCE(is_reversed, false);
  ELSIF p_document_type = 'receipt' THEN
    SELECT journal_entry_id INTO v_je FROM public.receipt_vouchers WHERE id = p_document_id;
  ELSIF p_document_type = 'payment' THEN
    SELECT journal_entry_id INTO v_je FROM public.payment_vouchers WHERE id = p_document_id;
  ELSIF p_document_type = 'fund_transfer' THEN
    SELECT journal_entry_id INTO v_je FROM public.fund_transfers WHERE id = p_document_id;
  ELSIF p_document_type = 'petty_cash' THEN
    SELECT journal_entry_id INTO v_je FROM public.petty_cash_transactions WHERE id = p_document_id;
  ELSIF p_document_type = 'tax_payment' THEN
    SELECT journal_entry_id INTO v_je FROM public.tax_payments WHERE id = p_document_id;
  ELSIF p_document_type = 'journal' THEN
    SELECT id INTO v_je FROM public.journal_entries WHERE id = p_document_id AND is_posted AND NOT COALESCE(is_reversed, false);
  ELSE
    RAISE EXCEPTION 'Unsupported reconciliation document type %', p_document_type;
  END IF;

  IF v_je IS NULL THEN
    RAISE EXCEPTION 'Document must have an active posted journal before reconciliation';
  END IF;

  SELECT coa_id, upper(currency) INTO v_bank_coa, v_bank_currency
    FROM public.bank_accounts WHERE id = v_line.bank_account_id;
  IF v_bank_coa IS NULL THEN
    RAISE EXCEPTION 'Selected bank account has no General Ledger account';
  END IF;

  IF p_document_type <> 'expense' THEN
    SELECT COALESCE(sum(CASE WHEN COALESCE(v_line.credit_amount, 0) > 0 THEN COALESCE(jel.transaction_debit, jel.debit)
                             ELSE COALESCE(jel.transaction_credit, jel.credit) END), 0)
      INTO v_doc_total FROM public.journal_entry_lines jel
     WHERE jel.journal_entry_id = v_je AND jel.account_id = v_bank_coa;
    IF v_doc_total <= 0.01 THEN
      RAISE EXCEPTION 'Document journal does not contain the selected bank account on the matching side';
    END IF;
  END IF;

  v_bank_total := COALESCE(NULLIF(v_line.debit_amount, 0), v_line.credit_amount, 0);
  SELECT COALESCE(sum(allocation_amount), 0) INTO v_bank_allocated
    FROM public.bank_statement_allocations WHERE bank_statement_line_id = p_bank_line_id;

  IF p_document_type = 'expense' THEN
    IF COALESCE(v_line.debit_amount, 0) <= 0 THEN
      RAISE EXCEPTION 'Expense payment requires an outgoing bank transaction';
    END IF;
    v_expense_currency := upper(COALESCE(v_expense.transaction_currency, v_expense.currency_code, 'IDR'));
    IF COALESCE(v_bank_currency, 'IDR') <> v_expense_currency THEN
      RAISE EXCEPTION 'Direct expense allocation requires matching expense and bank currencies';
    END IF;
    IF COALESCE(p_payment_kind, 'supplier') = 'supplier' THEN
      v_doc_total := COALESCE(public.calculate_finance_expense_payable(p_document_id), 0);
      SELECT id INTO v_settlement_coa FROM public.chart_of_accounts WHERE code = '2110' LIMIT 1;
    ELSIF p_payment_kind = 'pph23' THEN
      v_doc_total := COALESCE(v_expense.pph_amount, 0);
      SELECT id INTO v_settlement_coa FROM public.chart_of_accounts WHERE code = '2132' LIMIT 1;
    ELSE
      RAISE EXCEPTION 'Unsupported expense payment kind %', p_payment_kind;
    END IF;
    IF v_settlement_coa IS NULL THEN
      RAISE EXCEPTION 'Expense settlement account is not configured';
    END IF;

    SELECT
      COALESCE((SELECT sum(a.allocation_amount) FROM public.bank_statement_allocations a
                 WHERE a.document_type = 'expense' AND a.document_id = p_document_id
                   AND a.payment_kind = COALESCE(p_payment_kind, 'supplier')), 0)
      + COALESCE((SELECT sum(va.allocated_amount) FROM public.voucher_allocations va
                    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
                   WHERE va.finance_expense_id = p_document_id
                     AND COALESCE(va.payment_kind, 'supplier') = COALESCE(p_payment_kind, 'supplier')
                     AND pv.is_posted = true), 0)
      INTO v_doc_allocated;
  ELSE
    SELECT COALESCE(sum(allocation_amount), 0) INTO v_doc_allocated
      FROM public.bank_statement_allocations
     WHERE document_type = p_document_type AND document_id = p_document_id
       AND payment_kind = COALESCE(p_payment_kind, 'supplier');
  END IF;

  v_bank_remaining := v_bank_total - v_bank_allocated;
  v_doc_remaining := v_doc_total - v_doc_allocated;

  -- Universal Idempotency: Return existing allocation safely if already recorded
  IF EXISTS (
    SELECT 1 FROM public.bank_statement_allocations a
     WHERE a.bank_statement_line_id = p_bank_line_id
       AND a.document_type = p_document_type
       AND a.document_id = p_document_id
       AND a.payment_kind = COALESCE(p_payment_kind, 'supplier')
  ) THEN
    SELECT a.allocation_amount, a.journal_entry_id INTO v_allocate, v_je
      FROM public.bank_statement_allocations a
     WHERE a.bank_statement_line_id = p_bank_line_id
       AND a.document_type = p_document_type
       AND a.document_id = p_document_id
       AND a.payment_kind = COALESCE(p_payment_kind, 'supplier')
     LIMIT 1;

    PERFORM public.sync_bank_line_allocation_owner(p_bank_line_id);
    UPDATE public.bank_statement_lines
       SET matched_at = COALESCE(matched_at, now()),
           matched_by = COALESCE(matched_by, auth.uid()),
           manually_unlinked = true
     WHERE id = p_bank_line_id;
    PERFORM public.refresh_bank_statement_allocation_status(p_bank_line_id);
    IF p_document_type = 'expense' THEN PERFORM public.recalculate_expense_payment_state(p_document_id); END IF;
    RETURN jsonb_build_object(
      'allocation_amount', v_allocate,
      'bank_total', v_bank_total,
      'bank_allocated', v_bank_allocated,
      'bank_remaining', v_bank_remaining,
      'document_total', v_doc_total,
      'document_allocated', v_doc_allocated,
      'document_remaining', v_doc_remaining,
      'journal_entry_id', v_je,
      'status', 'already_linked'
    );
  END IF;

  v_allocate := round(COALESCE(NULLIF(p_allocation_amount, 0), LEAST(v_bank_remaining, v_doc_remaining)), 2);
  IF v_allocate <= 0.01 THEN RAISE EXCEPTION 'No remaining amount is available to allocate'; END IF;
  IF v_allocate > v_bank_remaining + 0.01 THEN RAISE EXCEPTION 'Allocation exceeds remaining bank amount'; END IF;
  IF v_allocate > v_doc_remaining + 0.01 THEN RAISE EXCEPTION 'Allocation exceeds document outstanding amount'; END IF;

  IF p_document_type = 'expense' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.journal_entries
       WHERE source_module = 'expense_payment'
         AND reference_number = 'EXP-PAY-' || v_allocation_id::text
         AND is_posted = true AND NOT COALESCE(is_reversed, false)
    ) THEN
      v_rate := COALESCE(NULLIF(v_expense.exchange_rate, 0), 1);
      v_functional_amount := round(v_allocate * v_rate, 2);
      SELECT id INTO v_period_id FROM public.accounting_periods
       WHERE v_line.transaction_date BETWEEN start_date AND end_date
       ORDER BY start_date DESC LIMIT 1;
      v_entry := public.next_journal_entry_number();
      INSERT INTO public.journal_entries (
        entry_number, entry_date, period_id, source_module, reference_id,
        reference_number, description, total_debit, total_credit, is_posted,
        is_reversed, posted_by, posted_at, created_by, transaction_currency,
        functional_currency, exchange_rate, amounts_are_functional
      ) VALUES (
        v_entry, v_line.transaction_date, v_period_id, 'expense_payment', p_document_id,
        'EXP-PAY-' || v_allocation_id::text,
        'Bank reconciliation payment for ' || COALESCE(v_expense.voucher_number, 'expense') || ' (Statement ' || COALESCE(v_line.reference, v_line.id::text) || ')',
        v_functional_amount, v_functional_amount, true, false, auth.uid(), now(), auth.uid(),
        v_expense_currency, 'IDR', v_rate, true
      ) RETURNING id INTO v_je;

      INSERT INTO public.journal_entry_lines (
        journal_entry_id, line_number, account_id, description, debit, credit,
        transaction_currency, transaction_debit, transaction_credit, functional_currency,
        exchange_rate, supplier_id
      ) VALUES
        (v_je, 1, v_settlement_coa, 'Expense settlement - ' || COALESCE(v_expense.voucher_number, ''), v_functional_amount, 0,
         v_expense_currency, v_allocate, 0, 'IDR', v_rate, v_expense.supplier_id),
        (v_je, 2, v_bank_coa, 'Bank payment - ' || COALESCE(v_expense.voucher_number, ''), 0, v_functional_amount,
         v_bank_currency, 0, v_allocate, 'IDR', v_rate, v_expense.supplier_id);
    END IF;
  END IF;

  INSERT INTO public.bank_statement_allocations(
    id, bank_statement_line_id, document_type, document_id, journal_entry_id,
    allocation_amount, payment_kind, created_by
  ) VALUES (
    v_allocation_id, p_bank_line_id, p_document_type, p_document_id, v_je,
    v_allocate, COALESCE(p_payment_kind, 'supplier'), auth.uid()
  );

  PERFORM public.sync_bank_line_allocation_owner(p_bank_line_id);
  UPDATE public.bank_statement_lines
     SET matched_at = now(), matched_by = auth.uid(), manually_unlinked = true
   WHERE id = p_bank_line_id;

  PERFORM public.refresh_bank_statement_allocation_status(p_bank_line_id);
  IF p_document_type = 'expense' THEN PERFORM public.recalculate_expense_payment_state(p_document_id); END IF;

  RETURN jsonb_build_object(
    'allocation_amount', v_allocate,
    'bank_total', v_bank_total,
    'bank_allocated', v_bank_allocated + v_allocate,
    'bank_remaining', v_bank_remaining - v_allocate,
    'document_total', v_doc_total,
    'document_allocated', v_doc_allocated + v_allocate,
    'document_remaining', v_doc_remaining - v_allocate,
    'journal_entry_id', v_je
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.link_or_generate_nota_retur_for_credit_note(p_credit_note_id uuid, p_nomor_nota_retur text DEFAULT NULL::text, p_tanggal_nota_retur date DEFAULT CURRENT_DATE, p_actor uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_inv public.sales_invoices%ROWTYPE;
  v_cust public.customers%ROWTYPE;
  v_nr_id uuid;
  v_caller uuid := auth.uid();
  v_tax_rate numeric(8,4) := 0.1100;
  v_nr_number text;
BEGIN
  IF v_caller IS NULL THEN
    IF current_user = 'service_role' OR session_user = 'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) OR (COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''), '')) = 'service_role' THEN
      v_caller := p_actor;
    ELSE
      RAISE EXCEPTION 'Authentication required: no active session';
    END IF;
  END IF;

  SELECT * INTO v_cn FROM public.credit_notes WHERE id = p_credit_note_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit note % not found', p_credit_note_id;
  END IF;

  -- Deduplication: return existing if already linked
  IF v_cn.nota_retur_id IS NOT NULL THEN
    RETURN v_cn.nota_retur_id;
  END IF;

  SELECT * INTO v_inv FROM public.sales_invoices WHERE id = v_cn.original_invoice_id;
  SELECT * INTO v_cust FROM public.customers WHERE id = v_cn.customer_id;

  -- Derive tax rate from invoice or credit note
  IF v_cn.subtotal > 0 AND v_cn.tax_amount > 0 THEN
    v_tax_rate := ROUND(v_cn.tax_amount / v_cn.subtotal, 4);
  ELSIF v_inv.subtotal > 0 AND v_inv.tax_amount > 0 THEN
    v_tax_rate := ROUND(v_inv.tax_amount / v_inv.subtotal, 4);
  END IF;

  v_nr_number := COALESCE(NULLIF(TRIM(p_nomor_nota_retur), ''), 'NR-' || to_char(COALESCE(p_tanggal_nota_retur, CURRENT_DATE), 'YYYY') || '-' || lpad(floor(random() * 9000 + 1000)::text, 4, '0'));

  INSERT INTO public.nota_retur (
    nota_retur_number,
    return_date,
    credit_note_id,
    material_return_id,
    sales_invoice_id,
    original_invoice_number,
    sales_invoice_number,
    customer_id,
    customer_name,
    customer_address,
    currency,
    dpp_amount,
    tax_rate,
    ppn_amount,
    total_amount,
    status,
    coretax_status,
    created_by
  ) VALUES (
    v_nr_number,
    COALESCE(p_tanggal_nota_retur, CURRENT_DATE),
    v_cn.id,
    v_cn.material_return_id,
    v_cn.original_invoice_id,
    v_inv.invoice_number,
    v_inv.invoice_number,
    v_cn.customer_id,
    v_cust.company_name,
    v_cust.address,
    v_cn.currency,
    v_cn.subtotal,
    v_tax_rate,
    v_cn.tax_amount,
    v_cn.total_amount,
    'draft',
    'draft',
    v_caller
  ) RETURNING id INTO v_nr_id;

  UPDATE public.credit_notes
     SET nota_retur_id = v_nr_id
   WHERE id = v_cn.id;

  RETURN v_nr_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_import_container(p_container_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public._sec_check_finance_role();

  UPDATE import_containers
  SET status = 'locked', locked_at = now(), locked_by = auth.uid(), updated_at = now()
  WHERE id = p_container_id AND status = 'allocated';
  IF NOT FOUND THEN RAISE EXCEPTION 'Container not found or already locked'; END IF;

  UPDATE batches SET cost_locked = true, cost_locked_at = now(), updated_at = now()
  WHERE import_container_id = p_container_id AND cost_locked = false;

  RETURN true;
END;
$function$

