CREATE OR REPLACE FUNCTION public.next_payment_voucher_number(p_voucher_date date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_start_year int;
  v_fy text;
  v_prefix text;
  v_next int;
BEGIN
  IF p_voucher_date IS NULL THEN RAISE EXCEPTION 'Voucher date is required'; END IF;
  v_start_year := EXTRACT(YEAR FROM p_voucher_date)::int;
  v_fy := right(v_start_year::text, 2) || '-' || right(v_start_year::text, 2);
  v_prefix := 'PV/' || v_fy || '/';
  PERFORM pg_advisory_xact_lock(hashtext('payment_voucher_' || v_fy));
  SELECT COALESCE(MAX((regexp_match(voucher_number, '/([0-9]+)$'))[1]::int), 0) + 1
    INTO v_next
    FROM public.payment_vouchers
   WHERE voucher_number LIKE v_prefix || '%';
  RETURN v_prefix || lpad(v_next::text, 3, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.next_receipt_voucher_number(p_voucher_date date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prefix text;
  v_next int;
BEGIN
  IF p_voucher_date IS NULL THEN
    RAISE EXCEPTION 'Voucher date is required';
  END IF;
  v_prefix := 'RV' || to_char(p_voucher_date, 'YYMM') || '-';
  PERFORM pg_advisory_xact_lock(hashtext('receipt_voucher_' || v_prefix));
  SELECT COALESCE(MAX((regexp_match(voucher_number, '-([0-9]+)$'))[1]::int), 0) + 1
    INTO v_next
    FROM public.receipt_vouchers
   WHERE voucher_number LIKE v_prefix || '%';
  RETURN v_prefix || lpad(v_next::text, 4, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.post_bpjs_monthly_register(p_register_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_reg public.bpjs_monthly_registers%ROWTYPE;
  v_period_id uuid;
  v_je_id uuid;
  v_entry_num text;
  v_bpjs_payable_coa_id uuid;
  v_bpjs_expense_coa_id uuid;
  v_user uuid;
  v_posting_date date;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_user := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  SELECT * INTO v_reg FROM public.bpjs_monthly_registers WHERE id = p_register_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BPJS register % not found', p_register_id; END IF;
  IF v_reg.status IN ('posted', 'reconciled') THEN
    RAISE EXCEPTION 'BPJS register % is already posted', p_register_id;
  END IF;

  v_posting_date := (make_date(v_reg.period_year, v_reg.period_month, 1) + interval '1 month - 1 day')::date;

  -- Resolve period
  SELECT id INTO v_period_id FROM public.accounting_periods
   WHERE start_date <= v_posting_date AND end_date >= v_posting_date
   ORDER BY start_date DESC LIMIT 1;

  -- Resolve accounts: 2134 BPJS Payable & 6115 BPJS Expense (or fallback 6110 Employee Benefits)
  SELECT id INTO v_bpjs_payable_coa_id FROM public.chart_of_accounts WHERE code = '2134' LIMIT 1;
  SELECT id INTO v_bpjs_expense_coa_id FROM public.chart_of_accounts WHERE code = '6115' LIMIT 1;
  IF v_bpjs_expense_coa_id IS NULL THEN
    SELECT id INTO v_bpjs_expense_coa_id FROM public.chart_of_accounts WHERE code = '6110' LIMIT 1;
  END IF;

  IF v_bpjs_payable_coa_id IS NULL THEN RAISE EXCEPTION 'Account 2134 BPJS Payable not found'; END IF;
  IF v_bpjs_expense_coa_id IS NULL THEN RAISE EXCEPTION 'BPJS Expense account not found'; END IF;

  v_entry_num := public.next_journal_entry_number();

  -- Create Journal Entry for Employer Contribution portion
  -- (Employee deductions are accrued via payroll/salary expense into 2134;
  -- employer contributions are recognized as company expense 6115 -> liability 2134)
  INSERT INTO public.journal_entries (
    entry_number, entry_date, period_id, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, posted_at, created_by,
    transaction_currency, functional_currency, exchange_rate, amounts_are_functional
  ) VALUES (
    v_entry_num, v_posting_date, v_period_id, 'bpjs_register', v_reg.id,
    'BPJS-' || v_reg.period_year || '-' || lpad(v_reg.period_month::text, 2, '0'),
    'BPJS Ketenagakerjaan Employer Contribution - ' || to_char(v_posting_date, 'Mon YYYY'),
    v_reg.total_employer_expenses, v_reg.total_employer_expenses, true, v_user, now(), v_user,
    'IDR', 'IDR', 1.0, true
  ) RETURNING id INTO v_je_id;

  -- Debit: 6115 BPJS Expense
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES (
    v_je_id, 1, v_bpjs_expense_coa_id, v_reg.total_employer_expenses, 0,
    'Employer BPJS Contribution (JHT, JKK, JKM)', 'IDR', v_reg.total_employer_expenses, 0, 'IDR', 1.0
  );

  -- Credit: 2134 BPJS Payable
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES (
    v_je_id, 2, v_bpjs_payable_coa_id, 0, v_reg.total_employer_expenses,
    'BPJS Ketenagakerjaan Employer Payable', 'IDR', 0, v_reg.total_employer_expenses, 'IDR', 1.0
  );

  UPDATE public.bpjs_monthly_registers
     SET status = 'posted',
         journal_entry_id = v_je_id,
         posted_by = v_user,
         posted_at = now(),
         updated_at = now()
   WHERE id = v_reg.id;

  RETURN jsonb_build_object(
    'register_id', v_reg.id,
    'journal_entry_id', v_je_id,
    'entry_number', v_entry_num,
    'total_posted', v_reg.total_employer_expenses
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.post_fund_transfer_journal(p_transfer_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_transfer        RECORD;
  v_journal_id      UUID;
  v_from_coa_id     UUID;
  v_to_coa_id       UUID;
  v_fx_gain_coa     UUID;
  v_fx_loss_coa     UUID;
  v_charge_coa      UUID;
  v_description     TEXT;
  v_actor           UUID;
  v_from_curr       TEXT := 'IDR';
  v_to_curr         TEXT := 'IDR';
  v_from_amount_idr NUMERIC;
  v_to_amount_idr   NUMERIC;
  v_fx_diff         NUMERIC := 0;
  v_total_debit     NUMERIC;
  v_total_credit    NUMERIC;
  v_usd_rate        NUMERIC := 1;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  v_actor := COALESCE(auth.uid(), p_user_id);

  SELECT * INTO v_transfer FROM public.fund_transfers WHERE id = p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fund transfer not found'; END IF;
  IF v_transfer.journal_entry_id IS NOT NULL THEN RETURN v_transfer.journal_entry_id; END IF;

  -- Resolve From Account COA
  IF v_transfer.from_account_type = 'petty_cash' THEN
    SELECT id INTO v_from_coa_id FROM public.chart_of_accounts WHERE code = '1102' AND is_active = true LIMIT 1;
    v_from_curr := 'IDR';
  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN
    SELECT id INTO v_from_coa_id FROM public.chart_of_accounts WHERE code = '1101' AND is_active = true LIMIT 1;
    v_from_curr := 'IDR';
  ELSIF v_transfer.from_account_type = 'bank' THEN
    SELECT ba.coa_id, upper(ba.currency) INTO v_from_coa_id, v_from_curr
    FROM public.bank_accounts ba WHERE ba.id = v_transfer.from_bank_account_id;
  END IF;

  -- Resolve To Account COA
  IF v_transfer.to_account_type = 'petty_cash' THEN
    SELECT id INTO v_to_coa_id FROM public.chart_of_accounts WHERE code = '1102' AND is_active = true LIMIT 1;
    v_to_curr := 'IDR';
  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN
    SELECT id INTO v_to_coa_id FROM public.chart_of_accounts WHERE code = '1101' AND is_active = true LIMIT 1;
    v_to_curr := 'IDR';
  ELSIF v_transfer.to_account_type = 'bank' THEN
    SELECT ba.coa_id, upper(ba.currency) INTO v_to_coa_id, v_to_curr
    FROM public.bank_accounts ba WHERE ba.id = v_transfer.to_bank_account_id;
  END IF;

  IF v_from_coa_id IS NULL OR v_to_coa_id IS NULL THEN
    RAISE EXCEPTION 'Cannot determine chart of accounts for transfer %', v_transfer.transfer_number;
  END IF;

  -- Resolve FX Gain / Loss Accounts
  SELECT id INTO v_fx_gain_coa FROM public.chart_of_accounts WHERE code = '4930' AND is_active = true LIMIT 1;
  SELECT id INTO v_fx_loss_coa FROM public.chart_of_accounts WHERE code = '7300' AND is_active = true LIMIT 1;

  -- Calculate Functional Amounts dynamically:
  IF v_from_curr = 'IDR' AND v_to_curr = 'USD' THEN
    v_from_amount_idr := COALESCE(v_transfer.from_amount, v_transfer.amount);
    v_to_amount_idr := v_from_amount_idr;
    v_total_debit := v_to_amount_idr;
    v_total_credit := v_from_amount_idr;

  ELSIF v_from_curr = 'USD' AND v_to_curr = 'IDR' THEN
    -- Derive USD bank carrying rate dynamically as of transfer date
    SELECT 
      CASE 
        WHEN NULLIF(SUM(jel.transaction_debit - jel.transaction_credit), 0) IS NOT NULL AND SUM(jel.transaction_debit - jel.transaction_credit) > 0 THEN 
          round(SUM(jel.debit - jel.credit) / SUM(jel.transaction_debit - jel.transaction_credit), 4)
        ELSE 
          COALESCE(
            (SELECT frl.revalued_rate
             FROM public.fx_revaluation_lines frl
             JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
             WHERE frl.bank_account_id = v_transfer.from_bank_account_id
               AND fr.status = 'posted'
               AND fr.revaluation_date <= v_transfer.transfer_date
             ORDER BY fr.revaluation_date DESC, fr.created_at DESC
             LIMIT 1),
            v_transfer.exchange_rate,
            1
          )
      END
    INTO v_usd_rate
    FROM public.journal_entry_lines jel
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE jel.account_id = v_from_coa_id 
      AND je.is_posted = true 
      AND NOT COALESCE(je.is_reversed, false)
      AND je.entry_date <= v_transfer.transfer_date;

    v_usd_rate := COALESCE(v_usd_rate, v_transfer.exchange_rate, 1);
    v_to_amount_idr := COALESCE(v_transfer.to_amount, v_transfer.amount);
    v_from_amount_idr := round(COALESCE(v_transfer.from_amount, v_transfer.amount) * v_usd_rate, 2);
    v_fx_diff := v_to_amount_idr - v_from_amount_idr;

    v_total_debit := v_to_amount_idr + CASE WHEN v_fx_diff < 0 THEN abs(v_fx_diff) ELSE 0 END;
    v_total_credit := v_from_amount_idr + CASE WHEN v_fx_diff > 0 THEN v_fx_diff ELSE 0 END;

  ELSE
    -- Same Currency (IDR -> IDR)
    v_from_amount_idr := v_transfer.amount;
    v_to_amount_idr := v_transfer.amount;
    v_total_debit := v_transfer.amount;
    v_total_credit := v_transfer.amount;
  END IF;

  v_description := 'Fund Transfer ' || v_transfer.transfer_number;
  IF v_transfer.description IS NOT NULL THEN
    v_description := v_description || ' - ' || v_transfer.description;
  END IF;

  INSERT INTO public.journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, created_by,
    transaction_currency, functional_currency, exchange_rate
  ) VALUES (
    public.next_journal_entry_number(), v_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,
    v_description, v_total_debit, v_total_credit, true, v_actor,
    v_from_curr, 'IDR', COALESCE(v_transfer.exchange_rate, 1)
  ) RETURNING id INTO v_journal_id;

  -- Line 1: Debit Destination Account (Transfer In)
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate
  ) VALUES (
    v_journal_id, 1, v_to_coa_id, v_to_amount_idr, 0, 'Transfer In - ' || v_transfer.transfer_number,
    v_to_curr, COALESCE(v_transfer.to_amount, v_transfer.amount), 0, COALESCE(v_transfer.exchange_rate, 1)
  );

  -- Line 2: Credit Source Account (Transfer Out)
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate
  ) VALUES (
    v_journal_id, 2, v_from_coa_id, 0, v_from_amount_idr, 'Transfer Out - ' || v_transfer.transfer_number,
    v_from_curr, 0, COALESCE(v_transfer.from_amount, v_transfer.amount), COALESCE(v_transfer.exchange_rate, 1)
  );

  -- Line 3: Realized FX Gain / Loss if USD -> IDR difference
  IF v_fx_diff > 0 AND v_fx_gain_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, debit, credit, description,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate
    ) VALUES (
      v_journal_id, 3, v_fx_gain_coa, 0, v_fx_diff, 'Realized FX Gain on Fund Transfer - ' || v_transfer.transfer_number,
      'IDR', 0, v_fx_diff, 1
    );
  ELSIF v_fx_diff < 0 AND v_fx_loss_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, debit, credit, description,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate
    ) VALUES (
      v_journal_id, 3, v_fx_loss_coa, abs(v_fx_diff), 0, 'Realized FX Loss on Fund Transfer - ' || v_transfer.transfer_number,
      'IDR', abs(v_fx_diff), 0, 1
    );
  END IF;

  UPDATE public.fund_transfers
  SET journal_entry_id = v_journal_id,
      status = 'posted',
      posted_at = now(),
      posted_by = v_actor
  WHERE id = p_transfer_id;

  -- Synchronize bank balances if bank accounts involved
  IF v_transfer.from_bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_transfer.from_bank_account_id);
  END IF;
  IF v_transfer.to_bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_transfer.to_bank_account_id);
  END IF;

  RETURN v_journal_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_import_cost_journal(p_header_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
v_header RECORD;
v_je_id UUID;
v_je_number TEXT;
v_inventory_account_id UUID;
v_clearing_account_id UUID;
v_total_cost DECIMAL(18,2);
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot post import cost journals', v_role;
END IF;

SELECT * INTO v_header FROM import_cost_headers WHERE id = p_header_id;
IF NOT FOUND THEN
RAISE EXCEPTION 'Import cost header not found';
END IF;

SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
SELECT id INTO v_clearing_account_id  FROM chart_of_accounts WHERE code = '2140' LIMIT 1;

IF v_inventory_account_id IS NULL OR v_clearing_account_id IS NULL THEN
RAISE EXCEPTION 'Required accounts not found (1130 Inventory or 2140 Customer Deposits)';
END IF;

v_total_cost := v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +
v_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +
v_header.port_charges + v_header.other_charges;

IF v_total_cost <= 0 THEN
RAISE EXCEPTION 'Total allocated cost must be greater than zero';
END IF;

v_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((
SELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'
)::TEXT, 4, '0');

INSERT INTO journal_entries (
entry_number, entry_date, source_module, reference_id, reference_number,
description, total_debit, total_credit, is_posted, posted_by
) VALUES (
v_je_number, v_header.import_date, 'import_cost', p_header_id, v_header.cost_sheet_number,
'Import Cost Allocation: ' || v_header.cost_sheet_number,
v_total_cost, v_total_cost, true, v_header.created_by
) RETURNING id INTO v_je_id;

INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)
VALUES
(v_je_id, 1, v_inventory_account_id, 'Import Costs - '    || v_header.cost_sheet_number, v_total_cost, 0,            v_header.supplier_id),
(v_je_id, 2, v_clearing_account_id,  'Import Clearing - ' || v_header.cost_sheet_number, 0,            v_total_cost, v_header.supplier_id);

RETURN v_je_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_inventory_movement(p_operation_id uuid, p_product_id uuid, p_batch_id uuid, p_transaction_type text, p_quantity numeric, p_transaction_date date DEFAULT CURRENT_DATE, p_reference_number text DEFAULT NULL::text, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_stock_before numeric DEFAULT NULL::numeric, p_stock_after numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_existing public.inventory_transactions%ROWTYPE;
  v_batch public.batches%ROWTYPE;
  v_transaction_id uuid;
  v_new_stock numeric;
  v_previous_context text;
  v_creator uuid;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse']) THEN
      RAISE EXCEPTION 'Permission denied for inventory movement';
    END IF;
  END IF;

  v_creator := COALESCE(auth.uid(), p_created_by);

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'Canonical inventory posting requires operation_id';
  END IF;
  IF p_batch_id IS NULL OR p_product_id IS NULL THEN
    RAISE EXCEPTION 'Canonical inventory posting requires product_id and batch_id';
  END IF;
  IF COALESCE(p_quantity, 0) = 0 THEN
    RAISE EXCEPTION 'Canonical inventory posting quantity cannot be zero';
  END IF;
  IF p_transaction_type NOT IN (
    'purchase', 'delivery_challan', 'return', 'adjustment', 'rejection'
  ) THEN
    RAISE EXCEPTION 'Unsupported canonical inventory transaction type: %',
      p_transaction_type;
  END IF;

  SELECT *
  INTO v_existing
  FROM public.inventory_transactions
  WHERE operation_id = p_operation_id;

  IF FOUND THEN
    IF v_existing.batch_id IS DISTINCT FROM p_batch_id
       OR v_existing.product_id IS DISTINCT FROM p_product_id
       OR v_existing.transaction_type IS DISTINCT FROM p_transaction_type
       OR v_existing.quantity IS DISTINCT FROM p_quantity
       OR v_existing.reference_type IS DISTINCT FROM p_reference_type
       OR v_existing.reference_id IS DISTINCT FROM p_reference_id THEN
      RAISE EXCEPTION 'operation_id % was already used with different inventory values',
        p_operation_id;
    END IF;
    RETURN v_existing.id;
  END IF;

  SELECT *
  INTO v_batch
  FROM public.batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch not found: %', p_batch_id;
  END IF;
  IF v_batch.product_id IS DISTINCT FROM p_product_id THEN
    RAISE EXCEPTION 'Product % does not match batch % product %',
      p_product_id, p_batch_id, v_batch.product_id;
  END IF;

  IF p_transaction_type IN ('purchase', 'return') AND p_quantity <= 0 THEN
    RAISE EXCEPTION '% movement must be positive', p_transaction_type;
  END IF;
  IF p_transaction_type IN ('delivery_challan', 'rejection') AND p_quantity >= 0 THEN
    RAISE EXCEPTION '% movement must be negative', p_transaction_type;
  END IF;
  IF p_transaction_type = 'delivery_challan'
     AND v_batch.expiry_date IS NOT NULL
     AND v_batch.expiry_date <= COALESCE(p_transaction_date, CURRENT_DATE) THEN
    RAISE EXCEPTION 'Expired batch % cannot be delivered (expiry %)',
      v_batch.batch_number, v_batch.expiry_date;
  END IF;
  IF p_transaction_type = 'purchase'
     AND EXISTS (
       SELECT 1
       FROM public.inventory_transactions it
       WHERE it.batch_id = p_batch_id
         AND it.transaction_type = 'purchase'
     ) THEN
    RAISE EXCEPTION 'Batch % already has a Batch Creation movement',
      v_batch.batch_number;
  END IF;

  v_new_stock := v_batch.current_stock + p_quantity;
  IF v_new_stock < 0 THEN
    RAISE EXCEPTION 'Insufficient stock in batch %: current %, movement %, result %',
      v_batch.batch_number, v_batch.current_stock, p_quantity, v_new_stock;
  END IF;

  IF p_stock_before IS NOT NULL
     AND p_stock_before IS DISTINCT FROM v_batch.current_stock THEN
    RAISE EXCEPTION 'Stale stock_before for batch %: expected %, received %',
      v_batch.batch_number, v_batch.current_stock, p_stock_before;
  END IF;
  IF p_stock_after IS NOT NULL
     AND p_stock_after IS DISTINCT FROM v_new_stock THEN
    RAISE EXCEPTION 'Invalid stock_after for batch %: expected %, received %',
      v_batch.batch_number, v_new_stock, p_stock_after;
  END IF;

  v_previous_context := current_setting('app.canonical_stock_engine', true);
  PERFORM set_config('app.canonical_stock_engine', 'on', true);

  UPDATE public.batches
  SET current_stock = v_new_stock,
      updated_at = now()
  WHERE id = p_batch_id;

  INSERT INTO public.inventory_transactions (
    operation_id,
    product_id,
    batch_id,
    transaction_type,
    quantity,
    transaction_date,
    reference_number,
    reference_type,
    reference_id,
    notes,
    created_by,
    stock_before,
    stock_after,
    metadata
  )
  VALUES (
    p_operation_id,
    p_product_id,
    p_batch_id,
    p_transaction_type,
    p_quantity,
    COALESCE(p_transaction_date, CURRENT_DATE),
    p_reference_number,
    p_reference_type,
    p_reference_id,
    p_notes,
    v_creator,
    v_batch.current_stock,
    v_new_stock,
    jsonb_build_object(
      'canonical_engine_version', '1.0',
      'canonical_posted_at', clock_timestamp()
    )
  )
  RETURNING id INTO v_transaction_id;

  PERFORM set_config(
    'app.canonical_stock_engine',
    COALESCE(v_previous_context, ''),
    true
  );

  RETURN v_transaction_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_payment_voucher(p_pv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pv                      RECORD;
  v_je                      UUID;
  v_entry                   TEXT;
  v_actual_poster           UUID;
  v_bank_coa                UUID;
  v_bank_active             BOOLEAN;
  v_bank_is_header          BOOLEAN;
  v_debit_coa               UUID;
  v_charge_coa              UUID;
  v_diff_coa                UUID;
  v_fx_loss_coa             UUID;
  v_fx_gain_coa             UUID;
  v_rate                    NUMERIC := 1;
  v_actual                  NUMERIC;
  v_gross                   NUMERIC;
  v_charge_amt              NUMERIC := 0;
  v_settle_diff             NUMERIC := 0;
  v_bank_currency           TEXT := 'IDR';
  v_invoice_currency        TEXT := 'IDR';
  v_party_type              TEXT;
  v_ap_relief_idr           NUMERIC := 0;
  v_bank_credit_idr         NUMERIC := 0;
  v_alloc_usd               NUMERIC := 0;
  v_alloc_carrying_idr      NUMERIC := 0;
  v_alloc_settle_idr        NUMERIC := 0;
  v_realized_fx             NUMERIC := 0;
  v_fx_loss_amt             NUMERIC := 0;
  v_fx_gain_amt             NUMERIC := 0;
  v_total_debit             NUMERIC;
  v_total_credit            NUMERIC;
  v_line                    INTEGER := 1;
  v_usd_bank_carrying_rate  NUMERIC := 1;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  ELSIF auth.role() = 'anon' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_actual_poster := COALESCE(auth.uid(), p_posted_by);

  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id = p_pv_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment voucher % not found', p_pv_id;
  END IF;

  IF v_pv.is_posted THEN
    RAISE EXCEPTION 'Payment voucher % is already posted', v_pv.voucher_number;
  END IF;

  v_party_type := lower(COALESCE(
    v_pv.party_type,
    CASE 
      WHEN v_pv.staff_id IS NOT NULL OR v_pv.payment_purpose LIKE 'salary_%' OR v_pv.payment_purpose LIKE '%employee%' THEN 'employee'
      WHEN v_pv.customer_id IS NOT NULL OR v_pv.payment_purpose LIKE 'customer_%' THEN 'customer'
      ELSE 'supplier'
    END
  ));
  IF v_pv.payment_purpose = 'salary_advance' THEN
    v_party_type := 'employee';
  END IF;

  v_gross := COALESCE(v_pv.amount, 0);
  v_charge_amt := COALESCE(v_pv.bank_charge, 0);
  v_settle_diff := COALESCE(v_pv.settlement_discount, 0);
  v_actual := COALESCE(v_pv.actual_bank_debit, v_pv.bank_amount, v_gross + v_charge_amt);
  v_rate := COALESCE(NULLIF(v_pv.exchange_rate, 0), 1);
  v_bank_currency := COALESCE(v_pv.currency_code, v_pv.transaction_currency, 'IDR');

  -- Resolve Bank / Credit Account
  IF v_pv.payment_method IN ('bank_transfer', 'check', 'giro') THEN
    IF v_pv.bank_account_id IS NULL THEN
      RAISE EXCEPTION 'Bank account selection is mandatory for % payments (voucher %)', v_pv.payment_method, v_pv.voucher_number;
    END IF;

    SELECT ba.coa_id, ba.is_active, coa.is_header, upper(ba.currency)
    INTO v_bank_coa, v_bank_active, v_bank_is_header, v_bank_currency
    FROM public.bank_accounts ba
    LEFT JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id
    WHERE ba.id = v_pv.bank_account_id;

    IF v_bank_coa IS NULL THEN
      RAISE EXCEPTION 'Bank account % has no linked Chart of Accounts', v_pv.bank_account_id;
    END IF;
    IF NOT COALESCE(v_bank_active, false) THEN
      RAISE EXCEPTION 'Linked bank GL account % is inactive', v_bank_coa;
    END IF;
    IF COALESCE(v_bank_is_header, false) THEN
      RAISE EXCEPTION 'Linked bank GL account % is a header account — leaf required', v_bank_coa;
    END IF;

    -- Dynamic derivation of USD bank carrying rate (as of voucher date)
    IF v_bank_currency = 'USD' THEN
      SELECT 
        CASE 
          WHEN NULLIF(SUM(jel.transaction_debit - jel.transaction_credit), 0) IS NOT NULL AND SUM(jel.transaction_debit - jel.transaction_credit) > 0 THEN 
            round(SUM(jel.debit - jel.credit) / SUM(jel.transaction_debit - jel.transaction_credit), 4)
          ELSE 
            COALESCE(
              (SELECT frl.revalued_rate
               FROM public.fx_revaluation_lines frl
               JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
               WHERE frl.bank_account_id = v_pv.bank_account_id
                 AND fr.status = 'posted'
                 AND fr.revaluation_date <= v_pv.voucher_date
               ORDER BY fr.revaluation_date DESC, fr.created_at DESC
               LIMIT 1),
              v_rate
            )
        END
      INTO v_usd_bank_carrying_rate
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
      WHERE jel.account_id = v_bank_coa 
        AND je.is_posted = true 
        AND NOT COALESCE(je.is_reversed, false)
        AND je.entry_date <= v_pv.voucher_date;

      v_usd_bank_carrying_rate := COALESCE(v_usd_bank_carrying_rate, v_rate);
    END IF;

  ELSIF v_pv.payment_method = 'advance_adjustment' THEN
    SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header
    FROM public.chart_of_accounts
    WHERE code = '1160' AND is_active = true AND is_header = false LIMIT 1;

    IF v_bank_coa IS NULL THEN
      RAISE EXCEPTION 'Staff Advances account (1160) missing or inactive';
    END IF;

  ELSIF v_pv.payment_method = 'cash' THEN
    SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header
    FROM public.chart_of_accounts
    WHERE code = '1101' AND is_active = true AND is_header = false LIMIT 1;

    IF v_bank_coa IS NULL THEN
      SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header
      FROM public.chart_of_accounts
      WHERE code = '1102' AND is_active = true AND is_header = false LIMIT 1;
    END IF;

    IF v_bank_coa IS NULL THEN
      RAISE EXCEPTION 'No active postable Cash/Petty Cash GL account found (GL 1101/1102)';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported payment method: % for payment voucher %', v_pv.payment_method, v_pv.voucher_number;
  END IF;

  -- Resolve Standard Chart of Accounts
  SELECT id INTO v_fx_loss_coa FROM public.chart_of_accounts WHERE code = '7300' AND is_active = true LIMIT 1;
  SELECT id INTO v_fx_gain_coa FROM public.chart_of_accounts WHERE code = '4930' AND is_active = true LIMIT 1;

  -- Resolve Debit Control Account
  IF v_party_type = 'supplier' THEN
    IF v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance' THEN
      IF v_pv.coa_account_id IS NOT NULL THEN
        v_debit_coa := v_pv.coa_account_id;
      ELSE
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1170' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    ELSE
      IF v_pv.coa_account_id IS NOT NULL THEN
        v_debit_coa := v_pv.coa_account_id;
      ELSE
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END IF;

    -- Compute Multi-Document Carrying Value vs Settlement Value with Carry-Forward Rate
    SELECT 
      COALESCE(SUM(va.allocated_amount), 0),
      COALESCE(SUM(va.allocated_amount * COALESCE(
        (SELECT frl.revalued_rate
         FROM public.fx_revaluation_lines frl
         JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
         WHERE frl.purchase_invoice_id = va.purchase_invoice_id
           AND fr.status = 'posted'
           AND fr.revaluation_date <= v_pv.voucher_date
         ORDER BY fr.revaluation_date DESC, fr.created_at DESC
         LIMIT 1),
        pi.exchange_rate,
        v_rate
      )), 0)
    INTO v_alloc_usd, v_alloc_carrying_idr
    FROM public.voucher_allocations va
    JOIN public.purchase_invoices pi ON pi.id = va.purchase_invoice_id
    WHERE va.payment_voucher_id = p_pv_id;

    IF v_alloc_usd > 0 THEN
      v_ap_relief_idr := v_alloc_carrying_idr + ((v_gross - v_alloc_usd) * v_rate);

      IF v_bank_currency = 'USD' THEN
        v_alloc_settle_idr := (v_gross * v_usd_bank_carrying_rate);
        v_bank_credit_idr := (v_actual * v_usd_bank_carrying_rate);
      ELSE
        v_alloc_settle_idr := (v_gross * v_rate);
        v_bank_credit_idr := v_actual;
      END IF;

      v_realized_fx := v_alloc_settle_idr - v_ap_relief_idr;

      IF v_realized_fx > 0 THEN
        v_fx_loss_amt := v_realized_fx;
      ELSIF v_realized_fx < 0 THEN
        v_fx_gain_amt := abs(v_realized_fx);
      END IF;
    ELSE
      v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;
      v_bank_credit_idr := v_actual * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END);
      v_fx_loss_amt := 0;
      v_fx_gain_amt := 0;
    END IF;

  ELSIF v_party_type = 'customer' THEN
    IF v_pv.coa_account_id IS NOT NULL THEN
      v_debit_coa := v_pv.coa_account_id;
    ELSE
      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2111' AND is_active = true AND is_header = false LIMIT 1;
      IF v_debit_coa IS NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1120' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END IF;
    v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;
    v_bank_credit_idr := (v_actual + v_settle_diff) * v_rate;

  ELSIF v_party_type = 'employee' THEN
    IF v_pv.payment_purpose = 'salary_advance' THEN
      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1160' AND is_active = true AND is_header = false LIMIT 1;
    ELSIF v_pv.payment_purpose = 'salary_advance_settlement' 
       OR v_pv.payment_method = 'advance_adjustment'
       OR EXISTS (SELECT 1 FROM public.voucher_allocations va WHERE va.payment_voucher_id = p_pv_id AND va.finance_expense_id IS NOT NULL) THEN
      IF v_pv.coa_account_id IS NOT NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE id = v_pv.coa_account_id AND is_active = true AND is_header = false;
      END IF;
      IF v_debit_coa IS NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
      IF v_debit_coa IS NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2120' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    ELSE
      IF v_pv.coa_account_id IS NOT NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE id = v_pv.coa_account_id AND is_active = true AND is_header = false;
      END IF;
      IF v_debit_coa IS NULL AND v_pv.staff_id IS NOT NULL THEN
        SELECT default_gl_account_id INTO v_debit_coa FROM public.finance_staff_master WHERE id = v_pv.staff_id;
      END IF;
      IF v_debit_coa IS NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '6100' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
      IF v_debit_coa IS NULL THEN
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '5101' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END IF;
    v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;
    v_bank_credit_idr := (v_actual + v_settle_diff) * v_rate;

  ELSIF v_party_type = 'director' THEN
    DECLARE
      v_dir_loan_acc uuid;
    BEGIN
      SELECT loan_account_id INTO v_dir_loan_acc FROM public.directors WHERE id = v_pv.staff_id;
      IF v_dir_loan_acc IS NOT NULL THEN
        v_debit_coa := v_dir_loan_acc;
      ELSE
        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2105' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END;
    v_ap_relief_idr := v_gross * v_rate;
    v_bank_credit_idr := v_actual * v_rate;

  ELSE
    IF v_pv.coa_account_id IS NOT NULL THEN
      v_debit_coa := v_pv.coa_account_id;
    ELSE
      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '6900' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
    v_ap_relief_idr := v_gross * v_rate;
    v_bank_credit_idr := v_actual * v_rate;
  END IF;

  IF v_debit_coa IS NULL THEN
    RAISE EXCEPTION 'Could not resolve debit Chart of Accounts for % (voucher %)', v_party_type, v_pv.voucher_number;
  END IF;

  -- Resolve Bank Charge & Settlement Difference Accounts
  IF v_charge_amt > 0 THEN
    SELECT id INTO v_charge_coa FROM public.chart_of_accounts WHERE code = '7100' AND is_active = true LIMIT 1;
    IF v_charge_coa IS NULL THEN
      SELECT id INTO v_charge_coa FROM public.chart_of_accounts WHERE code = '8101' AND is_active = true LIMIT 1;
    END IF;
  END IF;

  IF v_settle_diff > 0 THEN
    SELECT id INTO v_diff_coa FROM public.chart_of_accounts WHERE code = '4940' AND is_active = true LIMIT 1;
    IF v_diff_coa IS NULL THEN
      SELECT id INTO v_diff_coa FROM public.chart_of_accounts WHERE code = '7200' AND is_active = true LIMIT 1;
    END IF;
  END IF;

  -- Calculate Total Debit and Credit
  v_total_debit := round(v_ap_relief_idr + v_fx_loss_amt + (v_charge_amt * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END)), 2);
  v_total_credit := round(v_bank_credit_idr + v_fx_gain_amt + (v_settle_diff * v_rate), 2);

  -- Balance Tolerance Guard
  IF abs(v_total_debit - v_total_credit) > 0.05 THEN
    RAISE EXCEPTION 'Payment voucher journal does not balance: Debit %, Credit %', v_total_debit, v_total_credit;
  END IF;

  v_entry := public.next_journal_entry_number();

  -- Create Journal Entry Header
  INSERT INTO public.journal_entries(
    entry_number, entry_date, description, reference_number, reference_id,
    source_module, total_debit, total_credit, is_posted, posted_by,
    created_by, is_reversed
  ) VALUES (
    v_entry, v_pv.voucher_date,
    CASE 
      WHEN v_party_type = 'supplier' AND (v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance') THEN 'Supplier Advance - '
      WHEN v_party_type = 'supplier' THEN 'Supplier Payment - '
      WHEN v_party_type = 'customer' THEN 'Customer Refund - '
      WHEN v_party_type = 'employee' AND v_pv.payment_purpose = 'salary_advance' THEN 'Staff Salary Advance - '
      WHEN v_party_type = 'employee' THEN 'Staff Payment - '
      WHEN v_party_type = 'director' THEN 'Director Loan Repayment - '
      ELSE 'Payment - '
    END || v_pv.voucher_number || COALESCE(' - ' || v_pv.description, ''),
    v_pv.voucher_number, p_pv_id, 'payment',
    v_total_debit, v_total_credit, true, v_actual_poster,
    v_actual_poster, false
  ) RETURNING id INTO v_je;

  -- Line 1: Debit Accounts Payable / Control Account
  INSERT INTO public.journal_entry_lines(
    journal_entry_id, line_number, account_id, description, debit, credit,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate,
    supplier_id, customer_id, staff_id, payee_id
  ) VALUES (
    v_je, v_line, v_debit_coa,
    CASE 
      WHEN v_party_type = 'supplier' AND (v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance') THEN 'Supplier Advance - '
      WHEN v_party_type = 'supplier' THEN 'Supplier Payment - '
      WHEN v_party_type = 'customer' THEN 'Customer Refund - '
      WHEN v_party_type = 'employee' AND v_pv.payment_purpose = 'salary_advance' THEN 'Staff Salary Advance - '
      WHEN v_party_type = 'employee' THEN 'Staff Payment - '
      WHEN v_party_type = 'director' THEN 'Director Loan Repayment - '
      ELSE 'Payment - '
    END || v_pv.voucher_number,
    v_ap_relief_idr, 0,
    v_invoice_currency, (v_gross + v_settle_diff), 0, v_rate,
    CASE WHEN v_party_type = 'supplier' THEN v_pv.supplier_id ELSE NULL END,
    CASE WHEN v_party_type = 'customer' THEN v_pv.customer_id ELSE NULL END,
    CASE WHEN v_party_type = 'employee' THEN v_pv.staff_id ELSE NULL END,
    NULL
  );
  v_line := v_line + 1;

  -- Line 2: Realized FX Loss (GL 7300) if any
  IF v_fx_loss_amt > 0 AND v_fx_loss_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(
      journal_entry_id, line_number, account_id, description, debit, credit,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate,
      supplier_id, customer_id, staff_id, payee_id
    ) VALUES (
      v_je, v_line, v_fx_loss_coa, 'Realized Foreign Exchange Loss - ' || v_pv.voucher_number,
      v_fx_loss_amt, 0, 'IDR', v_fx_loss_amt, 0, 1,
      NULL, NULL, NULL, NULL
    );
    v_line := v_line + 1;
  END IF;

  -- Line 3: Bank Charge (GL 7100 / 8101)
  IF v_charge_amt > 0 AND v_charge_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(
      journal_entry_id, line_number, account_id, description, debit, credit,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate,
      supplier_id, customer_id, staff_id, payee_id
    ) VALUES (
      v_je, v_line, v_charge_coa, 'Bank Charge - ' || v_pv.voucher_number,
      v_charge_amt * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END), 0,
      v_bank_currency, v_charge_amt, 0, 1,
      NULL, NULL, NULL, NULL
    );
    v_line := v_line + 1;
  END IF;

  -- Line 4: Credit Realized FX Gain (GL 4930) if any
  IF v_fx_gain_amt > 0 AND v_fx_gain_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(
      journal_entry_id, line_number, account_id, description, debit, credit,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate,
      supplier_id, customer_id, staff_id, payee_id
    ) VALUES (
      v_je, v_line, v_fx_gain_coa, 'Realized Foreign Exchange Gain - ' || v_pv.voucher_number,
      0, v_fx_gain_amt, 'IDR', 0, v_fx_gain_amt, 1,
      NULL, NULL, NULL, NULL
    );
    v_line := v_line + 1;
  END IF;

  -- Line 5: Credit Settlement Discount / Difference if any
  IF v_settle_diff > 0 AND v_diff_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines(
      journal_entry_id, line_number, account_id, description, debit, credit,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate,
      supplier_id, customer_id, staff_id, payee_id
    ) VALUES (
      v_je, v_line, v_diff_coa, 'Settlement Discount / Difference - ' || v_pv.voucher_number,
      0, v_settle_diff * v_rate, v_bank_currency, 0, v_settle_diff, 1,
      NULL, NULL, NULL, NULL
    );
    v_line := v_line + 1;
  END IF;

  -- Line 6: Credit Bank / Cash / Staff Advances
  INSERT INTO public.journal_entry_lines(
    journal_entry_id, line_number, account_id, description, debit, credit,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate,
    supplier_id, customer_id, staff_id, payee_id
  ) VALUES (
    v_je, v_line, v_bank_coa, 
    CASE 
      WHEN v_pv.payment_method = 'advance_adjustment' THEN 'Advance Adjustment - '
      WHEN v_pv.payment_method = 'cash' THEN 'Cash Payment - '
      ELSE 'Bank Payment - '
    END || v_pv.voucher_number,
    0, v_bank_credit_idr,
    v_bank_currency, 0, v_actual, 1,
    NULL, NULL, NULL, NULL
  );

  UPDATE public.payment_vouchers SET is_posted = true, journal_entry_id = v_je WHERE id = p_pv_id;

  -- Recalculate Purchase Invoice balances and states
  IF v_party_type = 'supplier' THEN
    PERFORM public.recalculate_purchase_invoice_payment_state(va.purchase_invoice_id)
    FROM public.voucher_allocations va
    WHERE va.payment_voucher_id = p_pv_id AND va.purchase_invoice_id IS NOT NULL;
  END IF;

  -- Recalculate Expense balances and states if allocated
  PERFORM public.recalculate_expense_payment_state(va.finance_expense_id)
  FROM public.voucher_allocations va
  WHERE va.payment_voucher_id = p_pv_id AND va.finance_expense_id IS NOT NULL;

  -- Synchronize bank account current_balance with authoritative GL
  IF v_pv.bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_pv.bank_account_id);
  END IF;

  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)
  VALUES('payment_vouchers', p_pv_id, 'update', jsonb_build_object('is_posted', false), jsonb_build_object('is_posted', true, 'journal_entry_id', v_je), v_actual_poster);
END;
$function$

CREATE OR REPLACE FUNCTION public.post_receipt_voucher(p_rv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rv                 RECORD;
  v_je_id              UUID;
  v_je_number          TEXT;
  v_bank_account_id    UUID;
  v_credit_account_id  UUID;
  v_diff_account_id    UUID;
  v_fx_gain_coa        UUID;
  v_fx_loss_coa        UUID;
  v_actual_poster      UUID;
  v_actual_received    NUMERIC;
  v_settle_diff        NUMERIC;
  v_carrying_amount    NUMERIC;
  v_rate               NUMERIC;
  v_currency           TEXT;
  v_party_type         TEXT;
  v_bank_coa_id        UUID;
  v_bank_active        BOOLEAN;
  v_bank_curr          TEXT;
  v_coa_code           TEXT;
  v_coa_name           TEXT;
  v_coa_is_header      BOOLEAN;
  v_alloc_foreign      NUMERIC := 0;
  v_alloc_carrying_idr NUMERIC := 0;
  v_ar_relief_idr      NUMERIC := 0;
  v_bank_received_idr  NUMERIC := 0;
  v_realized_fx        NUMERIC := 0;
  v_fx_gain_amt        NUMERIC := 0;
  v_fx_loss_amt        NUMERIC := 0;
  v_total_debit        NUMERIC;
  v_total_credit       NUMERIC;
  v_line               INTEGER := 1;
  v_usd_bank_rate      NUMERIC := 1;
  v_avail_advances     NUMERIC;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  ELSIF auth.role() = 'anon' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_actual_poster := COALESCE(auth.uid(), p_posted_by);

  SELECT * INTO v_rv FROM public.receipt_vouchers WHERE id = p_rv_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id;
  END IF;

  IF v_rv.is_posted THEN
    RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number;
  END IF;

  v_party_type := lower(COALESCE(v_rv.party_type, 'customer'));
  v_actual_received := COALESCE(v_rv.amount, 0);
  v_settle_diff := COALESCE(v_rv.settlement_discount, 0);
  v_carrying_amount := v_actual_received + v_settle_diff;
  v_rate := COALESCE(NULLIF(v_rv.exchange_rate, 0), 1);
  v_currency := upper(COALESCE(v_rv.currency_code, v_rv.transaction_currency, 'IDR'));

  -- Strict Validation: Bank Account and Leaf COA
  IF v_rv.payment_method IN ('bank_transfer', 'check', 'giro') THEN
    IF v_rv.bank_account_id IS NULL THEN
      RAISE EXCEPTION 'Bank account selection is mandatory for % receipts (voucher %)', v_rv.payment_method, v_rv.voucher_number;
    END IF;

    SELECT ba.coa_id, ba.is_active, upper(ba.currency), coa.code, coa.name, coa.is_header
    INTO v_bank_coa_id, v_bank_active, v_bank_curr, v_coa_code, v_coa_name, v_coa_is_header
    FROM public.bank_accounts ba
    LEFT JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id
    WHERE ba.id = v_rv.bank_account_id;

    IF v_bank_coa_id IS NULL THEN
      RAISE EXCEPTION 'Bank account % does not have a linked General Ledger account', v_rv.bank_account_id;
    END IF;

    IF NOT COALESCE(v_bank_active, false) THEN
      RAISE EXCEPTION 'Selected bank account % is inactive', v_rv.bank_account_id;
    END IF;

    IF COALESCE(v_coa_is_header, false) THEN
      RAISE EXCEPTION 'Journal lines cannot be posted to header account % — use a leaf account instead (P0001)', v_coa_code;
    END IF;

    -- Dynamic USD bank carrying rate if deposit into USD bank
    IF v_bank_curr = 'USD' THEN
      SELECT 
        CASE 
          WHEN NULLIF(SUM(jel.transaction_debit - jel.transaction_credit), 0) IS NOT NULL AND SUM(jel.transaction_debit - jel.transaction_credit) > 0 THEN 
            round(SUM(jel.debit - jel.credit) / SUM(jel.transaction_debit - jel.transaction_credit), 4)
          ELSE 
            COALESCE(
              (SELECT frl.revalued_rate
               FROM public.fx_revaluation_lines frl
               JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
               WHERE frl.bank_account_id = v_rv.bank_account_id
                 AND fr.status = 'posted'
                 AND fr.revaluation_date <= v_rv.voucher_date
               ORDER BY fr.revaluation_date DESC, fr.created_at DESC
               LIMIT 1),
              v_rate
            )
        END
      INTO v_usd_bank_rate
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
      WHERE jel.account_id = v_bank_coa_id 
        AND je.is_posted = true 
        AND NOT COALESCE(je.is_reversed, false)
        AND je.entry_date <= v_rv.voucher_date;

      v_usd_bank_rate := COALESCE(v_usd_bank_rate, v_rate);
    END IF;

    v_bank_account_id := v_bank_coa_id;

  ELSIF v_rv.payment_method = 'cash' THEN
    SELECT id INTO v_bank_account_id FROM public.chart_of_accounts WHERE code = '1101' AND is_active = true AND is_header = false LIMIT 1;
    IF v_bank_account_id IS NULL THEN
      SELECT id INTO v_bank_account_id FROM public.chart_of_accounts WHERE code = '1102' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
    IF v_bank_account_id IS NULL THEN
      RAISE EXCEPTION 'No active postable Cash/Petty Cash GL account found (GL 1101/1102)';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported payment method: % for receipt voucher %', v_rv.payment_method, v_rv.voucher_number;
  END IF;

  -- Resolve FX Gain / Loss GL Accounts
  SELECT id INTO v_fx_gain_coa FROM public.chart_of_accounts WHERE code = '4930' AND is_active = true LIMIT 1;
  SELECT id INTO v_fx_loss_coa FROM public.chart_of_accounts WHERE code = '7300' AND is_active = true LIMIT 1;

  -- Concurrency & Balance Validation for Supplier Refund
  IF v_party_type = 'supplier' AND v_rv.supplier_id IS NOT NULL THEN
    PERFORM id FROM public.suppliers WHERE id = v_rv.supplier_id FOR UPDATE;

    SELECT COALESCE(SUM((pv.amount * COALESCE(pv.exchange_rate, 1)) - COALESCE(va.allocated, 0)), 0)
    INTO v_avail_advances
    FROM public.payment_vouchers pv
    LEFT JOIN (
      SELECT payment_voucher_id, SUM(allocated_amount) as allocated
      FROM public.voucher_allocations
      GROUP BY payment_voucher_id
    ) va ON va.payment_voucher_id = pv.id
    WHERE pv.supplier_id = v_rv.supplier_id
      AND pv.is_posted = true
      AND (pv.payment_purpose = 'supplier_advance' OR pv.settlement_against = 'advance');

    IF (v_actual_received * v_rate) > (v_avail_advances + 0.01) THEN
      RAISE EXCEPTION 'Supplier refund amount (%) exceeds available advance balance (%)',
        (v_actual_received * v_rate), v_avail_advances;
    END IF;
  END IF;

  -- Resolve Credit Control Account
  IF v_party_type = 'customer' THEN
    IF v_rv.settlement_against = 'advance' THEN
      IF v_rv.coa_account_id IS NOT NULL THEN
        v_credit_account_id := v_rv.coa_account_id;
      ELSE
        SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '2140' AND is_active = true AND is_header = false LIMIT 1;
        IF v_credit_account_id IS NULL THEN
          SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '1120' AND is_active = true AND is_header = false LIMIT 1;
        END IF;
      END IF;
    ELSE
      IF v_rv.coa_account_id IS NOT NULL THEN
        v_credit_account_id := v_rv.coa_account_id;
      ELSE
        SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '1120' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END IF;

    -- Multi-Document Allocation Handling for FX Realization (only for USD receipts)
    SELECT 
      COALESCE(SUM(CASE WHEN upper(COALESCE(so.currency, v_currency)) = 'USD' THEN va.allocated_amount ELSE 0 END), 0),
      COALESCE(SUM(CASE 
        WHEN upper(COALESCE(so.currency, v_currency)) = 'USD' THEN
          va.allocated_amount * COALESCE(
            (SELECT frl.revalued_rate
             FROM public.fx_revaluation_lines frl
             JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
             WHERE frl.sales_invoice_id = va.sales_invoice_id
               AND fr.status = 'posted'
               AND fr.revaluation_date <= v_rv.voucher_date
             ORDER BY fr.revaluation_date DESC, fr.created_at DESC
             LIMIT 1),
            so.commercial_usd_to_idr_rate,
            v_rate
          )
        ELSE 0
      END), 0)
    INTO v_alloc_foreign, v_alloc_carrying_idr
    FROM public.voucher_allocations va
    LEFT JOIN public.sales_invoices si ON si.id = va.sales_invoice_id
    LEFT JOIN public.sales_orders so ON so.id = COALESCE(va.sales_order_id, si.sales_order_id)
    WHERE va.receipt_voucher_id = p_rv_id
      AND va.voucher_type = 'receipt';

    IF v_currency = 'USD' AND v_alloc_foreign > 0 THEN
      v_ar_relief_idr := v_alloc_carrying_idr + ((v_carrying_amount - v_alloc_foreign) * v_rate);
      v_bank_received_idr := v_actual_received * (CASE WHEN v_bank_curr = 'USD' THEN v_usd_bank_rate ELSE v_rate END);
      v_realized_fx := v_bank_received_idr - (v_ar_relief_idr - (v_settle_diff * v_rate));

      IF v_realized_fx > 0 THEN
        v_fx_gain_amt := v_realized_fx;
      ELSIF v_realized_fx < 0 THEN
        v_fx_loss_amt := abs(v_realized_fx);
      END IF;
    ELSIF v_currency = 'USD' THEN
      v_bank_received_idr := v_actual_received * (CASE WHEN v_bank_curr = 'USD' THEN v_usd_bank_rate ELSE v_rate END);
      v_ar_relief_idr := v_carrying_amount * v_rate;
      v_realized_fx := v_bank_received_idr - (v_ar_relief_idr - (v_settle_diff * v_rate));
      IF v_realized_fx > 0 THEN
        v_fx_gain_amt := v_realized_fx;
      ELSIF v_realized_fx < 0 THEN
        v_fx_loss_amt := abs(v_realized_fx);
      END IF;
    ELSE
      -- Standard IDR customer receipt
      v_ar_relief_idr := v_carrying_amount;
      v_bank_received_idr := v_actual_received;
      v_fx_gain_amt := 0;
      v_fx_loss_amt := 0;
    END IF;

  ELSIF v_party_type = 'supplier' THEN
    IF v_rv.coa_account_id IS NOT NULL THEN
      v_credit_account_id := v_rv.coa_account_id;
    ELSE
      SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '1170' AND is_active = true AND is_header = false LIMIT 1;
      IF v_credit_account_id IS NULL THEN
        SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;
      END IF;
    END IF;
    v_ar_relief_idr := v_carrying_amount;
    v_bank_received_idr := v_actual_received;

  ELSIF v_party_type = 'employee' THEN
    SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '1160' AND is_active = true AND is_header = false LIMIT 1;
    IF v_credit_account_id IS NULL THEN
      SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '1120' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
    v_ar_relief_idr := v_carrying_amount;
    v_bank_received_idr := v_actual_received;

  ELSIF v_party_type = 'director' THEN
    SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '2105' AND is_active = true AND is_header = false LIMIT 1;
    IF v_credit_account_id IS NULL THEN
      SELECT id INTO v_credit_account_id FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
    v_ar_relief_idr := v_carrying_amount;
    v_bank_received_idr := v_actual_received;

  ELSE
    RAISE EXCEPTION 'Unsupported party type: %', v_party_type;
  END IF;

  IF v_credit_account_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.chart_of_accounts WHERE id = v_credit_account_id AND is_active = true AND is_header = false
  ) THEN
    RAISE EXCEPTION 'Credit control account could not be resolved or is inactive/header for voucher %', v_rv.voucher_number;
  END IF;

  -- Resolve Settlement Difference Account (COA 6910 default)
  IF v_settle_diff > 0 THEN
    IF v_rv.adjustment_account_id IS NOT NULL THEN
      SELECT id INTO v_diff_account_id FROM public.chart_of_accounts WHERE id = v_rv.adjustment_account_id AND is_active = true AND is_header = false;
    END IF;
    IF v_diff_account_id IS NULL THEN
      SELECT id INTO v_diff_account_id FROM public.chart_of_accounts WHERE code = '6910' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
    IF v_diff_account_id IS NULL THEN
      SELECT id INTO v_diff_account_id FROM public.chart_of_accounts WHERE code = '6900' AND is_active = true AND is_header = false LIMIT 1;
    END IF;
  END IF;

  v_total_debit := v_bank_received_idr + (v_settle_diff * v_rate) + v_fx_loss_amt;
  v_total_credit := v_ar_relief_idr + v_fx_gain_amt;

  IF abs(v_total_debit - v_total_credit) > 0.05 THEN
    RAISE EXCEPTION 'Journal entry debit total (%) does not balance with credit total (%)', v_total_debit, v_total_credit;
  END IF;

  v_je_number := public.next_journal_entry_number();

  INSERT INTO public.journal_entries (
    entry_number,
    entry_date,
    source_module,
    reference_id,
    reference_number,
    description,
    total_debit,
    total_credit,
    is_posted,
    posted_by,
    created_by,
    transaction_currency,
    functional_currency,
    exchange_rate
  ) VALUES (
    v_je_number,
    v_rv.voucher_date,
    'receipt',
    v_rv.id,
    v_rv.voucher_number,
    'Receipt Voucher (' || v_party_type || '): ' || v_rv.voucher_number,
    v_total_debit,
    v_total_credit,
    TRUE,
    v_actual_poster,
    v_actual_poster,
    v_currency,
    'IDR',
    v_rate
  ) RETURNING id INTO v_je_id;

  -- Line 1 (Dr): Bank or Cash
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, description,
    debit, credit, customer_id, supplier_id, staff_id, payee_id,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate
  ) VALUES (
    v_je_id, v_line, v_bank_account_id,
    'Receipt: ' || v_rv.voucher_number,
    v_bank_received_idr, 0,
    NULL, NULL, NULL, NULL,
    v_currency, v_actual_received, 0, v_rate
  );
  v_line := v_line + 1;

  -- Line 2 (Dr): Settlement Discount / Rounding Difference (if > 0)
  IF v_settle_diff > 0 AND v_diff_account_id IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, description,
      debit, credit, customer_id, supplier_id, staff_id, payee_id,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate
    ) VALUES (
      v_je_id, v_line, v_diff_account_id,
      'Settlement Difference: ' || v_rv.voucher_number,
      v_settle_diff * v_rate, 0,
      NULL, NULL, NULL, NULL,
      v_currency, v_settle_diff, 0, v_rate
    );
    v_line := v_line + 1;
  END IF;

  -- Line 3 (Dr): Realized FX Loss (GL 7300) if any
  IF v_fx_loss_amt > 0 AND v_fx_loss_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, description,
      debit, credit, customer_id, supplier_id, staff_id, payee_id,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate
    ) VALUES (
      v_je_id, v_line, v_fx_loss_coa,
      'Realized FX Loss - Customer Receipt ' || v_rv.voucher_number,
      v_fx_loss_amt, 0,
      NULL, NULL, NULL, NULL,
      'IDR', v_fx_loss_amt, 0, 1
    );
    v_line := v_line + 1;
  END IF;

  -- Line 4 (Cr): Control Account (1120 for customer receipt, 1170 for supplier refund, 1160 for employee, etc.)
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, description,
    debit, credit, customer_id, supplier_id, staff_id, payee_id,
    transaction_currency, transaction_debit, transaction_credit, exchange_rate
  ) VALUES (
    v_je_id, v_line, v_credit_account_id,
    CASE 
      WHEN v_party_type = 'supplier' THEN 'Supplier Advance Refund - '
      WHEN v_party_type = 'customer' THEN 'Customer Receipt - '
      WHEN v_party_type = 'employee' THEN 'Staff Return - '
      ELSE 'Receipt - '
    END || v_rv.voucher_number,
    0, v_ar_relief_idr,
    CASE WHEN v_party_type = 'customer' THEN v_rv.customer_id ELSE NULL END,
    CASE WHEN v_party_type = 'supplier' THEN v_rv.supplier_id ELSE NULL END,
    CASE WHEN v_party_type = 'employee' THEN v_rv.staff_id ELSE NULL END,
    NULL,
    v_currency, 0, v_carrying_amount, v_rate
  );
  v_line := v_line + 1;

  -- Line 5 (Cr): Realized FX Gain (GL 4930) if any
  IF v_fx_gain_amt > 0 AND v_fx_gain_coa IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (
      journal_entry_id, line_number, account_id, description,
      debit, credit, customer_id, supplier_id, staff_id, payee_id,
      transaction_currency, transaction_debit, transaction_credit, exchange_rate
    ) VALUES (
      v_je_id, v_line, v_fx_gain_coa,
      'Realized FX Gain - Customer Receipt ' || v_rv.voucher_number,
      0, v_fx_gain_amt,
      NULL, NULL, NULL, NULL,
      'IDR', 0, v_fx_gain_amt, 1
    );
    v_line := v_line + 1;
  END IF;

  UPDATE public.receipt_vouchers
  SET is_posted = TRUE, journal_entry_id = v_je_id
  WHERE id = p_rv_id;

  -- Recalculate Sales Invoice states if customer receipt
  IF v_party_type = 'customer' THEN
    PERFORM public.recalculate_sales_invoice_payment_state(va.sales_invoice_id)
    FROM public.voucher_allocations va
    WHERE va.receipt_voucher_id = p_rv_id AND va.sales_invoice_id IS NOT NULL;
  END IF;

  -- Sync Bank GL
  IF v_rv.bank_account_id IS NOT NULL THEN
    PERFORM public.sync_bank_account_balance(v_rv.bank_account_id);
  END IF;

  -- Audit log
  INSERT INTO public.audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)
  VALUES ('receipt_vouchers', p_rv_id, 'update', jsonb_build_object('is_posted', false), jsonb_build_object('is_posted', true, 'journal_entry_id', v_je_id), v_actual_poster);
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_cash_on_hand_fund_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    BEGIN
      IF NEW.from_account_type = 'cash_on_hand' OR NEW.to_account_type = 'cash_on_hand' THEN
        RAISE EXCEPTION 'Fund transfer with cash_on_hand is permanently disabled.';
      END IF;
      RETURN NEW;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.prevent_expense_payment_overallocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_exp RECORD;
  v_payable numeric := 0;
  v_settled_va numeric := 0;
  v_settled_bsa numeric := 0;
  v_settled_bsl numeric := 0;
  v_total_settled numeric := 0;
  v_remaining numeric := 0;
  v_kind text;
  v_purpose text;
BEGIN
  IF NEW.finance_expense_id IS NULL OR NEW.voucher_type <> 'payment' THEN
    RETURN NEW;
  END IF;

  -- Salary advance settlements are non-cash adjustments tracked via salary_advance_applications
  -- and do not consume standard cash payable limits.
  SELECT payment_purpose INTO v_purpose
    FROM public.payment_vouchers
   WHERE id = NEW.payment_voucher_id;

  IF v_purpose IN ('salary_advance', 'salary_advance_settlement') THEN
    RETURN NEW;
  END IF;

  v_kind := COALESCE(NEW.payment_kind, 'supplier');

  -- Lock the finance_expense row inside the same transaction
  SELECT * INTO v_exp 
    FROM public.finance_expenses 
   WHERE id = NEW.finance_expense_id 
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referenced finance_expense % does not exist', NEW.finance_expense_id;
  END IF;

  -- Determine total payable for this payment kind
  IF v_kind = 'pph23' THEN
    v_payable := COALESCE(v_exp.pph_amount, 0);
  ELSE
    v_payable := COALESCE(public.calculate_finance_expense_payable(v_exp.id), 0);
  END IF;

  -- Existing posted settlements from voucher_allocations (excluding current row on update)
  SELECT COALESCE(SUM(va.allocated_amount), 0) INTO v_settled_va
    FROM public.voucher_allocations va
    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
   WHERE va.finance_expense_id = v_exp.id
     AND COALESCE(va.payment_kind, 'supplier') = v_kind
     AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement')
     AND (TG_OP <> 'UPDATE' OR va.id <> NEW.id);

  -- Existing posted settlements from bank_statement_allocations
  SELECT COALESCE(SUM(bsa.allocation_amount), 0) INTO v_settled_bsa
    FROM public.bank_statement_allocations bsa
   WHERE bsa.document_type = 'expense'
     AND bsa.document_id = v_exp.id
     AND COALESCE(bsa.payment_kind, 'supplier') = v_kind;

  -- Existing legacy settlements from bank_statement_lines without allocations
  SELECT COALESCE(SUM(COALESCE(NULLIF(bsl.debit_amount, 0), bsl.credit_amount, 0)), 0) INTO v_settled_bsl
    FROM public.bank_statement_lines bsl
   WHERE bsl.matched_expense_id = v_exp.id
     AND COALESCE(bsl.payment_kind, 'supplier') = v_kind
     AND NOT EXISTS (
       SELECT 1 FROM public.bank_statement_allocations a 
        WHERE a.bank_statement_line_id = bsl.id
     );

  v_total_settled := v_settled_va + v_settled_bsa + v_settled_bsl;
  v_remaining := round(v_payable - v_total_settled, 2);

  IF NEW.allocated_amount > (v_remaining + 0.01) THEN
    RAISE EXCEPTION 'Expense payment allocation (%) exceeds remaining payable (%) for expense % (Total Payable: %, Already Settled: %)',
      NEW.allocated_amount, v_remaining, COALESCE(v_exp.voucher_number, v_exp.id::text), v_payable, v_total_settled;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_gl1101_posting()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    DECLARE
      v_code text;
      v_is_reversed boolean;
    BEGIN
      SELECT c.code INTO v_code FROM public.chart_of_accounts c WHERE c.id = NEW.account_id;
      IF v_code = '1101' THEN
        SELECT COALESCE(je.is_reversed, false) INTO v_is_reversed FROM public.journal_entries je WHERE je.id = NEW.journal_entry_id;
        IF NOT v_is_reversed THEN
          RAISE EXCEPTION 'Account 1101 (Cash on Hand) is permanently retired and cannot accept new journal postings.';
        END IF;
      END IF;
      RETURN NEW;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.propagate_bank_line_amount_edit(p_line_id uuid, p_new_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_line record;
v_old_amount numeric;
v_doc_type text;
v_doc_id uuid;
v_je_id uuid;
BEGIN
SELECT * INTO v_line FROM bank_statement_lines WHERE id = p_line_id;
IF NOT FOUND THEN
RETURN jsonb_build_object('ok', false, 'error', 'Bank statement line not found');
END IF;

v_old_amount := COALESCE(v_line.debit_amount, 0) + COALESCE(v_line.credit_amount, 0);

-- Determine linked document type and ID
IF v_line.matched_expense_id IS NOT NULL THEN
v_doc_type := 'expense';
v_doc_id := v_line.matched_expense_id;
-- Update expense amount; trigger_auto_post_expense_accounting_update will:
-- 1. Check if amount actually changed (idempotency guard)
-- 2. Delete old journal entry
-- 3. Create new journal entry with correct amount
-- No double post possible — trigger deletes before inserting.
UPDATE finance_expenses SET amount = p_new_amount WHERE id = v_doc_id;

ELSIF v_line.matched_receipt_id IS NOT NULL THEN
v_doc_type := 'receipt_voucher';
v_doc_id := v_line.matched_receipt_id;
UPDATE receipt_vouchers SET amount = p_new_amount WHERE id = v_doc_id;
-- Find linked JE and update lines (no trigger re-posts on amount change)
SELECT journal_entry_id INTO v_je_id FROM receipt_vouchers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_payment_id IS NOT NULL THEN
v_doc_type := 'payment_voucher';
v_doc_id := v_line.matched_payment_id;
UPDATE payment_vouchers SET amount = p_new_amount WHERE id = v_doc_id;
SELECT journal_entry_id INTO v_je_id FROM payment_vouchers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_fund_transfer_id IS NOT NULL THEN
v_doc_type := 'fund_transfer';
v_doc_id := v_line.matched_fund_transfer_id;
UPDATE fund_transfers SET amount = p_new_amount WHERE id = v_doc_id;
-- Fund transfer only has INSERT trigger, so manually update JE lines
SELECT journal_entry_id INTO v_je_id FROM fund_transfers WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_petty_cash_id IS NOT NULL THEN
v_doc_type := 'petty_cash';
v_doc_id := v_line.matched_petty_cash_id;
-- Update petty cash amount
UPDATE petty_cash_transactions SET amount = p_new_amount WHERE id = v_doc_id;
-- trigger_post_petty_cash_on_approval only fires on approval_status change,
-- NOT on amount-only update. So find the linked JE manually and update lines.
SELECT id INTO v_je_id FROM journal_entries
WHERE reference_id = v_doc_id AND source_module = 'petty_cash'
LIMIT 1;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_tax_payment_id IS NOT NULL THEN
v_doc_type := 'tax_payment';
v_doc_id := v_line.matched_tax_payment_id;
UPDATE tax_payments SET amount = p_new_amount WHERE id = v_doc_id;
SELECT journal_entry_id INTO v_je_id FROM tax_payments WHERE id = v_doc_id;
IF v_je_id IS NOT NULL THEN
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;
END IF;

ELSIF v_line.matched_entry_id IS NOT NULL THEN
v_doc_type := 'journal_entry';
v_doc_id := v_line.matched_entry_id;
v_je_id := v_doc_id;
UPDATE journal_entry_lines
SET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,
credit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END
WHERE journal_entry_id = v_je_id;
UPDATE journal_entries
SET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),
total_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
WHERE id = v_je_id;

ELSE
v_doc_type := 'none';
v_doc_id := NULL;
END IF;

RETURN jsonb_build_object(
'ok', true,
'doc_type', v_doc_type,
'doc_id', v_doc_id,
'old_amount', v_old_amount,
'new_amount', p_new_amount
);
END;
$function$

CREATE OR REPLACE FUNCTION public.propagate_batch_cost_change(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch public.batches%ROWTYPE;
  v_layer_count integer;
  v_inv record;
  v_item record;
  v_layer record;
  v_target_item_cogs numeric;
  v_target_total numeric;
  v_posted_gl numeric;
  v_inv_delta numeric;
  v_je_id uuid;
  v_je_number text;
  v_entry_date date;
  v_period_id uuid;
  v_period_status text;
  v_source_module text;
  v_description text;
  v_base_ref_num text;
  v_ref_num text;
  v_counter integer;
  v_cogs_account_id uuid;
  v_inventory_account_id uuid;
  v_line_number integer;
  v_adjusted_invoices_count integer := 0;
  v_adjusted_items_count integer := 0;
  v_total_delta_posted numeric := 0;

  -- FIFO simulation variables
  v_rem_to_consume numeric;
  v_layer_consume numeric;
  v_item_fifo_cogs numeric;
  v_item_layer_alloc jsonb;
  v_item_delta numeric;
  v_item_old_cogs numeric;
BEGIN
  -- Prevent trigger cascades while allowing normal execution
  IF current_setting('app.in_cogs_propagation', true) = 'on' THEN
    RETURN jsonb_build_object('success', true, 'message', 'Propagation already active in current session');
  END IF;

  PERFORM set_config('app.in_cogs_propagation', 'on', true);

  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND THEN
    PERFORM set_config('app.in_cogs_propagation', 'off', true);
    RETURN jsonb_build_object('success', false, 'error', 'Batch not found');
  END IF;

  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;
  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;
  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN
    PERFORM set_config('app.in_cogs_propagation', 'off', true);
    RAISE EXCEPTION 'Missing COGS (5100) or Inventory (1130) account in chart_of_accounts';
  END IF;

  -- Build temp table for layers of this batch with running remaining quantities
  DROP TABLE IF EXISTS tmp_batch_fifo_layers;
  CREATE TEMP TABLE tmp_batch_fifo_layers ON COMMIT DROP AS
    SELECT 
      pbcl.id as layer_id,
      pbcl.quantity as original_qty,
      pbcl.quantity as remaining_qty,
      pbcl.final_functional_unit_cost as unit_cost,
      pi.invoice_number as pi_number,
      COALESCE(pira.received_at, pi.invoice_date::timestamp, pbcl.created_at) as receipt_date
    FROM public.purchase_batch_cost_layers pbcl
    LEFT JOIN public.purchase_invoices pi ON pi.id = pbcl.purchase_invoice_id
    LEFT JOIN public.purchase_invoice_receiving_allocations pira ON pira.id = pbcl.receiving_allocation_id
   WHERE pbcl.batch_id = p_batch_id
   ORDER BY receipt_date ASC, pbcl.id ASC;

  SELECT COUNT(*) INTO v_layer_count FROM tmp_batch_fifo_layers;

  -- Iterate through each posted sales invoice containing items from this batch in chronological order
  FOR v_inv IN
    SELECT DISTINCT si.id, si.invoice_number, si.invoice_date, si.customer_id, si.created_by
      FROM public.sales_invoices si
      JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id
     WHERE sii.batch_id = p_batch_id
       AND NOT COALESCE(si.is_draft, false)
       AND public.is_reportable_sales_invoice(si.document_status, si.is_draft, si.notes)
     ORDER BY si.invoice_date ASC, si.id ASC
  LOOP
    -- Iterate through each item in this invoice for this batch
    FOR v_item IN
      SELECT sii.id, sii.quantity, COALESCE(sii.cogs_total_cost, 0) as old_cogs
        FROM public.sales_invoice_items sii
       WHERE sii.invoice_id = v_inv.id
         AND sii.batch_id = p_batch_id
       ORDER BY sii.id
    LOOP
      v_rem_to_consume := COALESCE(v_item.quantity, 0);
      v_item_fifo_cogs := 0;
      v_item_layer_alloc := '[]'::jsonb;

      IF v_layer_count > 0 THEN
        FOR v_layer IN
          SELECT * FROM tmp_batch_fifo_layers
           WHERE remaining_qty > 0.00001
           ORDER BY receipt_date ASC, layer_id ASC
        LOOP
          EXIT WHEN v_rem_to_consume <= 0.00001;
          v_layer_consume := LEAST(v_layer.remaining_qty, v_rem_to_consume);
          v_item_fifo_cogs := v_item_fifo_cogs + (v_layer_consume * v_layer.unit_cost);

          UPDATE tmp_batch_fifo_layers
             SET remaining_qty = remaining_qty - v_layer_consume
           WHERE layer_id = v_layer.layer_id;

          v_item_layer_alloc := v_item_layer_alloc || jsonb_build_object(
            'layer_id', v_layer.layer_id,
            'pi_number', v_layer.pi_number,
            'receipt_date', v_layer.receipt_date,
            'consumed_qty', v_layer_consume,
            'unit_cost', v_layer.unit_cost,
            'cost', ROUND(v_layer_consume * v_layer.unit_cost, 2)
          );

          v_rem_to_consume := v_rem_to_consume - v_layer_consume;
        END LOOP;
      ELSE
        -- Fallback to scalar batch cost if no layers exist
        v_item_fifo_cogs := v_rem_to_consume * COALESCE(v_batch.landed_cost_per_unit, v_batch.cost_per_unit, 0);
      END IF;

      v_target_item_cogs := ROUND(v_item_fifo_cogs, 2);

      -- Update snapshot on sales_invoice_items
      UPDATE public.sales_invoice_items
         SET cogs_unit_cost = CASE WHEN v_item.quantity > 0 THEN ROUND(v_target_item_cogs / v_item.quantity, 4) ELSE 0 END,
             cogs_total_cost = v_target_item_cogs,
             cogs_layer_allocations = v_item_layer_alloc
       WHERE id = v_item.id;

      v_adjusted_items_count := v_adjusted_items_count + 1;
    END LOOP;

    -- Now calculate invoice-level target total across ALL items of this invoice
    SELECT COALESCE(SUM(sii_all.cogs_total_cost), 0)
      INTO v_target_total
      FROM public.sales_invoice_items sii_all
     WHERE sii_all.invoice_id = v_inv.id;

    -- Calculate total posted GL 5100 for this invoice across all active journals
    SELECT COALESCE(SUM(jel.debit - jel.credit), 0)
      INTO v_posted_gl
      FROM public.journal_entries je
      JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id
      JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
     WHERE je.reference_id = v_inv.id
       AND coa.code = '5100'
       AND je.is_posted = true
       AND NOT COALESCE(je.is_reversed, false);

    v_inv_delta := ROUND(v_target_total - v_posted_gl, 2);

    IF ABS(v_inv_delta) >= 0.01 THEN
      SELECT ap.status INTO v_period_status
        FROM public.accounting_periods ap
       WHERE ap.start_date <= v_inv.invoice_date AND ap.end_date >= v_inv.invoice_date
       ORDER BY ap.start_date DESC LIMIT 1;

      IF v_period_status = 'open' THEN
        v_entry_date := v_inv.invoice_date;
      ELSE
        v_entry_date := CURRENT_DATE;
      END IF;

      SELECT id INTO v_period_id
        FROM public.accounting_periods
       WHERE start_date <= v_entry_date AND end_date >= v_entry_date
       ORDER BY start_date DESC LIMIT 1;

      v_source_module := 'sales_invoice_cogs_adjustment';
      v_description := 'FIFO COGS True-Up: ' || v_inv.invoice_number || ' (Batch ' || v_batch.batch_number || ')';
      v_base_ref_num := v_inv.invoice_number || '-FIFO-ADJ';
      v_ref_num := v_base_ref_num;
      v_counter := 2;
      WHILE EXISTS (
        SELECT 1 FROM public.journal_entries
         WHERE source_module = v_source_module
           AND reference_number = v_ref_num
           AND NOT COALESCE(is_reversed, false)
      ) LOOP
        v_ref_num := v_base_ref_num || '-' || v_counter;
        v_counter := v_counter + 1;
      END LOOP;

      v_je_number := public.next_journal_entry_number();

      INSERT INTO public.journal_entries (
        entry_number, entry_date, period_id, source_module, reference_id, reference_number,
        description, total_debit, total_credit, is_posted, posted_by, created_by
      ) VALUES (
        v_je_number, v_entry_date, v_period_id, v_source_module, v_inv.id, v_ref_num,
        v_description, ABS(v_inv_delta), ABS(v_inv_delta),
        true, COALESCE(auth.uid(), v_inv.created_by), COALESCE(auth.uid(), v_inv.created_by)
      ) RETURNING id INTO v_je_id;

      v_line_number := 1;

      IF v_inv_delta > 0 THEN
        -- Target > Posted: Debit 5100 COGS, Credit 1130 Inventory
        INSERT INTO public.journal_entry_lines (
          journal_entry_id, line_number, account_id, description, debit, credit,
          customer_id, batch_id
        ) VALUES (
          v_je_id, v_line_number, v_cogs_account_id,
          'FIFO COGS adjustment - ' || v_inv.invoice_number, v_inv_delta, 0,
          v_inv.customer_id, p_batch_id
        );
        v_line_number := v_line_number + 1;

        INSERT INTO public.journal_entry_lines (
          journal_entry_id, line_number, account_id, description, debit, credit,
          customer_id, batch_id
        ) VALUES (
          v_je_id, v_line_number, v_inventory_account_id,
          'FIFO Inventory revaluation - ' || v_inv.invoice_number, 0, v_inv_delta,
          v_inv.customer_id, p_batch_id
        );
      ELSE
        -- Target < Posted: Debit 1130 Inventory, Credit 5100 COGS
        INSERT INTO public.journal_entry_lines (
          journal_entry_id, line_number, account_id, description, debit, credit,
          customer_id, batch_id
        ) VALUES (
          v_je_id, v_line_number, v_inventory_account_id,
          'FIFO Inventory revaluation (downward) - ' || v_inv.invoice_number, ABS(v_inv_delta), 0,
          v_inv.customer_id, p_batch_id
        );
        v_line_number := v_line_number + 1;

        INSERT INTO public.journal_entry_lines (
          journal_entry_id, line_number, account_id, description, debit, credit,
          customer_id, batch_id
        ) VALUES (
          v_je_id, v_line_number, v_cogs_account_id,
          'FIFO COGS adjustment (downward) - ' || v_inv.invoice_number, 0, ABS(v_inv_delta),
          v_inv.customer_id, p_batch_id
        );
      END IF;

      v_adjusted_invoices_count := v_adjusted_invoices_count + 1;
      v_total_delta_posted := v_total_delta_posted + v_inv_delta;
    END IF;

  END LOOP;

  PERFORM set_config('app.in_cogs_propagation', 'off', true);

  RETURN jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number,
    'adjusted_invoices_count', v_adjusted_invoices_count,
    'adjusted_items_count', v_adjusted_items_count,
    'total_delta_posted', v_total_delta_posted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reallocate_container_costs(p_container_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_container record;
  v_shared_pool numeric := public.calculate_container_landed_cost_pool(p_container_id);
  v_pib_bm_pool numeric := 0;
  v_total_alloc_basis numeric := 0;
  v_duty_cif_total numeric := 0;
  v_method text;
  l record;
  v_batch_id uuid;
  v_batch_cost numeric;
  v_layer_duty numeric;
  v_layer_shared numeric;
  v_total_landed numeric;
  v_affected_batches uuid[] := ARRAY[]::uuid[];
  total_val numeric;
  batch_cost numeric;
BEGIN
  -- 1. Fetch container details & allocation method
  SELECT id, allocation_method INTO v_container
    FROM public.import_containers
   WHERE id = p_container_id;

  IF NOT FOUND THEN RETURN; END IF;

  v_method := COALESCE(v_container.allocation_method, 'invoice_value');

  -- 2. Link any cost layers for batches in this container that have NULL import_container_id
  UPDATE public.purchase_batch_cost_layers cl
     SET import_container_id = p_container_id
   WHERE cl.import_container_id IS NULL
     AND cl.batch_id IN (SELECT b.id FROM public.batches b WHERE b.import_container_id = p_container_id);

  -- 3. Calculate PIB Bea Masuk pool from approved PIB expenses
  -- Do not require include_in_landed_cost = true, because PIB import expenses are
  -- deliberately excluded from the general shared pool (calculate_container_landed_cost_pool)
  SELECT COALESCE(SUM(COALESCE(fe.pib_bm_amount, 0)), 0)
    INTO v_pib_bm_pool
    FROM public.finance_expenses fe
   WHERE fe.import_container_id = p_container_id
     AND fe.expense_category = 'pib_import'
     AND COALESCE(fe.approval_status, 'approved') NOT IN ('cancelled', 'rejected');

  -- 4. Branch 1: Purchase cost layers exist for this container
  IF EXISTS (SELECT 1 FROM public.purchase_batch_cost_layers WHERE import_container_id = p_container_id) THEN

    -- Calculate total allocation basis for shared pool according to container method
    -- Synchronize basis using batch master purchase price when available
    IF v_method = 'quantity' THEN
      SELECT COALESCE(SUM(quantity), 0) INTO v_total_alloc_basis
        FROM public.purchase_batch_cost_layers
       WHERE import_container_id = p_container_id;
    ELSE
      -- Default: invoice_value (functional_total_cost = unit_cost * quantity)
      SELECT COALESCE(SUM(
        COALESCE(NULLIF(b.import_price, 0), cl.functional_unit_cost) * cl.quantity
      ), 0) INTO v_total_alloc_basis
        FROM public.purchase_batch_cost_layers cl
        JOIN public.batches b ON b.id = cl.batch_id
       WHERE cl.import_container_id = p_container_id;
    END IF;

    -- Calculate total CIF value of duty-bearing products in this container
    SELECT COALESCE(SUM(
      COALESCE(NULLIF(b.import_price, 0), cl.functional_unit_cost) * cl.quantity
    ), 0)
      INTO v_duty_cif_total
      FROM public.purchase_batch_cost_layers cl
      JOIN public.batches b ON b.id = cl.batch_id
     WHERE cl.import_container_id = p_container_id
       AND (COALESCE(b.duty_charges, 0) > 0 OR COALESCE(b.actual_duty_charges, 0) > 0 OR b.batch_number = '4002/1101/25/A-0512B');

    -- Recalculate each cost layer
    FOR l IN 
      SELECT cl.id, cl.batch_id, cl.quantity,
             COALESCE(NULLIF(b.import_price, 0), cl.functional_unit_cost) as functional_unit_cost,
             b.duty_charges as batch_duty,
             b.actual_duty_charges as batch_actual_duty,
             b.exchange_rate_usd_to_idr as batch_fx,
             b.batch_number
        FROM public.purchase_batch_cost_layers cl
        JOIN public.batches b ON b.id = cl.batch_id
       WHERE cl.import_container_id = p_container_id
       ORDER BY cl.created_at, cl.id
       FOR UPDATE OF cl
    LOOP
      -- A. Shared expenses allocation (honouring allocation_method)
      IF v_total_alloc_basis > 0 THEN
        IF v_method = 'quantity' THEN
          v_layer_shared := ROUND(v_shared_pool * (l.quantity / v_total_alloc_basis), 2);
        ELSE
          v_layer_shared := ROUND(v_shared_pool * ((l.functional_unit_cost * l.quantity) / v_total_alloc_basis), 2);
        END IF;
      ELSE
        v_layer_shared := 0;
      END IF;

      -- B. Product-specific Customs Duty allocation (3-Tier Resolution)
      -- Tier 1: Authoritative historical overrides for 2nd FCL Ibuprofen batches
      IF l.batch_number = '4002/1101/25/A-0512B' THEN
        v_layer_duty := 6517000.00;
      ELSIF l.batch_number IN ('4001/1101/25/A-4276', '4001/1101/25/A-4277', '4001/1101/25/A-4632') THEN
        v_layer_duty := 6436000.00;
      -- Tier 2: Multi-batch container PIB pool distributed proportionally by CIF value
      ELSIF v_pib_bm_pool > 0 AND v_duty_cif_total > 0 AND (COALESCE(l.batch_duty, 0) > 0 OR COALESCE(l.batch_actual_duty, 0) > 0) THEN
        v_layer_duty := ROUND(v_pib_bm_pool * ((l.functional_unit_cost * l.quantity) / v_duty_cif_total), 2);
      -- Tier 3: Batch master authoritative actual duty charges or calculated unit duty
      ELSIF COALESCE(l.batch_actual_duty, 0) > 0 THEN
        v_layer_duty := l.batch_actual_duty;
      ELSIF COALESCE(l.batch_duty, 0) > 0 THEN
        v_layer_duty := ROUND(l.batch_duty * l.quantity, 2);
      ELSE
        v_layer_duty := 0;
      END IF;

      v_total_landed := v_layer_duty + v_layer_shared;

      -- Update purchase cost layer: synchronize purchase price, FX rate, landed cost amount, and final unit cost
      UPDATE public.purchase_batch_cost_layers
         SET functional_unit_cost = l.functional_unit_cost,
             functional_total_cost = ROUND(l.functional_unit_cost * l.quantity, 2),
             exchange_rate = COALESCE(NULLIF(l.batch_fx, 0), exchange_rate),
             landed_cost_amount = v_total_landed,
             final_functional_unit_cost = ROUND(l.functional_unit_cost + (v_total_landed / NULLIF(l.quantity, 0)), 4)
       WHERE id = l.id;
    END LOOP;

    -- Synchronize batch master fields for each affected batch
    FOR v_batch_id IN 
      SELECT DISTINCT cl.batch_id 
        FROM public.purchase_batch_cost_layers cl
       WHERE cl.import_container_id = p_container_id 
    LOOP
      SELECT COALESCE(SUM(quantity * final_functional_unit_cost) / NULLIF(SUM(quantity), 0), 0)
        INTO v_batch_cost
        FROM public.purchase_batch_cost_layers
       WHERE batch_id = v_batch_id;

      -- Update batch master:
      -- duty_charges: customs duty per unit
      -- import_cost_allocated: shared container costs only (deducts duty cleanly, never double-counts)
      -- landed_cost_per_unit = cost_per_unit = purchase price + duty + shared
      UPDATE public.batches b
         SET cost_per_unit = ROUND(v_batch_cost, 2),
             landed_cost_per_unit = ROUND(v_batch_cost, 2),
             final_landed_cost = ROUND(v_batch_cost * COALESCE(import_quantity, 1), 2),
             duty_charges = CASE 
               WHEN b.batch_number = '4002/1101/25/A-0512B' THEN 6517.00
               WHEN b.batch_number IN ('4001/1101/25/A-4276', '4001/1101/25/A-4277', '4001/1101/25/A-4632') THEN 6436.00
               WHEN v_pib_bm_pool > 0 AND COALESCE(b.duty_charges, 0) > 0 AND v_duty_cif_total > 0 THEN
                 ROUND((v_pib_bm_pool * (
                   COALESCE((SELECT SUM(functional_total_cost) FROM public.purchase_batch_cost_layers WHERE batch_id = v_batch_id), 0)
                   / v_duty_cif_total
                 )) / NULLIF(b.import_quantity, 0), 2)
               ELSE b.duty_charges
             END,
             actual_duty_charges = CASE
               WHEN b.batch_number = '4002/1101/25/A-0512B' THEN 6517000.00
               WHEN b.batch_number IN ('4001/1101/25/A-4276', '4001/1101/25/A-4277', '4001/1101/25/A-4632') THEN 6436000.00
               WHEN v_pib_bm_pool > 0 AND COALESCE(b.duty_charges, 0) > 0 AND v_duty_cif_total > 0 THEN
                 ROUND(v_pib_bm_pool * (
                   COALESCE((SELECT SUM(functional_total_cost) FROM public.purchase_batch_cost_layers WHERE batch_id = v_batch_id), 0)
                   / v_duty_cif_total
                 ), 2)
               ELSE COALESCE(b.actual_duty_charges, b.duty_charges * b.import_quantity, 0)
             END,
             import_cost_allocated = ROUND(COALESCE((
               SELECT SUM(pbcl.landed_cost_amount) - CASE 
                 WHEN b.batch_number = '4002/1101/25/A-0512B' THEN 6517000.00
                 WHEN b.batch_number IN ('4001/1101/25/A-4276', '4001/1101/25/A-4277', '4001/1101/25/A-4632') THEN 6436000.00
                 WHEN v_pib_bm_pool > 0 AND COALESCE(b.duty_charges, 0) > 0 AND v_duty_cif_total > 0 THEN
                   ROUND(v_pib_bm_pool * (
                     COALESCE((SELECT SUM(functional_total_cost) FROM public.purchase_batch_cost_layers WHERE batch_id = v_batch_id), 0)
                     / v_duty_cif_total
                   ), 2)
                 ELSE COALESCE(b.actual_duty_charges, b.duty_charges * b.import_quantity, 0)
               END
               FROM public.purchase_batch_cost_layers pbcl
               WHERE pbcl.batch_id = v_batch_id
             ), 0), 2),
             updated_at = now()
       WHERE id = v_batch_id;

      v_affected_batches := array_append(v_affected_batches, v_batch_id);
    END LOOP;

    -- Propagate cost changes to sales COGS and post balancing true-up journals
    FOREACH v_batch_id IN ARRAY v_affected_batches LOOP
      PERFORM public.propagate_batch_cost_change(v_batch_id);
    END LOOP;

    RETURN;
  END IF;

  -- Branch 2: Value-weighted allocation across linked batches (legacy containers without layers)
  SELECT COALESCE(SUM(COALESCE(import_price, 0) * COALESCE(import_quantity, 0)), 0)
    INTO total_val
    FROM public.batches
   WHERE import_container_id = p_container_id;

  IF total_val <= 0 THEN RETURN; END IF;

  FOR l IN SELECT id, import_price, import_quantity, duty_charges, actual_duty_charges, freight_charges, other_charges
    FROM public.batches WHERE import_container_id = p_container_id LOOP
    batch_cost := v_shared_pool * (COALESCE(l.import_price, 0) * COALESCE(l.import_quantity, 0)) / total_val;
    UPDATE public.batches
       SET import_cost_allocated = ROUND(batch_cost, 2),
           final_landed_cost = ROUND((COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0)) * COALESCE(l.import_quantity, 0) + COALESCE(l.freight_charges, 0) + COALESCE(l.other_charges, 0) + batch_cost, 2),
           landed_cost_per_unit = ROUND(COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0) + COALESCE(l.freight_charges, 0) / NULLIF(l.import_quantity, 0) + COALESCE(l.other_charges, 0) / NULLIF(l.import_quantity, 0) + batch_cost / NULLIF(l.import_quantity, 0), 2),
           cost_per_unit = ROUND(COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0) + COALESCE(l.freight_charges, 0) / NULLIF(l.import_quantity, 0) + COALESCE(l.other_charges, 0) / NULLIF(l.import_quantity, 0) + batch_cost / NULLIF(l.import_quantity, 0), 2),
           updated_at = now()
     WHERE id = l.id;

    v_affected_batches := array_append(v_affected_batches, l.id);
  END LOOP;

  -- Propagate cost changes to sales COGS for every affected batch
  FOREACH v_batch_id IN ARRAY v_affected_batches LOOP
    PERFORM public.propagate_batch_cost_change(v_batch_id);
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.reassign_tax_document_period(p_source text, p_document_id uuid, p_tax_period_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target public.tax_periods%ROWTYPE;
  v_old_period_id uuid;
  v_tax_type text;
  v_tax_code_id uuid;
  v_doc_date date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_target
    FROM public.tax_periods
   WHERE id = p_tax_period_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found', p_tax_period_id; END IF;
  IF v_target.status IN ('closed', 'filed') OR v_target.filing_status = 'filed' THEN
    RAISE EXCEPTION 'Tax period % is filed or closed and cannot be selected', p_tax_period_id;
  END IF;

  CASE p_source
    WHEN 'purchase_invoice' THEN
      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.purchase_invoices WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Purchase invoices require a PPN tax period'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    WHEN 'sales_invoice' THEN
      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.sales_invoices WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Sales invoice % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Sales invoices require a PPN tax period'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    WHEN 'credit_note' THEN
      SELECT tax_period_id, issue_date INTO v_old_period_id, v_doc_date FROM public.credit_notes WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Credit note % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Credit notes require a PPN tax period'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    WHEN 'finance_expense_ppn' THEN
      SELECT tax_period_id, expense_date INTO v_old_period_id, v_doc_date FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;
      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Expenses require a PPN tax period for PPN reporting'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    WHEN 'finance_expense_pph' THEN
      SELECT pph_tax_period_id, pph_code_id, expense_date INTO v_old_period_id, v_tax_code_id, v_doc_date
        FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;
      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Expense PPh tax type must match the selected period'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    WHEN 'payment_voucher' THEN
      SELECT tax_period_id, pph_code_id, voucher_date INTO v_old_period_id, v_tax_code_id, v_doc_date
        FROM public.payment_vouchers WHERE id=p_document_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_document_id; END IF;
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;
      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Payment voucher PPh tax type must match the selected period'; END IF;
      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN
        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;
      END IF;

    ELSE
      RAISE EXCEPTION 'Unsupported tax document source %', p_source;
  END CASE;

  IF v_old_period_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.tax_periods
     WHERE id=v_old_period_id AND (status IN ('closed', 'filed') OR filing_status='filed')
  ) THEN
    RAISE EXCEPTION 'The current tax period is filed or closed; reopen it before changing this document';
  END IF;

  CASE p_source
    WHEN 'purchase_invoice' THEN UPDATE public.purchase_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'sales_invoice' THEN
      UPDATE public.sales_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
      UPDATE public.faktur_pajak SET tax_period_id=p_tax_period_id WHERE sales_invoice_id=p_document_id;
    WHEN 'credit_note' THEN UPDATE public.credit_notes SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'finance_expense_ppn' THEN UPDATE public.finance_expenses SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'finance_expense_pph' THEN UPDATE public.finance_expenses SET pph_tax_period_id=p_tax_period_id WHERE id=p_document_id;
    WHEN 'payment_voucher' THEN UPDATE public.payment_vouchers SET tax_period_id=p_tax_period_id WHERE id=p_document_id;
  END CASE;

  IF v_old_period_id IS NOT NULL AND v_old_period_id <> p_tax_period_id THEN
    PERFORM public.compute_period_ppn(v_old_period_id);
  END IF;
  PERFORM public.compute_period_ppn(p_tax_period_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_batch_landed_cost(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_container_id uuid;
  v_direct_cost numeric;
  v_b record;
BEGIN
  SELECT * INTO v_b FROM public.batches WHERE id = p_batch_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_b.import_container_id IS NOT NULL THEN
    PERFORM public.reallocate_container_costs(v_b.import_container_id);
  ELSE
    -- Standalone batch with direct expense link
    v_direct_cost := public.calculate_batch_direct_landed_cost(p_batch_id);
    IF v_direct_cost > 0 AND COALESCE(v_b.cost_locked, false) = false THEN
      UPDATE public.batches
         SET import_cost_allocated = ROUND(v_direct_cost, 2),
             final_landed_cost = ROUND((COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0)) * COALESCE(v_b.import_quantity, 0) + COALESCE(v_b.freight_charges, 0) + COALESCE(v_b.other_charges, 0) + v_direct_cost, 2),
             landed_cost_per_unit = ROUND(COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0) + COALESCE(v_b.freight_charges, 0) / NULLIF(v_b.import_quantity, 0) + COALESCE(v_b.other_charges, 0) / NULLIF(v_b.import_quantity, 0) + v_direct_cost / NULLIF(v_b.import_quantity, 0), 2),
             cost_per_unit = ROUND(COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0) + COALESCE(v_b.freight_charges, 0) / NULLIF(v_b.import_quantity, 0) + COALESCE(v_b.other_charges, 0) / NULLIF(v_b.import_quantity, 0) + v_direct_cost / NULLIF(v_b.import_quantity, 0), 2),
             updated_at = now()
       WHERE id = p_batch_id;
    END IF;
    PERFORM public.propagate_batch_cost_change(p_batch_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_expense_payment_state(p_expense_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_supplier_paid numeric := 0;
  v_pph_paid numeric := 0;
  v_payable numeric := 0;
  v_target_paid numeric;
  v_target_pph_paid numeric;
BEGIN
  IF public.historical_repair_context_active() THEN RETURN; END IF;

  SELECT COALESCE(sum(va.allocated_amount),0) INTO v_supplier_paid
    FROM public.voucher_allocations va
    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id
   WHERE va.finance_expense_id=p_expense_id
     AND COALESCE(va.payment_kind,'supplier')='supplier'
     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement');

  SELECT v_supplier_paid+COALESCE(sum(allocation_amount),0) INTO v_supplier_paid
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=p_expense_id
     AND COALESCE(payment_kind,'supplier')='supplier';

  SELECT v_supplier_paid+COALESCE(sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0)),0) INTO v_supplier_paid
    FROM public.bank_statement_lines b
   WHERE b.matched_expense_id=p_expense_id AND b.payment_kind='supplier'
     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id);

  -- Include posted salary advance applications (advance recovery)
  SELECT v_supplier_paid+COALESCE(sum(sa.applied_amount),0) INTO v_supplier_paid
    FROM public.salary_advance_applications sa
    JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id
   WHERE sa.salary_expense_id = p_expense_id AND settlement.is_posted = true;

  SELECT COALESCE(sum(allocated_amount),0) INTO v_pph_paid
    FROM public.voucher_allocations va
    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id
   WHERE va.finance_expense_id=p_expense_id AND va.payment_kind='pph23'
     AND (va.payment_voucher_id IS NULL OR pv.is_posted = true);

  SELECT v_pph_paid+COALESCE(sum(allocation_amount),0) INTO v_pph_paid
    FROM public.bank_statement_allocations
   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='pph23';

  v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id),0);
  v_target_paid := LEAST(GREATEST(v_supplier_paid,0),GREATEST(v_payable,0));
  v_target_pph_paid := GREATEST(v_pph_paid,0);

  UPDATE public.finance_expenses
     SET paid_amount=v_target_paid,
         pph_paid_amount=v_target_pph_paid
   WHERE id=p_expense_id
     AND (paid_amount IS DISTINCT FROM v_target_paid OR pph_paid_amount IS DISTINCT FROM v_target_pph_paid);
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_purchase_invoice_payment_state(p_purchase_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invoice record;
  v_allocated numeric(18,2);
  v_adjustment numeric(18,2);
  v_paid numeric(18,2);
BEGIN
  IF p_purchase_invoice_id IS NULL THEN
    RETURN;
  END IF;

  SELECT id, total_amount
  INTO v_invoice
  FROM public.purchase_invoices
  WHERE id = p_purchase_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Only count allocations whose parent payment voucher is POSTED to GL
  SELECT COALESCE(SUM(va.allocated_amount), 0)
  INTO v_allocated
  FROM public.voucher_allocations va
  JOIN public.payment_vouchers pv
    ON pv.id = va.payment_voucher_id
  WHERE va.purchase_invoice_id = p_purchase_invoice_id
    AND va.voucher_type = 'payment'
    AND pv.is_posted = TRUE;

  -- Include settlement rounding/discount adjustments
  v_adjustment := public.get_purchase_invoice_rounding_adjustment_amount(p_purchase_invoice_id);
  v_paid := v_allocated + v_adjustment;

  UPDATE public.purchase_invoices
  SET
    paid_amount = v_paid,
    status = CASE
      WHEN v_paid <= 0 THEN 'unpaid'
      WHEN v_paid >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
      ELSE 'partial'
    END
  WHERE id = p_purchase_invoice_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_sales_invoice_payment_state(p_invoice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
      DECLARE
        v_invoice record;
        v_allocated numeric(18,2);
        v_adjustment numeric(18,2);
        v_credit_note numeric(18,2);
        v_paid numeric(18,2);
      BEGIN
        SELECT id, total_amount
        INTO v_invoice
        FROM public.sales_invoices
        WHERE id = p_invoice_id
        FOR UPDATE;

        IF NOT FOUND THEN
          RETURN;
        END IF;

        v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);
        v_adjustment := public.get_invoice_rounding_adjustment_amount(p_invoice_id);
        v_credit_note := public.get_invoice_credit_note_amount(p_invoice_id);

        v_paid := LEAST(
          GREATEST(COALESCE(v_allocated, 0) + COALESCE(v_adjustment, 0) + COALESCE(v_credit_note, 0), 0),
          COALESCE(v_invoice.total_amount, 0)
        );

        UPDATE public.sales_invoices
        SET
          paid_amount = v_paid,
          balance_amount = GREATEST(COALESCE(v_invoice.total_amount, 0) - v_paid, 0),
          payment_status = CASE
            WHEN v_paid <= 0 THEN 'pending'
            WHEN v_paid >= v_invoice.total_amount THEN 'paid'
            ELSE 'partial'
          END
        WHERE id = p_invoice_id;
      END;
      $function$

CREATE OR REPLACE FUNCTION public.receive_purchase_invoice_item(p_purchase_invoice_item_id uuid, p_payload jsonb, p_received_quantity numeric, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_item public.purchase_invoice_items%ROWTYPE;
  v_invoice public.purchase_invoices%ROWTYPE;
  v_batch public.batches%ROWTYPE;
  v_batch_id uuid;
  v_existing numeric;
  v_allocation_id uuid;
  v_make_id uuid;
  v_container_id uuid;
  v_currency text;
  v_rate numeric;
  v_tx_unit numeric;
  v_func_unit numeric;
  v_is_unreceived_batch boolean := false;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse']) THEN
    RAISE EXCEPTION 'Permission denied for inventory receiving';
  END IF;
  IF p_operation_id IS NULL OR p_received_quantity IS NULL OR p_received_quantity <= 0 THEN
    RAISE EXCEPTION 'A positive quantity and operation_id are required';
  END IF;
  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id = p_purchase_invoice_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice item not found'; END IF;
  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = v_item.purchase_invoice_id;
  IF v_item.item_type <> 'inventory' OR v_item.product_id IS NULL
     OR NULLIF(p_payload->>'product_id', '')::uuid IS DISTINCT FROM v_item.product_id THEN
    RAISE EXCEPTION 'Receiving requires the invoice inventory product';
  END IF;

  SELECT batch_id, id INTO v_batch_id, v_allocation_id
    FROM public.purchase_invoice_receiving_allocations WHERE operation_id = p_operation_id;
  IF FOUND THEN
    -- Ensure purchase_invoice_items.batch_id is set
    UPDATE public.purchase_invoice_items SET batch_id = v_batch_id WHERE id = v_item.id;
    RETURN jsonb_build_object('success', true, 'batch_id', v_batch_id,
      'allocation_id', v_allocation_id, 'idempotent_retry', true);
  END IF;

  v_existing := public.purchase_invoice_item_received_quantity(v_item.id);
  IF v_existing + p_received_quantity > v_item.quantity + 0.01 THEN
    RAISE EXCEPTION 'Received quantity exceeds invoice line quantity';
  END IF;

  v_make_id := NULLIF(p_payload->>'make_id', '')::uuid;
  v_container_id := NULLIF(p_payload->>'import_container_id', '')::uuid;
  IF v_make_id IS NOT NULL AND NOT EXISTS
    (SELECT 1 FROM public.product_sources WHERE id = v_make_id AND product_id = v_item.product_id) THEN
    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the invoice product';
  END IF;

  IF NULLIF(p_payload->>'batch_id', '') IS NOT NULL THEN
    SELECT * INTO v_batch FROM public.batches WHERE id = (p_payload->>'batch_id')::uuid FOR UPDATE;
  ELSE
    SELECT * INTO v_batch FROM public.batches
     WHERE product_id = v_item.product_id AND batch_number = p_payload->>'batch_number'
       AND (make_id = v_make_id OR make_id IS NULL) AND coalesce(is_active, true)
     ORDER BY (make_id IS NULL), created_at LIMIT 1 FOR UPDATE;
  END IF;

  IF FOUND THEN
    IF v_batch.product_id IS DISTINCT FROM v_item.product_id THEN
      RAISE EXCEPTION 'Product does not match selected batch';
    END IF;
    IF v_batch.make_id IS NOT NULL AND v_batch.make_id IS DISTINCT FROM v_make_id THEN
      RAISE EXCEPTION 'Make does not match selected batch';
    END IF;
    IF NULLIF(p_payload->>'expiry_date', '')::date IS NOT NULL
       AND v_batch.expiry_date IS NOT NULL
       AND NULLIF(p_payload->>'expiry_date', '')::date IS DISTINCT FROM v_batch.expiry_date THEN
      RAISE EXCEPTION 'Expiry date conflicts with existing physical batch';
    END IF;

    -- Check if this is a pre-created skeleton batch (current_stock = 0 and no transactions or allocations)
    v_is_unreceived_batch := (
      COALESCE(v_batch.current_stock, 0) = 0
      AND NOT EXISTS (SELECT 1 FROM public.purchase_invoice_receiving_allocations WHERE batch_id = v_batch.id)
      AND NOT EXISTS (SELECT 1 FROM public.inventory_transactions WHERE batch_id = v_batch.id)
    );

    IF v_is_unreceived_batch THEN
      -- Initial physical receipt into a pre-created batch:
      -- Post a 'purchase' movement from stock 0 -> p_received_quantity
      PERFORM public.post_inventory_movement(
        p_operation_id, v_batch.product_id, v_batch.id,
        'purchase', p_received_quantity, v_invoice.invoice_date, v_invoice.invoice_number,
        'purchase_invoice_receiving', v_invoice.id,
        'Purchase Invoice initial receiving into batch ' || v_batch.batch_number,
        auth.uid(), v_batch.current_stock, v_batch.current_stock + p_received_quantity
      );
      -- Update batch: set import_quantity = p_received_quantity (do not double add), plus any enriched fields
      UPDATE public.batches
         SET import_quantity = p_received_quantity,
             make_id = COALESCE(v_make_id, make_id),
             import_container_id = COALESCE(v_container_id, import_container_id),
             expiry_date = COALESCE(NULLIF(p_payload->>'expiry_date', '')::date, expiry_date),
             packaging_details = COALESCE(NULLIF(p_payload->>'packaging_details', ''), packaging_details),
             import_date = COALESCE(NULLIF(p_payload->>'import_date', '')::date, import_date, v_invoice.invoice_date),
             updated_at = now()
       WHERE id = v_batch.id;
    ELSE
      -- Existing batch receiving additional stock:
      PERFORM public.post_inventory_movement(
        p_operation_id, v_batch.product_id, v_batch.id,
        'adjustment', p_received_quantity, v_invoice.invoice_date, v_invoice.invoice_number,
        'purchase_invoice_receiving', v_invoice.id,
        'Purchase Invoice receiving into existing batch ' || v_batch.batch_number,
        auth.uid(), v_batch.current_stock, v_batch.current_stock + p_received_quantity
      );
      UPDATE public.batches
         SET import_quantity = import_quantity + p_received_quantity,
             updated_at = now()
       WHERE id = v_batch.id;
    END IF;
    v_batch_id := v_batch.id;
  ELSE
    p_payload := jsonb_set(p_payload, '{import_quantity}', to_jsonb(p_received_quantity), true);
    p_payload := jsonb_set(p_payload, '{purchase_invoice_id}', to_jsonb(v_item.purchase_invoice_id), true);
    p_payload := jsonb_set(p_payload, '{supplier_id}', to_jsonb(v_invoice.supplier_id), true);
    SELECT (public.save_batch_inventory_v1(NULL, p_payload, p_operation_id)->>'batch_id')::uuid INTO v_batch_id;
  END IF;

  v_currency := upper(coalesce(v_invoice.currency, 'IDR'));
  v_rate := CASE WHEN v_currency = 'IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate, 0) END;
  IF v_rate <= 0 THEN RAISE EXCEPTION 'Purchase invoice exchange rate is required'; END IF;
  v_tx_unit := coalesce(v_item.unit_price, 0);
  v_func_unit := round(v_tx_unit * v_rate, 2);
  INSERT INTO public.purchase_invoice_receiving_allocations(
    purchase_invoice_id, purchase_invoice_item_id, batch_id, received_quantity,
    operation_id, received_by, currency, exchange_rate, functional_unit_cost,
    functional_total_cost, import_container_id
  )
  VALUES (
    v_item.purchase_invoice_id, v_item.id, v_batch_id, p_received_quantity,
    p_operation_id, auth.uid(), v_currency, v_rate, v_func_unit,
    round(v_func_unit * p_received_quantity, 2), v_container_id
  )
  RETURNING id INTO v_allocation_id;

  INSERT INTO public.purchase_batch_cost_layers(
    receiving_allocation_id, purchase_invoice_id, purchase_invoice_item_id, batch_id,
    import_container_id, quantity, currency, exchange_rate, transaction_unit_cost,
    functional_unit_cost, functional_total_cost, final_functional_unit_cost
  )
  VALUES (
    v_allocation_id, v_item.purchase_invoice_id, v_item.id, v_batch_id, v_container_id,
    p_received_quantity, v_currency, v_rate, v_tx_unit, v_func_unit,
    round(v_func_unit * p_received_quantity, 2), v_func_unit
  );

  -- Apply weighted average to ensure batches record has correct unit cost
  PERFORM public.apply_batch_receipt_weighted_average(v_batch_id, p_received_quantity, v_func_unit);

  -- Persist batch_id and receiving_batch_number back onto purchase_invoice_items
  UPDATE public.purchase_invoice_items
     SET batch_id = v_batch_id,
         receiving_batch_number = COALESCE(receiving_batch_number, (SELECT batch_number FROM public.batches WHERE id = v_batch_id))
   WHERE id = v_item.id;

  RETURN jsonb_build_object('success', true, 'batch_id', v_batch_id, 'allocation_id', v_allocation_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.recompute_price_request_counts(p_pr_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role text;
  v_total    integer;
  v_src_recv integer;
  v_src_pend integer;
  v_fq_ready integer;
  v_fq_pend  integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid() AND is_active = true;
  IF v_role NOT IN ('admin', 'sales', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot recompute price request counts', v_role;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE price_status = 'received'),
    COUNT(*) FILTER (WHERE price_status IN ('pending', 'requested')),
    COUNT(*) FILTER (WHERE final_quote_price IS NOT NULL),
    COUNT(*) FILTER (WHERE price_status = 'received' AND final_quote_price IS NULL)
  INTO v_total, v_src_recv, v_src_pend, v_fq_ready, v_fq_pend
  FROM price_request_items
  WHERE price_request_id = p_pr_id;

  UPDATE price_requests
  SET
    total_products        = v_total,
    source_price_received = v_src_recv,
    source_price_pending  = v_src_pend,
    final_quote_ready     = v_fq_ready,
    final_quote_pending   = v_fq_pend,
    updated_at            = now()
  WHERE id = p_pr_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_all_sales_cogs(p_start_date date DEFAULT '2025-11-29'::date, p_end_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(total_invoices integer, total_items integer, snapshots_updated integer, delta_journals_created integer, total_delta_posted numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch_id uuid;
  v_res jsonb;
  v_tot_inv integer := 0;
  v_tot_items integer := 0;
  v_snap_updated integer := 0;
  v_je_created integer := 0;
  v_delta_posted numeric := 0;
BEGIN
  -- Count total non-draft sales invoices and items in scope
  SELECT COUNT(DISTINCT si.id), COUNT(sii.id)
    INTO v_tot_inv, v_tot_items
    FROM public.sales_invoices si
    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id
   WHERE NOT COALESCE(si.is_draft, false)
     AND si.invoice_date BETWEEN p_start_date AND p_end_date;

  DECLARE
    v_cont record;
  BEGIN
    -- Reallocate all import containers first to ensure canonical batch costs
    FOR v_cont IN
      SELECT id FROM public.import_containers
    LOOP
      PERFORM public.reallocate_container_costs(v_cont.id);
    END LOOP;
  END;

  -- Propagate cost changes for every batch sold in the period
  FOR v_batch_id IN
    SELECT DISTINCT sii.batch_id
      FROM public.sales_invoice_items sii
      JOIN public.sales_invoices si ON si.id = sii.invoice_id
     WHERE NOT COALESCE(si.is_draft, false)
       AND si.invoice_date BETWEEN p_start_date AND p_end_date
       AND sii.batch_id IS NOT NULL
  LOOP
    v_res := public.propagate_batch_cost_change(v_batch_id);
    v_je_created := v_je_created + COALESCE((v_res->>'adjusted_invoices_count')::integer, 0);
    v_snap_updated := v_snap_updated + COALESCE((v_res->>'adjusted_items_count')::integer, 0);
    v_delta_posted := v_delta_posted + COALESCE((v_res->>'total_delta_posted')::numeric, 0);
  END LOOP;

  -- Return final summary
  RETURN QUERY SELECT v_tot_inv, v_tot_items, v_snap_updated, v_je_created, v_delta_posted;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_bpjs_register_payment(p_register_id uuid, p_bank_line_id uuid, p_payment_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_reg public.bpjs_monthly_registers%ROWTYPE;
  v_accrual_je public.journal_entries%ROWTYPE;
  v_linked_emp_ded numeric := 0;
  v_expected_amount numeric;
  v_bank_line public.bank_statement_lines%ROWTYPE;
  v_bank_account public.bank_accounts%ROWTYPE;
  v_period_id uuid;
  v_pay_je_id uuid;
  v_entry_num text;
  v_bpjs_payable_coa_id uuid;
  v_payment_amount numeric;
  v_diff numeric;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  SELECT * INTO v_reg FROM public.bpjs_monthly_registers WHERE id = p_register_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BPJS register % not found', p_register_id; END IF;

  -- 1. Sequential lifecycle check: Register must be posted with an active accrual journal
  IF v_reg.status IN ('draft', 'reviewed') THEN
    RAISE EXCEPTION 'Cannot reconcile payment: BPJS register %-% is in % status. It must be approved and posted to the general ledger before payment reconciliation.',
      v_reg.period_year, v_reg.period_month, v_reg.status;
  END IF;

  IF v_reg.status = 'approved' AND v_reg.journal_entry_id IS NULL THEN
    RAISE EXCEPTION 'Cannot reconcile payment: BPJS register %-% is approved but its employer contribution accrual journal has not been posted yet.',
      v_reg.period_year, v_reg.period_month;
  END IF;

  IF v_reg.status NOT IN ('posted', 'reconciled') OR v_reg.journal_entry_id IS NULL THEN
    RAISE EXCEPTION 'Cannot reconcile payment: BPJS register %-% must have status ''posted'' with an active accrual journal (current status: %)',
      v_reg.period_year, v_reg.period_month, v_reg.status;
  END IF;

  -- 2. Verify active posted accrual journal
  SELECT * INTO v_accrual_je
    FROM public.journal_entries
   WHERE id = v_reg.journal_entry_id
     AND is_posted = true
     AND NOT COALESCE(is_reversed, false);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BPJS register %-% accrual journal % is missing, unposted, or reversed',
      v_reg.period_year, v_reg.period_month, v_reg.journal_entry_id;
  END IF;

  -- 3. Verify employer contribution journal reconciles to register employer expenses
  IF abs(COALESCE(v_accrual_je.total_credit, 0) - COALESCE(v_reg.total_employer_expenses, 0)) > 0.01 THEN
    RAISE EXCEPTION 'Posted employer contribution journal (Rp %) does not match register employer expenses (Rp %)',
      v_accrual_je.total_credit, v_reg.total_employer_expenses;
  END IF;

  -- 4. Verify employee BPJS deductions in linked salary expenses reconcile to register employee deductions
  SELECT COALESCE(SUM(fe.bpjs_employee_deduction), 0) INTO v_linked_emp_ded
    FROM public.finance_expenses fe
   WHERE fe.bpjs_register_item_id IN (
     SELECT id FROM public.bpjs_monthly_register_items WHERE register_id = v_reg.id
   ) AND fe.approval_status = 'approved';

  IF abs(v_linked_emp_ded - COALESCE(v_reg.total_employee_deductions, 0)) > 0.01 THEN
    RAISE EXCEPTION 'Salary-linked employee BPJS deductions (Rp %) do not reconcile to register employee deductions (Rp %)',
      v_linked_emp_ded, v_reg.total_employee_deductions;
  END IF;

  -- 5. Verify total liability equals register total
  IF abs((COALESCE(v_reg.total_employee_deductions, 0) + COALESCE(v_reg.total_employer_expenses, 0)) - COALESCE(v_reg.total_contribution_payable, 0)) > 0.01 THEN
    RAISE EXCEPTION 'Register total contribution payable (Rp %) does not equal employee deductions (Rp %) + employer expenses (Rp %)',
      v_reg.total_contribution_payable, v_reg.total_employee_deductions, v_reg.total_employer_expenses;
  END IF;

  -- 6. Validate bank statement line and payment amount
  SELECT * INTO v_bank_line FROM public.bank_statement_lines WHERE id = p_bank_line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line % not found', p_bank_line_id; END IF;

  SELECT * INTO v_bank_account FROM public.bank_accounts WHERE id = v_bank_line.bank_account_id;
  IF NOT FOUND OR v_bank_account.coa_id IS NULL THEN
    RAISE EXCEPTION 'Bank account COA not configured for line %', p_bank_line_id;
  END IF;

  SELECT id INTO v_bpjs_payable_coa_id FROM public.chart_of_accounts WHERE code = '2134' LIMIT 1;
  IF v_bpjs_payable_coa_id IS NULL THEN RAISE EXCEPTION 'Account 2134 BPJS Payable not found'; END IF;

  v_payment_amount := COALESCE(NULLIF(v_bank_line.debit_amount, 0), v_bank_line.credit_amount, 0);
  IF v_payment_amount <= 0 THEN RAISE EXCEPTION 'Bank statement line has zero payment amount'; END IF;

  -- 7. Payment amount matches official bill when available, otherwise calculated contribution
  v_expected_amount := CASE
    WHEN v_reg.has_official_bill = true AND v_reg.official_billed_amount IS NOT NULL
      THEN v_reg.official_billed_amount
    ELSE v_reg.total_contribution_payable
  END;

  v_diff := v_expected_amount - v_payment_amount;

  IF abs(v_diff) > 0.01 THEN
    RAISE EXCEPTION 'Payment amount (Rp %) does not match expected BPJS contribution (Rp %)',
      v_payment_amount, v_expected_amount;
  END IF;

  -- Resolve accounting period
  SELECT id INTO v_period_id FROM public.accounting_periods
   WHERE start_date <= v_bank_line.transaction_date AND end_date >= v_bank_line.transaction_date
   ORDER BY start_date DESC LIMIT 1;

  -- Create Payment Journal Entry
  -- Debit 2134 BPJS Payable, Credit Bank Account COA
  v_entry_num := public.next_journal_entry_number();
  INSERT INTO public.journal_entries (
    entry_number, entry_date, period_id, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, posted_at, created_by,
    transaction_currency, functional_currency, exchange_rate, amounts_are_functional
  ) VALUES (
    v_entry_num, v_bank_line.transaction_date, v_period_id, 'bpjs_payment', v_reg.id,
    'BPJS-PAY-' || v_reg.period_year || '-' || lpad(v_reg.period_month::text, 2, '0'),
    'BPJS Ketenagakerjaan Settlement - ' || COALESCE(p_payment_reference, v_reg.npp),
    v_payment_amount, v_payment_amount, true, auth.uid(), now(), auth.uid(),
    'IDR', 'IDR', 1.0, true
  ) RETURNING id INTO v_pay_je_id;

  -- Debit: 2134 BPJS Payable
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES (
    v_pay_je_id, 1, v_bpjs_payable_coa_id, v_payment_amount, 0,
    'BPJS Payment Settlement', 'IDR', v_payment_amount, 0, 'IDR', 1.0
  );

  -- Credit: Bank Account COA
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, debit, credit, description,
    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES (
    v_pay_je_id, 2, v_bank_account.coa_id, 0, v_payment_amount,
    'Bank Payment - BPJS Ketenagakerjaan', 'IDR', 0, v_payment_amount, 'IDR', 1.0
  );

  -- Link bank statement line
  UPDATE public.bank_statement_lines
     SET matched_entry_id = v_pay_je_id,
         reconciliation_status = 'matched',
         matching_status = 'confirmed',
         matched_at = now(),
         matched_by = auth.uid()
   WHERE id = v_bank_line.id;

  -- Update register status to reconciled
  UPDATE public.bpjs_monthly_registers
     SET bank_statement_line_id = v_bank_line.id,
         payment_journal_entry_id = v_pay_je_id,
         payment_reference = COALESCE(p_payment_reference, v_bank_line.description),
         actual_paid_amount = v_payment_amount,
         payment_status = 'paid',
         reconciliation_status = 'reconciled',
         status = 'reconciled',
         updated_at = now()
   WHERE id = v_reg.id;

  RETURN jsonb_build_object(
    'register_id', v_reg.id,
    'payment_journal_entry_id', v_pay_je_id,
    'bank_statement_line_id', v_bank_line.id,
    'actual_paid_amount', v_payment_amount,
    'difference', v_diff,
    'reconciliation_status', 'reconciled'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_so_product_reservation_v2(p_sales_order_item_id uuid, p_reason text DEFAULT 'SO state reconciliation'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_item record;
  v_res public.so_product_reservations%ROWTYPE;
  v_delivered numeric;
  v_required numeric;
  v_delta numeric;
  v_atp numeric;
  v_grant numeric;
  v_has_reservation boolean := false;
BEGIN
  SELECT soi.*, so.status::text AS so_status
  INTO v_item
  FROM public.sales_order_items soi
  JOIN public.sales_orders so ON so.id = soi.sales_order_id
  WHERE soi.id = p_sales_order_item_id
  FOR UPDATE OF soi, so;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Order item not found';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_item.product_id::text, 0));

  SELECT COALESCE(sum(dci.quantity), 0)
  INTO v_delivered
  FROM public.delivery_challan_items dci
  JOIN public.delivery_challans dc ON dc.id = dci.challan_id
  WHERE dci.sales_order_item_id = v_item.id
    AND dc.approval_status = 'approved';

  IF v_delivered > v_item.quantity THEN
    RAISE EXCEPTION 'Delivered quantity exceeds ordered quantity';
  END IF;

  v_required := CASE
    WHEN v_item.so_status IN ('pending_approval', 'approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')
      THEN v_item.quantity - v_delivered
    ELSE 0
  END;

  SELECT *
  INTO v_res
  FROM public.so_product_reservations
  WHERE sales_order_item_id = v_item.id
    AND status = 'active'
  FOR UPDATE;

  v_has_reservation := FOUND;

  IF v_required = 0 THEN
    IF v_has_reservation THEN
      UPDATE public.so_product_reservations
      SET reserved_quantity = 0,
          status = 'released',
          closed_at = now(),
          updated_at = now(),
          close_reason = p_reason
      WHERE id = v_res.id;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'released',
        -v_res.reserved_quantity, 0, p_reason, auth.uid()
      );
    END IF;
    RETURN 0;
  END IF;

  v_atp := public.product_available_to_promise(
    v_item.product_id,
    CASE WHEN v_has_reservation THEN v_item.id ELSE NULL END
  );

  v_grant := LEAST(v_required, GREATEST(COALESCE(v_atp, 0), 0));

  IF NOT v_has_reservation THEN
    IF v_grant > 0 THEN
      INSERT INTO public.so_product_reservations(
        sales_order_id, sales_order_item_id, product_id, reserved_quantity, created_by
      ) VALUES (
        v_item.sales_order_id, v_item.id, v_item.product_id, v_grant, auth.uid()
      ) RETURNING * INTO v_res;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'created',
        v_grant, v_grant, p_reason, auth.uid()
      );
    END IF;
  ELSE
    IF v_res.product_id <> v_item.product_id THEN
      RAISE EXCEPTION 'Cannot change product on an actively reserved SO item';
    END IF;

    IF v_grant = 0 THEN
      UPDATE public.so_product_reservations
      SET reserved_quantity = 0,
          status = 'released',
          closed_at = now(),
          updated_at = now(),
          close_reason = p_reason
      WHERE id = v_res.id;

      INSERT INTO public.so_product_reservation_events(
        reservation_id, sales_order_id, sales_order_item_id, event_type,
        quantity_delta, quantity_after, reason, actor_id
      ) VALUES (
        v_res.id, v_item.sales_order_id, v_item.id, 'released',
        -v_res.reserved_quantity, 0, p_reason, auth.uid()
      );
    ELSE
      v_delta := v_grant - v_res.reserved_quantity;
      IF v_delta <> 0 THEN
        UPDATE public.so_product_reservations
        SET reserved_quantity = v_grant,
            updated_at = now()
        WHERE id = v_res.id;

        INSERT INTO public.so_product_reservation_events(
          reservation_id, sales_order_id, sales_order_item_id, event_type,
          quantity_delta, quantity_after, reason, actor_id
        ) VALUES (
          v_res.id, v_item.sales_order_id, v_item.id,
          CASE WHEN v_delta > 0 THEN 'increased' ELSE 'decreased' END,
          v_delta, v_grant, p_reason, auth.uid()
        );
      END IF;
    END IF;
  END IF;

  RETURN v_grant;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_director_related_party_bank_transaction(p_bank_line_id uuid, p_director_name text DEFAULT 'Vijay Lunkad'::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_line public.bank_statement_lines%ROWTYPE;
  v_is_credit boolean;
  v_amount numeric;
  v_currency text;
  v_rate numeric := 1;
  v_bank_account public.bank_accounts%ROWTYPE;
  v_due_to_director numeric := 0;
  v_due_from_director numeric := 0;
  v_open_loan public.loans%ROWTYPE;
  v_repay_amount numeric;
  v_remaining_amount numeric;
  v_loan_payload jsonb;
  v_repay_payload jsonb;
  v_loan_res jsonb;
  v_repay_res jsonb;
  v_je_id uuid;
  v_result jsonb;
  v_description text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();

  -- 1. Fetch and lock bank statement line
  SELECT * INTO v_line
  FROM public.bank_statement_lines
  WHERE id = p_bank_line_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank statement line not found';
  END IF;

  IF v_line.matched_entry_id IS NOT NULL THEN
    RAISE EXCEPTION 'Bank statement line is already linked';
  END IF;

  SELECT * INTO v_bank_account
  FROM public.bank_accounts
  WHERE id = v_line.bank_account_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank account not found or inactive';
  END IF;

  v_currency := upper(COALESCE(v_line.currency, v_bank_account.currency, 'IDR'));

  -- Validate direction & amount
  IF COALESCE(v_line.credit_amount, 0) > 0 AND COALESCE(v_line.debit_amount, 0) = 0 THEN
    v_is_credit := true;
    v_amount := v_line.credit_amount;
  ELSIF COALESCE(v_line.debit_amount, 0) > 0 AND COALESCE(v_line.credit_amount, 0) = 0 THEN
    v_is_credit := false;
    v_amount := v_line.debit_amount;
  ELSE
    RAISE EXCEPTION 'Bank statement line must have either a positive debit or positive credit amount';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Transaction amount must be greater than zero';
  END IF;

  IF v_currency = 'USD' THEN
    IF v_bank_account.currency <> 'USD' THEN
      RAISE EXCEPTION 'Currency mismatch between line and bank account';
    END IF;
    -- For USD bank account, functional rate must be valid
    v_rate := 1; -- In underlying loans table, IDR is functional
  END IF;

  -- 2. Calculate current GL balances for Director
  -- Due TO Director (Account 2105 - Liability: Credit minus Debit)
  SELECT COALESCE(sum(jel.credit - jel.debit), 0) INTO v_due_to_director
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE coa.code = '2105'
    AND je.is_posted = true
    AND NOT COALESCE(je.is_reversed, false);

  -- Due FROM Director (Account 1310 - Asset: Debit minus Credit)
  SELECT COALESCE(sum(jel.debit - jel.credit), 0) INTO v_due_from_director
  FROM public.journal_entry_lines jel
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  WHERE coa.code = '1310'
    AND je.is_posted = true
    AND NOT COALESCE(je.is_reversed, false);

  v_description := COALESCE(NULLIF(trim(p_notes), ''), v_line.description, 'Director transaction');

  -- 3. Automatic Purpose & Accounting Direction Execution
  IF v_is_credit THEN
    -- MONEY IN FROM DIRECTOR (Bank Credit: Dr Bank)
    -- If director owes money (1310 > 0), settle 1310 first (Cr 1310).
    IF v_due_from_director > 0 THEN
      -- Find active 'given' loan if one exists
      SELECT * INTO v_open_loan
      FROM public.loans
      WHERE loan_type = 'given'
        AND status = 'active'
        AND outstanding_balance > 0
        AND counterparty_name ILIKE ('%' || trim(p_director_name) || '%')
      ORDER BY loan_date
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        v_repay_amount := LEAST(v_amount, v_open_loan.outstanding_balance);
        v_remaining_amount := v_amount - v_repay_amount;

        v_repay_payload := jsonb_build_object(
          'loan_id', v_open_loan.id,
          'transaction_date', v_line.transaction_date,
          'principal_amount', v_repay_amount,
          'interest_amount', 0,
          'bank_account_id', v_line.bank_account_id,
          'transaction_currency', v_currency,
          'exchange_rate', v_rate,
          'description', 'Settlement of Due from Director - ' || p_director_name
        );

        v_repay_res := public.save_finance_loan_repayment(v_repay_payload, p_bank_line_id);
        v_je_id := (v_repay_res->>'journal_entry_id')::uuid;

        -- If received amount exceeds open loan balance, record excess as new director funding (2105)
        IF v_remaining_amount > 0 THEN
          v_loan_payload := jsonb_build_object(
            'loan_date', v_line.transaction_date,
            'loan_type', 'taken',
            'counterparty_name', p_director_name,
            'counterparty_type', 'person',
            'principal_amount', v_remaining_amount,
            'bank_account_id', v_line.bank_account_id,
            'transaction_currency', v_currency,
            'exchange_rate', v_rate,
            'description', 'Director funding (excess) - ' || p_director_name
          );
          v_loan_res := public.save_finance_loan(v_loan_payload, NULL);
        END IF;

        v_result := jsonb_build_object(
          'action', 'settle_due_from_director',
          'repayment', v_repay_res,
          'journal_entry_id', v_je_id,
          'excess_loan', v_loan_res
        );
      ELSE
        -- No active given loan row, post journal directly to 1310
        v_result := public.save_bank_linked_finance_journal(
          p_bank_line_id,
          'Settlement of Due from Director - ' || p_director_name,
          '1310',
          'debit',
          v_currency,
          v_rate
        );
      END IF;
    ELSE
      -- Director is funding company -> Increase 2105 (Cr 2105)
      v_loan_payload := jsonb_build_object(
        'loan_date', v_line.transaction_date,
        'loan_type', 'taken',
        'counterparty_name', p_director_name,
        'counterparty_type', 'person',
        'principal_amount', v_amount,
        'bank_account_id', v_line.bank_account_id,
        'transaction_currency', v_currency,
        'exchange_rate', v_rate,
        'description', 'Director funding - ' || p_director_name
      );

      v_loan_res := public.save_finance_loan(v_loan_payload, p_bank_line_id);
      v_result := jsonb_build_object(
        'action', 'new_director_funding',
        'loan', v_loan_res,
        'journal_entry_id', (v_loan_res->>'journal_entry_id')::uuid
      );
    END IF;

  ELSE
    -- MONEY OUT TO DIRECTOR (Bank Debit: Cr Bank)
    -- If company owes director (2105 > 0), settle 2105 first (Dr 2105).
    IF v_due_to_director > 0 THEN
      -- Find active 'taken' loan if one exists
      SELECT * INTO v_open_loan
      FROM public.loans
      WHERE loan_type = 'taken'
        AND status = 'active'
        AND outstanding_balance > 0
        AND counterparty_name ILIKE ('%' || trim(p_director_name) || '%')
      ORDER BY loan_date
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        v_repay_amount := LEAST(v_amount, v_open_loan.outstanding_balance);
        v_remaining_amount := v_amount - v_repay_amount;

        v_repay_payload := jsonb_build_object(
          'loan_id', v_open_loan.id,
          'transaction_date', v_line.transaction_date,
          'principal_amount', v_repay_amount,
          'interest_amount', 0,
          'bank_account_id', v_line.bank_account_id,
          'transaction_currency', v_currency,
          'exchange_rate', v_rate,
          'description', 'Settlement of Due to Director - ' || p_director_name
        );

        v_repay_res := public.save_finance_loan_repayment(v_repay_payload, p_bank_line_id);
        v_je_id := (v_repay_res->>'journal_entry_id')::uuid;

        -- If paid amount exceeds open loan balance, record excess as advance to director (1310)
        IF v_remaining_amount > 0 THEN
          v_loan_payload := jsonb_build_object(
            'loan_date', v_line.transaction_date,
            'loan_type', 'given',
            'counterparty_name', p_director_name,
            'counterparty_type', 'person',
            'principal_amount', v_remaining_amount,
            'bank_account_id', v_line.bank_account_id,
            'transaction_currency', v_currency,
            'exchange_rate', v_rate,
            'description', 'Money given to Director (excess) - ' || p_director_name
          );
          v_loan_res := public.save_finance_loan(v_loan_payload, NULL);
        END IF;

        v_result := jsonb_build_object(
          'action', 'settle_due_to_director',
          'repayment', v_repay_res,
          'journal_entry_id', v_je_id,
          'excess_loan', v_loan_res
        );
      ELSE
        -- No active taken loan row, post journal directly to 2105 (e.g. settling petty cash liability)
        v_result := public.save_bank_linked_finance_journal(
          p_bank_line_id,
          'Settlement of Due to Director - ' || p_director_name,
          '2105',
          'credit',
          v_currency,
          v_rate
        );
      END IF;
    ELSE
      -- Company gives money to director -> Increase 1310 (Dr 1310)
      v_loan_payload := jsonb_build_object(
        'loan_date', v_line.transaction_date,
        'loan_type', 'given',
        'counterparty_name', p_director_name,
        'counterparty_type', 'person',
        'principal_amount', v_amount,
        'bank_account_id', v_line.bank_account_id,
        'transaction_currency', v_currency,
        'exchange_rate', v_rate,
        'description', 'Money given to Director - ' || p_director_name
      );

      v_loan_res := public.save_finance_loan(v_loan_payload, p_bank_line_id);
      v_result := jsonb_build_object(
        'action', 'money_given_to_director',
        'loan', v_loan_res,
        'journal_entry_id', (v_loan_res->>'journal_entry_id')::uuid
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'bank_line_id', p_bank_line_id,
    'direction', CASE WHEN v_is_credit THEN 'received_from_director' ELSE 'paid_to_director' END,
    'amount', v_amount,
    'director_name', p_director_name,
    'details', v_result
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.record_expense_cash_payment(p_expense_id uuid, p_payment_date date, p_payment_amount numeric, p_notes text DEFAULT NULL::text, p_payment_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_expense RECORD;
    v_event_id UUID;
    v_alloc_id UUID;
BEGIN
    -- Require authenticated finance role (admin, accounts)
    PERFORM public._sec_check_finance_role();

    SELECT * INTO v_expense FROM public.finance_expenses WHERE id = p_expense_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Expense % not found', p_expense_id;
    END IF;

    IF p_payment_date IS NULL THEN
        RAISE EXCEPTION 'Payment date is mandatory for recording cash disbursement';
    END IF;

    IF p_payment_amount <= 0 THEN
        RAISE EXCEPTION 'Payment amount must be greater than zero';
    END IF;

    v_event_id := COALESCE(p_payment_event_id, gen_random_uuid());

    -- Update paid_amount and payment state on expense
    UPDATE public.finance_expenses
    SET payment_method = 'cash',
        paid_amount = COALESCE(paid_amount, 0) + p_payment_amount
    WHERE id = p_expense_id;

    -- Sync PPh allocation
    v_alloc_id := public.sync_expense_pph_allocation(
        p_expense_id,
        'cash',
        v_event_id,
        p_payment_date,
        p_payment_amount,
        false,
        NULL,
        COALESCE(p_notes, 'Cash payment disbursement')
    );

    RETURN v_alloc_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_tax_payment(p_tax_period_id uuid, p_tax_type text, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text DEFAULT NULL::text, p_ntpn text DEFAULT NULL::text, p_government_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tp_id            uuid;
  v_je_id            uuid;
  v_je_number        text;
  v_period           tax_periods%ROWTYPE;
  v_payable_code     text;
  v_payable_acct_id  uuid;
  v_bank_acct_coa_id uuid;
  v_ref_number       text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Tax payment amount must be > 0';
  END IF;

  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;
  END IF;
  IF v_period.status = 'closed' THEN
    RAISE EXCEPTION 'Cannot record tax payment on a closed period';
  END IF;
  IF v_period.tax_type <> p_tax_type THEN
    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',
      v_period.tax_type, p_tax_type;
  END IF;

  -- Map tax type → payable account code
  v_payable_code := CASE p_tax_type
    WHEN 'PPN'      THEN '2130'
    WHEN 'PPh21'    THEN '2131'
    WHEN 'PPh22'    THEN '2137'
    WHEN 'PPh23'    THEN '2132'
    WHEN 'PPh4(2)'  THEN '2138'
    WHEN 'PPh_Unifikasi' THEN '2131'  -- treated as PPh 21 payable by default
    ELSE NULL
  END;

  IF v_payable_code IS NULL THEN
    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;
  END IF;

  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;
  IF v_payable_acct_id IS NULL THEN
    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;
  END IF;

  -- Bank account → CoA account
  IF p_bank_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account is required for a tax payment';
  END IF;
  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;
  IF v_bank_acct_coa_id IS NULL THEN
    -- Fallback to generic Bank BCA (1111) when bank_accounts.coa_id not wired
    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
  END IF;
  IF v_bank_acct_coa_id IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';
  END IF;

  -- 1) Create tax_payments row (draft)
  INSERT INTO tax_payments
    (tax_period_id, tax_type, payment_date, amount,
     bank_account_id, billing_code, ntpn, government_reference, notes,
     status, created_by)
  VALUES
    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,
     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference, p_notes,
     'draft', auth.uid())
  RETURNING id INTO v_tp_id;

  v_ref_number := COALESCE(NULLIF(p_ntpn,''), NULLIF(p_billing_code,''),
                           'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8));

  -- 2) Post journal entry: Dr Tax Payable / Cr Bank
  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries
    (entry_number, entry_date, source_module, reference_id, reference_number,
     description, total_debit, total_credit, is_posted, posted_by)
  VALUES
    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,
     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,
     p_amount, p_amount, true, auth.uid())
  RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines
    (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES
    (v_je_id, 1, v_payable_acct_id,
     p_tax_type || ' payment — ' || v_ref_number,
     p_amount, 0),
    (v_je_id, 2, v_bank_acct_coa_id,
     'Bank ' || p_tax_type || ' payment — ' || v_ref_number,
     0, p_amount);

  -- 3) Link back and mark posted
  UPDATE tax_payments SET
    journal_entry_id = v_je_id,
    status           = 'posted',
    updated_at       = now()
  WHERE id = v_tp_id;

  -- 4) Nudge the period status if it was open
  UPDATE tax_periods SET
    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,
    updated_at = now()
  WHERE id = p_tax_period_id;

  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)
  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,
          jsonb_build_object(
            'tax_period_id', p_tax_period_id,
            'tax_type',      p_tax_type,
            'amount',        p_amount,
            'journal_entry_id', v_je_id
          ));

  RETURN v_tp_id;
END $function$

