CREATE OR REPLACE FUNCTION public.refresh_bank_statement_allocation_status(p_bank_line_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_total numeric;
  v_allocated numeric;
  v_existing_status text;
  v_existing_matching_status text;
  v_new_matching_status text;
  v_new_recon_status text;
BEGIN
  SELECT COALESCE(NULLIF(debit_amount, 0), credit_amount, 0),
         reconciliation_status, matching_status
    INTO v_total, v_existing_status, v_existing_matching_status
    FROM public.bank_statement_lines
   WHERE id = p_bank_line_id
   FOR UPDATE;

  SELECT COALESCE(sum(allocation_amount), 0)
    INTO v_allocated
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_line_id;

  IF v_allocated <= 0.01 THEN
    v_new_recon_status := 'unmatched';
    v_new_matching_status := 'none';
  ELSIF v_allocated < v_total - 0.01 THEN
    v_new_recon_status := 'partially_reconciled';
    v_new_matching_status := CASE WHEN v_existing_matching_status = 'confirmed' THEN 'confirmed' ELSE 'suggested' END;
  ELSE
    v_new_recon_status := 'matched';
    v_new_matching_status := CASE WHEN v_existing_matching_status = 'confirmed' THEN 'confirmed' ELSE 'suggested' END;
  END IF;

  UPDATE public.bank_statement_lines
     SET reconciliation_status = v_new_recon_status,
         matching_status = v_new_matching_status,
         matched_at = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_at, now()) END,
         matched_by = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_by, auth.uid()) END
   WHERE id = p_bank_line_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_credit_note(p_credit_note_id uuid, p_amount numeric, p_bank_account_id uuid, p_payment_method text DEFAULT 'bank_transfer'::text, p_reference text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_role text;
  v_caller uuid := auth.uid();
  v_ar_id uuid;
  v_bank_coa_id uuid;
  v_je_id uuid;
  v_je_number text;
  v_remaining_balance numeric(15,2);
BEGIN
  IF v_caller IS NULL THEN
    v_caller := p_actor;
  END IF;
  SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot refund credit notes', COALESCE(v_role, 'none');
  END IF;

  SELECT * INTO v_cn FROM public.credit_notes WHERE id = p_credit_note_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit Note % not found', p_credit_note_id;
  END IF;

  IF v_cn.status <> 'approved' THEN
    RAISE EXCEPTION 'Cannot refund unapproved Credit Note %', v_cn.credit_note_number;
  END IF;

  IF COALESCE(v_cn.customer_credit_balance, 0) < p_amount THEN
    RAISE EXCEPTION 'Insufficient credit balance % on Credit Note % (Requested %)',
      v_cn.customer_credit_balance, v_cn.credit_note_number, p_amount;
  END IF;

  -- Resolve bank account CoA
  SELECT id INTO v_ar_id FROM chart_of_accounts WHERE code = '1120';
  IF p_bank_account_id IS NOT NULL THEN
    SELECT coa_id INTO v_bank_coa_id FROM bank_accounts WHERE id = p_bank_account_id;
  END IF;
  IF v_bank_coa_id IS NULL THEN
    SELECT id INTO v_bank_coa_id FROM chart_of_accounts WHERE code LIKE '1-102%' OR code = '1102' OR LOWER(name) LIKE '%bank%' LIMIT 1;
  END IF;

  IF v_bank_coa_id IS NULL OR v_ar_id IS NULL THEN
    RAISE EXCEPTION 'Chart of accounts missing A/R (1120) or bank account mapping';
  END IF;

  -- Post Refund Journal: Dr A/R (clearing credit balance), Cr Bank
  v_je_number := public.next_journal_entry_number();
  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, created_by
  ) VALUES (
    v_je_number, CURRENT_DATE, 'customer_refund', v_cn.id, v_cn.credit_note_number,
    'Customer refund for Credit Note ' || v_cn.credit_note_number || ' - Ref: ' || COALESCE(p_reference, 'Bank Transfer'),
    p_amount, p_amount, true, v_caller, v_caller
  ) RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, 1, v_ar_id, 'Customer refund debit - ' || v_cn.credit_note_number, p_amount, 0, v_cn.customer_id);

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES (v_je_id, 2, v_bank_coa_id, 'Bank payout refund - ' || v_cn.credit_note_number, 0, p_amount);

  v_remaining_balance := v_cn.customer_credit_balance - p_amount;

  UPDATE public.credit_notes
     SET customer_credit_balance = v_remaining_balance,
         refund_amount = COALESCE(refund_amount, 0) + p_amount,
         refund_date = CURRENT_DATE,
         settlement_status = CASE 
           WHEN v_remaining_balance <= 0.01 THEN 'refunded'
           ELSE 'partially_allocated'
         END,
         updated_at = now()
   WHERE id = v_cn.id;

  RETURN jsonb_build_object(
    'success', true,
    'credit_note_id', v_cn.id,
    'credit_note_number', v_cn.credit_note_number,
    'refund_amount', p_amount,
    'remaining_credit_balance', v_remaining_balance,
    'journal_entry_number', v_je_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_credit_note(p_credit_note_id uuid, p_refund_amount numeric, p_refund_date date DEFAULT CURRENT_DATE, p_bank_account_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT 'bank_transfer'::text, p_reference text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_role text;
  v_caller uuid := auth.uid();
  v_ar_id uuid;
  v_bank_coa_id uuid;
  v_bank_acc public.bank_accounts%ROWTYPE;
  v_je_id uuid;
  v_je_number text;
  v_pv_id uuid;
  v_pv_number text;
  v_remaining_balance numeric(18,2);
BEGIN
  -- Strict Authentication & Authorization check (prevent caller spoofing)
  IF v_caller IS NULL THEN
    IF current_user = 'service_role' OR session_user = 'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) OR (COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''), '')) = 'service_role' THEN
      v_caller := p_actor;
    ELSE
      RAISE EXCEPTION 'Authentication required: no active session';
    END IF;
  END IF;

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required: valid actor identity missing';
  END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'manager') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot refund credit notes', COALESCE(v_role, 'none');
  END IF;

  IF p_refund_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be strictly positive (got %)', p_refund_amount;
  END IF;

  -- Deterministic row locking
  SELECT * INTO v_cn FROM public.credit_notes WHERE id = p_credit_note_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit Note % not found', p_credit_note_id;
  END IF;

  IF v_cn.status <> 'approved' THEN
    RAISE EXCEPTION 'Cannot refund unapproved Credit Note %', v_cn.credit_note_number;
  END IF;

  IF COALESCE(v_cn.customer_credit_balance, 0) < p_refund_amount THEN
    RAISE EXCEPTION 'Insufficient credit balance % on Credit Note % (Requested %)',
      v_cn.customer_credit_balance, v_cn.credit_note_number, p_refund_amount;
  END IF;

  -- Validate Chart of Accounts
  v_ar_id := public.validate_coa_account('1120', 'asset', 'debit');

  -- Validate Bank Account
  IF p_bank_account_id IS NOT NULL THEN
    SELECT * INTO v_bank_acc FROM public.bank_accounts WHERE id = p_bank_account_id;
    IF NOT FOUND OR v_bank_acc.is_active IS FALSE THEN
      RAISE EXCEPTION 'Specified bank account % is invalid or inactive', p_bank_account_id;
    END IF;
    v_bank_coa_id := v_bank_acc.coa_id;
  ELSE
    SELECT * INTO v_bank_acc FROM public.bank_accounts WHERE is_active = true ORDER BY id LIMIT 1;
    v_bank_coa_id := v_bank_acc.coa_id;
  END IF;

  IF v_bank_coa_id IS NULL THEN
    SELECT id INTO v_bank_coa_id FROM public.chart_of_accounts WHERE code = '1102' OR code LIKE '1-102%' LIMIT 1;
  END IF;

  IF v_bank_coa_id IS NULL THEN
    RAISE EXCEPTION 'Bank account chart of accounts mapping missing for refund';
  END IF;

  -- 1. Post Refund Journal: Dr A/R (clearing credit balance), Cr Bank
  v_je_number := public.next_journal_entry_number();
  INSERT INTO journal_entries (
    entry_number, entry_date, source_module, reference_id, reference_number,
    description, total_debit, total_credit, is_posted, posted_by, created_by
  ) VALUES (
    v_je_number, COALESCE(p_refund_date, CURRENT_DATE), 'customer_refund', v_cn.id, v_cn.credit_note_number,
    'Customer refund for Credit Note ' || v_cn.credit_note_number || ' - ' || COALESCE(p_reference, 'Bank Transfer'),
    p_refund_amount, p_refund_amount, true, v_caller, v_caller
  ) RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)
  VALUES (v_je_id, 1, v_ar_id, 'Customer refund clearing - ' || v_cn.credit_note_number, p_refund_amount, 0, v_cn.customer_id);

  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES (v_je_id, 2, v_bank_coa_id, 'Bank payout refund - ' || v_cn.credit_note_number, 0, p_refund_amount);

  -- 2. Create actual payment voucher record in payment_vouchers table
  v_pv_number := 'PV-REF-' || to_char(CURRENT_DATE, 'YYMM') || '-' || lpad(floor(random() * 9000 + 1000)::text, 4, '0');
  INSERT INTO public.payment_vouchers (
    voucher_number, voucher_date, payment_type, payment_method, bank_account_id,
    reference_number, amount, description, journal_entry_id, status, is_posted, created_by
  ) VALUES (
    v_pv_number, COALESCE(p_refund_date, CURRENT_DATE), 'customer_refund', p_payment_method,
    v_bank_acc.id, v_cn.credit_note_number, p_refund_amount,
    'Customer refund for Credit Note ' || v_cn.credit_note_number,
    v_je_id, 'approved', true, v_caller
  ) RETURNING id INTO v_pv_id;

  v_remaining_balance := v_cn.customer_credit_balance - p_refund_amount;

  -- 3. Update Credit Note
  UPDATE public.credit_notes
     SET customer_credit_balance = v_remaining_balance,
         refund_amount = COALESCE(refund_amount, 0) + p_refund_amount,
         refund_date = COALESCE(p_refund_date, CURRENT_DATE),
         refund_payment_voucher_id = v_pv_id,
         settlement_status = CASE 
           WHEN v_remaining_balance <= 0.01 THEN 'refunded'
           ELSE 'partially_allocated'
         END,
         updated_at = now()
   WHERE id = v_cn.id;

  RETURN jsonb_build_object(
    'success', true,
    'credit_note_id', v_cn.id,
    'credit_note_number', v_cn.credit_note_number,
    'refund_amount', p_refund_amount,
    'remaining_credit_balance', v_remaining_balance,
    'journal_entry_number', v_je_number,
    'payment_voucher_number', v_pv_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_purchase_invoice_inward(p_purchase_invoice_id uuid, p_purchase_invoice_item_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_status text;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  IF p_reason IS NULL OR length(trim(p_reason))=0 THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;
  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved Purchase Invoices can be rejected at inward'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id AND purchase_invoice_id=p_purchase_invoice_id AND item_type='inventory') THEN
    RAISE EXCEPTION 'Purchase Invoice item does not belong to this invoice';
  END IF;
  INSERT INTO public.purchase_invoice_inward_rejections(purchase_invoice_id,purchase_invoice_item_id,reason,rejected_by) VALUES (p_purchase_invoice_id,p_purchase_invoice_item_id,trim(p_reason),auth.uid());
  UPDATE public.purchase_invoices SET receiving_approval_status='rejected', receiving_rejection_reason=trim(p_reason), updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','rejected');
END; $function$

CREATE OR REPLACE FUNCTION public.release_so_product_reservations_v2(p_so_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.so_product_reservations%ROWTYPE;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse','sales'])
     AND current_setting('app.canonical_reservation_engine',true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'Permission denied for reservation release';
  END IF;
  FOR r IN SELECT * FROM public.so_product_reservations WHERE sales_order_id=p_so_id AND status='active' ORDER BY id FOR UPDATE LOOP
    UPDATE public.so_product_reservations SET reserved_quantity=0,status='released',closed_at=now(),updated_at=now(),close_reason=p_reason WHERE id=r.id;
    INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,reason,actor_id)
    VALUES(r.id,r.sales_order_id,r.sales_order_item_id,'released',-r.reserved_quantity,0,p_reason,auth.uid());
  END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.relink_historical_bank_allocation(p_allocation_id uuid, p_replacement_journal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_alloc public.bank_statement_allocations%rowtype;
  v_old public.journal_entries%rowtype;
  v_new public.journal_entries%rowtype;
  v_before_amount numeric;
BEGIN
  IF current_user NOT IN ('postgres', 'supabase_admin')
     AND auth.role() <> 'service_role'
     AND NOT EXISTS (
       SELECT 1 FROM public.user_profiles
        WHERE id = auth.uid() AND is_active = true AND role = 'admin'
     ) THEN
    RAISE EXCEPTION 'Historical allocation relink requires admin or service_role';
  END IF;

  SELECT * INTO v_alloc
    FROM public.bank_statement_allocations
   WHERE id = p_allocation_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation not found'; END IF;

  SELECT * INTO v_old FROM public.journal_entries WHERE id = v_alloc.journal_entry_id FOR UPDATE;
  SELECT * INTO v_new FROM public.journal_entries WHERE id = p_replacement_journal_id FOR UPDATE;
  IF v_old.id IS NULL OR NOT v_old.is_reversed THEN
    RAISE EXCEPTION 'Source journal must be reversed';
  END IF;
  IF v_new.id IS NULL OR NOT v_new.is_posted OR v_new.is_reversed THEN
    RAISE EXCEPTION 'Replacement journal must be posted and not reversed';
  END IF;
  IF v_old.reference_id IS DISTINCT FROM v_new.reference_id
     AND NOT EXISTS (
       SELECT 1 FROM public.fund_transfers ft_old
       JOIN public.fund_transfers ft_new ON ft_new.id = ft_old.id
       WHERE ft_old.journal_entry_id = v_old.id AND ft_new.journal_entry_id = v_new.id
     ) THEN
    RAISE EXCEPTION 'Journals do not belong to the same underlying transaction';
  END IF;
  IF v_alloc.journal_entry_id = v_new.id THEN
    RETURN jsonb_build_object('idempotent', true, 'allocation_id', v_alloc.id,
      'journal_entry_id', v_new.id, 'allocation_amount', v_alloc.allocation_amount);
  END IF;

  v_before_amount := v_alloc.allocation_amount;
  PERFORM set_config('app.historical_allocation_relink', 'on', true);
  UPDATE public.bank_statement_allocations
     SET journal_entry_id = v_new.id
   WHERE id = v_alloc.id;

  IF (SELECT allocation_amount FROM public.bank_statement_allocations WHERE id = v_alloc.id) <> v_before_amount THEN
    RAISE EXCEPTION 'Allocation amount changed';
  END IF;

  RETURN jsonb_build_object('idempotent', false, 'allocation_id', v_alloc.id,
    'old_journal_entry_id', v_old.id, 'new_journal_entry_id', v_new.id,
    'allocation_amount', v_before_amount);
END;
$function$

CREATE OR REPLACE FUNCTION public.reopen_bpjs_monthly_register(p_register_id uuid, p_reason text DEFAULT 'Revision'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_reg public.bpjs_monthly_registers%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  SELECT * INTO v_reg FROM public.bpjs_monthly_registers WHERE id = p_register_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BPJS register % not found', p_register_id; END IF;

  IF v_reg.status IN ('posted', 'reconciled') THEN
    RAISE EXCEPTION 'Cannot reopen % register: register is already % (requires formal reversal first)',
      to_char(make_date(v_reg.period_year, v_reg.period_month, 1), 'Mon YYYY'), v_reg.status;
  END IF;

  IF v_reg.status = 'draft' THEN
    RETURN jsonb_build_object('register_id', v_reg.id, 'status', 'draft', 'message', 'Already draft');
  END IF;

  UPDATE public.bpjs_monthly_registers
     SET status = 'draft',
         approved_at = NULL,
         approved_by = NULL,
         notes = COALESCE(notes || E'\n', '') || 'Reopened to draft on ' || now()::text || ': ' || COALESCE(p_reason, 'Revision'),
         updated_at = now()
   WHERE id = v_reg.id;

  RETURN jsonb_build_object('register_id', v_reg.id, 'status', 'draft');
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_all_posted_fund_transfers()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  t record;
  eligibility text;
  result jsonb;
  scanned integer := 0;
  repaired integer := 0;
  skipped integer := 0;
  skipped_details jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  FOR t IN SELECT id, transfer_number FROM public.fund_transfers WHERE status='posted' ORDER BY transfer_date, transfer_number LOOP
    scanned := scanned + 1;
    eligibility := public.audit_fund_transfer_repair_eligibility(t.id);
    IF eligibility IS NOT NULL THEN
      skipped := skipped + 1;
      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(
        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number, 'reason', eligibility));
      CONTINUE;
    END IF;
    SELECT public.repair_posted_fund_transfer_from_source(t.id) INTO result;
    IF COALESCE((result->>'repaired')::boolean, false) THEN
      repaired := repaired + 1;
      IF NOT EXISTS (
        SELECT 1 FROM public.audit_logs a
        WHERE a.table_name='fund_transfers' AND a.record_id=t.id
          AND a.new_values->>'validation_rerun'='true'
      ) THEN
        INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)
        VALUES ('fund_transfers', 'update', t.id,
          jsonb_build_object('event','batch_repair','transfer_number',t.transfer_number),
          jsonb_build_object('event','batch_repair','repair_result',result,'validation_rerun',true),
          COALESCE(ARRAY(SELECT jsonb_array_elements_text(result->'repaired_fields')), ARRAY[]::text[]));
      END IF;
    ELSE
      skipped := skipped + 1;
      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(
        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number,
        'reason', COALESCE(result->>'reason', 'Repair did not pass validation')));
    END IF;
  END LOOP;
  RETURN jsonb_build_object('total_scanned', scanned, 'automatically_repaired', repaired,
    'skipped', skipped, 'skipped_details', skipped_details);
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_historical_usd_idr_transfer_fx(p_cutoff date DEFAULT '2026-08-01'::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record; l record; v_reversal uuid; v_corrected uuid; v_entry text; v_line int; v_run uuid; v_repaired int:=0; v_skipped int:=0; v_exception int:=0; BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_historical_repair_relink','on',true);
  INSERT INTO public.finance_historical_repair_runs(notes) VALUES ('Controlled historical USD→IDR fund-transfer FX correction before cutoff '||p_cutoff::text) RETURNING id INTO v_run;
  FOR r IN
    SELECT ft.id, ft.transfer_number, ft.transfer_date, ft.from_amount, ft.to_amount, ft.exchange_rate, ft.journal_entry_id,
           je.entry_number, je.total_debit, je.total_credit,
           fba.coa_id from_coa, fba.currency from_currency, tba.coa_id to_coa, tba.currency to_currency,
           fs.id from_stmt, ts.id to_stmt, fs.debit_amount from_debit, fs.credit_amount from_credit, fs.currency from_stmt_currency,
           ts.debit_amount to_debit, ts.credit_amount to_credit, ts.currency to_stmt_currency
    FROM public.fund_transfers ft
    JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id
    JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id
    JOIN public.journal_entries je ON je.id=ft.journal_entry_id
    JOIN public.bank_statement_lines fs ON fs.id=ft.from_bank_statement_line_id
    JOIN public.bank_statement_lines ts ON ts.id=ft.to_bank_statement_line_id
    WHERE ft.status='posted' AND ft.transfer_date < p_cutoff AND fba.currency='USD' AND tba.currency='IDR'
      AND fs.currency='USD' AND ts.currency='IDR'
      AND abs(fs.debit_amount-ft.from_amount)<0.01 AND abs(fs.credit_amount)<0.01
      AND abs(ts.credit_amount-ft.to_amount)<0.01 AND abs(ts.debit_amount)<0.01
      AND NOT COALESCE(je.is_reversed,false)
    ORDER BY ft.transfer_date, ft.transfer_number
    FOR UPDATE OF ft,je,fs,ts
  LOOP
    IF abs(r.total_debit-r.to_amount)<0.01 AND abs(r.total_credit-r.to_amount)<0.01 THEN v_skipped:=v_skipped+1; CONTINUE; END IF;
    IF NOT (abs(r.total_debit-r.from_amount)<0.01 AND abs(r.total_credit-r.from_amount)<0.01) THEN
      v_exception:=v_exception+1;
      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)
      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_amounts'],'Journal amount does not match either the USD source amount or evidenced IDR destination amount','Accountant review of the original journal and bank evidence');
      CONTINUE;
    END IF;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-REV-'||r.transfer_number,'Reversal of legacy USD-source functional posting '||r.entry_number,r.total_credit,r.total_debit,true,now(),'IDR','IDR',r.exchange_rate,true)
    RETURNING id INTO v_reversal;
    v_line:=1;
    FOR l IN SELECT jl.* FROM public.journal_entry_lines jl WHERE jl.journal_entry_id=r.journal_entry_id ORDER BY jl.line_number LOOP
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
      VALUES(v_reversal,v_line,l.account_id,l.credit,l.debit,'Historical FX reversal: '||COALESCE(l.description,''),l.supplier_id,l.transaction_currency,l.transaction_credit,l.transaction_debit,l.functional_currency,l.exchange_rate);
      v_line:=v_line+1;
    END LOOP;
    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal WHERE id=r.journal_entry_id;
    v_entry:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-FX-'||r.transfer_number,'Corrected USD→IDR fund transfer '||r.transfer_number,r.to_amount,r.to_amount,true,now(),'IDR','IDR',r.exchange_rate,true)
    RETURNING id INTO v_corrected;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_corrected,1,r.to_coa,r.to_amount,0,'Corrected transfer into IDR bank','IDR',r.to_amount,0,'IDR',1);
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
    VALUES(v_corrected,2,r.from_coa,0,r.to_amount,'Corrected transfer out of USD bank','USD',0,r.from_amount,'IDR',r.exchange_rate);
    UPDATE public.fund_transfers SET journal_entry_id=v_corrected WHERE id=r.id;
    UPDATE public.bank_statement_lines SET matched_entry_id=v_corrected, reconciliation_status='matched' WHERE id IN(r.from_stmt,r.to_stmt);
    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)
    VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry','bank matched_entry_id'],jsonb_build_object('journal_entry_id',r.journal_entry_id,'entry_number',r.entry_number,'total',r.total_debit),jsonb_build_object('reversal_journal_id',v_reversal,'replacement_journal_id',v_corrected,'replacement_entry_number',v_entry,'functional_idr',r.to_amount,'transaction_usd',r.from_amount,'rate',r.exchange_rate),'Both bank statement sides prove the USD source amount, IDR destination amount, and historical FX rate');
    v_repaired:=v_repaired+1;
  END LOOP;
  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_repaired+v_skipped+v_exception,records_repaired=v_repaired,records_manual_review=v_exception,records_skipped=v_skipped WHERE id=v_run;
  RETURN jsonb_build_object('run_id',v_run,'repaired',v_repaired,'skipped_already_correct',v_skipped,'manual_review',v_exception,'cutoff',p_cutoff);
END $function$

CREATE OR REPLACE FUNCTION public.repair_posted_fund_transfer_from_source(p_fund_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_transfer public.fund_transfers%ROWTYPE;
  v_journal public.journal_entries%ROWTYPE;
  v_from_coa uuid;
  v_to_coa uuid;
  v_from_currency text;
  v_to_currency text;
  v_journal_currency text;
  v_expected_rate numeric;
  v_before_lines jsonb;
  v_after_lines jsonb;
  v_repaired_fields text[] := ARRAY[]::text[];
  v_possible_bank_transactions integer;
  v_validation_failures integer;
  v_live_validation_failures integer;
  v_validation_passed boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  PERFORM set_config('app.finance_historical_repair', 'on', true);
  PERFORM set_config('app.finance_metadata_repair', 'on', true);

  SELECT * INTO v_transfer
  FROM public.fund_transfers
  WHERE id = p_fund_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fund Transfer not found';
  END IF;
  IF v_transfer.status <> 'posted' OR v_transfer.journal_entry_id IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer is not posted with an existing journal');
  END IF;

  SELECT * INTO v_journal
  FROM public.journal_entries
  WHERE id = v_transfer.journal_entry_id
  FOR UPDATE;

  IF NOT FOUND OR NOT COALESCE(v_journal.is_posted, false) OR COALESCE(v_journal.is_reversed, false) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer journal is not an active posted journal');
  END IF;
  IF v_journal.source_module NOT IN ('fund_transfer', 'fund_transfers')
     OR v_journal.reference_id IS DISTINCT FROM v_transfer.id THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer and journal do not prove an authoritative relationship');
  END IF;

  IF v_transfer.from_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO v_from_coa, v_from_currency
    FROM public.bank_accounts WHERE id = v_transfer.from_bank_account_id AND is_active;
  ELSIF v_transfer.from_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;
  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN
    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;
  END IF;

  IF v_transfer.to_account_type = 'bank' THEN
    SELECT coa_id, upper(currency) INTO v_to_coa, v_to_currency
    FROM public.bank_accounts WHERE id = v_transfer.to_bank_account_id AND is_active;
  ELSIF v_transfer.to_account_type = 'petty_cash' THEN
    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;
  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN
    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;
  END IF;

  IF v_from_coa IS NULL OR v_to_coa IS NULL OR v_from_currency IS NULL OR v_to_currency IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source does not contain complete active account and currency information');
  END IF;
  IF v_transfer.from_amount IS NULL OR v_transfer.to_amount IS NULL OR v_transfer.exchange_rate IS NULL THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source is missing an amount or exchange rate');
  END IF;

  v_expected_rate := CASE
    WHEN v_from_currency = v_to_currency THEN 1
    WHEN v_from_currency = 'IDR' AND v_transfer.to_amount > 0 THEN v_transfer.from_amount / v_transfer.to_amount
    WHEN v_to_currency = 'IDR' AND v_transfer.from_amount > 0 THEN v_transfer.to_amount / v_transfer.from_amount
  END;
  IF v_expected_rate IS NULL OR abs(v_transfer.exchange_rate - v_expected_rate) > 0.000001 THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer exchange rate is not internally consistent with its stored amounts');
  END IF;
  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id) <> 2
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 1 AND COALESCE(debit, 0) > 0 AND COALESCE(credit, 0) = 0)
     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 2 AND COALESCE(credit, 0) > 0 AND COALESCE(debit, 0) = 0) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing journal lines are not a safe two-line transfer journal');
  END IF;
  IF abs(COALESCE(v_journal.total_debit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01
     OR abs(COALESCE(v_journal.total_credit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01
     OR EXISTS (
       SELECT 1 FROM public.journal_entry_lines l
       WHERE l.journal_entry_id = v_journal.id
         AND ((l.line_number = 1 AND abs(COALESCE(l.debit, 0) - v_transfer.from_amount) > 0.01)
           OR (l.line_number = 2 AND abs(COALESCE(l.credit, 0) - v_transfer.from_amount) > 0.01))
     ) THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing posted journal amounts do not match the Fund Transfer source');
  END IF;

  -- No bank transaction is inferred or relinked. If the source document does
  -- not name a line, explicitly refuse to guess, especially when candidates
  -- are ambiguous. The accountant can resolve the missing source information.
  IF v_transfer.from_bank_statement_line_id IS NULL AND v_transfer.from_account_type = 'bank' THEN
    SELECT count(*) INTO v_possible_bank_transactions
    FROM public.bank_statement_lines b
    WHERE b.bank_account_id = v_transfer.from_bank_account_id
      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8
      AND (COALESCE(b.debit_amount, 0) = v_transfer.from_amount OR COALESCE(b.credit_amount, 0) = v_transfer.from_amount);
    IF v_possible_bank_transactions > 1 THEN
      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible From Bank transactions exist; no bank link was guessed');
    END IF;
  END IF;
  IF v_transfer.to_bank_statement_line_id IS NULL AND v_transfer.to_account_type = 'bank' THEN
    SELECT count(*) INTO v_possible_bank_transactions
    FROM public.bank_statement_lines b
    WHERE b.bank_account_id = v_transfer.to_bank_account_id
      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8
      AND (COALESCE(b.debit_amount, 0) = v_transfer.to_amount OR COALESCE(b.credit_amount, 0) = v_transfer.to_amount);
    IF v_possible_bank_transactions > 1 THEN
      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible To Bank transactions exist; no bank link was guessed');
    END IF;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)
  INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;

  v_journal_currency := CASE WHEN v_from_currency = v_to_currency THEN v_from_currency ELSE 'IDR' END;
  UPDATE public.journal_entries
  SET source_module = 'fund_transfers', reference_id = v_transfer.id,
      reference_number = v_transfer.transfer_number, transaction_currency = v_journal_currency,
      functional_currency = 'IDR', exchange_rate = v_transfer.exchange_rate,
      amounts_are_functional = true
  WHERE id = v_journal.id
    AND (source_module IS DISTINCT FROM 'fund_transfers' OR reference_id IS DISTINCT FROM v_transfer.id
      OR reference_number IS DISTINCT FROM v_transfer.transfer_number OR transaction_currency IS DISTINCT FROM v_journal_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM v_transfer.exchange_rate
      OR amounts_are_functional IS DISTINCT FROM true);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_metadata'); END IF;

  UPDATE public.journal_entry_lines
  SET account_id = v_to_coa, transaction_currency = v_to_currency,
      functional_currency = 'IDR', exchange_rate = CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END
  WHERE journal_entry_id = v_journal.id AND line_number = 1
    AND (account_id IS DISTINCT FROM v_to_coa OR transaction_currency IS DISTINCT FROM v_to_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_debit_line_metadata'); END IF;

  UPDATE public.journal_entry_lines
  SET account_id = v_from_coa, transaction_currency = v_from_currency,
      functional_currency = 'IDR', exchange_rate = CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END
  WHERE journal_entry_id = v_journal.id AND line_number = 2
    AND (account_id IS DISTINCT FROM v_from_coa OR transaction_currency IS DISTINCT FROM v_from_currency
      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);
  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_credit_line_metadata'); END IF;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)
  INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;
  IF v_before_lines IS DISTINCT FROM v_after_lines THEN
    RAISE EXCEPTION 'Fund Transfer repair cancelled because a debit or credit value changed';
  END IF;

  -- The existing validation projections are live views. Read them after the
  -- metadata updates; resolve the false-positive only when they are clean.
  SELECT count(*) INTO v_validation_failures
  FROM public.finance_historical_repair_verification_failures f
  WHERE f.document_type = 'fund_transfer' AND f.database_id = v_transfer.id;
  SELECT count(*) INTO v_live_validation_failures
  FROM public.finance_live_verification_failures f
  WHERE f.document_type = 'fund_transfer' AND f.document_id = v_transfer.id;
  v_validation_failures := v_validation_failures + v_live_validation_failures;
  v_validation_passed := v_validation_failures = 0;
  IF v_validation_passed THEN
    UPDATE public.finance_historical_repair_exceptions
    SET status = 'resolved'
    WHERE status = 'manual_review' AND document_type = 'fund_transfer' AND document_id = v_transfer.id;
  END IF;

  -- A no-op retry produces no second audit mutation. The first successful
  -- call records the exact derived fields changed and immutable line values.
  IF COALESCE(array_length(v_repaired_fields, 1), 0) > 0 THEN
    INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)
    VALUES ('fund_transfers', 'update', v_transfer.id,
      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_before_lines),
      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_after_lines,
        'validation_rerun', true, 'validation_passed', v_validation_passed),
      v_repaired_fields);
  END IF;

  IF NOT v_validation_passed THEN
    RETURN jsonb_build_object('repaired', false, 'reason', 'Derived data still fails the existing Finance validation', 'validation_failures', v_validation_failures);
  END IF;

  RETURN jsonb_build_object('repaired', true, 'repaired_fields', v_repaired_fields,
    'validation_rerun', true, 'journal_entry_id', v_journal.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_trans_exis_jaya_supplier_advance(p_dry_run boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor               uuid;
  v_supplier_id         uuid := '701bbcb1-3fe8-421f-acec-9d216193346d'::uuid; -- PT TRANS EXIS JAYA
  v_bank_line_id        uuid := '26fb3731-977e-41d1-a21b-661a29bd7c82'::uuid; -- 15 Oct Outgoing
  v_refund_line_id      uuid := 'b0757040-9080-455f-9ff8-6aa00e0331f7'::uuid; -- 30 Oct Incoming
  v_rv_id               uuid := '80b23e4e-ad5b-4d6d-bb60-2e8d25575e76'::uuid; -- RV2610-0018
  v_old_rv_je_id        uuid := 'e998a539-9138-43f2-92e2-4311ae1c4b2d'::uuid; -- JE2610-0239
  v_expense_id          uuid := '25974efd-37fe-400c-b635-514387acbb45'::uuid; -- EXP/26/317
  v_exp_je_id           uuid := '1a2c4c29-f93a-464c-9a9e-04b101f5b12e'::uuid; -- JE2610-0196
  v_bank_account_id     uuid := 'bfe79829-07d1-48ed-8965-ff9d367d758e'::uuid; -- BCA IDR

  -- Accounts
  v_bank_coa            uuid;
  v_bank_coa_code       text;
  v_coa_1170            uuid;
  v_coa_2110            uuid;
  v_coa_6910            uuid;

  -- State variables
  v_bank_before         numeric;
  v_bank_after          numeric;

  -- Existing records check
  v_bsl_15              public.bank_statement_lines%ROWTYPE;
  v_bsl_30              public.bank_statement_lines%ROWTYPE;
  v_rv                  public.receipt_vouchers%ROWTYPE;
  v_old_je              public.journal_entries%ROWTYPE;
  v_exp                 public.finance_expenses%ROWTYPE;
  v_exp_je              public.journal_entries%ROWTYPE;
  v_period_15_id        uuid;
  v_period_31_id        uuid;
  v_period_15_open      boolean;
  v_period_31_open      boolean;

  -- Line counts and integrity checks
  v_exp_je_line_count   int;
  v_old_je_line_count   int;

  -- Allocations check
  v_bsl_15_alloc_sum    numeric;
  v_bsl_15_alloc_count  int;
  v_exp_alloc           public.bank_statement_allocations%ROWTYPE;

  -- Idempotency check: existing payment voucher & replacement
  v_existing_pv         public.payment_vouchers%ROWTYPE;
  v_draft_pv            public.payment_vouchers%ROWTYPE;
  v_is_already_repaired boolean := false;
  v_existing_rep_je     public.journal_entries%ROWTYPE;
  v_existing_rev_je     public.journal_entries%ROWTYPE;
  v_existing_pv_je      public.journal_entries%ROWTYPE;
  v_existing_pv_alloc   public.bank_statement_allocations%ROWTYPE;

  -- Generated IDs
  v_pv_id               uuid;
  v_pv_number           text;
  v_pv_je_id            uuid;
  v_pv_je_number        text;
  v_rev_je_id           uuid;
  v_rev_je_number       text;
  v_rep_je_id           uuid;
  v_rep_je_number       text;
  v_pv_alloc_id         uuid;

  -- Dynamic validation errors
  v_errors              text[] := ARRAY[]::text[];
BEGIN
  -- 1. Concurrency-safe idempotency: acquire transaction-level advisory lock immediately
  -- Any concurrent call will wait on this lock and observe the committed results of the earlier call
  PERFORM pg_advisory_xact_lock(hashtext('repair_trans_exis_jaya_supplier_advance'));

  -- 2. Security Authorization Check
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  ELSIF auth.role() = 'anon' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(auth.uid(), p_actor, '1075a773-bb55-4296-bc71-af2eab9a0780'::uuid);

  -- 3. Validate Chart of Accounts (COA 1170, 111101, 2110, 6910)
  SELECT id INTO v_coa_1170 FROM public.chart_of_accounts WHERE code = '1170' AND is_active = true AND is_header = false LIMIT 1;
  IF v_coa_1170 IS NULL THEN v_errors := array_append(v_errors, 'COA 1170 (Supplier Advances & Deposits) does not exist, is inactive, or is marked as header'); END IF;

  SELECT id INTO v_coa_6910 FROM public.chart_of_accounts WHERE code = '6910' AND is_active = true AND is_header = false LIMIT 1;
  IF v_coa_6910 IS NULL THEN v_errors := array_append(v_errors, 'COA 6910 (Settlement Discount & Rounding Difference) does not exist, is inactive, or is marked as header'); END IF;

  SELECT id INTO v_coa_2110 FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;
  IF v_coa_2110 IS NULL THEN v_errors := array_append(v_errors, 'COA 2110 (Accounts Payable) does not exist, is inactive, or is marked as header'); END IF;

  SELECT ba.coa_id, coa.code, ba.current_balance 
  INTO v_bank_coa, v_bank_coa_code, v_bank_before
  FROM public.bank_accounts ba
  JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id
  WHERE ba.id = v_bank_account_id AND ba.is_active = true AND coa.is_active = true AND coa.is_header = false;

  IF v_bank_coa IS NULL THEN
    v_errors := array_append(v_errors, 'Bank account BCA IDR (' || v_bank_account_id::text || ') is inactive or has invalid COA mapping');
  ELSIF v_bank_coa_code <> '111101' THEN
    v_errors := array_append(v_errors, 'Bank account BCA IDR is mapped to COA ' || v_bank_coa_code || ', expected 111101');
  END IF;

  -- 3. Validate Bank Statement Line 15 Oct 2026 (26fb3731-977e-41d1-a21b-661a29bd7c82)
  SELECT * INTO v_bsl_15 FROM public.bank_statement_lines WHERE id = v_bank_line_id;
  IF v_bsl_15.id IS NULL THEN
    v_errors := array_append(v_errors, 'Bank statement line 15 Oct 2026 (' || v_bank_line_id::text || ') not found');
  ELSE
    IF v_bsl_15.debit_amount <> 17671854.00 THEN
      v_errors := array_append(v_errors, 'Bank statement line 15 Oct debit amount is ' || v_bsl_15.debit_amount::text || ', expected 17671854.00');
    END IF;
    IF upper(COALESCE(v_bsl_15.currency, 'IDR')) <> 'IDR' THEN
      v_errors := array_append(v_errors, 'Bank statement line 15 Oct currency is ' || v_bsl_15.currency || ', expected IDR');
    END IF;

    SELECT count(*), COALESCE(sum(allocation_amount), 0)
    INTO v_bsl_15_alloc_count, v_bsl_15_alloc_sum
    FROM public.bank_statement_allocations
    WHERE bank_statement_line_id = v_bank_line_id;

    SELECT * INTO v_exp_alloc
    FROM public.bank_statement_allocations
    WHERE bank_statement_line_id = v_bank_line_id AND document_type = 'expense' AND document_id = v_expense_id;

    IF v_exp_alloc.id IS NULL THEN
      v_errors := array_append(v_errors, 'Bank statement line 15 Oct lacks expected expense allocation for ' || v_expense_id::text);
    ELSIF v_exp_alloc.allocation_amount <> 16002854.00 THEN
      v_errors := array_append(v_errors, 'Expense allocation amount is ' || v_exp_alloc.allocation_amount::text || ', expected 16002854.00');
    END IF;
  END IF;

  -- 5. Strengthened Validation: Original Expense Journal JE2610-0196 (Header + Lines)
  SELECT * INTO v_exp_je FROM public.journal_entries WHERE id = v_exp_je_id;
  IF v_exp_je.id IS NULL THEN
    v_errors := array_append(v_errors, 'Expense journal JE2610-0196 (' || v_exp_je_id::text || ') not found');
  ELSE
    IF NOT v_exp_je.is_posted THEN v_errors := array_append(v_errors, 'Expense journal JE2610-0196 is not posted'); END IF;
    IF COALESCE(v_exp_je.is_reversed, false) THEN v_errors := array_append(v_errors, 'Expense journal JE2610-0196 is unexpectedly marked as reversed'); END IF;
    IF v_exp_je.total_debit <> 16002854.00 OR v_exp_je.total_credit <> 16002854.00 THEN
      v_errors := array_append(v_errors, 'Expense journal JE2610-0196 total is ' || v_exp_je.total_debit::text || ', expected 16002854.00');
    END IF;

    -- Validate exact lines of JE2610-0196
    SELECT count(*) INTO v_exp_je_line_count FROM public.journal_entry_lines WHERE journal_entry_id = v_exp_je_id;
    IF v_exp_je_line_count <> 2 THEN
      v_errors := array_append(v_errors, 'Expense journal JE2610-0196 line count is ' || v_exp_je_line_count || ', expected 2');
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines 
        WHERE journal_entry_id = v_exp_je_id AND account_id = v_coa_2110 AND debit = 16002854.00 AND credit = 0 AND supplier_id = v_supplier_id
      ) THEN
        v_errors := array_append(v_errors, 'Expense journal JE2610-0196 missing expected Dr 2110 Rp 16,002,854.00 line');
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines 
        WHERE journal_entry_id = v_exp_je_id AND account_id = v_bank_coa AND debit = 0 AND credit = 16002854.00
      ) THEN
        v_errors := array_append(v_errors, 'Expense journal JE2610-0196 missing expected Cr 111101 Rp 16,002,854.00 line');
      END IF;
    END IF;
  END IF;

  -- 6. Validate Bank Statement Line 30 Oct 2026 (b0757040-9080-455f-9ff8-6aa00e0331f7)
  SELECT * INTO v_bsl_30 FROM public.bank_statement_lines WHERE id = v_refund_line_id;
  IF v_bsl_30.id IS NULL THEN
    v_errors := array_append(v_errors, 'Refund bank statement line 30 Oct (' || v_refund_line_id::text || ') not found');
  ELSE
    IF v_bsl_30.bank_account_id <> v_bank_account_id THEN
      v_errors := array_append(v_errors, 'Refund bank statement line bank_account_id is ' || v_bsl_30.bank_account_id::text || ', expected ' || v_bank_account_id::text);
    END IF;
    IF v_bsl_30.credit_amount <> 1666000.00 THEN
      v_errors := array_append(v_errors, 'Refund bank statement credit amount is ' || v_bsl_30.credit_amount::text || ', expected 1666000.00');
    END IF;
    IF upper(COALESCE(v_bsl_30.currency, 'IDR')) <> 'IDR' THEN
      v_errors := array_append(v_errors, 'Refund bank statement line currency is ' || v_bsl_30.currency || ', expected IDR');
    END IF;
  END IF;

  -- 7. Validate Receipt Voucher RV2610-0018 (80b23e4e-ad5b-4d6d-bb60-2e8d25575e76)
  SELECT * INTO v_rv FROM public.receipt_vouchers WHERE id = v_rv_id;
  IF v_rv.id IS NULL THEN
    v_errors := array_append(v_errors, 'Receipt voucher RV2610-0018 (' || v_rv_id::text || ') not found');
  ELSE
    IF v_rv.supplier_id IS DISTINCT FROM v_supplier_id THEN
      v_errors := array_append(v_errors, 'Receipt voucher RV2610-0018 supplier_id is ' || COALESCE(v_rv.supplier_id::text, 'null') || ', expected ' || v_supplier_id::text);
    END IF;
    IF v_rv.amount <> 1666000.00 THEN
      v_errors := array_append(v_errors, 'Receipt voucher RV2610-0018 amount is ' || v_rv.amount::text || ', expected 1666000.00');
    END IF;
    IF v_rv.settlement_discount <> 3000.00 THEN
      v_errors := array_append(v_errors, 'Receipt voucher RV2610-0018 settlement_discount is ' || v_rv.settlement_discount::text || ', expected 3000.00');
    END IF;
    IF NOT v_rv.is_posted THEN
      v_errors := array_append(v_errors, 'Receipt voucher RV2610-0018 is not posted');
    END IF;
  END IF;

  -- 8. Strengthened Validation: Original Receipt Journal JE2610-0239 (Header + Lines)
  SELECT * INTO v_old_je FROM public.journal_entries WHERE id = v_old_rv_je_id;
  IF v_old_je.id IS NULL THEN
    v_errors := array_append(v_errors, 'Original receipt journal JE2610-0239 (' || v_old_rv_je_id::text || ') not found');
  ELSE
    IF v_old_je.total_debit <> 1669000.00 OR v_old_je.total_credit <> 1669000.00 THEN
      v_errors := array_append(v_errors, 'Original receipt journal JE2610-0239 total is ' || v_old_je.total_debit::text || ', expected 1669000.00');
    END IF;

    SELECT count(*) INTO v_old_je_line_count FROM public.journal_entry_lines WHERE journal_entry_id = v_old_rv_je_id;
    IF v_old_je_line_count <> 3 THEN
      v_errors := array_append(v_errors, 'Receipt journal JE2610-0239 line count is ' || v_old_je_line_count || ', expected 3');
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines
        WHERE journal_entry_id = v_old_rv_je_id AND account_id = v_bank_coa AND debit = 1666000.00 AND credit = 0
      ) THEN
        v_errors := array_append(v_errors, 'Receipt journal JE2610-0239 missing expected Dr 111101 Rp 1,666,000.00 line');
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines
        WHERE journal_entry_id = v_old_rv_je_id AND account_id = v_coa_6910 AND debit = 3000.00 AND credit = 0
      ) THEN
        v_errors := array_append(v_errors, 'Receipt journal JE2610-0239 missing expected Dr 6910 Rp 3,000.00 line');
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines
        WHERE journal_entry_id = v_old_rv_je_id AND account_id = v_coa_2110 AND debit = 0 AND credit = 1669000.00 AND supplier_id = v_supplier_id
      ) THEN
        v_errors := array_append(v_errors, 'Receipt journal JE2610-0239 missing expected Cr 2110 Rp 1,669,000.00 line');
      END IF;
    END IF;
  END IF;

  -- 9. Validate Accounting Periods (open for 2026-10-15 and 2026-10-31)
  SELECT id INTO v_period_15_id FROM public.accounting_periods WHERE '2026-10-15'::date BETWEEN start_date AND end_date LIMIT 1;
  SELECT id INTO v_period_31_id FROM public.accounting_periods WHERE '2026-10-31'::date BETWEEN start_date AND end_date LIMIT 1;

  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'accounting_periods' AND column_name = 'status') THEN
    EXECUTE 'SELECT COALESCE(bool_or(status = ''open''), false) FROM public.accounting_periods WHERE ''2026-10-15''::date BETWEEN start_date AND end_date' INTO v_period_15_open;
    EXECUTE 'SELECT COALESCE(bool_or(status = ''open''), false) FROM public.accounting_periods WHERE ''2026-10-31''::date BETWEEN start_date AND end_date' INTO v_period_31_open;
  ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'accounting_periods' AND column_name = 'is_closed') THEN
    EXECUTE 'SELECT COALESCE(bool_or(is_closed = false), false) FROM public.accounting_periods WHERE ''2026-10-15''::date BETWEEN start_date AND end_date' INTO v_period_15_open;
    EXECUTE 'SELECT COALESCE(bool_or(is_closed = false), false) FROM public.accounting_periods WHERE ''2026-10-31''::date BETWEEN start_date AND end_date' INTO v_period_31_open;
  ELSE
    v_period_15_open := true;
    v_period_31_open := true;
  END IF;

  IF NOT v_period_15_open THEN
    v_errors := array_append(v_errors, 'Accounting period covering 2026-10-15 is closed or not found');
  END IF;
  IF NOT v_period_31_open THEN
    v_errors := array_append(v_errors, 'Accounting period covering 2026-10-31 is closed or not found');
  END IF;

  -- 10. Check Both Posted and Draft Matching Advance Vouchers
  SELECT * INTO v_existing_pv
  FROM public.payment_vouchers
  WHERE supplier_id = v_supplier_id
    AND amount = 1669000.00
    AND (payment_purpose = 'supplier_advance' OR payment_purpose = 'general')
    AND settlement_against = 'advance'
    AND reference_number = '1510/FTSCY/WS95051'
    AND is_posted = true
  ORDER BY created_at DESC LIMIT 1;

  SELECT * INTO v_draft_pv
  FROM public.payment_vouchers
  WHERE supplier_id = v_supplier_id
    AND amount = 1669000.00
    AND (payment_purpose = 'supplier_advance' OR payment_purpose = 'general')
    AND settlement_against = 'advance'
    AND reference_number = '1510/FTSCY/WS95051'
    AND is_posted = false
  ORDER BY created_at DESC LIMIT 1;

  -- 11. Concurrency-Safe Idempotency Check
  -- Re-query replacement journal, reversal journal, and statement allocation
  IF v_rv.id IS NOT NULL AND v_rv.journal_entry_id IS NOT NULL AND v_rv.journal_entry_id <> v_old_rv_je_id THEN
    SELECT * INTO v_existing_rep_je FROM public.journal_entries WHERE id = v_rv.journal_entry_id AND source_module = 'receipt' AND reference_id = v_rv_id;
  END IF;

  IF v_old_je.id IS NOT NULL AND COALESCE(v_old_je.is_reversed, false) = true AND v_old_je.reversed_by_id IS NOT NULL THEN
    SELECT * INTO v_existing_rev_je FROM public.journal_entries WHERE id = v_old_je.reversed_by_id;
  END IF;

  IF v_existing_pv.id IS NOT NULL THEN
    SELECT * INTO v_existing_pv_je FROM public.journal_entries WHERE id = v_existing_pv.journal_entry_id;
    SELECT * INTO v_existing_pv_alloc FROM public.bank_statement_allocations 
    WHERE bank_statement_line_id = v_bank_line_id AND document_type = 'payment' AND document_id = v_existing_pv.id;
  END IF;

  -- Verify all conditions for ALREADY_COMPLETED:
  -- 1. Advance PV exists, posted, with balanced journal
  -- 2. Statement line 15 Oct has allocation to advance PV and status is 'matched'
  -- 3. Original receipt journal JE2610-0239 is marked reversed by reversal journal
  -- 4. Replacement journal exists, posted, credits 1170 for 1,669,000
  -- 5. Receipt voucher RV2610-0018 is relinked to replacement journal with adjustment account 6910 and discount 3,000
  IF v_existing_pv.id IS NOT NULL 
     AND v_existing_pv.is_posted = true
     AND v_existing_pv_alloc.id IS NOT NULL
     AND v_bsl_15.reconciliation_status = 'matched'
     AND v_existing_rep_je.id IS NOT NULL 
     AND v_existing_rev_je.id IS NOT NULL 
     AND v_old_je.is_reversed = true 
     AND v_rv.journal_entry_id = v_existing_rep_je.id
     AND v_rv.adjustment_account_id = v_coa_6910
     AND v_rv.settlement_discount = 3000.00
  THEN
    v_is_already_repaired := true;
  END IF;

  -- If not already repaired, original journal JE2610-0239 MUST be in active unreversed state
  IF NOT v_is_already_repaired THEN
    IF NOT v_old_je.is_posted THEN v_errors := array_append(v_errors, 'Original receipt journal JE2610-0239 is not posted'); END IF;
    IF COALESCE(v_old_je.is_reversed, false) THEN v_errors := array_append(v_errors, 'Original receipt journal JE2610-0239 is already reversed but replacement is incomplete'); END IF;
  END IF;

  -- 12. If any validation errors exist, halt and return failure
  IF array_length(v_errors, 1) > 0 THEN
    RETURN jsonb_build_object(
      'dry_run', p_dry_run,
      'status', 'VALIDATION_FAILED',
      'summary', 'Dynamic pre-condition validation failed for PT TRANS EXIS JAYA repair',
      'error_count', array_length(v_errors, 1),
      'validation_errors', to_jsonb(v_errors),
      'validation_passed', false
    );
  END IF;

  -- 13. Genuine Idempotency Short-Circuit: If already repaired, return current state without touching records
  IF v_is_already_repaired THEN
    RETURN jsonb_build_object(
      'dry_run', p_dry_run,
      'status', 'ALREADY_COMPLETED',
      'already_repaired', true,
      'summary', 'PT TRANS EXIS JAYA supplier advance and refund repair is already fully executed and balanced',
      'payment_voucher', jsonb_build_object('id', v_existing_pv.id, 'number', v_existing_pv.voucher_number, 'journal_id', v_existing_pv.journal_entry_id),
      'reversal_journal', jsonb_build_object('id', v_existing_rev_je.id, 'number', v_existing_rev_je.entry_number),
      'replacement_journal', jsonb_build_object('id', v_existing_rep_je.id, 'number', v_existing_rep_je.entry_number),
      'receipt_voucher', jsonb_build_object('id', v_rv.id, 'number', v_rv.voucher_number, 'adjustment_account_id', v_rv.adjustment_account_id),
      'bank_balance_current', v_bank_before
    );
  END IF;

  -- 14. Dry-Run Planning Output (Dynamic validation passed, returns execution plan)
  IF p_dry_run THEN
    RETURN jsonb_build_object(
      'dry_run', true,
      'status', 'READY_FOR_AUTHORIZATION',
      'validation_passed', true,
      'summary', 'Dynamic pre-condition validation passed. Ready for authorized atomic execution.',
      'validated_records', jsonb_build_object(
        'supplier', jsonb_build_object('id', v_supplier_id, 'name', 'PT. TRANS EXIS JAYA'),
        'bank_statement_15oct', jsonb_build_object(
          'id', v_bank_line_id,
          'total_debit', v_bsl_15.debit_amount,
          'existing_expense_allocation', v_exp_alloc.allocation_amount,
          'unallocated_remainder', (v_bsl_15.debit_amount - v_exp_alloc.allocation_amount),
          'reconciliation_status', v_bsl_15.reconciliation_status
        ),
        'bank_statement_30oct', jsonb_build_object(
          'id', v_refund_line_id,
          'credit_amount', v_bsl_30.credit_amount,
          'reconciliation_status', v_bsl_30.reconciliation_status
        ),
        'expense_journal', jsonb_build_object('id', v_exp_je.id, 'entry_number', v_exp_je.entry_number, 'total', v_exp_je.total_debit),
        'erroneous_receipt_journal', jsonb_build_object(
          'id', v_old_je.id,
          'entry_number', v_old_je.entry_number,
          'total', v_old_je.total_debit,
          'erroneous_ap_credit', 1669000.00
        ),
        'receipt_voucher', jsonb_build_object(
          'id', v_rv.id,
          'voucher_number', v_rv.voucher_number,
          'refund_amount', v_rv.amount,
          'settlement_discount', v_rv.settlement_discount
        ),
        'draft_payment_voucher_found', (v_draft_pv.id IS NOT NULL),
        'coa_mapping', jsonb_build_object(
          '1170_supplier_advances', v_coa_1170,
          '111101_bank_bca_idr', v_bank_coa,
          '2110_accounts_payable', v_coa_2110,
          '6910_settlement_diff', v_coa_6910
        ),
        'accounting_periods', jsonb_build_object(
          'period_15oct_id', v_period_15_id,
          'period_15oct_open', v_period_15_open,
          'period_31oct_id', v_period_31_id,
          'period_31oct_open', v_period_31_open
        )
      ),
      'actions', jsonb_build_array(
        jsonb_build_object(
          'step', 1,
          'action', 'create_supplier_advance_payment_voucher',
          'supplier', 'PT. TRANS EXIS JAYA',
          'amount', 1669000.00,
          'voucher_date', '2026-10-15',
          'payment_purpose', 'general',
          'settlement_against', 'advance',
          'reference_number', '1510/FTSCY/WS95051',
          'proposed_journal', jsonb_build_object(
            'Dr 1170 Supplier Advances & Deposits', 1669000.00,
            'Cr 111101 Bank BCA - IDR', 1669000.00
          )
        ),
        jsonb_build_object(
          'step', 2,
          'action', 'allocate_to_outgoing_bank_statement',
          'bank_statement_line_id', v_bank_line_id,
          'total_statement_debit', 17671854.00,
          'allocation_1_expense', 16002854.00,
          'allocation_2_advance', 1669000.00,
          'resulting_unallocated', 0.00,
          'resulting_reconciliation_status', 'matched'
        ),
        jsonb_build_object(
          'step', 3,
          'action', 'reverse_erroneous_receipt_journal',
          'original_journal_id', v_old_rv_je_id,
          'original_journal_entry', 'JE2610-0239',
          'reversal_lines', jsonb_build_object(
            'Dr 2110 Accounts Payable (reverses erroneous AP credit)', 1669000.00,
            'Cr 111101 Bank BCA - IDR', 1666000.00,
            'Cr 6910 Settlement Discount', 3000.00
          )
        ),
        jsonb_build_object(
          'step', 4,
          'action', 'create_replacement_receipt_journal',
          'receipt_voucher', 'RV2610-0018',
          'replacement_lines', jsonb_build_object(
            'Dr 111101 Bank BCA - IDR', 1666000.00,
            'Dr 6910 Settlement Discount & Rounding Difference', 3000.00,
            'Cr 1170 Supplier Advances & Deposits (clears advance asset)', 1669000.00
          )
        ),
        jsonb_build_object(
          'step', 5,
          'action', 'update_receipt_voucher_and_refund_allocation',
          'adjustment_account_id', v_coa_6910,
          'adjustment_notes', 'Approved settlement difference of 3,000 against advance refund 1,669,000',
          'relink_statement_line', v_refund_line_id
        )
      ),
      'net_balance_impact', jsonb_build_object(
        '1170_supplier_advances', 'Rp 1,669,000 Dr (PV) - Rp 1,669,000 Cr (RV) = Rp 0 Net Balance',
        '2110_accounts_payable', 'Erroneous Rp 1,669,000 credit reversed by Dr Rp 1,669,000 -> Net 0 AP change',
        '6910_settlement_difference', 'Rp 3,000 Dr preserved',
        '111101_bank_bca_idr', 'Credits full Rp 17,671,854 actual bank debit instead of Rp 16,002,854'
      )
    );
  END IF;

  -- ==============================================================================
  -- EXECUTION MODE (Only runs when p_dry_run = false and authorized)
  -- Uses strict row-level locking in hierarchical order to ensure transactional safety
  -- ==============================================================================

  -- Row-level locking
  PERFORM id FROM public.bank_accounts WHERE id = v_bank_account_id FOR UPDATE;
  PERFORM id FROM public.bank_statement_lines WHERE id = v_bank_line_id FOR UPDATE;
  PERFORM id FROM public.bank_statement_lines WHERE id = v_refund_line_id FOR UPDATE;
  PERFORM id FROM public.suppliers WHERE id = v_supplier_id FOR UPDATE;
  PERFORM id FROM public.receipt_vouchers WHERE id = v_rv_id FOR UPDATE;
  PERFORM id FROM public.journal_entries WHERE id = v_old_rv_je_id FOR UPDATE;

  -- Step 1: Create and Post Payment Voucher for Rp 1,669,000 (or post existing draft)
  IF v_existing_pv.id IS NULL AND v_draft_pv.id IS NULL THEN
    v_pv_number := public.next_payment_voucher_number('2026-10-15'::date);
    INSERT INTO public.payment_vouchers (
      voucher_number,
      voucher_date,
      party_type,
      supplier_id,
      payment_method,
      bank_account_id,
      reference_number,
      amount,
      actual_bank_debit,
      payment_currency,
      exchange_rate,
      payment_purpose,
      settlement_against,
      description,
      created_by
    ) VALUES (
      v_pv_number,
      '2026-10-15'::date,
      'supplier',
      v_supplier_id,
      'bank_transfer',
      v_bank_account_id,
      '1510/FTSCY/WS95051',
      1669000.00,
      1669000.00,
      'IDR',
      1.000000,
      'general',
      'advance',
      'Supplier advance from bank payment remainder: 1510/FTSCY/WS95051',
      v_actor
    ) RETURNING id INTO v_pv_id;

    PERFORM public.post_payment_voucher(v_pv_id, v_actor);
  ELSIF v_existing_pv.id IS NULL AND v_draft_pv.id IS NOT NULL THEN
    v_pv_id := v_draft_pv.id;
    v_pv_number := v_draft_pv.voucher_number;
    PERFORM public.post_payment_voucher(v_pv_id, v_actor);
  ELSE
    v_pv_id := v_existing_pv.id;
    v_pv_number := v_existing_pv.voucher_number;
  END IF;

  SELECT journal_entry_id INTO v_pv_je_id FROM public.payment_vouchers WHERE id = v_pv_id;
  SELECT entry_number INTO v_pv_je_number FROM public.journal_entries WHERE id = v_pv_je_id;

  -- Ensure complete journal metadata on Payment Voucher Journal
  UPDATE public.journal_entries 
  SET period_id = COALESCE(period_id, v_period_15_id),
      posted_by = COALESCE(posted_by, v_actor),
      posted_at = COALESCE(posted_at, now()),
      created_by = COALESCE(created_by, v_actor),
      transaction_currency = COALESCE(transaction_currency, 'IDR'),
      functional_currency = COALESCE(functional_currency, 'IDR'),
      exchange_rate = COALESCE(exchange_rate, 1.000000),
      amounts_are_functional = true
  WHERE id = v_pv_je_id;

  UPDATE public.journal_entry_lines
  SET transaction_currency = COALESCE(transaction_currency, 'IDR'),
      functional_currency = COALESCE(functional_currency, 'IDR'),
      exchange_rate = COALESCE(exchange_rate, 1.000000),
      transaction_debit = COALESCE(transaction_debit, debit),
      transaction_credit = COALESCE(transaction_credit, credit)
  WHERE journal_entry_id = v_pv_je_id;

  -- Step 2: Allocate 2nd document on bank statement line 26fb3731-977e-41d1-a21b-661a29bd7c82
  SELECT id INTO v_pv_alloc_id FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = v_bank_line_id AND document_type = 'payment' AND document_id = v_pv_id LIMIT 1;
  IF v_pv_alloc_id IS NULL THEN
    v_pv_alloc_id := gen_random_uuid();
    INSERT INTO public.bank_statement_allocations (
      id, bank_statement_line_id, document_type, document_id, journal_entry_id,
      allocation_amount, payment_kind, created_by
    ) VALUES (
      v_pv_alloc_id, v_bank_line_id, 'payment', v_pv_id, v_pv_je_id,
      1669000.00, 'supplier', v_actor
    );
  END IF;

  PERFORM public.sync_bank_line_allocation_owner(v_bank_line_id);
  PERFORM public.refresh_bank_statement_allocation_status(v_bank_line_id);

  -- Step 3: Reverse Erroneous Receipt Journal JE2610-0239 with complete accounting metadata
  v_rev_je_number := public.next_journal_entry_number('2026-10-31'::date);
  INSERT INTO public.journal_entries (
    entry_number,
    entry_date,
    period_id,
    source_module,
    reference_id,
    reference_number,
    description,
    total_debit,
    total_credit,
    is_posted,
    is_reversed,
    posted_by,
    posted_at,
    created_by,
    created_at,
    transaction_currency,
    functional_currency,
    exchange_rate,
    amounts_are_functional
  ) VALUES (
    v_rev_je_number,
    '2026-10-31'::date,
    v_period_31_id,
    'receipt_reversal',
    v_old_rv_je_id,
    'JE2610-0239',
    'Reversal of erroneous Receipt Journal JE2610-0239 (PT TRANS EXIS JAYA AP misposting)',
    1669000.00,
    1669000.00,
    true,
    true,
    v_actor,
    now(),
    v_actor,
    now(),
    'IDR',
    'IDR',
    1.000000,
    true
  ) RETURNING id INTO v_rev_je_id;

  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, description, debit, credit,
    supplier_id, transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES
    (v_rev_je_id, 1, v_coa_2110, 'Reversal: Remove erroneous AP credit for PT TRANS EXIS JAYA', 1669000.00, 0, v_supplier_id, 'IDR', 1669000.00, 0, 'IDR', 1.000000),
    (v_rev_je_id, 2, v_bank_coa, 'Reversal: Revert Bank BCA debit', 0, 1666000.00, NULL, 'IDR', 0, 1666000.00, 'IDR', 1.000000),
    (v_rev_je_id, 3, v_coa_6910, 'Reversal: Revert settlement discount', 0, 3000.00, v_supplier_id, 'IDR', 0, 3000.00, 'IDR', 1.000000);

  UPDATE public.journal_entries
     SET is_reversed = true,
         reversed_by_id = v_rev_je_id,
         description = COALESCE(description, '') || ' [Reversed: Authoritative Advance Refund]'
   WHERE id = v_old_rv_je_id;

  -- Step 4: Create Replacement Receipt Journal Linked to GL 1170 with complete accounting metadata
  v_rep_je_number := public.next_journal_entry_number('2026-10-31'::date);
  INSERT INTO public.journal_entries (
    entry_number,
    entry_date,
    period_id,
    source_module,
    reference_id,
    reference_number,
    description,
    total_debit,
    total_credit,
    is_posted,
    posted_by,
    posted_at,
    created_by,
    created_at,
    transaction_currency,
    functional_currency,
    exchange_rate,
    amounts_are_functional
  ) VALUES (
    v_rep_je_number,
    '2026-10-31'::date,
    v_period_31_id,
    'receipt',
    v_rv_id,
    'RV2610-0018',
    'Receipt Voucher (supplier advance refund): RV2610-0018 - PT TRANS EXIS JAYA',
    1669000.00,
    1669000.00,
    true,
    v_actor,
    now(),
    v_actor,
    now(),
    'IDR',
    'IDR',
    1.000000,
    true
  ) RETURNING id INTO v_rep_je_id;

  INSERT INTO public.journal_entry_lines (
    journal_entry_id, line_number, account_id, description, debit, credit,
    supplier_id, transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate
  ) VALUES
    (v_rep_je_id, 1, v_bank_coa, 'Receipt from PT TRANS EXIS JAYA (advance refund)', 1666000.00, 0, NULL, 'IDR', 1666000.00, 0, 'IDR', 1.000000),
    (v_rep_je_id, 2, v_coa_6910, 'Approved Settlement Difference on supplier advance refund', 3000.00, 0, v_supplier_id, 'IDR', 3000.00, 0, 'IDR', 1.000000),
    (v_rep_je_id, 3, v_coa_1170, 'Clear Supplier Advance asset for PT TRANS EXIS JAYA', 0, 1669000.00, v_supplier_id, 'IDR', 0, 1669000.00, 'IDR', 1.000000);

  -- Step 5: Update Receipt Voucher & Relink Bank Allocation
  UPDATE public.receipt_vouchers
     SET journal_entry_id = v_rep_je_id,
         adjustment_account_id = v_coa_6910,
         settlement_discount = 3000.00,
         adjustment_notes = 'Approved settlement difference of 3,000 against advance refund 1,669,000'
   WHERE id = v_rv_id;

  UPDATE public.bank_statement_allocations
     SET journal_entry_id = v_rep_je_id
   WHERE document_type = 'receipt' AND document_id = v_rv_id;

  UPDATE public.bank_statement_lines
     SET matched_entry_id = v_rep_je_id
   WHERE id = v_refund_line_id;

  -- Re-sync bank account balance
  PERFORM public.sync_bank_account_balance(v_bank_account_id);
  SELECT current_balance INTO v_bank_after FROM public.bank_accounts WHERE id = v_bank_account_id;

  RETURN jsonb_build_object(
    'success', true,
    'dry_run', false,
    'status', 'COMPLETED',
    'payment_voucher', jsonb_build_object('id', v_pv_id, 'number', v_pv_number, 'journal', v_pv_je_number),
    'reversal_journal', jsonb_build_object('id', v_rev_je_id, 'number', v_rev_je_number, 'reverses_id', v_old_rv_je_id),
    'replacement_journal', jsonb_build_object('id', v_rep_je_id, 'number', v_rep_je_number),
    'bank_balance_before', v_bank_before,
    'bank_balance_after', v_bank_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_bank_allocation_document(p_journal_entry_id uuid)
 RETURNS TABLE(document_type text, document_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_module text;
  v_reference uuid;
BEGIN
  SELECT lower(COALESCE(source_module,'')), reference_id
    INTO v_module, v_reference
    FROM public.journal_entries
   WHERE id = p_journal_entry_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_module IN ('payment','payments','payment_voucher')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN
    document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('receipt','receipts','receipt_voucher')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN
    document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('expense','expenses','expense_payment')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN
    document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('fund_transfer','fund_transfers')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN
    document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('tax_payment','tax_payments')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN
    document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module IN ('petty_cash','petty_cash_transaction')
     AND v_reference IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN
    document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;
  ELSIF v_module = 'historical_repair' AND v_reference IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN
      document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN
      document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN
      document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN
      document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN
      document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;
    ELSIF EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN
      document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;
    END IF;
  END IF;

  document_type := 'journal';
  document_id := p_journal_entry_id;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_bpjs_monthly_register(p_register_id uuid, p_reason text DEFAULT 'Correction'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_reg public.bpjs_monthly_registers%ROWTYPE;
BEGIN
  PERFORM public._sec_check_finance_role();

  SELECT * INTO v_reg FROM public.bpjs_monthly_registers WHERE id = p_register_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BPJS register % not found', p_register_id; END IF;

  IF v_reg.payment_journal_entry_id IS NOT NULL THEN
    UPDATE public.journal_entries
       SET is_reversed = true
     WHERE id = v_reg.payment_journal_entry_id;
  END IF;

  IF v_reg.journal_entry_id IS NOT NULL THEN
    UPDATE public.journal_entries
       SET is_reversed = true
     WHERE id = v_reg.journal_entry_id;
  END IF;

  IF v_reg.bank_statement_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
       SET matched_entry_id = NULL,
           reconciliation_status = 'unmatched',
           matching_status = 'none',
           matched_at = NULL,
           matched_by = NULL
     WHERE id = v_reg.bank_statement_line_id;
  END IF;

  UPDATE public.bpjs_monthly_registers
     SET status = 'cancelled',
         notes = COALESCE(notes || ' | ', '') || 'Reversed: ' || p_reason,
         payment_status = 'unpaid',
         reconciliation_status = 'unreconciled',
         updated_at = now()
   WHERE id = v_reg.id;

  RETURN jsonb_build_object('success', true, 'register_id', v_reg.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.run_fx_month_end_revaluation(p_period_date date, p_closing_rate numeric, p_rate_source text DEFAULT 'Bank Indonesia JISDOR'::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_period_name TEXT;
  v_period_id UUID;
  v_existing_reval RECORD;
  v_reval_id UUID;
  v_reval_num TEXT;
  v_je_id UUID;
  v_je_entry_num TEXT;
  v_actor UUID;
  v_fx_gain_coa UUID;
  v_fx_loss_coa UUID;
  v_ap_coa UUID;
  v_total_unrealized_gain NUMERIC := 0;
  v_total_unrealized_loss NUMERIC := 0;
  v_total_je_debit NUMERIC := 0;
  v_total_je_credit NUMERIC := 0;
  v_line_no INTEGER := 1;
  v_ba RECORD;
  v_pi RECORD;
  v_bank_qty_usd NUMERIC;
  v_bank_carrying_idr NUMERIC;
  v_bank_revalued_idr NUMERIC;
  v_bank_diff NUMERIC;
  v_pi_carrying_rate NUMERIC;
  v_pi_carrying_idr NUMERIC;
  v_pi_revalued_idr NUMERIC;
  v_pi_diff NUMERIC;
  v_inserted_lines INTEGER := 0;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  END IF;

  v_actor := COALESCE(auth.uid(), p_created_by);
  v_period_name := to_char(p_period_date, 'YYYY-MM');

  IF p_closing_rate IS NULL OR p_closing_rate <= 0 THEN
    RAISE EXCEPTION 'A positive closing exchange rate is required for FX revaluation';
  END IF;

  -- 1. Idempotency Guard: October 2026 protection
  IF v_period_name = '2026-10' OR p_period_date <= '2026-10-31' THEN
    SELECT * INTO v_existing_reval FROM public.fx_revaluations WHERE period_name = '2026-10' LIMIT 1;
    IF v_existing_reval.id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'success', true,
        'message', 'October 2026 revaluation is authoritative and preserved (JE2611-0314). No duplicates created.',
        'revaluation_id', v_existing_reval.id,
        'revaluation_number', v_existing_reval.revaluation_number,
        'journal_entry_id', v_existing_reval.journal_entry_id,
        'closing_rate', v_existing_reval.closing_rate,
        'is_existing', true
      );
    END IF;
  END IF;

  -- 2. Guard against duplicate revaluation for any period
  SELECT * INTO v_existing_reval FROM public.fx_revaluations WHERE period_name = v_period_name AND status = 'posted' LIMIT 1;
  IF v_existing_reval.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Revaluation for period ' || v_period_name || ' already exists (' || v_existing_reval.revaluation_number || ').',
      'revaluation_id', v_existing_reval.id,
      'revaluation_number', v_existing_reval.revaluation_number,
      'journal_entry_id', v_existing_reval.journal_entry_id,
      'closing_rate', v_existing_reval.closing_rate,
      'is_existing', true
    );
  END IF;

  -- Resolve Accounting Period ID
  SELECT id INTO v_period_id 
  FROM public.accounting_periods 
  WHERE p_period_date BETWEEN start_date::date AND end_date::date 
  LIMIT 1;

  -- Resolve Standard Chart of Accounts
  SELECT id INTO v_fx_gain_coa FROM public.chart_of_accounts WHERE code = '4930' AND is_active = true LIMIT 1;
  SELECT id INTO v_fx_loss_coa FROM public.chart_of_accounts WHERE code = '7300' AND is_active = true LIMIT 1;
  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true LIMIT 1;

  IF v_fx_gain_coa IS NULL OR v_fx_loss_coa IS NULL OR v_ap_coa IS NULL THEN
    RAISE EXCEPTION 'Required GL accounts (4930 FX Gain, 7300 FX Loss, 2110 AP) could not be resolved';
  END IF;

  -- Generate Revaluation Number
  v_reval_num := 'REV-' || to_char(p_period_date, 'YYMM') || '-0001';

  INSERT INTO public.fx_revaluations (
    revaluation_number, revaluation_date, period_name, currency, closing_rate,
    rate_source, status, created_by
  ) VALUES (
    v_reval_num, p_period_date, v_period_name, 'USD', p_closing_rate,
    p_rate_source, 'draft', v_actor
  ) RETURNING id INTO v_reval_id;

  -- 3. Reconstruct USD Bank Balance as of p_period_date
  FOR v_ba IN (
    SELECT ba.id, ba.account_name, ba.currency, ba.current_balance, ba.coa_id
    FROM public.bank_accounts ba
    WHERE upper(ba.currency) = 'USD' AND ba.is_active = true
  ) LOOP
    IF v_ba.coa_id IS NOT NULL THEN
      -- USD Quantity as of p_period_date from GL
      SELECT COALESCE(SUM(jel.transaction_debit - jel.transaction_credit), 0)
      INTO v_bank_qty_usd
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
      WHERE jel.account_id = v_ba.coa_id
        AND je.is_posted = true
        AND NOT COALESCE(je.is_reversed, false)
        AND je.entry_date <= p_period_date;

      IF v_bank_qty_usd <= 0 AND v_ba.current_balance > 0 THEN
        v_bank_qty_usd := v_ba.current_balance;
      END IF;

      -- Carrying IDR balance as of p_period_date from GL
      SELECT COALESCE(SUM(jel.debit - jel.credit), 0)
      INTO v_bank_carrying_idr
      FROM public.journal_entry_lines jel
      JOIN public.journal_entries je ON je.id = jel.journal_entry_id
      WHERE jel.account_id = v_ba.coa_id
        AND je.is_posted = true
        AND NOT COALESCE(je.is_reversed, false)
        AND je.entry_date <= p_period_date;

      IF v_bank_qty_usd > 0 THEN
        v_bank_revalued_idr := round((v_bank_qty_usd * p_closing_rate), 2);
        v_bank_diff := v_bank_revalued_idr - v_bank_carrying_idr;

        IF abs(v_bank_diff) >= 0.01 THEN
          INSERT INTO public.fx_revaluation_lines (
            revaluation_id, line_type, bank_account_id, foreign_amount,
            carrying_rate, carrying_amount_idr, revalued_rate, revalued_amount_idr,
            fx_difference, gain_loss_type
          ) VALUES (
            v_reval_id, 'bank_asset', v_ba.id, v_bank_qty_usd,
            round(v_bank_carrying_idr / v_bank_qty_usd, 4),
            v_bank_carrying_idr, p_closing_rate, v_bank_revalued_idr,
            abs(v_bank_diff),
            CASE WHEN v_bank_diff > 0 THEN 'unrealized_gain' ELSE 'unrealized_loss' END
          );
          v_inserted_lines := v_inserted_lines + 1;

          IF v_bank_diff > 0 THEN
            v_total_unrealized_gain := v_total_unrealized_gain + v_bank_diff;
          ELSE
            v_total_unrealized_loss := v_total_unrealized_loss + abs(v_bank_diff);
          END IF;
        END IF;
      END IF;
    END IF;
  END LOOP;

  -- 4. Reconstruct Open USD Payables as of p_period_date
  FOR v_pi IN (
    SELECT pi.id, pi.invoice_number, pi.supplier_id, pi.exchange_rate,
           (pi.total_amount - COALESCE((
             SELECT SUM(va.allocated_amount)
             FROM public.voucher_allocations va
             JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id
             WHERE va.purchase_invoice_id = pi.id
               AND pv.is_posted = true
               AND pv.voucher_date <= p_period_date
           ), 0)) as remaining_usd
    FROM public.purchase_invoices pi
    WHERE upper(pi.currency) = 'USD'
      AND pi.status != 'paid'
      AND pi.invoice_date <= p_period_date
    ORDER BY pi.invoice_date
  ) LOOP
    IF v_pi.remaining_usd > 0 THEN
      -- Carry-forward rate from latest posted revaluation prior to period date, or invoice rate
      SELECT COALESCE(
        (SELECT frl.revalued_rate
         FROM public.fx_revaluation_lines frl
         JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id
         WHERE frl.purchase_invoice_id = v_pi.id
           AND fr.status = 'posted'
           AND fr.revaluation_date < p_period_date
         ORDER BY fr.revaluation_date DESC, fr.created_at DESC
         LIMIT 1),
        v_pi.exchange_rate,
        p_closing_rate
      ) INTO v_pi_carrying_rate;

      v_pi_carrying_idr := round((v_pi.remaining_usd * v_pi_carrying_rate), 2);
      v_pi_revalued_idr := round((v_pi.remaining_usd * p_closing_rate), 2);
      v_pi_diff := v_pi_revalued_idr - v_pi_carrying_idr;

      IF abs(v_pi_diff) >= 0.01 THEN
        INSERT INTO public.fx_revaluation_lines (
          revaluation_id, line_type, purchase_invoice_id, supplier_id, foreign_amount,
          carrying_rate, carrying_amount_idr, revalued_rate, revalued_amount_idr,
          fx_difference, gain_loss_type
        ) VALUES (
          v_reval_id, 'ap_payable', v_pi.id, v_pi.supplier_id, v_pi.remaining_usd,
          v_pi_carrying_rate, v_pi_carrying_idr, p_closing_rate, v_pi_revalued_idr,
          abs(v_pi_diff),
          CASE WHEN v_pi_diff > 0 THEN 'unrealized_loss' ELSE 'unrealized_gain' END
        );
        v_inserted_lines := v_inserted_lines + 1;

        IF v_pi_diff > 0 THEN
          v_total_unrealized_loss := v_total_unrealized_loss + v_pi_diff;
        ELSE
          v_total_unrealized_gain := v_total_unrealized_gain + abs(v_pi_diff);
        END IF;
      END IF;
    END IF;
  END LOOP;

  -- 5. Create Accounting Journal if adjustments exist
  IF v_total_unrealized_gain > 0 OR v_total_unrealized_loss > 0 THEN
    v_je_entry_num := public.next_journal_entry_number();
    v_total_je_debit := v_total_unrealized_loss + v_total_unrealized_gain;
    v_total_je_credit := v_total_je_debit;

    INSERT INTO public.journal_entries (
      entry_number, entry_date, source_module, reference_id, reference_number,
      description, total_debit, total_credit, is_posted, posted_by, created_by,
      transaction_currency, functional_currency, exchange_rate, period_id
    ) VALUES (
      v_je_entry_num, p_period_date, 'fx_revaluation', v_reval_id, v_reval_num,
      'Month-End Foreign Currency Revaluation for ' || v_period_name || ' at ' || p_rate_source || ' Rp' || round(p_closing_rate, 0)::text || '/USD',
      v_total_je_debit, v_total_je_credit, true, v_actor, v_actor,
      'USD', 'IDR', p_closing_rate, v_period_id
    ) RETURNING id INTO v_je_id;

    -- Lines: Loss portion: Dr GL 7300, Cr Accounts (Bank or AP)
    IF v_total_unrealized_loss > 0 THEN
      INSERT INTO public.journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate
      ) VALUES (
        v_je_id, v_line_no, v_fx_loss_coa,
        'Unrealized FX Loss (' || v_period_name || ' Revaluation at Rp' || round(p_closing_rate, 0)::text || '/USD)',
        v_total_unrealized_loss, 0, 'IDR', v_total_unrealized_loss, 0, 1
      );
      v_line_no := v_line_no + 1;
    END IF;

    -- Gain portion: Cr GL 4930, Dr Accounts (Bank or AP)
    IF v_total_unrealized_gain > 0 THEN
      INSERT INTO public.journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate
      ) VALUES (
        v_je_id, v_line_no, v_fx_gain_coa,
        'Unrealized FX Gain (' || v_period_name || ' Revaluation at Rp' || round(p_closing_rate, 0)::text || '/USD)',
        0, v_total_unrealized_gain, 'IDR', 0, v_total_unrealized_gain, 1
      );
      v_line_no := v_line_no + 1;
    END IF;

    -- Balance against Bank Assets
    FOR v_ba IN (
      SELECT frl.line_type, frl.fx_difference, frl.gain_loss_type, ba.coa_id
      FROM public.fx_revaluation_lines frl
      JOIN public.bank_accounts ba ON ba.id = frl.bank_account_id
      WHERE frl.revaluation_id = v_reval_id AND frl.line_type = 'bank_asset'
    ) LOOP
      INSERT INTO public.journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate
      ) VALUES (
        v_je_id, v_line_no, v_ba.coa_id,
        'USD Bank Asset Revaluation - ' || v_period_name,
        CASE WHEN v_ba.gain_loss_type = 'unrealized_gain' THEN v_ba.fx_difference ELSE 0 END,
        CASE WHEN v_ba.gain_loss_type = 'unrealized_loss' THEN v_ba.fx_difference ELSE 0 END,
        'IDR',
        CASE WHEN v_ba.gain_loss_type = 'unrealized_gain' THEN v_ba.fx_difference ELSE 0 END,
        CASE WHEN v_ba.gain_loss_type = 'unrealized_loss' THEN v_ba.fx_difference ELSE 0 END,
        1
      );
      v_line_no := v_line_no + 1;
    END LOOP;

    -- Balance against AP Payables
    FOR v_pi IN (
      SELECT frl.supplier_id, SUM(CASE WHEN frl.gain_loss_type = 'unrealized_loss' THEN frl.fx_difference ELSE -frl.fx_difference END) as net_ap_diff
      FROM public.fx_revaluation_lines frl
      WHERE frl.revaluation_id = v_reval_id AND frl.line_type = 'ap_payable'
      GROUP BY frl.supplier_id
    ) LOOP
      IF v_pi.net_ap_diff <> 0 THEN
        INSERT INTO public.journal_entry_lines (
          journal_entry_id, line_number, account_id, description,
          debit, credit, supplier_id, transaction_currency, transaction_debit, transaction_credit, exchange_rate
        ) VALUES (
          v_je_id, v_line_no, v_ap_coa,
          'Accounts Payable USD Revaluation - ' || v_period_name,
          CASE WHEN v_pi.net_ap_diff < 0 THEN abs(v_pi.net_ap_diff) ELSE 0 END,
          CASE WHEN v_pi.net_ap_diff > 0 THEN v_pi.net_ap_diff ELSE 0 END,
          v_pi.supplier_id, 'IDR',
          CASE WHEN v_pi.net_ap_diff < 0 THEN abs(v_pi.net_ap_diff) ELSE 0 END,
          CASE WHEN v_pi.net_ap_diff > 0 THEN v_pi.net_ap_diff ELSE 0 END,
          1
        );
        v_line_no := v_line_no + 1;
      END IF;
    END LOOP;

    UPDATE public.fx_revaluations
    SET journal_entry_id = v_je_id,
        status = 'posted',
        total_gain_loss = (v_total_unrealized_gain - v_total_unrealized_loss),
        updated_at = now()
    WHERE id = v_reval_id;

  ELSE
    UPDATE public.fx_revaluations
    SET status = 'posted',
        total_gain_loss = 0,
        updated_at = now()
    WHERE id = v_reval_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'revaluation_id', v_reval_id,
    'revaluation_number', v_reval_num,
    'journal_entry_id', v_je_id,
    'period_name', v_period_name,
    'closing_rate', p_closing_rate,
    'unrealized_gain', v_total_unrealized_gain,
    'unrealized_loss', v_total_unrealized_loss,
    'net_gain_loss', (v_total_unrealized_gain - v_total_unrealized_loss),
    'lines_count', v_inserted_lines
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.safe_delete_bank_statement_lines(p_bank_account_id uuid, p_start_date date, p_end_date date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_total_count      INTEGER;
v_reconciled_count INTEGER;
v_deletable_count  INTEGER;
v_deleted_count    INTEGER;
v_role             text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot delete bank statement lines', v_role;
END IF;

SELECT COUNT(*) INTO v_total_count FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date;

SELECT COUNT(*) INTO v_reconciled_count FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date
AND reconciliation_status IN ('matched','recorded','suggested');

v_deletable_count := v_total_count - v_reconciled_count;

IF v_reconciled_count > 0 THEN
RETURN json_build_object(
'success', false,
'error', 'Cannot delete: ' || v_reconciled_count || ' transaction(s) are reconciled',
'total_count', v_total_count, 'reconciled_count', v_reconciled_count,
'deletable_count', v_deletable_count, 'deleted_count', 0
);
END IF;

DELETE FROM bank_statement_lines
WHERE bank_account_id = p_bank_account_id
AND transaction_date BETWEEN p_start_date AND p_end_date
AND reconciliation_status = 'unmatched';
GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

RETURN json_build_object(
'success', true, 'total_count', v_total_count, 'reconciled_count', v_reconciled_count,
'deletable_count', v_deletable_count, 'deleted_count', v_deleted_count
);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_and_link_finance_expense_atomic(p_expense_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid, p_allocation_amount numeric DEFAULT NULL::numeric, p_approved_by uuid DEFAULT NULL::uuid, p_apply_salary_advances boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_expense_id uuid;
  v_journal_id uuid;
  v_journal_count integer;
  v_allocation_count integer;
BEGIN
  PERFORM public._sec_check_finance_role();

  IF p_bank_statement_line_id IS NULL THEN
    RAISE EXCEPTION 'A bank statement line is required for atomic expense linking';
  END IF;

  -- Serialize concurrent attempts against both the source document and bank
  -- line before any document or accounting write is made.
  PERFORM 1
    FROM public.bank_statement_lines
   WHERE id = p_bank_statement_line_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;

  IF p_expense_id IS NOT NULL THEN
    PERFORM 1 FROM public.finance_expenses WHERE id = p_expense_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.finance_expenses
       WHERE id = p_expense_id AND approval_status = 'approved'
    ) THEN
      RAISE EXCEPTION 'Approved expenses must use the canonical approved-edit command';
    END IF;
  END IF;

  -- Existing document command: a new/unlinked expense remains pending until
  -- the approval call below. Any later failure rolls this insert/update back.
  -- The selected statement makes this a controlled bank-linked save.
  PERFORM set_config('app.expense_atomic_bank_link','on',true);
  v_expense_id := public.save_finance_expense(p_expense_id, p_payload);

  IF p_apply_salary_advances THEN
    PERFORM public.apply_salary_advances_to_expense(v_expense_id, true);
  END IF;

  -- Existing approval command invokes the one canonical expense journal
  -- builder through trigger_auto_post_expense_accounting.
  PERFORM public.approve_finance_expense(
    v_expense_id,
    COALESCE(p_approved_by, auth.uid())
  );

  SELECT count(*), (array_agg(id ORDER BY created_at DESC, id DESC))[1]
    INTO v_journal_count, v_journal_id
    FROM public.journal_entries
   WHERE source_module IN ('expense', 'expenses')
     AND (
       reference_id = v_expense_id
       OR reference_number = 'EXP-' || v_expense_id::text
     )
     AND is_posted = true
     AND NOT COALESCE(is_reversed, false);
  IF v_journal_count <> 1 THEN
    RAISE EXCEPTION 'Expense bank link requires exactly one active effective journal';
  END IF;

  -- Existing canonical link command validates bank account, currency, amount,
  -- journal bank side, split-allocation capacity, and duplicate allocation.
  PERFORM public.link_bank_statement_line(
    p_bank_statement_line_id,
    'expense',
    v_expense_id,
    'supplier',
    p_allocation_amount
  );

  SELECT count(*) INTO v_allocation_count
    FROM public.bank_statement_allocations
   WHERE bank_statement_line_id = p_bank_statement_line_id
     AND document_type = 'expense'
     AND document_id = v_expense_id
     AND payment_kind = 'supplier'
     AND journal_entry_id = v_journal_id;
  IF v_allocation_count <> 1 THEN
    RAISE EXCEPTION 'Expense bank link did not preserve exactly one canonical allocation';
  END IF;

  PERFORM public.recalculate_expense_payment_state(v_expense_id);
  RETURN v_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_bank_linked_finance_journal(p_bank_line_id uuid, p_description text, p_counter_account_code text, p_bank_side text, p_transaction_currency text, p_exchange_rate numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_line public.bank_statement_lines%ROWTYPE; v_bank_coa uuid; v_counter_coa uuid;
  v_amount numeric; v_journal uuid; v_lines jsonb; v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_line_id FOR UPDATE;
  IF NOT FOUND OR v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is missing or already linked'; END IF;
  SELECT coa_id INTO v_bank_coa FROM public.bank_accounts WHERE id=v_line.bank_account_id AND is_active=true AND upper(currency)=upper(p_transaction_currency);
  SELECT id INTO v_counter_coa FROM public.chart_of_accounts WHERE code=p_counter_account_code AND is_active=true AND COALESCE(is_header,false)=false;
  IF v_bank_coa IS NULL OR v_counter_coa IS NULL THEN RAISE EXCEPTION 'Bank or counter account is not configured'; END IF;
  IF p_bank_side='debit' THEN v_amount:=COALESCE(v_line.credit_amount,0);
  ELSIF p_bank_side='credit' THEN v_amount:=COALESCE(v_line.debit_amount,0);
  ELSE RAISE EXCEPTION 'Bank side must be debit or credit'; END IF;
  IF v_amount<=0 THEN RAISE EXCEPTION 'Bank statement direction does not match this journal action'; END IF;
  v_lines:=CASE WHEN p_bank_side='debit' THEN jsonb_build_array(
      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',v_amount,'credit',0),
      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',0,'credit',v_amount))
    ELSE jsonb_build_array(
      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',v_amount,'credit',0),
      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',0,'credit',v_amount)) END;
  v_journal:=public.save_finance_journal(NULL,v_line.transaction_date,p_description,v_lines,upper(p_transaction_currency),p_exchange_rate);
  v_result:=public.link_bank_statement_line(p_bank_line_id,'journal',v_journal,'supplier');
  RETURN jsonb_build_object('document_id',v_journal,'journal_entry_id',v_journal,'link',v_result);
END $function$

CREATE OR REPLACE FUNCTION public.save_batch_inventory_v1(p_batch_id uuid, p_payload jsonb, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch public.batches%ROWTYPE;
  v_existing_batch_id uuid;
  v_actor uuid := auth.uid();
  v_delta numeric;
  v_previous_context text;
  v_unit_price numeric;
  v_is_local boolean;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse']) THEN
    RAISE EXCEPTION 'Permission denied for canonical batch save';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'operation_id is required';
  END IF;
  IF p_batch_id IS NULL AND NULLIF(p_payload->>'make_id', '') IS NULL THEN
    RAISE EXCEPTION 'Make / Manufacturer is required for new inventory batches';
  END IF;
  IF NULLIF(p_payload->>'make_id', '') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.product_sources
        WHERE id = (p_payload->>'make_id')::uuid
          AND product_id = (p_payload->>'product_id')::uuid
     ) THEN
    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the selected product';
  END IF;

  v_unit_price := COALESCE((p_payload->>'import_price')::numeric, 0);
  v_is_local := NULLIF(p_payload->>'import_container_id', '') IS NULL;

  IF p_batch_id IS NULL THEN
    SELECT batch_id INTO v_existing_batch_id
      FROM public.inventory_transactions
     WHERE operation_id = p_operation_id AND transaction_type = 'purchase';
    IF FOUND THEN
      RETURN jsonb_build_object('success', true, 'batch_id', v_existing_batch_id, 'idempotent_retry', true);
    END IF;

    v_previous_context := current_setting('app.canonical_stock_engine', true);
    PERFORM set_config('app.canonical_stock_engine', 'on', true);
    INSERT INTO public.batches (
      batch_number, product_id, make_id, import_container_id, import_date,
      import_quantity, current_stock, packaging_details, import_price,
      import_price_usd, exchange_rate_usd_to_idr, duty_percent, duty_charges,
      duty_charge_type, freight_charges, freight_charge_type, other_charges,
      other_charge_type, expiry_date, is_active, created_by,
      cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit
    ) VALUES (
      p_payload->>'batch_number', (p_payload->>'product_id')::uuid,
      NULLIF(p_payload->>'make_id', '')::uuid,
      NULLIF(p_payload->>'import_container_id', '')::uuid,
      (p_payload->>'import_date')::date, (p_payload->>'import_quantity')::numeric,
      0, NULLIF(p_payload->>'packaging_details', ''),
      v_unit_price,
      NULLIF(p_payload->>'import_price_usd', '')::numeric,
      NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,
      COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), 'fixed'),
      COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), 'fixed'),
      COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),
      COALESCE(NULLIF(p_payload->>'other_charge_type', ''), 'fixed'),
      NULLIF(p_payload->>'expiry_date', '')::date, true, v_actor,
      v_unit_price,
      CASE WHEN v_is_local THEN v_unit_price ELSE 0 END,
      CASE WHEN v_is_local THEN v_unit_price * (p_payload->>'import_quantity')::numeric ELSE 0 END,
      v_unit_price
    ) RETURNING * INTO v_batch;
    PERFORM set_config('app.canonical_stock_engine', COALESCE(v_previous_context, ''), true);
    PERFORM public.post_inventory_movement(
      p_operation_id, v_batch.product_id, v_batch.id, 'purchase',
      v_batch.import_quantity, v_batch.import_date, v_batch.batch_number,
      'batch_creation', v_batch.id, 'Canonical Batch Creation: ' || v_batch.batch_number,
      v_actor, 0, v_batch.import_quantity
    );
    RETURN jsonb_build_object('success', true, 'batch_id', v_batch.id);
  END IF;

  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found'; END IF;
  IF (p_payload->>'product_id')::uuid IS DISTINCT FROM v_batch.product_id
     AND EXISTS (SELECT 1 FROM public.inventory_transactions WHERE batch_id = p_batch_id AND transaction_type <> 'purchase') THEN
    RAISE EXCEPTION 'Cannot change product after batch stock movement exists';
  END IF;

  v_delta := (p_payload->>'import_quantity')::numeric - v_batch.import_quantity;
  UPDATE public.batches SET
    batch_number = p_payload->>'batch_number', product_id = (p_payload->>'product_id')::uuid,
    make_id = NULLIF(p_payload->>'make_id', '')::uuid,
    import_container_id = NULLIF(p_payload->>'import_container_id', '')::uuid,
    import_date = (p_payload->>'import_date')::date, import_quantity = (p_payload->>'import_quantity')::numeric,
    packaging_details = NULLIF(p_payload->>'packaging_details', ''),
    import_price = COALESCE((p_payload->>'import_price')::numeric, import_price),
    import_price_usd = NULLIF(p_payload->>'import_price_usd', '')::numeric,
    exchange_rate_usd_to_idr = NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,
    duty_percent = COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),
    duty_charges = COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),
    duty_charge_type = COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), duty_charge_type),
    freight_charges = COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),
    freight_charge_type = COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), freight_charge_type),
    other_charges = COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),
    other_charge_type = COALESCE(NULLIF(p_payload->>'other_charge_type', ''), other_charge_type),
    expiry_date = NULLIF(p_payload->>'expiry_date', '')::date,
    cost_per_unit = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)
      ELSE cost_per_unit
    END,
    landed_cost_per_unit = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)
      ELSE landed_cost_per_unit
    END,
    final_landed_cost = CASE
      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL
        THEN COALESCE((p_payload->>'import_price')::numeric, import_price) * (p_payload->>'import_quantity')::numeric
      ELSE final_landed_cost
    END,
    import_price_per_unit = COALESCE((p_payload->>'import_price')::numeric, import_price),
    updated_at = now()
  WHERE id = p_batch_id;

  IF v_delta <> 0 THEN
    PERFORM public.post_inventory_movement(
      p_operation_id, (p_payload->>'product_id')::uuid, p_batch_id, 'adjustment',
      v_delta, CURRENT_DATE, p_payload->>'batch_number', 'batch_edit', p_batch_id,
      format('Canonical Batch Edit quantity correction: %s to %s', v_batch.import_quantity, (p_payload->>'import_quantity')::numeric),
      v_actor, v_batch.current_stock, v_batch.current_stock + v_delta
    );
  END IF;
  RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_crm_inquiry_pricing_options(p_inquiry_id uuid, p_options jsonb, p_selected_option_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inq record;
  v_opt jsonb;
  v_opt_id uuid;
  v_selected_id uuid;
  v_opt_make text;
  v_is_selected boolean;
  v_include_in_quote boolean;
  v_matched_id uuid;
  v_saved_options jsonb := '[]'::jsonb;
  v_active_make text;
  v_active_source_price numeric;
  v_active_source_currency text;
  v_active_quote_price numeric;
  v_active_quote_currency text;
  v_active_landed_usd numeric;
  v_active_found boolean := false;
  v_idx int := 0;
  v_user_role text;
BEGIN
  -- 1. Ensure user is authenticated and has required role
  SELECT role INTO v_user_role FROM public.user_profiles WHERE id = auth.uid() AND is_active = true;
  IF v_user_role IS NULL AND auth.role() <> 'service_role' THEN
    -- Fallback check for session or direct RPC invocation
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles 
      WHERE role IN ('admin', 'manager', 'sales', 'sales_support', 'accounts') AND is_active = true LIMIT 1
    ) THEN
      RAISE EXCEPTION 'Access denied: insufficient privileges to save pricing options.';
    END IF;
  END IF;

  -- 2. Lock and verify parent inquiry
  SELECT * INTO v_inq FROM public.crm_inquiries WHERE id = p_inquiry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CRM Inquiry with ID % not found', p_inquiry_id;
  END IF;

  -- 3. Iterate through options provided
  FOR v_opt IN SELECT * FROM jsonb_array_elements(COALESCE(p_options, '[]'::jsonb))
  LOOP
    v_idx := v_idx + 1;
    v_opt_id := NULL;
    IF (v_opt->>'id') IS NOT NULL AND (v_opt->>'id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_opt_id := (v_opt->>'id')::uuid;
    END IF;

    v_opt_make := trim(COALESCE(v_opt->>'offered_make', ''));

    -- Determine is_selected
    IF p_selected_option_id IS NOT NULL AND v_opt_id IS NOT NULL AND p_selected_option_id = v_opt_id THEN
      v_is_selected := true;
    ELSIF p_selected_option_id IS NULL AND (v_opt->>'is_selected')::boolean = true THEN
      v_is_selected := true;
    ELSIF p_selected_option_id IS NULL AND v_idx = 1 AND NOT v_active_found THEN
      v_is_selected := true;
    ELSE
      v_is_selected := false;
    END IF;

    IF v_is_selected THEN
      v_active_found := true;
    END IF;

    -- Determine include_in_customer_quote
    IF (v_opt->>'include_in_customer_quote') IS NOT NULL THEN
      v_include_in_quote := (v_opt->>'include_in_customer_quote')::boolean;
    ELSE
      v_include_in_quote := v_is_selected;
    END IF;

    -- Match existing record by ID or normalized manufacturer name
    v_matched_id := NULL;
    IF v_opt_id IS NOT NULL THEN
      SELECT id INTO v_matched_id FROM public.crm_inquiry_pricing_options
      WHERE id = v_opt_id AND inquiry_id = p_inquiry_id;
    END IF;

    IF v_matched_id IS NULL AND length(v_opt_make) > 0 THEN
      SELECT id INTO v_matched_id FROM public.crm_inquiry_pricing_options
      WHERE inquiry_id = p_inquiry_id
        AND lower(trim(offered_make)) = lower(v_opt_make)
      LIMIT 1;
    END IF;

    IF v_matched_id IS NOT NULL THEN
      -- UPDATE existing option
      UPDATE public.crm_inquiry_pricing_options
      SET
        source_type = COALESCE(v_opt->>'source_type', source_type, 'india'),
        offered_make = v_opt_make,
        source_price = CASE WHEN (v_opt->>'source_price') IS NOT NULL AND (v_opt->>'source_price') <> '' THEN (v_opt->>'source_price')::numeric ELSE NULL END,
        source_currency = COALESCE(v_opt->>'source_currency', source_currency, 'INR'),
        selling_price = CASE WHEN (v_opt->>'selling_price') IS NOT NULL AND (v_opt->>'selling_price') <> '' THEN (v_opt->>'selling_price')::numeric ELSE NULL END,
        selling_currency = COALESCE(v_opt->>'selling_currency', selling_currency, 'USD'),
        landed_cost_usd = CASE WHEN (v_opt->>'landed_cost_usd') IS NOT NULL AND (v_opt->>'landed_cost_usd') <> '' THEN (v_opt->>'landed_cost_usd')::numeric ELSE NULL END,
        suggested_quote_usd = CASE WHEN (v_opt->>'suggested_quote_usd') IS NOT NULL AND (v_opt->>'suggested_quote_usd') <> '' THEN (v_opt->>'suggested_quote_usd')::numeric ELSE NULL END,
        margin_pct = CASE WHEN (v_opt->>'margin_pct') IS NOT NULL AND (v_opt->>'margin_pct') <> '' THEN (v_opt->>'margin_pct')::numeric ELSE NULL END,
        supplier = COALESCE(v_opt->>'supplier', supplier),
        specification = COALESCE(v_opt->>'specification', specification),
        availability = COALESCE(v_opt->>'availability', availability, 'available'),
        moq = COALESCE(v_opt->>'moq', moq),
        packing = COALESCE(v_opt->>'packing', packing),
        lead_time = COALESCE(v_opt->>'lead_time', lead_time),
        origin = COALESCE(v_opt->>'origin', origin),
        remark = COALESCE(v_opt->>'remark', remark),
        is_selected = v_is_selected,
        include_in_customer_quote = v_include_in_quote,
        updated_at = now()
      WHERE id = v_matched_id;
      v_opt_id := v_matched_id;
    ELSE
      -- INSERT new option
      INSERT INTO public.crm_inquiry_pricing_options (
        inquiry_id,
        source_type,
        offered_make,
        source_price,
        source_currency,
        selling_price,
        selling_currency,
        landed_cost_usd,
        suggested_quote_usd,
        margin_pct,
        supplier,
        specification,
        availability,
        moq,
        packing,
        lead_time,
        origin,
        remark,
        is_selected,
        include_in_customer_quote,
        created_by,
        created_at,
        updated_at
      ) VALUES (
        p_inquiry_id,
        COALESCE(v_opt->>'source_type', 'india'),
        v_opt_make,
        CASE WHEN (v_opt->>'source_price') IS NOT NULL AND (v_opt->>'source_price') <> '' THEN (v_opt->>'source_price')::numeric ELSE NULL END,
        COALESCE(v_opt->>'source_currency', 'INR'),
        CASE WHEN (v_opt->>'selling_price') IS NOT NULL AND (v_opt->>'selling_price') <> '' THEN (v_opt->>'selling_price')::numeric ELSE NULL END,
        COALESCE(v_opt->>'selling_currency', 'USD'),
        CASE WHEN (v_opt->>'landed_cost_usd') IS NOT NULL AND (v_opt->>'landed_cost_usd') <> '' THEN (v_opt->>'landed_cost_usd')::numeric ELSE NULL END,
        CASE WHEN (v_opt->>'suggested_quote_usd') IS NOT NULL AND (v_opt->>'suggested_quote_usd') <> '' THEN (v_opt->>'suggested_quote_usd')::numeric ELSE NULL END,
        CASE WHEN (v_opt->>'margin_pct') IS NOT NULL AND (v_opt->>'margin_pct') <> '' THEN (v_opt->>'margin_pct')::numeric ELSE NULL END,
        v_opt->>'supplier',
        v_opt->>'specification',
        COALESCE(v_opt->>'availability', 'available'),
        v_opt->>'moq',
        v_opt->>'packing',
        v_opt->>'lead_time',
        v_opt->>'origin',
        v_opt->>'remark',
        v_is_selected,
        v_include_in_quote,
        auth.uid(),
        now(),
        now()
      )
      RETURNING id INTO v_opt_id;
    END IF;

    IF v_is_selected THEN
      v_selected_id := v_opt_id;
      v_active_make := v_opt_make;
      v_active_source_price := CASE WHEN (v_opt->>'source_price') IS NOT NULL AND (v_opt->>'source_price') <> '' THEN (v_opt->>'source_price')::numeric ELSE NULL END;
      v_active_source_currency := COALESCE(v_opt->>'source_currency', 'INR');
      v_active_quote_price := CASE WHEN (v_opt->>'selling_price') IS NOT NULL AND (v_opt->>'selling_price') <> '' THEN (v_opt->>'selling_price')::numeric ELSE NULL END;
      v_active_quote_currency := COALESCE(v_opt->>'selling_currency', 'USD');
      v_active_landed_usd := CASE WHEN (v_opt->>'landed_cost_usd') IS NOT NULL AND (v_opt->>'landed_cost_usd') <> '' THEN (v_opt->>'landed_cost_usd')::numeric ELSE NULL END;
    END IF;
  END LOOP;

  -- 4. Enforce that only the selected option has is_selected = true
  IF v_active_found AND v_selected_id IS NOT NULL THEN
    UPDATE public.crm_inquiry_pricing_options
    SET is_selected = false
    WHERE inquiry_id = p_inquiry_id
      AND id <> v_selected_id
      AND is_selected = true;
  END IF;

  -- 5. Update parent inquiry legacy single-value fields for backward compatibility
  IF v_active_found THEN
    UPDATE public.crm_inquiries
    SET
      supplier_name = CASE WHEN length(v_active_make) > 0 THEN v_active_make ELSE supplier_name END,
      purchase_price = v_active_landed_usd,
      purchase_price_currency = 'USD',
      offered_price = v_active_quote_price,
      offered_price_currency = v_active_quote_currency,
      kunal_price_status = CASE WHEN v_active_quote_price > 0 THEN 'entered' ELSE kunal_price_status END,
      price_ready = CASE WHEN v_active_quote_price > 0 THEN true ELSE price_ready END,
      updated_at = now()
    WHERE id = p_inquiry_id;
  END IF;

  -- 6. Return all options for this inquiry
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', id,
      'inquiry_id', inquiry_id,
      'source_type', source_type,
      'offered_make', offered_make,
      'source_price', source_price,
      'source_currency', source_currency,
      'selling_price', selling_price,
      'selling_currency', selling_currency,
      'landed_cost_usd', landed_cost_usd,
      'suggested_quote_usd', suggested_quote_usd,
      'margin_pct', margin_pct,
      'supplier', supplier,
      'specification', specification,
      'availability', availability,
      'moq', moq,
      'packing', packing,
      'lead_time', lead_time,
      'origin', origin,
      'remark', remark,
      'is_selected', is_selected,
      'include_in_customer_quote', include_in_customer_quote,
      'is_accepted', is_accepted,
      'created_at', created_at,
      'updated_at', updated_at
    ) ORDER BY is_selected DESC, created_at ASC
  ) INTO v_saved_options
  FROM public.crm_inquiry_pricing_options
  WHERE inquiry_id = p_inquiry_id;

  RETURN COALESCE(v_saved_options, '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_capital_contribution(p_payload jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid:=gen_random_uuid(); v_number text; v_je uuid; v_line public.bank_statement_lines%ROWTYPE; v_amount numeric; v_date date;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date:=(p_payload->>'voucher_date')::date; v_amount:=(p_payload->>'amount')::numeric;
  IF v_amount<=0 THEN RAISE EXCEPTION 'Capital contribution amount must be positive'; END IF;
  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;
    IF NOT FOUND OR COALESCE(v_line.credit_amount,0)<>v_amount OR v_line.bank_account_id<>(p_payload->>'bank_account_id')::uuid THEN RAISE EXCEPTION 'Bank statement line does not exactly match this capital contribution'; END IF;
    IF v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is already linked'; END IF;
  END IF;
  v_number:=public.next_capital_contribution_number(v_date);
  INSERT INTO public.capital_contributions(id,voucher_number,voucher_date,director_id,contribution_type,bank_account_id,amount,description,created_by,
    transaction_currency,functional_currency,exchange_rate,bank_account_currency,bank_statement_line_id)
  VALUES(v_id,v_number,v_date,NULL,'bank_transfer',(p_payload->>'bank_account_id')::uuid,v_amount,COALESCE(p_payload->>'description',''),
    COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),upper(p_payload->>'transaction_currency'),'IDR',(p_payload->>'exchange_rate')::numeric,
    upper(p_payload->>'transaction_currency'),p_bank_statement_line_id) RETURNING journal_entry_id INTO v_je;
  IF p_bank_statement_line_id IS NOT NULL THEN PERFORM public._link_native_bank_document(p_bank_statement_line_id,v_je,'Capital Contribution - '||v_number); END IF;
  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number,'journal_entry_id',v_je);
END $function$

CREATE OR REPLACE FUNCTION public.save_finance_exception_corrections(p_corrections jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c jsonb;
  v_document_type text;
  v_document_id uuid;
  v_exception_id bigint;
  v_reason text;
  v_journal_id uuid;
  v_line_id uuid;
  v_account_id uuid;
  v_bank_id uuid;
  v_bank_coa_id uuid;
  v_bank_currency text;
  v_tax_code_id uuid;
  v_tax_type text;
  v_exchange_rate numeric;
  v_before_lines jsonb;
  v_after_lines jsonb;
  v_resolved boolean := false;
  v_saved integer := 0;
  v_resolved_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  IF jsonb_typeof(p_corrections) <> 'array' OR jsonb_array_length(p_corrections)=0 THEN
    RAISE EXCEPTION 'Select at least one correction before saving';
  END IF;

  -- Existing source triggers read these flags. Metadata corrections must never
  -- regenerate journals or recalculate historical debit/credit values.
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_metadata_repair','on',true);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections)
  LOOP
    v_document_type := c->>'document_type';
    v_document_id := (c->>'document_id')::uuid;
    v_exception_id := NULLIF(c->>'exception_id','')::bigint;
    v_line_id := NULLIF(c->>'journal_line_id','')::uuid;
    v_bank_id := NULLIF(c->>'bank_account_id','')::uuid;
    v_tax_code_id := NULLIF(c->>'tax_code_id','')::uuid;
    v_exchange_rate := NULLIF(c->>'exchange_rate','')::numeric;
    v_resolved := false;

    IF v_exception_id IS NOT NULL THEN
      SELECT reason INTO v_reason
      FROM public.finance_historical_repair_exceptions
      WHERE id=v_exception_id AND document_type=v_document_type
        AND document_id=v_document_id AND status='manual_review'
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'This exception is no longer open'; END IF;
    ELSE
      v_reason := 'Live Finance verification failure';
      IF NOT EXISTS (
        SELECT 1 FROM public.finance_exception_correction_dashboard d
        WHERE d.document_type=v_document_type AND d.document_id=v_document_id
          AND d.status='Verification failed'
      ) THEN RAISE EXCEPTION 'This verification failure is no longer open'; END IF;
    END IF;

    SELECT CASE v_document_type
      WHEN 'journal' THEN v_document_id
      WHEN 'receipt' THEN (SELECT journal_entry_id FROM public.receipt_vouchers WHERE id=v_document_id)
      WHEN 'payment' THEN (SELECT journal_entry_id FROM public.payment_vouchers WHERE id=v_document_id)
      WHEN 'fund_transfer' THEN (SELECT journal_entry_id FROM public.fund_transfers WHERE id=v_document_id)
      WHEN 'loan' THEN (SELECT journal_entry_id FROM public.loans WHERE id=v_document_id)
      WHEN 'loan_transaction' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)
      WHEN 'loan_repayment' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)
      WHEN 'capital_contribution' THEN (SELECT journal_entry_id FROM public.capital_contributions WHERE id=v_document_id)
      WHEN 'tax_payment' THEN (SELECT journal_entry_id FROM public.tax_payments WHERE id=v_document_id)
      WHEN 'sales_invoice' THEN (SELECT journal_entry_id FROM public.sales_invoices WHERE id=v_document_id)
      WHEN 'purchase_invoice' THEN (SELECT journal_entry_id FROM public.purchase_invoices WHERE id=v_document_id)
      WHEN 'bank_reconciliation' THEN (SELECT matched_entry_id FROM public.bank_statement_lines WHERE id=v_document_id)
      WHEN 'expense' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module IN('expense','expenses')
        AND (j.reference_id=v_document_id OR j.reference_number='EXP-'||v_document_id::text)
        AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)
      WHEN 'petty_cash' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module='petty_cash'
        AND j.reference_id=v_document_id AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)
    END INTO v_journal_id;

    IF v_journal_id IS NOT NULL THEN
      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)
      INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;
    END IF;

    IF v_bank_id IS NOT NULL THEN
      SELECT ba.coa_id,upper(ba.currency) INTO v_bank_coa_id,v_bank_currency
      FROM public.bank_accounts ba JOIN public.chart_of_accounts coa ON coa.id=ba.coa_id
      WHERE ba.id=v_bank_id AND ba.is_active=true AND coa.is_active=true AND COALESCE(coa.is_header,false)=false;
      IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Selected bank has no active posting account'; END IF;
    END IF;

    v_account_id := COALESCE(NULLIF(c->>'account_id','')::uuid,
      NULLIF(c->>'loan_account_id','')::uuid,
      NULLIF(c->>'capital_account_id','')::uuid,
      CASE WHEN v_bank_id IS NOT NULL THEN v_bank_coa_id END);
    IF v_account_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.chart_of_accounts WHERE id=v_account_id AND is_active=true AND COALESCE(is_header,false)=false
    ) THEN RAISE EXCEPTION 'Selected account is not an active posting account'; END IF;

    IF v_tax_code_id IS NOT NULL THEN
      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id AND is_active=true;
      IF v_tax_type IS NULL THEN RAISE EXCEPTION 'Selected tax category is not active'; END IF;
    END IF;

    -- Source metadata. Every assignment is to an existing row; no insert,
    -- delete, posting, numbering, date, narration, or amount field is allowed.
    IF v_document_type='expense' THEN
      UPDATE public.finance_expenses SET
        expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),
        payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),
        pph_code_id=COALESCE(v_tax_code_id,pph_code_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),
        currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),
        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR')
      WHERE id=v_document_id;
    ELSIF v_document_type='receipt' THEN
      UPDATE public.receipt_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='payment' THEN
      UPDATE public.payment_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),
        bank_account_id=COALESCE(v_bank_id,bank_account_id),pph_code_id=COALESCE(v_tax_code_id,pph_code_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),
        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='loan' THEN
      UPDATE public.loans SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        coa_id=COALESCE(NULLIF(c->>'loan_account_id','')::uuid,coa_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency=COALESCE(v_bank_currency,currency),
        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),functional_currency=COALESCE(functional_currency,'IDR')
      WHERE id=v_document_id;
    ELSIF v_document_type IN ('loan_transaction','loan_repayment') THEN
      UPDATE public.loan_transactions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='capital_contribution' THEN
      UPDATE public.capital_contributions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        contribution_type=COALESCE(NULLIF(c->>'expense_category',''),contribution_type),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),
        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;
    ELSIF v_document_type='petty_cash' THEN
      UPDATE public.petty_cash_transactions SET expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),
        bank_account_id=COALESCE(v_bank_id,bank_account_id) WHERE id=v_document_id;
    ELSIF v_document_type='tax_payment' THEN
      UPDATE public.tax_payments SET bank_account_id=COALESCE(v_bank_id,bank_account_id),
        tax_type=COALESCE(v_tax_type,tax_type) WHERE id=v_document_id;
    ELSIF v_document_type='sales_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN
      UPDATE public.sales_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;
    ELSIF v_document_type='purchase_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN
      UPDATE public.purchase_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;
    ELSIF v_document_type='bank_reconciliation' AND NULLIF(c->>'payment_type','') IS NOT NULL THEN
      UPDATE public.bank_statement_lines SET payment_kind=c->>'payment_type' WHERE id=v_document_id;
    END IF;

    IF v_journal_id IS NOT NULL THEN
      UPDATE public.journal_entries SET
        source_module=COALESCE(NULLIF(c->>'document_classification',''),source_module),
        transaction_currency=COALESCE(v_bank_currency,transaction_currency),
        functional_currency=COALESCE(functional_currency,'IDR'),
        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),
        amounts_are_functional=COALESCE(amounts_are_functional,true)
      WHERE id=v_journal_id;
    END IF;

    IF v_account_id IS NOT NULL THEN
      IF v_line_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.journal_entry_lines WHERE id=v_line_id AND journal_entry_id=v_journal_id
      ) THEN RAISE EXCEPTION 'The account line can no longer be identified safely'; END IF;
      UPDATE public.journal_entry_lines SET account_id=v_account_id WHERE id=v_line_id;
    END IF;

    IF v_journal_id IS NOT NULL THEN
      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)
      INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;
      IF v_before_lines IS DISTINCT FROM v_after_lines THEN
        RAISE EXCEPTION 'Correction cancelled because a debit or credit value changed';
      END IF;
    END IF;

    -- Resolve only when the specific historical problem is now disproved.
    IF v_reason ILIKE '%missing Faktur Pajak%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.sales_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.purchase_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL);
    ELSIF v_reason ILIKE '%no historical transaction-date rate%' OR v_reason ILIKE '%no authoritative historical rate%' THEN
      v_resolved := v_exchange_rate IS NOT NULL AND v_exchange_rate>0;
    ELSIF v_reason ILIKE '%does not use the Expense bank account%' OR v_reason ILIKE '%does not post to this bank account%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.journal_entry_lines jl JOIN public.bank_accounts ba ON ba.coa_id=jl.account_id
        WHERE jl.journal_entry_id=v_journal_id AND ba.id=COALESCE(v_bank_id,(SELECT bank_account_id FROM public.bank_statement_lines WHERE id=v_document_id)));
    ELSIF v_reason ILIKE 'No unique authoritative relationship%' THEN
      IF v_document_type='expense' THEN v_resolved := EXISTS(SELECT 1 FROM public.finance_expenses x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));
      ELSIF v_document_type='receipt' THEN v_resolved := EXISTS(SELECT 1 FROM public.receipt_vouchers x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));
      ELSIF v_document_type='payment' THEN v_resolved := EXISTS(SELECT 1 FROM public.payment_vouchers x WHERE x.id=v_document_id
        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL
        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL)); END IF;
    ELSIF v_reason ILIKE '%metadata conflicts%' THEN
      v_resolved := v_bank_id IS NOT NULL;
    ELSIF v_reason ILIKE '%Journal metadata cannot be derived%' THEN
      v_resolved := EXISTS(SELECT 1 FROM public.journal_entries WHERE id=v_journal_id AND source_module IS NOT NULL
        AND transaction_currency IS NOT NULL AND functional_currency IS NOT NULL
        AND (transaction_currency='IDR' OR exchange_rate IS NOT NULL));
    END IF;

    IF v_exception_id IS NOT NULL AND v_resolved THEN
      UPDATE public.finance_historical_repair_exceptions SET status='resolved' WHERE id=v_exception_id;
      v_resolved_count := v_resolved_count + 1;
    END IF;

    INSERT INTO public.audit_logs(table_name,action_type,record_id,old_values,new_values,changed_fields)
    VALUES('finance_exception_correction_dashboard','update',v_document_id,
      jsonb_build_object('exception_id',v_exception_id,'journal_lines',v_before_lines),
      jsonb_build_object('correction',c,'journal_lines',v_after_lines,'resolved',v_resolved),
      ARRAY['finance_metadata','account_classification','exception_status']);
    v_saved := v_saved + 1;
  END LOOP;

  RETURN jsonb_build_object('saved',v_saved,'resolved',v_resolved_count,'refresh_required',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_exception_corrections_v2(p_corrections jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c jsonb;
  v_type text;
  v_id uuid;
  v_exception bigint;
  v_journal uuid;
  v_line uuid;
  v_supplier uuid;
  v_customer uuid;
  v_from_bank uuid;
  v_to_bank uuid;
  v_from_old uuid;
  v_to_old uuid;
  v_from_old_coa uuid;
  v_to_old_coa uuid;
  v_from_new_coa uuid;
  v_to_new_coa uuid;
  v_from_alias text;
  v_to_alias text;
  v_from_currency text;
  v_to_currency text;
  v_link_type text;
  v_link_id uuid;
  v_result jsonb;
  v_resolved_ids jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  PERFORM public._sec_check_finance_role();
  IF jsonb_typeof(p_corrections)<>'array' OR jsonb_array_length(p_corrections)=0 THEN
    RAISE EXCEPTION 'Select at least one correction before saving';
  END IF;
  PERFORM set_config('app.finance_historical_repair','on',true);
  PERFORM set_config('app.finance_metadata_repair','on',true);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP
    v_type:=c->>'document_type';
    v_id:=(c->>'document_id')::uuid;
    v_exception:=NULLIF(c->>'exception_id','')::bigint;
    v_journal:=NULLIF(c->>'journal_entry_id','')::uuid;
    v_line:=NULLIF(c->>'journal_line_id','')::uuid;
    v_supplier:=NULLIF(c->>'supplier_id','')::uuid;
    v_customer:=NULLIF(c->>'customer_id','')::uuid;
    v_from_bank:=NULLIF(c->>'from_bank_account_id','')::uuid;
    v_to_bank:=NULLIF(c->>'to_bank_account_id','')::uuid;
    v_link_type:=NULLIF(c->>'linked_document_type','');
    v_link_id:=NULLIF(c->>'linked_document_id','')::uuid;

    IF NOT EXISTS (SELECT 1 FROM public.finance_exception_correction_dashboard x WHERE x.document_type=v_type AND x.document_id=v_id) THEN
      RAISE EXCEPTION 'This exception is no longer open';
    END IF;
    IF v_supplier IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id=v_supplier AND COALESCE(is_active,true)) THEN
      RAISE EXCEPTION 'Selected supplier is not active';
    END IF;
    IF v_customer IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id=v_customer) THEN
      RAISE EXCEPTION 'Selected customer does not exist';
    END IF;

    IF v_type='expense' THEN
      UPDATE public.finance_expenses SET
        expense_type=COALESCE(NULLIF(c->>'expense_subcategory',''),expense_type),
        supplier_id=COALESCE(v_supplier,supplier_id),
        payment_reference=COALESCE(NULLIF(c->>'reference',''),payment_reference)
      WHERE id=v_id;
    ELSIF v_type='receipt' THEN
      UPDATE public.receipt_vouchers SET customer_id=COALESCE(v_customer,customer_id),
        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;
    ELSIF v_type='payment' THEN
      UPDATE public.payment_vouchers SET supplier_id=COALESCE(v_supplier,supplier_id),
        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;
    ELSIF v_type='loan' THEN
      UPDATE public.loans SET loan_type=COALESCE(NULLIF(c->>'finance_classification',''),loan_type) WHERE id=v_id;
    ELSIF v_type='capital_contribution' THEN
      UPDATE public.capital_contributions SET contribution_type=COALESCE(NULLIF(c->>'finance_classification',''),contribution_type) WHERE id=v_id;
    END IF;

    IF v_line IS NOT NULL THEN
      UPDATE public.journal_entry_lines SET
        supplier_id=COALESCE(v_supplier,supplier_id),customer_id=COALESCE(v_customer,customer_id)
      WHERE id=v_line AND journal_entry_id=v_journal;
    END IF;

    IF v_type='fund_transfer' AND (v_from_bank IS NOT NULL OR v_to_bank IS NOT NULL) THEN
      SELECT from_bank_account_id,to_bank_account_id,journal_entry_id INTO v_from_old,v_to_old,v_journal
      FROM public.fund_transfers WHERE id=v_id FOR UPDATE;
      v_from_bank:=COALESCE(v_from_bank,v_from_old);
      v_to_bank:=COALESCE(v_to_bank,v_to_old);
      IF v_from_bank=v_to_bank THEN RAISE EXCEPTION 'From Bank and To Bank must be different'; END IF;
      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_from_new_coa,v_from_alias,v_from_currency
        FROM public.bank_accounts WHERE id=v_from_bank AND is_active;
      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_to_new_coa,v_to_alias,v_to_currency
        FROM public.bank_accounts WHERE id=v_to_bank AND is_active;
      SELECT coa_id INTO v_from_old_coa FROM public.bank_accounts WHERE id=v_from_old;
      SELECT coa_id INTO v_to_old_coa FROM public.bank_accounts WHERE id=v_to_old;
      IF v_from_new_coa IS NULL OR v_to_new_coa IS NULL THEN RAISE EXCEPTION 'Both transfer banks need active Bank Master posting accounts'; END IF;
      UPDATE public.journal_entry_lines SET account_id=v_from_new_coa
        WHERE journal_entry_id=v_journal AND account_id=v_from_old_coa AND COALESCE(credit,0)>0;
      UPDATE public.journal_entry_lines SET account_id=v_to_new_coa
        WHERE journal_entry_id=v_journal AND account_id=v_to_old_coa AND COALESCE(debit,0)>0;
      UPDATE public.fund_transfers SET from_bank_account_id=v_from_bank,to_bank_account_id=v_to_bank WHERE id=v_id;
    END IF;

    IF v_type='bank_reconciliation' AND v_link_id IS NOT NULL THEN
      IF v_link_type IS NULL THEN RAISE EXCEPTION 'Select the linked document type'; END IF;
      PERFORM public.link_bank_statement_line(v_id,v_link_type,v_link_id,COALESCE(NULLIF(c->>'payment_type',''),'supplier'));
    END IF;
  END LOOP;

  -- Existing RPC owns GL classification, bank master mapping, tax/currency
  -- metadata, balance protection, audit logging and reason-specific verification.
  v_result:=public.save_finance_exception_corrections(p_corrections);

  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP
    v_exception:=NULLIF(c->>'exception_id','')::bigint;
    IF v_exception IS NOT NULL AND COALESCE((c->>'confirm_resolved')::boolean,false)
       AND EXISTS (
         SELECT 1 FROM jsonb_each_text(c) x
         WHERE x.key IN ('expense_category','expense_subcategory','account_id','bank_account_id','from_bank_account_id',
           'to_bank_account_id','loan_account_id','capital_account_id','tax_code_id','payment_type','document_classification',
           'exchange_rate','faktur_pajak_number','supplier_id','customer_id','reference','finance_classification','linked_document_id')
           AND NULLIF(x.value,'') IS NOT NULL
       ) THEN
      UPDATE public.finance_historical_repair_exceptions SET status='resolved'
      WHERE id=v_exception AND status='manual_review';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.finance_exception_correction_dashboard x
      WHERE x.document_type=c->>'document_type' AND x.document_id=(c->>'document_id')::uuid
    ) THEN v_resolved_ids:=v_resolved_ids || jsonb_build_array(c->>'row_id'); END IF;
  END LOOP;

  RETURN v_result || jsonb_build_object('resolved_row_ids',v_resolved_ids,'verification_refreshed',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_expense(p_expense_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_id uuid;
  v_orig_line_id uuid;
  v_date date;
  v_cat text;
  v_pay_method text;
  v_bank_id uuid;
  v_bank_currency text;
  v_currency text;
  v_rate numeric;
  v_docs text[];
  v_sup_id uuid;
  v_staff_id uuid;
  v_payee_id uuid;
  v_ppn_amt numeric;
  v_pph_amt numeric;
  v_pph_treatment text;
  v_bpjs_ded numeric;
  v_bpjs_item_id uuid;
  v_p_month integer;
  v_p_year integer;
  v_desc text;
  v_month_match text[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF COALESCE((p_payload->>'amount')::numeric, 0) <= 0 THEN
    RAISE EXCEPTION 'Expense amount must be greater than zero';
  END IF;

  v_cat := p_payload->>'expense_category';
  IF v_cat IS NULL OR v_cat = '' THEN
    RAISE EXCEPTION 'Expense category is required';
  END IF;

  v_date := COALESCE((p_payload->>'expense_date')::date, CURRENT_DATE);
  v_pay_method := NULLIF(p_payload->>'payment_method', '');
  v_bank_id := NULLIF(p_payload->>'bank_account_id', '')::uuid;

  IF v_bank_id IS NOT NULL THEN
    SELECT currency INTO v_bank_currency FROM public.bank_accounts WHERE id = v_bank_id;
    IF v_bank_currency IS NULL THEN
      RAISE EXCEPTION 'Selected bank account does not exist';
    END IF;
  END IF;

  v_currency := COALESCE(NULLIF(p_payload->>'transaction_currency', ''), v_bank_currency, 'IDR');
  IF v_currency = 'USD' THEN
    v_rate := COALESCE((p_payload->>'exchange_rate')::numeric, 1);
    IF v_rate <= 1 THEN
      RAISE EXCEPTION 'A valid USD rate greater than 1 is required';
    END IF;
  ELSE
    v_currency := 'IDR';
    v_rate := 1;
  END IF;

  IF p_payload ? 'document_urls' THEN
    SELECT COALESCE(array_agg(elem::text), ARRAY[]::text[])
      INTO v_docs
      FROM jsonb_array_elements_text(p_payload->'document_urls') AS elem;
  ELSE
    v_docs := ARRAY[]::text[];
  END IF;

  v_sup_id := NULLIF(p_payload->>'supplier_id', '')::uuid;
  v_staff_id := NULLIF(p_payload->>'staff_id', '')::uuid;
  v_payee_id := NULLIF(p_payload->>'payee_id', '')::uuid;

  v_ppn_amt := COALESCE(NULLIF(p_payload->>'ppn_amount', '')::numeric, 0);
  v_pph_amt := COALESCE(NULLIF(p_payload->>'pph_amount', '')::numeric, 0);
  v_pph_treatment := COALESCE(NULLIF(p_payload->>'pph_treatment', ''), 'deduct');

  -- Salary and BPJS period handling
  v_bpjs_ded := COALESCE(NULLIF(p_payload->>'bpjs_employee_deduction', '')::numeric, 0);
  v_bpjs_item_id := NULLIF(p_payload->>'bpjs_register_item_id', '')::uuid;
  v_p_month := NULLIF(p_payload->>'payroll_period_month', '')::integer;
  v_p_year := NULLIF(p_payload->>'payroll_period_year', '')::integer;
  v_desc := NULLIF(p_payload->>'description', '');

  IF v_cat = 'salary' THEN
    -- Parse payroll period if missing
    IF v_p_month IS NULL OR v_p_year IS NULL THEN
      IF v_desc ~ '·\s*([A-Za-z]{3})-(\d{2})' THEN
        v_month_match := regexp_matches(v_desc, '·\s*([A-Za-z]{3})-(\d{2})');
        v_p_year := 2000 + v_month_match[2]::integer;
        v_p_month := CASE lower(v_month_match[1])
          WHEN 'jan' THEN 1 WHEN 'feb' THEN 2 WHEN 'mar' THEN 3 WHEN 'apr' THEN 4
          WHEN 'may' THEN 5 WHEN 'jun' THEN 6 WHEN 'jul' THEN 7 WHEN 'aug' THEN 8
          WHEN 'sep' THEN 9 WHEN 'oct' THEN 10 WHEN 'nov' THEN 11 WHEN 'dec' THEN 12
          ELSE EXTRACT(MONTH FROM v_date)::integer
        END;
      ELSE
        v_p_year := EXTRACT(YEAR FROM v_date)::integer;
        v_p_month := EXTRACT(MONTH FROM v_date)::integer;
      END IF;
    END IF;

    -- Derive BPJS deduction from Staff Master if not provided
    IF v_bpjs_ded = 0 AND v_staff_id IS NOT NULL THEN
      DECLARE
        v_sal_calc jsonb;
      BEGIN
        v_sal_calc := public.calculate_staff_salary(v_staff_id, v_date, (p_payload->>'amount')::numeric);
        v_bpjs_ded := COALESCE((v_sal_calc->>'bpjs_amount')::numeric, 0);
      EXCEPTION WHEN OTHERS THEN
        v_bpjs_ded := 0;
      END;
    END IF;

    -- Link BPJS register item if not explicitly passed
    IF v_bpjs_item_id IS NULL AND v_staff_id IS NOT NULL AND v_p_year IS NOT NULL AND v_p_month IS NOT NULL THEN
      SELECT ri.id INTO v_bpjs_item_id
        FROM public.bpjs_monthly_register_items ri
        JOIN public.bpjs_monthly_registers r ON r.id = ri.register_id
       WHERE ri.staff_id = v_staff_id
         AND r.period_year = v_p_year
         AND r.period_month = v_p_month
       LIMIT 1;
    END IF;
  END IF;

  v_orig_line_id := NULLIF(p_payload->>'originating_bank_statement_line_id', '')::uuid;

  IF p_expense_id IS NULL THEN
    INSERT INTO public.finance_expenses (
      expense_category, expense_type, amount, expense_date, description, batch_id,
      import_container_id, delivery_challan_id,
      payment_method, bank_account_id, payment_reference,
      paid_by, document_urls,
      supplier_id, staff_id, payee_id,
      linked_sales_invoice_id,
      pph_calculation_regime,
      pph_dpp_ratio,
      pph_dpp_amount,
      pph_rate,
      is_tax_manual_override,
      invoice_number, due_date,
      broker_items, pib_bm_amount,
      pib_ppn_amount, pib_pph_amount,
      ppn_amount, ppn_manual_override,
      ppn_calc_mode, dpp_amount,
      ppn_rate, pph_amount,
      pph_code_id, pph_treatment,
      stamp_duty_amount,
      fixed_asset_account_id,
      bank_charges_amount,
      approval_status,
      created_by,
      currency_code, transaction_currency, functional_currency, exchange_rate, bank_account_currency, payment_currency,
      sales_order_allocations,
      originating_bank_statement_line_id,
      bpjs_employee_deduction,
      bpjs_register_item_id,
      payroll_period_month,
      payroll_period_year
    ) VALUES (
      v_cat, COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),
      (p_payload->>'amount')::numeric, v_date, v_desc, NULLIF(p_payload->>'batch_id','')::uuid,
      NULLIF(p_payload->>'import_container_id','')::uuid, NULLIF(p_payload->>'delivery_challan_id','')::uuid,
      v_pay_method, v_bank_id, NULLIF(p_payload->>'payment_reference',''),
      NULLIF(p_payload->>'paid_by',''), NULLIF(v_docs, ARRAY[]::text[]),
      v_sup_id, v_staff_id, v_payee_id,
      NULLIF(p_payload->>'linked_sales_invoice_id', '')::uuid,
      NULLIF(p_payload->>'pph_calculation_regime', ''),
      NULLIF(p_payload->>'pph_dpp_ratio', '')::numeric,
      NULLIF(p_payload->>'pph_dpp_amount', '')::numeric,
      NULLIF(p_payload->>'pph_rate', '')::numeric,
      COALESCE((p_payload->>'is_tax_manual_override')::boolean, false),
      NULLIF(p_payload->>'invoice_number',''), NULLIF(p_payload->>'due_date','')::date,
      NULLIF(p_payload->'broker_items','null'::jsonb), NULLIF(p_payload->>'pib_bm_amount','')::numeric,
      NULLIF(p_payload->>'pib_ppn_amount','')::numeric, NULLIF(p_payload->>'pib_pph_amount','')::numeric,
      v_ppn_amt, COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
      COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'), NULLIF(p_payload->>'dpp_amount','')::numeric,
      COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11), v_pph_amt,
      NULLIF(p_payload->>'pph_code_id','')::uuid, v_pph_treatment,
      COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
      NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
      COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
      COALESCE(NULLIF(p_payload->>'approval_status',''),'pending_approval'),
      COALESCE(NULLIF(p_payload->>'created_by','')::uuid, auth.uid()),
      v_currency, v_currency, 'IDR', v_rate, COALESCE(v_bank_currency,v_currency), v_currency,
      COALESCE(p_payload->'sales_order_allocations', '[]'::jsonb),
      v_orig_line_id,
      v_bpjs_ded,
      v_bpjs_item_id,
      v_p_month,
      v_p_year
    ) RETURNING id INTO v_id;
  ELSE
    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN
      RAISE EXCEPTION 'This expense is posted. Cancel Posting first to make changes.';
    END IF;
    UPDATE public.finance_expenses SET
      expense_category=v_cat, expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),
      amount=(p_payload->>'amount')::numeric, expense_date=v_date, description=v_desc,
      batch_id=NULLIF(p_payload->>'batch_id','')::uuid, import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,
      delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,
      payment_method=v_pay_method, bank_account_id=v_bank_id,
      payment_reference=NULLIF(p_payload->>'payment_reference',''), paid_by=NULLIF(p_payload->>'paid_by',''),
      document_urls=NULLIF(v_docs,ARRAY[]::text[]), supplier_id=v_sup_id,
      staff_id=v_staff_id, payee_id=v_payee_id,
      linked_sales_invoice_id=NULLIF(p_payload->>'linked_sales_invoice_id', '')::uuid,
      pph_calculation_regime=NULLIF(p_payload->>'pph_calculation_regime', ''),
      pph_dpp_ratio=NULLIF(p_payload->>'pph_dpp_ratio', '')::numeric,
      pph_dpp_amount=NULLIF(p_payload->>'pph_dpp_amount', '')::numeric,
      pph_rate=NULLIF(p_payload->>'pph_rate', '')::numeric,
      is_tax_manual_override=COALESCE((p_payload->>'is_tax_manual_override')::boolean, false),
      invoice_number=NULLIF(p_payload->>'invoice_number',''),
      due_date=NULLIF(p_payload->>'due_date','')::date, broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),
      pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,
      pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,
      pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,
      ppn_amount=v_ppn_amt,
      ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),
      ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),
      dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric, ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),
      pph_amount=v_pph_amt, pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,
      pph_treatment=v_pph_treatment,
      stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),
      fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,
      bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),
      currency_code=v_currency, transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate,
      bank_account_currency=COALESCE(v_bank_currency,v_currency), payment_currency=v_currency,
      sales_order_allocations=COALESCE(p_payload->'sales_order_allocations', '[]'::jsonb),
      originating_bank_statement_line_id=COALESCE(v_orig_line_id, originating_bank_statement_line_id),
      bpjs_employee_deduction=v_bpjs_ded,
      bpjs_register_item_id=v_bpjs_item_id,
      payroll_period_month=v_p_month,
      payroll_period_year=v_p_year
    WHERE id=p_expense_id RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_journal(p_entry_id uuid DEFAULT NULL::uuid, p_entry_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb, p_transaction_currency text DEFAULT 'IDR'::text, p_exchange_rate numeric DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
  v_line jsonb;
  v_dr numeric:=0;
  v_cr numeric:=0;
  v_factor numeric;
  v_num text;
  v_i int:=0;
BEGIN
  PERFORM public._sec_check_finance_role();
  p_transaction_currency:=upper(COALESCE(p_transaction_currency,'IDR'));
  IF p_transaction_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported journal currency'; END IF;
  IF p_exchange_rate IS NULL OR p_exchange_rate<=0 OR (p_transaction_currency='USD' AND p_exchange_rate<=1) THEN
    RAISE EXCEPTION 'A valid exchange rate is required';
  END IF;
  v_factor:=CASE WHEN p_transaction_currency='IDR' THEN 1 ELSE p_exchange_rate END;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_dr:=v_dr+COALESCE((v_line->>'debit')::numeric,0);
    v_cr:=v_cr+COALESCE((v_line->>'credit')::numeric,0);
  END LOOP;
  IF v_dr<=0 OR abs(v_dr-v_cr)>0.01 THEN RAISE EXCEPTION 'Journal must be balanced and greater than zero'; END IF;

  IF p_entry_id IS NULL THEN
    v_num:=public.generate_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,description,source_module,total_debit,total_credit,
      is_posted,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_num,p_entry_date,NULLIF(p_description,''),'manual',round(v_dr*v_factor,2),round(v_cr*v_factor,2),
      true,auth.uid(),auth.uid(),p_transaction_currency,'IDR',v_factor,true)
    RETURNING id INTO v_id;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.journal_entries WHERE id=p_entry_id AND source_module='manual') THEN
      RAISE EXCEPTION 'Only manual journals can be edited';
    END IF;
    v_id:=p_entry_id;
    UPDATE public.journal_entries SET entry_date=p_entry_date,description=NULLIF(p_description,''),
      total_debit=round(v_dr*v_factor,2),total_credit=round(v_cr*v_factor,2),transaction_currency=p_transaction_currency,
      functional_currency='IDR',exchange_rate=v_factor,amounts_are_functional=true WHERE id=v_id;
    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_id;
  END IF;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    IF COALESCE((v_line->>'debit')::numeric,0)>0 OR COALESCE((v_line->>'credit')::numeric,0)>0 THEN
      v_i:=v_i+1;
      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
        transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)
      VALUES(v_id,v_i,(v_line->>'account_id')::uuid,NULLIF(v_line->>'description',''),
        round(COALESCE((v_line->>'debit')::numeric,0)*v_factor,2),
        round(COALESCE((v_line->>'credit')::numeric,0)*v_factor,2),p_transaction_currency,
        COALESCE((v_line->>'debit')::numeric,0),COALESCE((v_line->>'credit')::numeric,0),'IDR',v_factor);
    END IF;
  END LOOP;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_loan(p_payload jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid := gen_random_uuid();
  v_number text;
  v_je uuid;
  v_coa uuid;
  v_line public.bank_statement_lines%ROWTYPE;
  v_amount numeric;
  v_date date;
  v_loan_type text;
  v_counterparty text;
  v_counterparty_type text;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date := (p_payload->>'loan_date')::date;
  v_amount := (p_payload->>'principal_amount')::numeric;
  v_loan_type := COALESCE(NULLIF(p_payload->>'loan_type', ''), 'taken');
  v_counterparty := trim(p_payload->>'counterparty_name');

  IF NULLIF(v_counterparty, '') IS NULL OR v_amount <= 0 THEN
    RAISE EXCEPTION 'Loan counterparty and positive principal are required';
  END IF;

  -- Resolve counterparty_type
  v_counterparty_type := COALESCE(NULLIF(p_payload->>'counterparty_type', ''), 'person');
  IF v_counterparty_type = 'bank' AND v_counterparty !~* 'bank|bca|mandiri|bni|bri|cimb|danamon|permata|uob' THEN
    v_counterparty_type := 'person';
  END IF;

  -- 1. Account resolution: user-selected coa_id takes top priority
  IF NULLIF(p_payload->>'coa_id', '') IS NOT NULL THEN
    SELECT id INTO v_coa
    FROM public.chart_of_accounts
    WHERE id = (p_payload->>'coa_id')::uuid
      AND is_active = true
      AND COALESCE(is_header, false) = false;
  ELSIF p_payload->>'liability_kind' = 'director_owner' THEN
    SELECT id INTO v_coa
    FROM public.chart_of_accounts
    WHERE id = NULLIF(p_payload->>'liability_account_id', '')::uuid
      AND is_active = true
      AND COALESCE(is_header, false) = false
      AND lower(account_type) = 'liability';
  END IF;

  -- Fallback if no coa was provided
  IF v_coa IS NULL THEN
    IF v_loan_type = 'given' THEN
      SELECT id INTO v_coa FROM public.chart_of_accounts WHERE code = '1310' AND is_active = true LIMIT 1;
    ELSE
      -- loan taken
      IF v_counterparty_type = 'person' THEN
        SELECT id INTO v_coa FROM public.chart_of_accounts WHERE code = '2105' AND is_active = true LIMIT 1;
      ELSE
        SELECT id INTO v_coa FROM public.chart_of_accounts WHERE code = '2210' AND is_active = true LIMIT 1;
      END IF;
    END IF;
  END IF;

  IF v_coa IS NULL THEN
    RAISE EXCEPTION 'Required loan control account is not configured';
  END IF;

  -- 2. Validate Bank Statement Line based on direction
  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line
    FROM public.bank_statement_lines
    WHERE id = p_bank_statement_line_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Bank statement line not found';
    END IF;

    IF v_loan_type = 'given' THEN
      IF COALESCE(v_line.debit_amount, 0) <> v_amount THEN
        RAISE EXCEPTION 'Bank statement line debit amount (%) does not match loan amount (%)', v_line.debit_amount, v_amount;
      END IF;
    ELSE
      IF COALESCE(v_line.credit_amount, 0) <> v_amount THEN
        RAISE EXCEPTION 'Bank statement line credit amount (%) does not match loan amount (%)', v_line.credit_amount, v_amount;
      END IF;
    END IF;

    IF v_line.bank_account_id <> (p_payload->>'bank_account_id')::uuid THEN
      RAISE EXCEPTION 'Bank account mismatch on bank statement line';
    END IF;

    IF v_line.matched_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'Bank statement line is already linked';
    END IF;
  END IF;

  v_number := public.next_loan_number(v_date);
  INSERT INTO public.loans(
    id, loan_number, loan_type, counterparty_name, counterparty_type,
    principal_amount, interest_rate, loan_date, bank_account_id, coa_id,
    currency, transaction_currency, functional_currency, exchange_rate,
    bank_account_currency, description, created_by, bank_statement_line_id
  )
  VALUES (
    v_id, v_number, v_loan_type, v_counterparty,
    v_counterparty_type,
    v_amount, 0, v_date, (p_payload->>'bank_account_id')::uuid, v_coa,
    upper(p_payload->>'transaction_currency'), upper(p_payload->>'transaction_currency'),
    'IDR', (p_payload->>'exchange_rate')::numeric,
    upper(p_payload->>'transaction_currency'), COALESCE(p_payload->>'description', ''),
    COALESCE(NULLIF(p_payload->>'created_by', '')::uuid, auth.uid()),
    p_bank_statement_line_id
  )
  RETURNING journal_entry_id INTO v_je;

  IF p_bank_statement_line_id IS NOT NULL THEN
    PERFORM public._link_native_bank_document(
      p_bank_statement_line_id,
      v_je,
      'Loan - ' || v_number
    );
  END IF;

  RETURN jsonb_build_object('id', v_id, 'loan_number', v_number, 'journal_entry_id', v_je);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_finance_loan_repayment(p_payload jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid := gen_random_uuid();
  v_number text;
  v_je uuid;
  v_line public.bank_statement_lines%ROWTYPE;
  v_amount numeric;
  v_date date;
  v_loan public.loans%ROWTYPE;
BEGIN
  PERFORM public._sec_check_finance_role();
  v_date := (p_payload->>'transaction_date')::date;
  v_amount := COALESCE((p_payload->>'principal_amount')::numeric, 0) + COALESCE((p_payload->>'interest_amount')::numeric, 0);

  SELECT * INTO v_loan FROM public.loans WHERE id = (p_payload->>'loan_id')::uuid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Loan not found';
  END IF;

  IF p_bank_statement_line_id IS NOT NULL THEN
    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id = p_bank_statement_line_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Bank statement line not found';
    END IF;

    -- For loan taken (borrowing): repayment is a bank DEBIT (cash outflow)
    -- For loan given (receivable): repayment is a bank CREDIT (cash inflow)
    IF v_loan.loan_type = 'given' THEN
      IF COALESCE(v_line.credit_amount, 0) <> v_amount THEN
        RAISE EXCEPTION 'Bank statement line credit (%) does not match repayment amount (%)', v_line.credit_amount, v_amount;
      END IF;
    ELSE
      IF COALESCE(v_line.debit_amount, 0) <> v_amount THEN
        RAISE EXCEPTION 'Bank statement line debit (%) does not match repayment amount (%)', v_line.debit_amount, v_amount;
      END IF;
    END IF;

    IF v_line.bank_account_id <> (p_payload->>'bank_account_id')::uuid THEN
      RAISE EXCEPTION 'Bank account mismatch on bank statement line';
    END IF;

    IF v_line.matched_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'Bank statement line is already linked';
    END IF;
  END IF;

  v_number := public.next_loan_transaction_number(v_date);
  INSERT INTO public.loan_transactions(
    id, transaction_number, loan_id, transaction_type, transaction_date,
    amount, principal_amount, interest_amount,
    bank_account_id, bank_statement_line_id, description, created_by,
    transaction_currency, functional_currency, exchange_rate, bank_account_currency
  )
  VALUES (
    v_id, v_number, v_loan.id, 'repayment', v_date,
    v_amount, (p_payload->>'principal_amount')::numeric,
    COALESCE((p_payload->>'interest_amount')::numeric, 0),
    (p_payload->>'bank_account_id')::uuid, p_bank_statement_line_id,
    COALESCE(p_payload->>'description', ''),
    COALESCE(NULLIF(p_payload->>'created_by', '')::uuid, auth.uid()),
    upper(p_payload->>'transaction_currency'), 'IDR',
    (p_payload->>'exchange_rate')::numeric, upper(p_payload->>'transaction_currency')
  )
  RETURNING journal_entry_id INTO v_je;

  IF p_bank_statement_line_id IS NOT NULL THEN
    PERFORM public._link_native_bank_document(
      p_bank_statement_line_id,
      v_je,
      'Loan Repayment - ' || v_number
    );
  END IF;

  RETURN jsonb_build_object('id', v_id, 'transaction_number', v_number, 'journal_entry_id', v_je);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_payment_voucher_command(p_voucher_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_allocations jsonb DEFAULT '[]'::jsonb, p_payment_purpose text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_number text;
  v_id uuid;
  v_date date := (p_payload->>'voucher_date')::date;
  v_payment_currency text := upper(COALESCE(NULLIF(p_payload->>'payment_currency',''),'IDR'));
  v_invoice_currency text := upper(COALESCE(
    NULLIF(p_payload->>'invoice_currency',''),
    NULLIF((SELECT COALESCE(a->>'currency',a->>'allocated_currency')
            FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) a
            WHERE COALESCE(a->>'currency',a->>'allocated_currency') IS NOT NULL LIMIT 1),''),
    v_payment_currency));
  v_bank_currency text;
  v_rate numeric := COALESCE(NULLIF(p_payload->>'exchange_rate','')::numeric,1);
  v_invoice_amount numeric := COALESCE(NULLIF(p_payload->>'invoice_amount','')::numeric,
    NULLIF(p_payload->>'amount','')::numeric,0);
  v_payment_amount numeric := COALESCE(NULLIF(p_payload->>'payment_amount','')::numeric,
    v_invoice_amount-COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0));
  v_converted numeric;
  v_actual numeric;
  v_bank_charge numeric := COALESCE(NULLIF(p_payload->>'bank_charge','')::numeric,0);
  v_docs text[];
  v_purpose text := COALESCE(p_payment_purpose, NULLIF(p_payload->>'payment_purpose',''), 'general');
  v_staff_id uuid := NULLIF(p_payload->>'staff_id','')::uuid;
  v_customer_id uuid := NULLIF(p_payload->>'customer_id','')::uuid;
  v_supplier_id uuid := NULLIF(p_payload->>'supplier_id','')::uuid;
  v_party_type text := lower(COALESCE(
    NULLIF(p_payload->>'party_type',''),
    CASE 
      WHEN v_staff_id IS NOT NULL OR v_purpose LIKE 'salary_%' OR v_purpose LIKE '%employee%' THEN 'employee'
      WHEN v_customer_id IS NOT NULL OR v_purpose LIKE 'customer_%' THEN 'customer'
      ELSE 'supplier'
    END
  ));
  v_settle_against text := COALESCE(NULLIF(p_payload->>'settlement_against',''), 'outstanding_balance');
  v_settle_disc numeric := COALESCE(NULLIF(p_payload->>'settlement_discount','')::numeric, 0);
  v_adj_reason text := NULLIF(p_payload->>'adjustment_reason','');
  v_adj_account_id uuid := NULLIF(p_payload->>'adjustment_account_id','')::uuid;
  v_adj_notes text := NULLIF(p_payload->>'adjustment_notes','');
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts
   WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;
  v_bank_currency:=COALESCE(v_bank_currency,v_payment_currency);
  IF v_payment_currency NOT IN('IDR','USD') OR v_invoice_currency NOT IN('IDR','USD')
     OR v_bank_currency NOT IN('IDR','USD') OR v_rate<=0 THEN
    RAISE EXCEPTION 'Payment currencies or exchange rate are invalid';
  END IF;
  v_converted:=COALESCE(NULLIF(p_payload->>'converted_amount','')::numeric,
    v_payment_amount*CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE v_rate END);
  v_actual:=COALESCE(NULLIF(p_payload->>'actual_bank_debit','')::numeric,
    NULLIF(p_payload->>'bank_amount','')::numeric,v_converted+v_bank_charge);
  IF v_actual<=0 AND v_invoice_amount>0 THEN RAISE EXCEPTION 'Actual bank debit must be positive'; END IF;
  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs
    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));

  SELECT voucher_number INTO v_number FROM public.payment_vouchers WHERE id=p_voucher_id;
  v_number:=COALESCE(v_number,public.next_payment_voucher_number(v_date));

  v_id:=public.save_payment_voucher_with_allocations(
    p_voucher_id=>p_voucher_id,
    p_voucher_number=>v_number,
    p_voucher_date=>v_date,
    p_supplier_id=>v_supplier_id,
    p_payment_method=>p_payload->>'payment_method',
    p_bank_account_id=>NULLIF(p_payload->>'bank_account_id','')::uuid,
    p_reference_number=>NULLIF(p_payload->>'reference_number',''),
    p_amount=>v_invoice_amount,
    p_pph_amount=>COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),
    p_pph_code_id=>NULLIF(p_payload->>'pph_code_id','')::uuid,
    p_description=>NULLIF(p_payload->>'description',''),
    p_payment_currency=>v_payment_currency,
    p_exchange_rate=>v_rate,
    p_bank_amount=>v_actual,
    p_bank_charge=>v_bank_charge,
    p_created_by=>COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),
    p_allocations=>p_allocations,
    p_staff_id=>v_staff_id,
    p_payment_purpose=>v_purpose,
    p_party_type=>v_party_type,
    p_customer_id=>v_customer_id,
    p_settlement_against=>v_settle_against,
    p_settlement_discount=>v_settle_disc,
    p_adjustment_reason=>v_adj_reason,
    p_adjustment_account_id=>v_adj_account_id,
    p_adjustment_notes=>v_adj_notes
  );

  UPDATE public.payment_vouchers SET
    invoice_currency=v_invoice_currency,
    invoice_amount=v_invoice_amount,
    payment_amount=v_payment_amount,
    payment_currency=v_payment_currency,
    transaction_currency=v_invoice_currency,
    functional_currency='IDR',
    exchange_rate=v_rate,
    bank_currency=v_bank_currency,
    bank_account_currency=v_bank_currency,
    converted_amount=v_converted,
    actual_bank_debit=v_actual,
    bank_amount=v_actual,
    document_urls=NULLIF(v_docs,ARRAY[]::text[])
  WHERE id=v_id;

  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_payment_voucher_with_allocations(p_voucher_id uuid DEFAULT NULL::uuid, p_voucher_number text DEFAULT NULL::text, p_voucher_date date DEFAULT NULL::date, p_supplier_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_bank_account_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_pph_amount numeric DEFAULT 0, p_pph_code_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_payment_currency text DEFAULT 'IDR'::text, p_exchange_rate numeric DEFAULT 1, p_bank_amount numeric DEFAULT NULL::numeric, p_bank_charge numeric DEFAULT 0, p_created_by uuid DEFAULT NULL::uuid, p_allocations jsonb DEFAULT '[]'::jsonb, p_staff_id uuid DEFAULT NULL::uuid, p_payment_purpose text DEFAULT 'general'::text, p_party_type text DEFAULT 'supplier'::text, p_customer_id uuid DEFAULT NULL::uuid, p_settlement_against text DEFAULT 'outstanding_balance'::text, p_settlement_discount numeric DEFAULT 0, p_adjustment_reason text DEFAULT NULL::text, p_adjustment_account_id uuid DEFAULT NULL::uuid, p_adjustment_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_voucher_id UUID;
  v_alloc JSONB;
  v_alloc_amount NUMERIC;
  v_alloc_discount NUMERIC;
  v_invoice_id UUID;
  v_expense_id UUID;
  v_creator UUID;
  v_purpose TEXT := COALESCE(p_payment_purpose, 'general');
  v_party_type TEXT := lower(COALESCE(p_party_type, 'supplier'));
BEGIN
  PERFORM public._sec_check_finance_role();
  v_creator := auth.uid();
  IF v_creator IS NULL THEN
    IF current_user = 'service_role' OR session_user = 'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) THEN
      v_creator := COALESCE(p_created_by, 'a0000000-0000-0000-0000-000000000001'::uuid);
    END IF;
  END IF;

  IF v_party_type NOT IN ('customer', 'supplier', 'employee', 'director', 'other') THEN
    RAISE EXCEPTION 'Unsupported party type %', v_party_type;
  END IF;

  IF v_party_type = 'supplier' AND p_supplier_id IS NULL AND p_staff_id IS NULL THEN
    RAISE EXCEPTION 'Supplier is required for supplier payment';
  END IF;

  IF v_party_type = 'customer' AND p_customer_id IS NULL THEN
    RAISE EXCEPTION 'Customer is required for customer refund payment';
  END IF;

  IF v_party_type = 'employee' AND p_staff_id IS NULL THEN
    RAISE EXCEPTION 'Staff member is required for employee payment';
  END IF;

  IF p_settlement_discount < 0 THEN
    RAISE EXCEPTION 'Settlement discount cannot be negative';
  END IF;

  IF p_settlement_discount <> 0 AND (p_adjustment_reason IS NULL OR trim(p_adjustment_reason) = '') THEN
    RAISE EXCEPTION 'Adjustment reason is mandatory when settlement discount/difference is non-zero';
  END IF;

  IF p_voucher_id IS NULL THEN
    INSERT INTO payment_vouchers (
      voucher_number, voucher_date, party_type, supplier_id, customer_id, staff_id, payment_method,
      bank_account_id, reference_number, amount, pph_amount, pph_code_id,
      description, payment_currency, exchange_rate,
      bank_amount, bank_charge, created_by,
      payment_purpose, salary_advance_status,
      settlement_against, settlement_discount, adjustment_reason, adjustment_account_id, adjustment_notes
    ) VALUES (
      p_voucher_number, p_voucher_date, v_party_type, p_supplier_id, p_customer_id, p_staff_id, COALESCE(NULLIF(p_payment_method,''), 'bank_transfer'),
      p_bank_account_id, p_reference_number, p_amount, p_pph_amount, p_pph_code_id,
      p_description, p_payment_currency, p_exchange_rate,
      p_bank_amount, p_bank_charge, v_creator,
      v_purpose,
      CASE v_purpose WHEN 'salary_advance' THEN 'outstanding' ELSE 'not_applicable' END,
      p_settlement_against, p_settlement_discount, p_adjustment_reason, p_adjustment_account_id, p_adjustment_notes
    ) RETURNING id INTO v_voucher_id;
  ELSE
    v_voucher_id := p_voucher_id;

    IF EXISTS (SELECT 1 FROM payment_vouchers WHERE id = v_voucher_id AND is_posted = TRUE) THEN
      RAISE EXCEPTION 'Cannot edit: % is posted. Cancel Posting first to make changes.', p_voucher_number;
    END IF;

    UPDATE payment_vouchers SET
      voucher_date          = p_voucher_date,
      party_type            = v_party_type,
      supplier_id           = p_supplier_id,
      customer_id           = p_customer_id,
      staff_id              = p_staff_id,
      payment_method        = COALESCE(NULLIF(p_payment_method,''), 'bank_transfer'),
      bank_account_id       = p_bank_account_id,
      reference_number      = p_reference_number,
      amount                = p_amount,
      pph_amount            = p_pph_amount,
      pph_code_id           = p_pph_code_id,
      description           = p_description,
      payment_currency      = p_payment_currency,
      exchange_rate         = p_exchange_rate,
      bank_amount           = p_bank_amount,
      bank_charge           = p_bank_charge,
      payment_purpose       = v_purpose,
      salary_advance_status = CASE v_purpose WHEN 'salary_advance' THEN 'outstanding' ELSE 'not_applicable' END,
      settlement_against    = p_settlement_against,
      settlement_discount   = p_settlement_discount,
      adjustment_reason     = p_adjustment_reason,
      adjustment_account_id = p_adjustment_account_id,
      adjustment_notes      = p_adjustment_notes,
      updated_at            = NOW()
    WHERE id = v_voucher_id;
  END IF;

  DELETE FROM voucher_allocations WHERE payment_voucher_id = v_voucher_id;

  FOR v_alloc IN SELECT value FROM jsonb_array_elements(p_allocations) AS value
  LOOP
    v_alloc_amount := COALESCE((v_alloc->>'amount')::NUMERIC, 0);
    IF v_alloc_amount <= 0 THEN
      CONTINUE;
    END IF;

    v_alloc_discount := COALESCE((v_alloc->>'settlement_discount')::NUMERIC, 0);
    IF v_alloc_discount < 0 THEN
      RAISE EXCEPTION 'Settlement discount cannot be negative';
    END IF;

    v_invoice_id := NULLIF(v_alloc->>'invoice_id', '')::UUID;
    v_expense_id := NULLIF(v_alloc->>'finance_expense_id', '')::UUID;

    IF v_invoice_id IS NOT NULL THEN
      INSERT INTO voucher_allocations (
        payment_voucher_id, purchase_invoice_id,
        allocated_amount, allocated_currency, voucher_type,
        settlement_discount, adjustment_reason, notes
      ) VALUES (
        v_voucher_id, v_invoice_id, v_alloc_amount,
        COALESCE(v_alloc->>'currency', 'IDR'), 'payment',
        v_alloc_discount,
        NULLIF(v_alloc->>'adjustment_reason', ''),
        NULLIF(v_alloc->>'notes', '')
      );
    ELSIF v_expense_id IS NOT NULL THEN
      INSERT INTO voucher_allocations (
        payment_voucher_id, finance_expense_id,
        allocated_amount, allocated_currency, voucher_type,
        settlement_discount, adjustment_reason, notes
      ) VALUES (
        v_voucher_id, v_expense_id, v_alloc_amount,
        COALESCE(v_alloc->>'currency', 'IDR'), 'payment',
        v_alloc_discount,
        NULLIF(v_alloc->>'adjustment_reason', ''),
        NULLIF(v_alloc->>'notes', '')
      );
    END IF;
  END LOOP;

  RETURN v_voucher_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_purchase_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  DECLARE
    v_invoice_id        UUID;
    v_je_id             UUID;
    v_je_number         TEXT;
    v_ap_account_id     UUID;
    v_ppn_account_id    UUID;
    v_bm_account_id     UUID;
    v_account_id        UUID;
    v_item              JSONB;
    v_line_number       INTEGER;
    v_invoice_date      DATE;
    v_invoice_number    TEXT;
    v_supplier_id       UUID;
    v_total_amount      NUMERIC(15,2);
    v_tax_amount        NUMERIC(15,2);
    v_stamp_duty_amount NUMERIC(15,2);
    v_created_by        UUID;
    v_item_type         TEXT;
    v_line_total        NUMERIC(15,2);
    v_item_id           UUID;
    v_po_id             UUID;
    v_currency          TEXT;
    v_rate              NUMERIC;

    -- Batch resolution variables
    v_product_id        UUID;
    v_make_id           UUID;
    v_batch_number      TEXT;
    v_container_id      UUID;
    v_expiry_date       DATE;
    v_quantity          NUMERIC;
    v_unit_price        NUMERIC;
    v_unit              TEXT;
    v_batch_id          UUID;
    v_resolved_batch_id UUID;
  BEGIN
    v_created_by        := auth.uid();
    v_invoice_date      := (p_invoice_data->>'invoice_date')::DATE;
    v_invoice_number    := p_invoice_data->>'invoice_number';
    v_total_amount      := (p_invoice_data->>'total_amount')::NUMERIC(15,2);
    v_tax_amount        := COALESCE((p_invoice_data->>'tax_amount')::NUMERIC(15,2), 0);
    v_stamp_duty_amount := COALESCE((p_invoice_data->>'stamp_duty_amount')::NUMERIC(15,2), 0);
    v_supplier_id       := (p_invoice_data->>'supplier_id')::UUID;
    v_po_id             := NULLIF(p_invoice_data->>'purchase_order_id', '')::UUID;
    v_currency := upper(coalesce(p_invoice_data->>'currency', 'IDR'));
    v_rate := CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULLIF((p_invoice_data->>'exchange_rate')::NUMERIC, 0) END;
    IF v_currency <> 'IDR' AND (v_rate IS NULL OR v_rate <= 1) THEN
      RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate greater than 1', v_invoice_number;
    END IF;

    SELECT id INTO v_ap_account_id  FROM chart_of_accounts WHERE code = '2110' LIMIT 1;
    SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;
    SELECT id INTO v_bm_account_id  FROM chart_of_accounts WHERE code = '6950' LIMIT 1;

    IF v_ap_account_id IS NULL THEN
      RAISE EXCEPTION 'A/P account (code 2110) not found in chart of accounts';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext('je_number_' || TO_CHAR(v_invoice_date, 'YYMM')));

    IF p_invoice_id IS NULL THEN
      -- ── CREATE path ──────────────────────────────────────────────────────────

      v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((
        SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\d+)$') AS INTEGER)), 0) + 1
        FROM journal_entries
        WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'
      )::TEXT, 4, '0');

      INSERT INTO journal_entries (
        entry_number, entry_date, source_module, reference_id, reference_number,
        description, total_debit, total_credit, is_posted, posted_by, created_by
      ) VALUES (
        v_je_number, v_invoice_date, 'purchase_invoice', gen_random_uuid(), v_invoice_number,
        'Purchase Invoice: ' || v_invoice_number,
        0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by
      ) RETURNING id INTO v_je_id;

      INSERT INTO purchase_invoices (
        invoice_number, supplier_id, invoice_date, due_date,
        currency, exchange_rate, subtotal, tax_amount, stamp_duty_amount, total_amount,
        paid_amount, status,
        faktur_pajak_number, notes, document_urls,
        requires_faktur_pajak, purchase_type,
        purchase_order_id,
        journal_entry_id, created_by
      ) VALUES (
        v_invoice_number,
        v_supplier_id,
        v_invoice_date,
        NULLIF(p_invoice_data->>'due_date', '')::DATE,
        COALESCE(p_invoice_data->>'currency', 'IDR'),
        COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),
        COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),
        v_tax_amount,
        v_stamp_duty_amount,
        v_total_amount,
        0,
        'unpaid',
        NULLIF(p_invoice_data->>'faktur_pajak_number', ''),
        NULLIF(p_invoice_data->>'notes', ''),
        CASE
          WHEN p_invoice_data -> 'document_urls' IS NOT NULL
            AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0
          THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))
          ELSE NULL
        END,
        COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),
        COALESCE(p_invoice_data->>'purchase_type', 'inventory'),
        v_po_id,
        v_je_id,
        v_created_by
      ) RETURNING id INTO v_invoice_id;

      UPDATE journal_entries SET reference_id = v_invoice_id WHERE id = v_je_id;

    ELSE
      -- ── EDIT path ──────────────────────────────────────────────────────────

      v_invoice_id := p_invoice_id;

      SELECT journal_entry_id INTO v_je_id
      FROM purchase_invoices WHERE id = v_invoice_id;

      UPDATE purchase_invoices SET
        invoice_number        = v_invoice_number,
        supplier_id           = v_supplier_id,
        invoice_date          = v_invoice_date,
        due_date              = NULLIF(p_invoice_data->>'due_date', '')::DATE,
        currency              = COALESCE(p_invoice_data->>'currency', 'IDR'),
        exchange_rate         = COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),
        subtotal              = COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),
        tax_amount            = v_tax_amount,
        stamp_duty_amount     = v_stamp_duty_amount,
        total_amount          = v_total_amount,
        faktur_pajak_number   = NULLIF(p_invoice_data->>'faktur_pajak_number', ''),
        notes                 = NULLIF(p_invoice_data->>'notes', ''),
        document_urls         = CASE
                                  WHEN p_invoice_data -> 'document_urls' IS NOT NULL
                                    AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0
                                  THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))
                                  ELSE NULL
                                END,
        requires_faktur_pajak = COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),
        purchase_type         = COALESCE(p_invoice_data->>'purchase_type', 'inventory'),
        purchase_order_id     = v_po_id,
        updated_at            = NOW()
      WHERE id = v_invoice_id;

      IF EXISTS (
        SELECT 1 FROM purchase_invoice_items i 
        WHERE i.purchase_invoice_id = v_invoice_id 
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x 
            WHERE NULLIF(x->>'id','')::uuid = i.id
          ) 
          AND (
            EXISTS (SELECT 1 FROM purchase_invoice_receiving_allocations a WHERE a.purchase_invoice_item_id = i.id) 
            OR i.batch_id IS NOT NULL
          )
      ) THEN 
        RAISE EXCEPTION 'Cannot remove invoice line with receiving or inventory history'; 
      END IF;

      DELETE FROM purchase_invoice_items i 
      WHERE i.purchase_invoice_id = v_invoice_id 
        AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x 
          WHERE NULLIF(x->>'id','')::uuid = i.id
        );

      IF v_je_id IS NOT NULL THEN
        DELETE FROM journal_entry_lines WHERE journal_entry_id = v_je_id;
        UPDATE journal_entries SET
          entry_date       = v_invoice_date,
          reference_number = v_invoice_number,
          description      = 'Purchase Invoice: ' || v_invoice_number,
          total_debit      = 0,
          total_credit     = v_total_amount * v_rate
        WHERE id = v_je_id;
      ELSE
        v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((
          SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\d+)$') AS INTEGER)), 0) + 1
          FROM journal_entries
          WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'
        )::TEXT, 4, '0');

        INSERT INTO journal_entries (
          entry_number, entry_date, source_module, reference_id, reference_number,
          description, total_debit, total_credit, is_posted, posted_by, created_by
        ) VALUES (
          v_je_number, v_invoice_date, 'purchase_invoice', v_invoice_id, v_invoice_number,
          'Purchase Invoice: ' || v_invoice_number,
          0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by
        ) RETURNING id INTO v_je_id;

        UPDATE purchase_invoices SET journal_entry_id = v_je_id WHERE id = v_invoice_id;
      END IF;
    END IF;

    -- ── Insert/Update items and build JE debit lines ───────────────────────────
    v_line_number := 1;

    FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
    LOOP
      v_item_type    := v_item->>'item_type';
      v_line_total   := COALESCE((v_item->>'line_total')::NUMERIC(15,2), 0);
      v_item_id      := NULLIF(v_item->>'id', '')::UUID;
      v_product_id   := NULLIF(v_item->>'product_id', '')::UUID;
      v_make_id      := NULLIF(v_item->>'receiving_make_id', '')::UUID;
      v_batch_number := NULLIF(TRIM(v_item->>'receiving_batch_number'), '');
      v_container_id := NULLIF(v_item->>'receiving_import_container_id', '')::UUID;
      v_expiry_date  := NULLIF(v_item->>'receiving_expiry_date', '')::DATE;
      v_quantity     := COALESCE((v_item->>'quantity')::NUMERIC, 1);
      v_unit_price   := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
      v_unit         := v_item->>'unit';
      v_batch_id     := NULLIF(v_item->>'batch_id', '')::UUID;
      v_resolved_batch_id := NULL;

      -- ── Resolve or create batch if item has a Batch Number ────────────────
      IF v_item_type = 'inventory' AND v_product_id IS NOT NULL AND v_batch_number IS NOT NULL THEN
        -- 1. Check if provided batch_id matches the product and batch_number
        IF v_batch_id IS NOT NULL THEN
          SELECT id INTO v_resolved_batch_id
            FROM public.batches
           WHERE id = v_batch_id
             AND product_id = v_product_id
             AND (v_batch_number IS NULL OR batch_number = v_batch_number)
             AND coalesce(is_active, true);
        END IF;

        -- 2. Resolve existing batch by product_id and batch_number (preferring matching make_id)
        IF v_resolved_batch_id IS NULL THEN
          SELECT id INTO v_resolved_batch_id
            FROM public.batches
           WHERE product_id = v_product_id
             AND batch_number = v_batch_number
             AND (make_id = v_make_id OR v_make_id IS NULL OR make_id IS NULL)
             AND coalesce(is_active, true)
           ORDER BY (make_id = v_make_id) DESC, created_at DESC
           LIMIT 1;
        END IF;

        IF v_resolved_batch_id IS NULL THEN
          SELECT id INTO v_resolved_batch_id
            FROM public.batches
           WHERE product_id = v_product_id
             AND batch_number = v_batch_number
             AND coalesce(is_active, true)
           ORDER BY created_at DESC
           LIMIT 1;
        END IF;

        -- 3. If batch does not exist, create it using the existing batch model
        IF v_resolved_batch_id IS NULL THEN
          PERFORM set_config('app.canonical_stock_engine', 'on', true);
          INSERT INTO public.batches (
            batch_number, product_id, make_id, import_container_id,
            import_date, import_quantity, current_stock,
            import_price, import_price_usd, exchange_rate_usd_to_idr,
            cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit,
            is_active, created_by, purchase_invoice_id, supplier_id, packaging_details, expiry_date
          ) VALUES (
            v_batch_number, v_product_id, v_make_id, v_container_id,
            v_invoice_date, v_quantity, 0,
            v_unit_price, CASE WHEN v_currency = 'USD' THEN v_unit_price ELSE NULL END,
            CASE WHEN v_currency = 'USD' THEN v_rate ELSE NULL END,
            v_unit_price * v_rate,
            CASE WHEN v_container_id IS NULL THEN v_unit_price * v_rate ELSE 0 END,
            CASE WHEN v_container_id IS NULL THEN v_unit_price * v_rate * v_quantity ELSE 0 END,
            v_unit_price * v_rate,
            true, v_created_by, v_invoice_id, v_supplier_id, v_unit, v_expiry_date
          ) RETURNING id INTO v_resolved_batch_id;
        END IF;
      END IF;

      IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM purchase_invoice_items WHERE id = v_item_id AND purchase_invoice_id = v_invoice_id) THEN
        UPDATE purchase_invoice_items SET 
          item_type                     = v_item_type, 
          product_id                    = v_product_id, 
          batch_id                      = v_resolved_batch_id,
          description                   = v_item->>'description', 
          quantity                      = v_quantity, 
          unit                          = v_unit, 
          unit_price                    = v_unit_price, 
          discount_percent              = (v_item->>'discount_percent')::NUMERIC, 
          line_total                    = v_line_total, 
          tax_amount                    = (v_item->>'tax_amount')::NUMERIC, 
          expense_account_id            = NULLIF(v_item->>'expense_account_id','')::UUID, 
          asset_account_id              = NULLIF(v_item->>'asset_account_id','')::UUID, 
          purchase_order_item_id        = NULLIF(v_item->>'purchase_order_item_id','')::UUID, 
          receiving_make_id             = v_make_id, 
          receiving_batch_number        = v_batch_number, 
          receiving_expiry_date         = v_expiry_date, 
          receiving_import_container_id = v_container_id, 
          receiving_notes               = NULLIF(v_item->>'receiving_notes','') 
        WHERE id = v_item_id;
      ELSE
        INSERT INTO purchase_invoice_items (
          purchase_invoice_id, item_type, product_id, batch_id, description,
          quantity, unit, unit_price, discount_percent, line_total,
          tax_amount, expense_account_id, asset_account_id,
          purchase_order_item_id, receiving_make_id, receiving_batch_number,
          receiving_expiry_date, receiving_import_container_id, receiving_notes
        ) VALUES (
          v_invoice_id,
          v_item_type,
          v_product_id,
          v_resolved_batch_id,
          v_item->>'description',
          v_quantity,
          v_unit,
          v_unit_price,
          (v_item->>'discount_percent')::NUMERIC,
          v_line_total,
          (v_item->>'tax_amount')::NUMERIC,
          NULLIF(v_item->>'expense_account_id', '')::UUID,
          NULLIF(v_item->>'asset_account_id',   '')::UUID,
          NULLIF(v_item->>'purchase_order_item_id', '')::UUID,
          v_make_id,
          v_batch_number,
          v_expiry_date,
          v_container_id,
          NULLIF(v_item->>'receiving_notes', '')
        );
      END IF;

      IF v_item_type = 'inventory' THEN
        SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;
      ELSIF v_item_type = 'fixed_asset' THEN
        v_account_id := NULLIF(v_item->>'asset_account_id', '')::UUID;
        IF v_account_id IS NULL THEN
          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;
        END IF;
      ELSE
        v_account_id := NULLIF(v_item->>'expense_account_id', '')::UUID;
        IF v_account_id IS NULL THEN
          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;
        END IF;
      END IF;

      IF v_account_id IS NOT NULL AND v_line_total <> 0 THEN
        INSERT INTO journal_entry_lines (
          journal_entry_id, line_number, account_id, description,
          debit, credit, supplier_id
        ) VALUES (
          v_je_id, v_line_number, v_account_id,
          COALESCE(LEFT(v_item->>'description', 100), 'Purchase Item'),
          v_line_total * v_rate, 0, v_supplier_id
        );
        v_line_number := v_line_number + 1;
      END IF;
    END LOOP;

    -- PPN Input debit line (DR 1150)
    IF v_tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, supplier_id
      ) VALUES (
        v_je_id, v_line_number, v_ppn_account_id,
        'PPN Masukan - ' || v_invoice_number,
        v_tax_amount * v_rate, 0, v_supplier_id
      );
      v_line_number := v_line_number + 1;
    END IF;

    -- Stamp duty debit line (DR 6950)
    IF v_stamp_duty_amount > 0 AND v_bm_account_id IS NOT NULL THEN
      INSERT INTO journal_entry_lines (
        journal_entry_id, line_number, account_id, description,
        debit, credit, supplier_id
      ) VALUES (
        v_je_id, v_line_number, v_bm_account_id,
        'Bea Meterai - ' || v_invoice_number,
        v_stamp_duty_amount, 0, v_supplier_id
      );
      v_line_number := v_line_number + 1;
    END IF;

    -- A/P credit line (CR 2110)
    INSERT INTO journal_entry_lines (
      journal_entry_id, line_number, account_id, description,
      debit, credit, supplier_id
    ) VALUES (
      v_je_id, v_line_number, v_ap_account_id,
      'A/P - ' || v_invoice_number,
      0, v_total_amount * v_rate, v_supplier_id
    );

    UPDATE journal_entries
    SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)
    WHERE id = v_je_id;

    RETURN jsonb_build_object(
      'success',        TRUE,
      'invoice_id',     v_invoice_id,
      'invoice_number', v_invoice_number,
      'total_amount',   v_total_amount
    );
  END;
$function$

CREATE OR REPLACE FUNCTION public.save_purchase_invoice_with_receiving_details(p_invoice_id uuid, p_purchase_order_id uuid, p_invoice_data jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_data jsonb := coalesce(p_invoice_data, '{}'::jsonb);
  v_items jsonb := '[]'::jsonb;
  v_item jsonb;
  v_old public.purchase_invoice_items%rowtype;
  v_po uuid;
  v_result jsonb;
  v_id uuid;
  v_rate numeric;
  v_ccy text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles
      WHERE id = auth.uid()
        AND is_active = true
        AND role IN ('admin', 'accounts', 'warehouse')
    ) THEN
      RAISE EXCEPTION 'Permission denied for purchase invoice receiving';
    END IF;
  END IF;

  IF p_invoice_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN
    SELECT purchase_order_id INTO v_po FROM purchase_invoices WHERE id = p_invoice_id;
    IF v_po IS NOT NULL THEN v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(v_po), true); END IF;
  ELSIF p_invoice_id IS NULL AND p_purchase_order_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN
    v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(p_purchase_order_id), true);
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) LOOP
    IF p_invoice_id IS NOT NULL AND nullif(v_item->>'id', '') IS NOT NULL THEN
      SELECT * INTO v_old FROM purchase_invoice_items WHERE id = (v_item->>'id')::uuid AND purchase_invoice_id = p_invoice_id;
      IF FOUND THEN
        IF nullif(v_item->>'batch_id', '') IS NULL 
           AND v_old.batch_id IS NOT NULL 
           AND (nullif(v_item->>'receiving_batch_number', '') IS NULL 
                OR nullif(v_item->>'receiving_batch_number', '') = v_old.receiving_batch_number) THEN
          v_item := jsonb_set(v_item, '{batch_id}', to_jsonb(v_old.batch_id), true);
        END IF;
        IF nullif(v_item->>'purchase_order_item_id', '') IS NULL AND v_old.purchase_order_item_id IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{purchase_order_item_id}', to_jsonb(v_old.purchase_order_item_id), true);
        END IF;
        IF nullif(v_item->>'receiving_make_id', '') IS NULL AND v_old.receiving_make_id IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{receiving_make_id}', to_jsonb(v_old.receiving_make_id), true);
        END IF;
        IF nullif(v_item->>'receiving_batch_number', '') IS NULL AND v_old.receiving_batch_number IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{receiving_batch_number}', to_jsonb(v_old.receiving_batch_number), true);
        END IF;
        IF nullif(v_item->>'receiving_expiry_date', '') IS NULL AND v_old.receiving_expiry_date IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{receiving_expiry_date}', to_jsonb(v_old.receiving_expiry_date), true);
        END IF;
        IF nullif(v_item->>'receiving_import_container_id', '') IS NULL AND v_old.receiving_import_container_id IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{receiving_import_container_id}', to_jsonb(v_old.receiving_import_container_id), true);
        END IF;
        IF nullif(v_item->>'receiving_notes', '') IS NULL AND v_old.receiving_notes IS NOT NULL THEN
          v_item := jsonb_set(v_item, '{receiving_notes}', to_jsonb(v_old.receiving_notes), true);
        END IF;
      END IF;
    END IF;
    v_items := v_items || jsonb_build_array(v_item);
  END LOOP;

  v_result := CASE
    WHEN p_invoice_id IS NOT NULL THEN save_purchase_invoice(p_invoice_id, v_data, v_items)
    WHEN p_purchase_order_id IS NOT NULL THEN create_purchase_invoice_from_po(p_purchase_order_id, v_data, v_items)
    ELSE save_purchase_invoice(NULL, v_data, v_items)
  END;

  v_id := (v_result->>'invoice_id')::uuid;
  SELECT upper(currency), exchange_rate INTO v_ccy, v_rate FROM purchase_invoices WHERE id = v_id;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_receipt_voucher_with_allocations(p_receipt_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_allocations jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
  v_alloc jsonb;
  v_currency text;
  v_rate numeric;
  v_actor uuid;
  v_party_type text;
  v_customer_id uuid;
  v_supplier_id uuid;
  v_staff_id uuid;
  v_purpose text;
  v_settle_against text;
  v_settle_disc numeric;
  v_alloc_disc numeric;
  v_adj_reason text;
  v_adj_account_id uuid;
  v_adj_notes text;
  v_method text;
  v_bank_id uuid;
  v_ref text;
  v_amount numeric;
  v_desc text;
  v_date date;
  v_existing RECORD;
BEGIN
  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN
    PERFORM public._sec_check_finance_role();
  ELSIF auth.role() = 'anon' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(auth.uid(), NULLIF(p_payload->>'created_by','')::uuid);

  v_party_type := lower(COALESCE(p_payload->>'party_type', 'customer'));
  v_customer_id := NULLIF(p_payload->>'customer_id', '')::uuid;
  v_supplier_id := NULLIF(p_payload->>'supplier_id', '')::uuid;
  v_staff_id := NULLIF(p_payload->>'staff_id', '')::uuid;
  v_purpose := COALESCE(p_payload->>'payment_purpose', CASE WHEN v_party_type = 'supplier' THEN 'supplier_refund' ELSE 'invoice_payment' END);
  v_settle_against := COALESCE(p_payload->>'settlement_against', CASE WHEN v_party_type = 'customer' THEN 'specific_document' ELSE 'advance' END);
  v_settle_disc := COALESCE((p_payload->>'settlement_discount')::numeric, 0);
  v_adj_reason := NULLIF(p_payload->>'adjustment_reason', '');
  v_adj_account_id := NULLIF(p_payload->>'adjustment_account_id', '')::uuid;
  v_adj_notes := NULLIF(p_payload->>'adjustment_notes', '');
  v_method := COALESCE(p_payload->>'payment_method', 'bank_transfer');
  v_bank_id := NULLIF(p_payload->>'bank_account_id', '')::uuid;
  v_ref := NULLIF(p_payload->>'reference_number', '');
  v_amount := COALESCE((p_payload->>'amount')::numeric, 0);
  v_desc := NULLIF(p_payload->>'description', '');
  v_date := COALESCE(NULLIF(p_payload->>'voucher_date', '')::date, CURRENT_DATE);
  v_currency := upper(COALESCE(p_payload->>'transaction_currency', p_payload->>'currency_code', 'IDR'));
  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric, 0), 1);

  -- Auto-assign default difference account 6910 if discount is positive and account not provided
  IF v_settle_disc > 0 AND v_adj_account_id IS NULL THEN
    SELECT id INTO v_adj_account_id FROM public.chart_of_accounts WHERE code = '6910' AND is_active = true AND is_header = false LIMIT 1;
  END IF;

  IF p_receipt_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.receipt_vouchers WHERE id = p_receipt_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_receipt_id; END IF;
    IF v_existing.is_posted THEN RAISE EXCEPTION 'Cannot update posted receipt voucher %', v_existing.voucher_number; END IF;
    v_id := p_receipt_id;

    UPDATE public.receipt_vouchers
    SET voucher_date = v_date,
        party_type = v_party_type,
        customer_id = v_customer_id,
        supplier_id = v_supplier_id,
        staff_id = v_staff_id,
        payment_purpose = v_purpose,
        settlement_against = v_settle_against,
        settlement_discount = v_settle_disc,
        adjustment_reason = v_adj_reason,
        adjustment_account_id = v_adj_account_id,
        adjustment_notes = v_adj_notes,
        payment_method = v_method,
        bank_account_id = v_bank_id,
        reference_number = v_ref,
        amount = v_amount,
        description = v_desc,
        currency_code = v_currency,
        transaction_currency = v_currency,
        exchange_rate = v_rate
    WHERE id = v_id;

    DELETE FROM public.voucher_allocations WHERE receipt_voucher_id = v_id;
  ELSE
    INSERT INTO public.receipt_vouchers (
      voucher_number,
      voucher_date,
      party_type,
      customer_id,
      supplier_id,
      staff_id,
      payment_purpose,
      settlement_against,
      settlement_discount,
      adjustment_reason,
      adjustment_account_id,
      adjustment_notes,
      payment_method,
      bank_account_id,
      reference_number,
      amount,
      description,
      currency_code,
      transaction_currency,
      exchange_rate,
      created_by
    ) VALUES (
      public.next_receipt_voucher_number(v_date),
      v_date,
      v_party_type,
      v_customer_id,
      v_supplier_id,
      v_staff_id,
      v_purpose,
      v_settle_against,
      v_settle_disc,
      v_adj_reason,
      v_adj_account_id,
      v_adj_notes,
      v_method,
      v_bank_id,
      v_ref,
      v_amount,
      v_desc,
      v_currency,
      v_currency,
      v_rate,
      v_actor
    ) RETURNING id INTO v_id;
  END IF;

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_alloc_disc := COALESCE((v_alloc->>'discountAmount')::numeric, 0);
    INSERT INTO public.voucher_allocations (
      voucher_type,
      receipt_voucher_id,
      sales_invoice_id,
      sales_order_id,
      allocated_amount,
      settlement_discount,
      adjustment_reason,
      notes
    ) VALUES (
      'receipt',
      v_id,
      NULLIF(v_alloc->>'sales_invoice_id', '')::uuid,
      NULLIF(v_alloc->>'sales_order_id', '')::uuid,
      COALESCE((v_alloc->>'amount')::numeric, 0),
      v_alloc_disc,
      NULLIF(v_alloc->>'adjustment_reason', ''),
      NULLIF(v_alloc->>'notes', '')
    );
  END LOOP;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_invoice public.purchase_invoices%ROWTYPE;
BEGIN
  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts']) THEN RAISE EXCEPTION 'Permission denied'; END IF;
  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = p_purchase_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;
  IF v_invoice.status = 'cancelled' THEN RAISE EXCEPTION 'Cancelled Purchase Invoice cannot be submitted'; END IF;
  UPDATE public.purchase_invoices SET receiving_approval_status='pending_approval', receiving_submitted_at=now(), receiving_submitted_by=auth.uid(), receiving_rejection_reason=NULL, updated_at=now() WHERE id=p_purchase_invoice_id;
  RETURN jsonb_build_object('success',true,'status','pending_approval');
END; $function$

CREATE OR REPLACE FUNCTION public.transition_enquiry_request_atomic(p_request_id uuid, p_event_type text, p_summary text, p_new_status text DEFAULT NULL::text, p_new_waiting_for text DEFAULT NULL::text, p_new_requirement text DEFAULT NULL::text, p_new_parameters jsonb DEFAULT NULL::jsonb, p_current_issue text DEFAULT NULL::text, p_next_action text DEFAULT NULL::text, p_new_assigned_to uuid DEFAULT NULL::uuid, p_new_assigned_team text DEFAULT NULL::text, p_response_text text DEFAULT NULL::text, p_response_value jsonb DEFAULT NULL::jsonb, p_details jsonb DEFAULT '{}'::jsonb, p_source_message_id uuid DEFAULT NULL::uuid, p_actor_type text DEFAULT 'user'::text, p_actor_id uuid DEFAULT NULL::uuid, p_expected_values jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_role TEXT;
  v_caller_auth_uid UUID;
  v_effective_actor_type TEXT;
  v_effective_actor_id UUID;
  v_user_role TEXT;

  v_req public.enquiry_requests%ROWTYPE;
  v_effective_status TEXT;
  v_effective_waiting_for TEXT;
  v_effective_requirement TEXT;
  v_effective_parameters JSONB;
  v_effective_assigned_to UUID;
  v_effective_assigned_team TEXT;
  v_effective_current_issue TEXT;
  v_effective_next_action TEXT;
  v_effective_response_text TEXT;
  v_effective_response_value JSONB;
  v_resolved_at TIMESTAMPTZ;
  v_resolved_by UUID;
  v_event_details JSONB;
BEGIN
  v_caller_role := auth.role();
  v_caller_auth_uid := auth.uid();

  IF v_caller_role = 'authenticated' THEN
    SELECT role INTO v_user_role
    FROM public.user_profiles
    WHERE id = v_caller_auth_uid AND is_active = true;

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN
      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can update enquiry requests';
    END IF;

    -- Anti-spoofing guards
    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN
      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';
    END IF;

    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN
      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';
    END IF;

    v_effective_actor_type := 'user';
    v_effective_actor_id := v_caller_auth_uid;

  ELSIF v_caller_role = 'service_role' THEN
    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN
      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';
    END IF;
    v_effective_actor_type := p_actor_type;
    v_effective_actor_id := p_actor_id;

  ELSE
    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';
  END IF;

  -- Validate event_type check constraint
  IF p_event_type NOT IN (
    'created',
    'requirement_changed',
    'supplier_response',
    'customer_decision',
    'status_changed',
    'waiting_for_changed',
    'owner_reassigned',
    'escalated',
    'resolved',
    'cancelled'
  ) THEN
    RAISE EXCEPTION 'Invalid event_type: %', p_event_type;
  END IF;

  -- Row lock target enquiry_requests record
  SELECT * INTO v_req
  FROM public.enquiry_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enquiry request not found: %', p_request_id;
  END IF;

  -- Stale proposal / concurrency check inside the transaction
  IF p_expected_values IS NOT NULL AND p_expected_values <> '{}'::jsonb THEN
    IF p_expected_values ? 'customer_requirement' THEN
      IF trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(p_expected_values->>'customer_requirement', '')) THEN
        RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI suggestion was created (expected: "%", current: "%")',
          p_expected_values->>'customer_requirement', v_req.customer_requirement
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF p_expected_values ? 'status' THEN
      IF v_req.status <> (p_expected_values->>'status') THEN
        RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI suggestion was created (expected: "%", current: "%")',
          p_expected_values->>'status', v_req.status
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF p_expected_values ? 'waiting_for' THEN
      IF v_req.waiting_for <> (p_expected_values->>'waiting_for') THEN
        RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI suggestion was created (expected: "%", current: "%")',
          p_expected_values->>'waiting_for', v_req.waiting_for
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF p_expected_values ? 'assigned_team' THEN
      IF COALESCE(v_req.assigned_team, '') <> COALESCE(p_expected_values->>'assigned_team', '') THEN
        RAISE EXCEPTION 'STALE_PROPOSAL: assigned_team has changed since AI suggestion was created (expected: "%", current: "%")',
          p_expected_values->>'assigned_team', v_req.assigned_team
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  -- Resolve effective state values
  v_effective_status := COALESCE(p_new_status, v_req.status);
  v_effective_waiting_for := COALESCE(p_new_waiting_for, v_req.waiting_for);
  v_effective_requirement := COALESCE(p_new_requirement, v_req.customer_requirement);
  v_effective_parameters := COALESCE(p_new_parameters, v_req.parameters);
  v_effective_assigned_to := CASE WHEN p_new_assigned_to IS NOT NULL THEN p_new_assigned_to ELSE v_req.assigned_to END;
  v_effective_assigned_team := CASE WHEN p_new_assigned_team IS NOT NULL THEN p_new_assigned_team ELSE v_req.assigned_team END;
  v_effective_current_issue := CASE WHEN p_current_issue IS NOT NULL THEN p_current_issue ELSE v_req.current_issue END;
  v_effective_next_action := CASE WHEN p_next_action IS NOT NULL THEN p_next_action ELSE v_req.next_action END;
  v_effective_response_text := CASE WHEN p_response_text IS NOT NULL THEN p_response_text ELSE v_req.response_text END;
  v_effective_response_value := CASE WHEN p_response_value IS NOT NULL THEN p_response_value ELSE v_req.response_value END;
  v_resolved_at := v_req.resolved_at;
  v_resolved_by := v_req.resolved_by;

  -- State-specific validations
  IF v_effective_status = 'RESOLVED' THEN
    IF (v_effective_response_text IS NULL OR trim(v_effective_response_text) = '')
       AND (v_effective_response_value IS NULL OR v_effective_response_value = '{}'::jsonb) THEN
      RAISE EXCEPTION 'RESOLVED requests require response_text or response_value';
    END IF;
    v_effective_waiting_for := 'NONE';
    v_resolved_at := now();
    v_resolved_by := v_effective_actor_id;
  END IF;

  IF v_effective_status = 'BLOCKED' THEN
    IF v_effective_waiting_for = 'NONE' THEN
      RAISE EXCEPTION 'BLOCKED requests must specify waiting_for dependency (INTERNAL, INDIA, MANUFACTURER, CUSTOMER)';
    END IF;
    IF v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '' THEN
      RAISE EXCEPTION 'BLOCKED requests must have a current_issue describing the impediment';
    END IF;
  END IF;

  IF v_effective_status = 'CANCELLED' THEN
    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')
       AND (p_details->>'cancellation_reason' IS NULL OR trim(p_details->>'cancellation_reason') = '') THEN
      RAISE EXCEPTION 'CANCELLED requests must have a cancellation reason in current_issue or details.cancellation_reason';
    END IF;
  END IF;

  IF v_effective_status = 'NOT_POSSIBLE' THEN
    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')
       AND (p_details->>'reason' IS NULL OR trim(p_details->>'reason') = '') THEN
      RAISE EXCEPTION 'NOT_POSSIBLE requests must have an explanation in current_issue or details.reason';
    END IF;
  END IF;

  -- Build details diff
  v_event_details := COALESCE(p_details, '{}'::jsonb);
  IF p_new_requirement IS NOT NULL AND p_new_requirement <> v_req.customer_requirement THEN
    v_event_details := v_event_details || jsonb_build_object(
      'requirement_diff', jsonb_build_object('old', v_req.customer_requirement, 'new', p_new_requirement)
    );
  END IF;

  -- Apply updates to enquiry_requests
  UPDATE public.enquiry_requests
  SET
    status = v_effective_status,
    waiting_for = v_effective_waiting_for,
    customer_requirement = v_effective_requirement,
    parameters = v_effective_parameters,
    assigned_to = v_effective_assigned_to,
    assigned_team = v_effective_assigned_team,
    current_issue = v_effective_current_issue,
    next_action = v_effective_next_action,
    response_text = v_effective_response_text,
    response_value = v_effective_response_value,
    resolved_at = v_resolved_at,
    resolved_by = v_resolved_by,
    updated_at = now()
  WHERE id = p_request_id;

  -- Append event to enquiry_request_events
  INSERT INTO public.enquiry_request_events (
    request_id,
    inquiry_id,
    event_type,
    summary,
    old_status,
    new_status,
    old_waiting_for,
    new_waiting_for,
    details,
    source_message_id,
    actor_type,
    actor_id
  ) VALUES (
    p_request_id,
    v_req.inquiry_id,
    p_event_type,
    p_summary,
    v_req.status,
    v_effective_status,
    v_req.waiting_for,
    v_effective_waiting_for,
    v_event_details,
    p_source_message_id,
    v_effective_actor_type,
    v_effective_actor_id
  );

  -- Link provenance if source message provided
  IF p_source_message_id IS NOT NULL THEN
    INSERT INTO public.enquiry_request_messages (
      request_id,
      message_id,
      relationship
    ) VALUES (
      p_request_id,
      p_source_message_id,
      CASE
        WHEN v_effective_status = 'RESOLVED' THEN 'resolved'
        WHEN v_effective_status = 'BLOCKED' THEN 'blocked'
        ELSE 'clarified'
      END
    )
    ON CONFLICT (request_id, message_id, relationship) DO NOTHING;
  END IF;

END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_sync_bank_alloc_pph()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_tx_date DATE;
    v_has_pph BOOLEAN;
BEGIN
    IF NEW.document_type = 'expense' THEN
        SELECT (COALESCE(pph_amount, 0) > 0) INTO v_has_pph
        FROM public.finance_expenses
        WHERE id = NEW.document_id;

        IF v_has_pph THEN
            SELECT transaction_date INTO v_tx_date
            FROM public.bank_statement_lines
            WHERE id = NEW.bank_statement_line_id;

            IF v_tx_date IS NOT NULL THEN
                PERFORM public.sync_expense_pph_allocation(
                    NEW.document_id,
                    'bank_statement_allocation',
                    NEW.id, -- Use allocation UUID as the stable payment_event_id
                    v_tx_date,
                    NEW.allocation_amount,
                    false,
                    NEW.id,
                    'Synced from bank statement allocation'
                );
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_fn_sync_voucher_alloc_pph()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_has_pph BOOLEAN;
    v_voucher RECORD;
BEGIN
    IF NEW.finance_expense_id IS NOT NULL THEN
        SELECT (COALESCE(pph_amount, 0) > 0) INTO v_has_pph
        FROM public.finance_expenses
        WHERE id = NEW.finance_expense_id;

        IF v_has_pph THEN
            SELECT * INTO v_voucher
            FROM public.payment_vouchers
            WHERE id = NEW.payment_voucher_id;

            IF v_voucher.id IS NOT NULL AND v_voucher.voucher_date IS NOT NULL THEN
                PERFORM public.sync_expense_pph_allocation(
                    NEW.finance_expense_id,
                    'voucher_allocation',
                    NEW.id, -- Stable payment_event_id is the voucher_allocation id
                    v_voucher.voucher_date,
                    NEW.allocated_amount,
                    false,
                    NEW.id,
                    'Synced from payment voucher ' || COALESCE(v_voucher.voucher_number, '')
                );
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

