CREATE OR REPLACE FUNCTION public.trg_validate_credit_note_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inv public.sales_invoices%ROWTYPE;
  v_already_credited numeric(15,2);
  v_item record;
  v_orig_item public.sales_invoice_items%ROWTYPE;
  v_already_returned_qty numeric(12,3);
BEGIN
  -- If linked to an original invoice, validate invoice lifecycle and returnable limits
  IF NEW.original_invoice_id IS NOT NULL THEN
    SELECT * INTO v_inv
    FROM public.sales_invoices
    WHERE id = NEW.original_invoice_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Original Sales Invoice % does not exist', NEW.original_invoice_id;
    END IF;

    -- Cannot issue credit note against cancelled or draft sales invoices
    IF NOT public.is_reportable_sales_invoice(v_inv.document_status, v_inv.is_draft, v_inv.notes) THEN
      RAISE EXCEPTION 'Cannot issue Credit Note against cancelled or draft invoice %', v_inv.invoice_number;
    END IF;

    -- Validate eligible total amount across all active credit notes for this invoice
    SELECT COALESCE(SUM(total_amount), 0)
    INTO v_already_credited
    FROM public.credit_notes
    WHERE original_invoice_id = NEW.original_invoice_id
      AND status <> 'rejected'
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

    IF (v_already_credited + COALESCE(NEW.total_amount, 0)) > (v_inv.total_amount + 0.05) THEN
      RAISE EXCEPTION 'Credit Note amount % exceeds remaining eligible invoice total % (Invoice total %, already credited %)',
        NEW.total_amount, (v_inv.total_amount - v_already_credited), v_inv.total_amount, v_already_credited;
    END IF;
  END IF;

  -- Ensure credit_note_type matches business case
  IF NEW.business_case IN ('price_adjustment', 'post_invoice_discount', 'customer_refund', 'future_credit_adjustment') THEN
    NEW.credit_note_type := 'commercial_credit';
  ELSE
    NEW.credit_note_type := 'physical_return';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_validate_credit_note_item_quantities()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_sii public.sales_invoice_items%ROWTYPE;
  v_already_returned_qty numeric(12,3);
  v_eligible_qty numeric(12,3);
BEGIN
  SELECT * INTO v_cn FROM public.credit_notes WHERE id = NEW.credit_note_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  IF NEW.quantity <= 0 THEN
    RAISE EXCEPTION 'Credit note item quantity must be greater than zero (received %)', NEW.quantity;
  END IF;

  -- If credit note is commercial/price-only, items should not move physical stock
  IF v_cn.credit_note_type = 'commercial_credit' THEN
    NEW.disposition := 'rejected'; -- ensures no inventory movement is generated
  END IF;

  -- If original invoice exists, validate return quantities against invoice line
  IF v_cn.original_invoice_id IS NOT NULL THEN
    -- Match by sales_invoice_item_id or (product_id, batch_id)
    IF NEW.sales_invoice_item_id IS NOT NULL THEN
      SELECT * INTO v_sii FROM public.sales_invoice_items WHERE id = NEW.sales_invoice_item_id;
    ELSE
      SELECT * INTO v_sii 
      FROM public.sales_invoice_items 
      WHERE invoice_id = v_cn.original_invoice_id
        AND product_id = NEW.product_id
        AND (batch_id IS NOT DISTINCT FROM NEW.batch_id OR NEW.batch_id IS NULL)
      ORDER BY quantity DESC
      LIMIT 1;
    END IF;

    IF v_sii.id IS NOT NULL THEN
      NEW.sales_invoice_item_id := v_sii.id;
      IF NEW.delivery_challan_item_id IS NULL THEN
        NEW.delivery_challan_item_id := v_sii.delivery_challan_item_id;
      END IF;

      -- Calculate quantity already returned by other approved or active credit notes on this line
      SELECT COALESCE(SUM(cni.quantity), 0)
      INTO v_already_returned_qty
      FROM public.credit_note_items cni
      JOIN public.credit_notes cn ON cn.id = cni.credit_note_id
      WHERE cn.original_invoice_id = v_cn.original_invoice_id
        AND cn.status <> 'rejected'
        AND cni.sales_invoice_item_id = v_sii.id
        AND cni.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

      v_eligible_qty := GREATEST(v_sii.quantity - v_already_returned_qty, 0);

      IF NEW.quantity > (v_eligible_qty + 0.001) THEN
        RAISE EXCEPTION 'Return quantity % exceeds remaining returnable quantity % (Invoiced %, already returned %)',
          NEW.quantity, v_eligible_qty, v_sii.quantity, v_already_returned_qty;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.undo_reverse_fund_transfer(p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_message  text;
  v_conflict jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  BEGIN
    RETURN public.undo_reverse_fund_transfer_core(p_id, p_reason);
  EXCEPTION WHEN integrity_constraint_violation THEN
    GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;

    IF v_message LIKE
       'Cannot undo reversal: the % bank statement line is now linked to another transaction' THEN
      v_conflict := public.describe_undo_reverse_bank_conflict(p_id);
      IF v_conflict IS NOT NULL THEN
        RAISE EXCEPTION '%', v_message
          USING
            ERRCODE = 'integrity_constraint_violation',
            DETAIL = v_conflict::text;
      END IF;
    END IF;

    RAISE;
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.unlink_expense_from_bank_statement(p_bank_statement_line_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_role text;
BEGIN
SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin','accounts') THEN
RAISE EXCEPTION 'Permission denied: role % cannot unlink bank statement entries', v_role;
END IF;

UPDATE bank_statement_lines
SET matched_expense_id = NULL, reconciliation_status = 'unmatched',
matched_at = NULL, matched_by = NULL, notes = NULL
WHERE id = p_bank_statement_line_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.unlink_finance_expense_bank_atomic(p_expense_id uuid, p_reason text DEFAULT 'Bank statement link removed by user'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_expense public.finance_expenses%ROWTYPE;
  v_allocation record;
  v_released integer := 0;
BEGIN
  PERFORM public._sec_check_finance_role();
  IF btrim(COALESCE(p_reason, '')) = '' THEN
    RAISE EXCEPTION 'An unlink reason is required';
  END IF;

  SELECT * INTO v_expense
  FROM public.finance_expenses
  WHERE id = p_expense_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense not found';
  END IF;
  IF v_expense.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'Only an active posted expense can be unlinked through this workflow';
  END IF;

  FOR v_allocation IN
    SELECT id
    FROM public.bank_statement_allocations
    WHERE document_type = 'expense'
      AND document_id = p_expense_id
    ORDER BY id
    FOR UPDATE
  LOOP
    PERFORM public.unmatch_bank_statement_allocation(v_allocation.id);
    v_released := v_released + 1;
  END LOOP;
  IF v_released = 0 THEN
    RAISE EXCEPTION 'Expense has no canonical bank allocation to unlink';
  END IF;

  PERFORM public.recalculate_expense_payment_state(p_expense_id);
  PERFORM public.cancel_expense_posting(p_expense_id, auth.uid(), p_reason);

  IF EXISTS (
    SELECT 1 FROM public.bank_statement_allocations
    WHERE document_type = 'expense' AND document_id = p_expense_id
  ) THEN
    RAISE EXCEPTION 'Expense unlink left a bank allocation behind';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.journal_entries
    WHERE source_module IN ('expense', 'expenses')
      AND (reference_id = p_expense_id OR reference_number = 'EXP-' || p_expense_id::text)
      AND is_posted AND NOT COALESCE(is_reversed, false)
  ) THEN
    RAISE EXCEPTION 'Expense unlink left an active journal behind';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.finance_expenses
    WHERE id = p_expense_id AND approval_status = 'cancelled'
  ) THEN
    RAISE EXCEPTION 'Expense unlink did not cancel the document';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'expense_id', p_expense_id,
    'released_allocations', v_released
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.unmatch_bank_statement_allocation(p_allocation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_a public.bank_statement_allocations%rowtype; v_payment_je public.journal_entries%rowtype;
  v_reversal_id uuid; v_reversal_number text; v_period_status text;
BEGIN
  PERFORM public._sec_check_finance_role();
  SELECT * INTO v_a FROM public.bank_statement_allocations WHERE id=p_allocation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank allocation not found'; END IF;
  SELECT * INTO v_payment_je FROM public.journal_entries
   WHERE id=v_a.journal_entry_id AND source_module='expense_payment'
     AND reference_number='EXP-PAY-'||p_allocation_id::text
     AND is_posted AND NOT COALESCE(is_reversed,false) FOR UPDATE;
  IF FOUND THEN
    SELECT status INTO v_period_status FROM public.accounting_periods
     WHERE start_date<=v_payment_je.entry_date AND end_date>=v_payment_je.entry_date
     ORDER BY start_date DESC LIMIT 1;
    IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN
      RAISE EXCEPTION 'Cannot unlink expense payment in a closed accounting period';
    END IF;
    v_reversal_number:=public.next_journal_entry_number();
    INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,
      reference_number,description,total_debit,total_credit,is_posted,is_reversed,posted_by,posted_at,created_by,
      transaction_currency,functional_currency,exchange_rate,amounts_are_functional)
    VALUES(v_reversal_number,v_payment_je.entry_date,v_payment_je.period_id,'expense_payment_reversal',v_a.document_id,
      'REV-EXP-PAY-'||p_allocation_id::text,'Reversal of '||v_payment_je.entry_number,
      v_payment_je.total_credit,v_payment_je.total_debit,true,true,auth.uid(),now(),auth.uid(),
      v_payment_je.transaction_currency,v_payment_je.functional_currency,v_payment_je.exchange_rate,v_payment_je.amounts_are_functional)
    RETURNING id INTO v_reversal_id;
    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,
      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_debit,transaction_credit,
      functional_currency,exchange_rate)
    SELECT v_reversal_id,line_number,account_id,'REVERSAL: '||COALESCE(description,''),credit,debit,
      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_credit,transaction_debit,
      functional_currency,exchange_rate
      FROM public.journal_entry_lines WHERE journal_entry_id=v_payment_je.id ORDER BY line_number;
    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal_id
     WHERE id=v_payment_je.id;
  END IF;
  DELETE FROM public.bank_statement_allocations WHERE id=p_allocation_id;
  PERFORM public.sync_bank_line_allocation_owner(v_a.bank_statement_line_id);
  PERFORM public.refresh_bank_statement_allocation_status(v_a.bank_statement_line_id);
  IF v_a.document_type='expense' THEN PERFORM public.recalculate_expense_payment_state(v_a.document_id); END IF;
  RETURN jsonb_build_object('success',true,'bank_line_id',v_a.bank_statement_line_id,
    'allocation_id',p_allocation_id,'reversal_journal_id',v_reversal_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_nota_retur_coretax_status(p_nota_retur_id uuid, p_coretax_status text, p_djp_reference text DEFAULT NULL::text, p_evidence_url text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_role text;
  v_nr public.nota_retur%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN
    IF current_user = 'service_role' OR session_user = 'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) OR (COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''), '')) = 'service_role' THEN
      v_caller := p_actor;
    ELSE
      RAISE EXCEPTION 'Authentication required: no active session';
    END IF;
  END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'manager') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot update coretax status', COALESCE(v_role, 'none');
  END IF;

  IF p_coretax_status NOT IN ('draft', 'submitted', 'approved_by_djp', 'rejected_by_djp') THEN
    RAISE EXCEPTION 'Invalid coretax status: %', p_coretax_status;
  END IF;

  SELECT * INTO v_nr FROM public.nota_retur WHERE id = p_nota_retur_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nota retur % not found', p_nota_retur_id;
  END IF;

  UPDATE public.nota_retur
     SET coretax_status = p_coretax_status,
         status = CASE
           WHEN p_coretax_status = 'approved_by_djp' THEN 'approved'
           WHEN p_coretax_status = 'rejected_by_djp' THEN 'rejected'
           ELSE status
         END,
         coretax_reference_number = COALESCE(p_djp_reference, coretax_reference_number),
         document_url = COALESCE(p_evidence_url, document_url),
         notes = CASE WHEN p_evidence_url IS NOT NULL THEN COALESCE(notes, '') || ' [Evidence: ' || p_evidence_url || ']' ELSE notes END,
         updated_at = now()
   WHERE id = p_nota_retur_id;

  RETURN jsonb_build_object(
    'success', true,
    'nota_retur_id', p_nota_retur_id,
    'coretax_status', p_coretax_status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_items jsonb, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_result := public.update_sales_invoice_atomic(
    p_invoice_id,
    p_invoice_updates,
    ARRAY(
      SELECT value
      FROM jsonb_array_elements(
        CASE jsonb_typeof(p_items)
          WHEN 'array' THEN p_items
          ELSE '[]'::jsonb
        END
      )
    )
  );

  RETURN jsonb_build_object('success', true, 'invoice_id', v_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_new_items jsonb[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role text;
  v_old_je_id uuid;
  v_result uuid;
  v_existing_invoice public.sales_invoices%ROWTYPE;
  v_old_dc_item_ids uuid[];
  v_new_dc_item_ids uuid[];
  v_all_dc_item_ids uuid[];
  v_all_parent_dc_ids uuid[];
  v_linked_challan_ids text[];
  v_sales_order_ids uuid[];
  v_customer_ids uuid[];
  v_item jsonb;
  v_dc_item uuid;
  v_product uuid;
  v_batch uuid;
  v_qty numeric;
  v_price numeric;
  v_dci_product uuid;
  v_dci_batch uuid;
  v_dci_qty numeric;
  v_other_invoiced numeric;
  v_req_dc_qty numeric;
BEGIN
  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'sales') THEN
    RAISE EXCEPTION 'Permission denied: role % cannot update sales invoices', COALESCE(v_role, 'none');
  END IF;

  -- 1. Fetch and lock existing invoice record
  SELECT * INTO v_existing_invoice
  FROM public.sales_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sales Invoice % not found', p_invoice_id;
  END IF;

  -- TERMINAL CANCELLATION GUARD: Cancelled invoices cannot be updated
  IF v_existing_invoice.document_status = 'cancelled'
     OR (COALESCE(v_existing_invoice.notes, '') LIKE '[CANCELLED%' OR LOWER(COALESCE(v_existing_invoice.notes, '')) LIKE 'cancelled%') THEN
    RAISE EXCEPTION 'Cannot update cancelled sales invoice %: cancellation is terminal', v_existing_invoice.invoice_number;
  END IF;

  -- 2. Collect old and new DC item IDs
  SELECT array_agg(DISTINCT delivery_challan_item_id)
  INTO v_old_dc_item_ids
  FROM public.sales_invoice_items
  WHERE invoice_id = p_invoice_id AND delivery_challan_item_id IS NOT NULL;

  SELECT array_agg(DISTINCT NULLIF(item->>'delivery_challan_item_id', '')::uuid)
  INTO v_new_dc_item_ids
  FROM unnest(p_new_items) AS item
  WHERE NULLIF(item->>'delivery_challan_item_id', '') IS NOT NULL;

  IF v_new_dc_item_ids IS NULL OR cardinality(v_new_dc_item_ids) = 0 THEN
    RAISE EXCEPTION 'Sales Invoice must contain Delivery Challan-linked items';
  END IF;

  -- Combine for deterministic locking
  SELECT array_agg(DISTINCT dci_id ORDER BY dci_id ASC)
  INTO v_all_dc_item_ids
  FROM (
    SELECT unnest(COALESCE(v_old_dc_item_ids, ARRAY[]::uuid[])) AS dci_id
    UNION
    SELECT unnest(v_new_dc_item_ids) AS dci_id
  ) t;

  -- Collect parent DC IDs
  SELECT array_agg(DISTINCT challan_id ORDER BY challan_id ASC)
  INTO v_all_parent_dc_ids
  FROM public.delivery_challan_items
  WHERE id = ANY(v_all_dc_item_ids);

  -- 3. Deterministic Locking:
  -- Step A: Lock parent delivery_challans in ASC order
  PERFORM dc.id
  FROM public.delivery_challans dc
  WHERE dc.id = ANY(v_all_parent_dc_ids)
  ORDER BY dc.id ASC
  FOR UPDATE;

  -- Step B: Lock child delivery_challan_items in ASC order
  PERFORM dci.id
  FROM public.delivery_challan_items dci
  WHERE dci.id = ANY(v_all_dc_item_ids)
  ORDER BY dci.id ASC
  FOR UPDATE;

  -- 4. Validate Delivery Challan eligibility on new items
  IF cardinality(v_new_dc_item_ids) <> (
    SELECT count(*) FROM public.delivery_challan_items WHERE id = ANY(v_new_dc_item_ids)
  ) THEN
    RAISE EXCEPTION 'Sales Invoice contains a missing Delivery Challan item';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.delivery_challan_items dci
    JOIN public.delivery_challans dc ON dc.id = dci.challan_id
    WHERE dci.id = ANY(v_new_dc_item_ids)
      AND dc.approval_status::text <> 'approved'
  ) THEN
    RAISE EXCEPTION 'All source Delivery Challans must be approved';
  END IF;

  SELECT
    array_agg(DISTINCT dc.id::text ORDER BY dc.id::text),
    array_agg(DISTINCT dc.sales_order_id),
    array_agg(DISTINCT dc.customer_id)
  INTO v_linked_challan_ids, v_sales_order_ids, v_customer_ids
  FROM public.delivery_challan_items dci
  JOIN public.delivery_challans dc ON dc.id = dci.challan_id
  WHERE dci.id = ANY(v_new_dc_item_ids);

  IF cardinality(v_customer_ids) <> 1
     OR (p_invoice_updates ? 'customer_id'
         AND (p_invoice_updates->>'customer_id')::uuid IS DISTINCT FROM v_customer_ids[1]) THEN
    RAISE EXCEPTION 'Invoice customer must match all linked Delivery Challans';
  END IF;

  -- 5. Validate complete requested quantities against available DC capacities
  -- (excluding the invoice currently being updated)
  FOR v_item IN SELECT unnest(p_new_items)
  LOOP
    v_dc_item := NULLIF(v_item->>'delivery_challan_item_id', '')::uuid;
    v_qty := (v_item->>'quantity')::numeric;
    v_product := (v_item->>'product_id')::uuid;
    v_batch := NULLIF(v_item->>'batch_id', '')::uuid;
    v_price := (v_item->>'unit_price')::numeric;

    IF v_product IS NULL OR v_dc_item IS NULL OR COALESCE(v_qty, 0) <= 0 OR COALESCE(v_price, 0) < 0 THEN
      RAISE EXCEPTION 'Every invoice line must have a valid Delivery Challan item, product, and positive quantity';
    END IF;

    SELECT dci.product_id, dci.batch_id, dci.quantity
    INTO v_dci_product, v_dci_batch, v_dci_qty
    FROM public.delivery_challan_items dci
    WHERE dci.id = v_dc_item;

    IF v_dci_product IS DISTINCT FROM v_product OR v_dci_batch IS DISTINCT FROM v_batch THEN
      RAISE EXCEPTION 'Invoice line product or batch does not match source Delivery Challan item';
    END IF;

    -- Calculate already invoiced by other reportable invoices
    SELECT COALESCE(SUM(sii.quantity), 0)
    INTO v_other_invoiced
    FROM public.sales_invoice_items sii
    JOIN public.sales_invoices si ON si.id = sii.invoice_id
    WHERE sii.delivery_challan_item_id = v_dc_item
      AND si.id <> p_invoice_id
      AND public.is_reportable_sales_invoice(si.document_status, si.is_draft, si.notes);

    -- Calculate total requested for this DC item in current payload
    SELECT COALESCE(SUM((val->>'quantity')::numeric), 0)
    INTO v_req_dc_qty
    FROM unnest(p_new_items) val
    WHERE NULLIF(val->>'delivery_challan_item_id', '')::uuid = v_dc_item;

    IF (v_other_invoiced + v_req_dc_qty) > v_dci_qty THEN
      RAISE EXCEPTION 'Invoice quantity % exceeds remaining Delivery Challan quantity % (DC total %, already invoiced by other invoices %)',
        v_req_dc_qty, (v_dci_qty - v_other_invoiced), v_dci_qty, v_other_invoiced;
    END IF;
  END LOOP;

  -- 6. Remove old journal entries
  SELECT journal_entry_id INTO v_old_je_id
  FROM public.sales_invoices
  WHERE id = p_invoice_id;

  IF v_old_je_id IS NOT NULL THEN
    UPDATE public.sales_invoices SET journal_entry_id = NULL WHERE id = p_invoice_id;
    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_old_je_id;
    DELETE FROM public.journal_entries WHERE id = v_old_je_id;
  END IF;

  DELETE FROM public.journal_entry_lines
  WHERE journal_entry_id IN (
    SELECT id FROM public.journal_entries
    WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id
  );
  DELETE FROM public.journal_entries
  WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id;

  -- 7. Replace invoice items atomically
  DELETE FROM public.sales_invoice_items WHERE invoice_id = p_invoice_id;
  PERFORM set_config('app.sales_invoice_rebuild', 'true', true);

  UPDATE public.sales_invoices
  SET
    invoice_date       = COALESCE((p_invoice_updates->>'invoice_date')::date, invoice_date),
    due_date           = COALESCE((p_invoice_updates->>'due_date')::date, due_date),
    customer_id        = v_customer_ids[1],
    sales_order_id     = CASE WHEN cardinality(v_sales_order_ids) = 1 THEN v_sales_order_ids[1] ELSE NULL END,
    subtotal           = COALESCE((p_invoice_updates->>'subtotal')::numeric, subtotal),
    tax_amount         = COALESCE((p_invoice_updates->>'tax_amount')::numeric, tax_amount),
    total_amount       = COALESCE((p_invoice_updates->>'total_amount')::numeric, total_amount),
    discount_amount    = COALESCE((p_invoice_updates->>'discount_amount')::numeric, discount_amount),
    stamp_duty_amount  = COALESCE((p_invoice_updates->>'stamp_duty_amount')::numeric, stamp_duty_amount),
    po_number          = COALESCE(p_invoice_updates->>'po_number', po_number),
    payment_terms_days = COALESCE((p_invoice_updates->>'payment_terms_days')::integer, payment_terms_days),
    notes              = COALESCE(p_invoice_updates->>'notes', notes),
    linked_challan_ids = v_linked_challan_ids,
    document_status    = CASE
                           WHEN p_invoice_updates ? 'document_status'
                           THEN p_invoice_updates->>'document_status'
                           ELSE document_status
                         END,
    updated_at         = now()
  WHERE id = p_invoice_id
  RETURNING id INTO v_result;

  INSERT INTO public.sales_invoice_items (
    invoice_id, product_id, batch_id, quantity, unit_price, tax_rate, delivery_challan_item_id
  )
  SELECT
    p_invoice_id,
    (item->>'product_id')::uuid,
    NULLIF(item->>'batch_id', '')::uuid,
    (item->>'quantity')::numeric,
    (item->>'unit_price')::numeric,
    (item->>'tax_rate')::numeric,
    NULLIF(item->>'delivery_challan_item_id', '')::uuid
  FROM unnest(p_new_items) AS item;

  PERFORM set_config('app.sales_invoice_rebuild', 'false', true);
  UPDATE public.sales_invoices SET updated_at = now()
  WHERE id = p_invoice_id AND journal_entry_id IS NULL;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_sales_order_commercial_rate(p_so_id uuid, p_new_rate numeric, p_reason text DEFAULT 'Commercial FX rate updated'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_so public.sales_orders%ROWTYPE;
  v_old_rate numeric;
  v_user_id uuid := auth.uid();
  v_user_email text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Only admin, manager, accounts, sales roles can update commercial rates
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = v_user_id AND role IN ('admin', 'manager', 'accounts', 'sales')
  ) THEN
    RAISE EXCEPTION 'Unauthorized to modify commercial rates';
  END IF;

  SELECT * INTO v_so FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sales order not found');
  END IF;

  v_old_rate := v_so.commercial_usd_to_idr_rate;
  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  IF p_new_rate IS NOT NULL AND p_new_rate <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Commercial exchange rate must be positive or null');
  END IF;

  UPDATE public.sales_orders
     SET commercial_usd_to_idr_rate = p_new_rate,
         updated_at = now()
   WHERE id = p_so_id;

  INSERT INTO public.audit_logs (
    table_name,
    record_id,
    action_type,
    old_values,
    new_values,
    changed_fields,
    user_id,
    user_email,
    created_at
  ) VALUES (
    'sales_orders',
    p_so_id,
    'update',
    jsonb_build_object(
      'so_number', v_so.so_number,
      'currency', v_so.currency,
      'total_amount', v_so.total_amount,
      'commercial_usd_to_idr_rate', v_old_rate
    ),
    jsonb_build_object(
      'so_number', v_so.so_number,
      'currency', v_so.currency,
      'total_amount', v_so.total_amount,
      'commercial_usd_to_idr_rate', p_new_rate,
      'reason', COALESCE(NULLIF(trim(p_reason), ''), 'Commercial FX rate update')
    ),
    ARRAY['commercial_usd_to_idr_rate'],
    v_user_id,
    v_user_email,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'so_id', p_so_id,
    'so_number', v_so.so_number,
    'old_rate', v_old_rate,
    'new_rate', p_new_rate,
    'reason', p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_tax_payment(p_id uuid, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text DEFAULT NULL::text, p_ntpn text DEFAULT NULL::text, p_government_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_old              tax_payments%ROWTYPE;
  v_period           tax_periods%ROWTYPE;
  v_je_number        text;
  v_je_id            uuid;
  v_old_je_ids       uuid[];
  v_payable_code     text;
  v_payable_acct_id  uuid;
  v_bank_acct_coa_id uuid;
  v_ref_number       text;
  v_is_admin         boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Tax payment amount must be > 0';
  END IF;
  IF p_bank_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account is required';
  END IF;

  SELECT * INTO v_old FROM tax_payments WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';
  END IF;

  SELECT * INTO v_period FROM tax_periods WHERE id = v_old.tax_period_id;
  IF v_period.status = 'closed' AND current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    RAISE EXCEPTION 'Tax period is closed; cannot edit tax payment. Reopen the period first.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Reconciled payments can only be edited by admin (edit implies breaking
  -- the current bank reconciliation match). Non-admins must first unmatch
  -- via the Bank Reconciliation screen.
  IF v_old.status = 'reconciled' THEN
    SELECT (up.role = 'admin' AND up.is_active) INTO v_is_admin
      FROM user_profiles up WHERE up.id = auth.uid();
    IF NOT COALESCE(v_is_admin, false) THEN
      RAISE EXCEPTION 'Tax payment is reconciled; only an admin may edit it. Unmatch it in Bank Reconciliation first.'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  -- Resolve accounts (same logic as record_tax_payment)
  v_payable_code := CASE v_old.tax_type
    WHEN 'PPN'      THEN '2130'
    WHEN 'PPh21'    THEN '2131'
    WHEN 'PPh22'    THEN '2137'
    WHEN 'PPh23'    THEN '2132'
    WHEN 'PPh4(2)'  THEN '2138'
    WHEN 'PPh_Unifikasi' THEN '2131'
    ELSE NULL
  END;
  IF v_payable_code IS NULL THEN
    RAISE EXCEPTION 'Unknown tax_type: %', v_old.tax_type;
  END IF;

  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;
  IF v_payable_acct_id IS NULL THEN
    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;
  END IF;

  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;
  IF v_bank_acct_coa_id IS NULL THEN
    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;
  END IF;
  IF v_bank_acct_coa_id IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve bank CoA account';
  END IF;

  -- Reverse old JE(s)
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_old_je_ids
    FROM journal_entries
   WHERE source_module = 'tax_payment' AND reference_id = p_id;
  IF v_old.journal_entry_id IS NOT NULL AND NOT v_old.journal_entry_id = ANY (v_old_je_ids) THEN
    v_old_je_ids := array_append(v_old_je_ids, v_old.journal_entry_id);
  END IF;

  -- Release bank recon matches before deleting the JEs.
  -- NOTE: bank_statement_lines has no updated_at column — do not write it.
  UPDATE bank_statement_lines
     SET matched_entry_id       = NULL,
         matched_tax_payment_id = NULL,
         reconciliation_status  = 'unmatched'
   WHERE matched_tax_payment_id = p_id
      OR (array_length(v_old_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_old_je_ids));

  IF array_length(v_old_je_ids, 1) IS NOT NULL THEN
    UPDATE bank_reconciliation_items
       SET is_matched = false, matched_at = NULL
     WHERE journal_entry_id = ANY (v_old_je_ids);
    DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_old_je_ids);
    DELETE FROM journal_entries     WHERE id = ANY (v_old_je_ids);
  END IF;

  -- Update the payment row (period + type unchanged; use delete+create for that)
  UPDATE tax_payments SET
    payment_date         = p_payment_date,
    amount               = p_amount,
    bank_account_id      = p_bank_account_id,
    billing_code         = p_billing_code,
    ntpn                 = p_ntpn,
    government_reference = p_government_reference,
    notes                = p_notes,
    payment_reference    = p_payment_reference,
    journal_entry_id     = NULL,
    status               = 'draft',
    updated_at           = now()
  WHERE id = p_id;

  -- Post fresh JE
  v_ref_number := COALESCE(
    NULLIF(p_ntpn, ''), NULLIF(p_billing_code, ''), NULLIF(p_payment_reference, ''),
    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(p_id::text, 1, 8)
  );
  v_je_number := next_journal_entry_number();

  INSERT INTO journal_entries
    (entry_number, entry_date, source_module, reference_id, reference_number,
     description, total_debit, total_credit, is_posted, posted_by)
  VALUES
    (v_je_number, p_payment_date, 'tax_payment', p_id, v_ref_number,
     'Tax Payment ' || v_old.tax_type || ' — ' || v_ref_number,
     p_amount, p_amount, true, auth.uid())
  RETURNING id INTO v_je_id;

  INSERT INTO journal_entry_lines
    (journal_entry_id, line_number, account_id, description, debit, credit)
  VALUES
    (v_je_id, 1, v_payable_acct_id,
     v_old.tax_type || ' payment — ' || v_ref_number, p_amount, 0),
    (v_je_id, 2, v_bank_acct_coa_id,
     'Bank ' || v_old.tax_type || ' payment — ' || v_ref_number, 0, p_amount);

  UPDATE tax_payments SET journal_entry_id = v_je_id, status = 'posted', updated_at = now()
   WHERE id = p_id;

  -- Refresh period snapshot (belt-and-braces; the AFTER trigger also fires)
  PERFORM compute_period_ppn(v_old.tax_period_id);

  -- Audit log — captures full before/after
  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, old_values, new_values)
  VALUES (
    auth.uid(), 'tax_payments', 'update', p_id,
    jsonb_build_object(
      'payment_date',      v_old.payment_date,
      'amount',            v_old.amount,
      'bank_account_id',   v_old.bank_account_id,
      'ntpn',              v_old.ntpn,
      'billing_code',      v_old.billing_code,
      'payment_reference', v_old.payment_reference,
      'notes',             v_old.notes,
      'status',            v_old.status,
      'old_je_ids',        to_jsonb(v_old_je_ids)
    ),
    jsonb_build_object(
      'payment_date',      p_payment_date,
      'amount',            p_amount,
      'bank_account_id',   p_bank_account_id,
      'ntpn',              p_ntpn,
      'billing_code',      p_billing_code,
      'payment_reference', p_payment_reference,
      'notes',             p_notes,
      'new_je_id',         v_je_id,
      'edited_at',         now()
    )
  );

  RETURN p_id;
END $function$

CREATE OR REPLACE FUNCTION public.upsert_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_reference_id uuid DEFAULT NULL::uuid, p_reference_type text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inserted integer := 0;
  v_caller uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  -- Service role is always authorized
  IF v_jwt_role = 'service_role' THEN
    INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
    VALUES (p_user_id, p_type, p_title, p_message, p_reference_id, p_reference_type, false)
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    RETURN v_inserted > 0;
  END IF;

  -- Must be authenticated
  IF v_caller IS NULL THEN
    RETURN false;
  END IF;

  -- Caller can only notify themselves unless they are admin or manager
  IF v_caller != p_user_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles 
      WHERE id = v_caller AND role IN ('admin', 'manager')
    ) THEN
      -- Deny unauthorized cross-user notification gracefully without raising a fatal DB exception
      RETURN false;
    END IF;
  END IF;

  INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)
  VALUES (p_user_id, p_type, p_title, p_message, p_reference_id, p_reference_type, false)
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_coa_account(p_code text, p_expected_type text, p_expected_balance text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rec record;
  v_is_type_valid boolean := false;
BEGIN
  SELECT id, code, name, account_type, normal_balance, is_active
  INTO v_rec
  FROM public.chart_of_accounts
  WHERE code = p_code;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Chart of Accounts validation failed: account % does not exist', p_code;
  END IF;

  IF NOT v_rec.is_active THEN
    RAISE EXCEPTION 'Chart of Accounts validation failed: account % (%) is inactive', p_code, v_rec.name;
  END IF;

  -- Flexible account type check supporting contra-revenue (such as Account 4300 Sales Returns)
  IF p_code = '4300' THEN
    v_is_type_valid := (v_rec.account_type IN ('contra', 'revenue', 'contra_revenue'));
  ELSE
    v_is_type_valid := (v_rec.account_type = p_expected_type OR v_rec.account_type LIKE '%' || p_expected_type || '%');
  END IF;

  IF NOT v_is_type_valid THEN
    RAISE EXCEPTION 'Chart of Accounts validation failed: account % expected type %, found %',
      p_code, p_expected_type, v_rec.account_type;
  END IF;

  IF v_rec.normal_balance IS NOT NULL AND LOWER(v_rec.normal_balance) <> LOWER(p_expected_balance) THEN
    RAISE EXCEPTION 'Chart of Accounts validation failed: account % expected normal balance %, found %',
      p_code, p_expected_balance, v_rec.normal_balance;
  END IF;

  RETURN v_rec.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_credit_note_item_quantities()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cn public.credit_notes%ROWTYPE;
  v_sii public.sales_invoice_items%ROWTYPE;
  v_already_returned numeric(18,3) := 0;
  v_remaining_returnable numeric(18,3) := 0;
BEGIN
  IF NEW.quantity <= 0 THEN
    RAISE EXCEPTION 'Credit note item quantity must be strictly positive (got %)', NEW.quantity;
  END IF;

  IF NEW.unit_price < 0 THEN
    RAISE EXCEPTION 'Credit note item unit price cannot be negative (got %)', NEW.unit_price;
  END IF;

  SELECT * INTO v_cn FROM public.credit_notes WHERE id = NEW.credit_note_id;

  -- If credit note is tied to an original invoice, lock rows and validate returnable limit
  IF v_cn.original_invoice_id IS NOT NULL THEN
    -- Deterministic row locking on sales invoice and invoice items
    PERFORM 1 FROM public.sales_invoices WHERE id = v_cn.original_invoice_id FOR UPDATE;

    IF NEW.sales_invoice_item_id IS NOT NULL THEN
      SELECT * INTO v_sii
      FROM public.sales_invoice_items
      WHERE id = NEW.sales_invoice_item_id
        AND invoice_id = v_cn.original_invoice_id
      FOR UPDATE;
    ELSE
      SELECT * INTO v_sii
      FROM public.sales_invoice_items
      WHERE invoice_id = v_cn.original_invoice_id
        AND product_id = NEW.product_id
        AND (batch_id = NEW.batch_id OR (batch_id IS NULL AND NEW.batch_id IS NULL))
      ORDER BY id
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_sii.id IS NOT NULL THEN
      -- Calculate already returned in active credit notes
      -- Cumulative rule: Include other active credit notes, PLUS any earlier lines in the current credit note.
      -- On UPDATE, exclude only the current row being updated (cni.id = OLD.id).
      SELECT COALESCE(SUM(cni.quantity), 0)
        INTO v_already_returned
        FROM public.credit_note_items cni
        JOIN public.credit_notes existing_cn ON existing_cn.id = cni.credit_note_id
       WHERE existing_cn.original_invoice_id = v_cn.original_invoice_id
         AND (
           (cni.sales_invoice_item_id IS NOT NULL AND cni.sales_invoice_item_id = v_sii.id)
           OR (cni.sales_invoice_item_id IS NULL AND cni.product_id = v_sii.product_id AND (cni.batch_id = v_sii.batch_id OR (cni.batch_id IS NULL AND v_sii.batch_id IS NULL)))
         )
         AND existing_cn.status IN ('pending_approval', 'approved')
         AND (
           existing_cn.id <> v_cn.id
           OR (existing_cn.id = v_cn.id AND (TG_OP = 'INSERT' OR cni.id <> OLD.id))
         );

      v_remaining_returnable := GREATEST(0, v_sii.quantity - v_already_returned);

      IF NEW.quantity > (v_remaining_returnable + 0.0001) THEN
        RAISE EXCEPTION 'Return quantity % exceeds remaining returnable quantity % (Invoiced: %, Already Credited: %) for product %',
          NEW.quantity, v_remaining_returnable, v_sii.quantity, v_already_returned, v_sii.product_id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_material_return_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_return public.material_returns%ROWTYPE;
  v_original_qty numeric;
  v_found boolean := false;
BEGIN
  IF NEW.quantity_returned IS NULL OR NEW.quantity_returned <= 0 THEN
    RAISE EXCEPTION 'Returned quantity must be greater than 0';
  END IF;

  SELECT * INTO v_return FROM public.material_returns WHERE id = NEW.return_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referenced material return % does not exist', NEW.return_id;
  END IF;

  -- 1. Sourced from Delivery Challan
  IF v_return.original_dc_id IS NOT NULL THEN
    SELECT true, dci.quantity
    INTO v_found, v_original_qty
    FROM public.delivery_challan_items dci
    WHERE dci.challan_id = v_return.original_dc_id
      AND dci.product_id = NEW.product_id
      AND (NEW.batch_id IS NULL OR dci.batch_id = NEW.batch_id)
    LIMIT 1;

    IF NOT COALESCE(v_found, false) THEN
      RAISE EXCEPTION 'Item (Product %, Batch %) was not part of original Delivery Challan %',
        NEW.product_id, NEW.batch_id, v_return.original_dc_id;
    END IF;

    IF NEW.quantity_returned > v_original_qty THEN
      RAISE EXCEPTION 'Return quantity (%) exceeds original delivered quantity (%) for product %',
        NEW.quantity_returned, v_original_qty, NEW.product_id;
    END IF;

    NEW.original_quantity := COALESCE(NEW.original_quantity, v_original_qty);

  -- 2. Sourced from Sales Invoice
  ELSIF v_return.original_invoice_id IS NOT NULL THEN
    SELECT true, sii.quantity
    INTO v_found, v_original_qty
    FROM public.sales_invoice_items sii
    WHERE sii.invoice_id = v_return.original_invoice_id
      AND sii.product_id = NEW.product_id
      AND (NEW.batch_id IS NULL OR sii.batch_id = NEW.batch_id)
    LIMIT 1;

    IF NOT COALESCE(v_found, false) THEN
      RAISE EXCEPTION 'Item (Product %, Batch %) was not part of original Sales Invoice %',
        NEW.product_id, NEW.batch_id, v_return.original_invoice_id;
    END IF;

    IF NEW.quantity_returned > v_original_qty THEN
      RAISE EXCEPTION 'Return quantity (%) exceeds original invoiced quantity (%) for product %',
        NEW.quantity_returned, v_original_qty, NEW.product_id;
    END IF;

    NEW.original_quantity := COALESCE(NEW.original_quantity, v_original_qty);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tax_expense_linkage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Service role or repair bypass
  IF current_setting('app.finance_metadata_repair', true) = 'on'
     OR current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- Statutory Rule: Any expense with PPN or PPh liabilities requires a valid party
  IF (COALESCE(NEW.ppn_amount, 0) > 0 OR COALESCE(NEW.pph_amount, 0) > 0)
     AND COALESCE(NEW.expense_category, '') <> 'pib_import' THEN
    IF NEW.supplier_id IS NULL AND NEW.payee_id IS NULL AND NEW.staff_id IS NULL THEN
      RAISE EXCEPTION 'Please select a Supplier/Payee and complete the required payment details before saving this tax expense.'
        USING ERRCODE = 'check_violation';
    END IF;

    -- If marked as paid, require valid payment details
    IF (NEW.payment_method IS NOT NULL AND NEW.payment_method <> 'outstanding')
       OR COALESCE(NEW.paid_amount, 0) > 0.01 THEN
      IF NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding' THEN
        RAISE EXCEPTION 'Please select a valid payment method for this paid expense.'
          USING ERRCODE = 'check_violation';
      END IF;

      IF NEW.payment_method = 'bank_transfer'
         AND NEW.bank_account_id IS NULL
         AND NEW.originating_bank_statement_line_id IS NULL
         AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations bsa WHERE bsa.document_id = NEW.id) THEN
        RAISE EXCEPTION 'Please select a valid payment account for this paid expense.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
